        loc('vs_saltmere', 'Saltmere Harbor', 'South Coast', 'area', 'Sea walls, fish markets and deepwater piers beneath a merchant citadel. Foreign coin buys influence faster here than blood does.', [{ text: 'upriver to River Quays', travelTime: 240 }, { text: 'north to Mirecross', travelTime: 160 }, { text: 'east to Sea Gate', travelTime: 20 }], { population: 9200, prosperity: 84, danger: 37, food: 61, unrest: 29, simulateSettlement: true, controlFactionId: 'fac_guilds', shop: [{ item: 'salt fish', price: 2, quantity: 120, maxQuantity: 150, regenPerTurn: 8 }, { item: 'crossbow', price: 55, quantity: 8, maxQuantity: 12, regenPerTurn: 1 }, { item: 'foreign spice', price: 20, quantity: 16, maxQuantity: 20, regenPerTurn: 1 }] }),
        loc('vs_seagate', 'Sea Gate', 'South Coast', 'area', 'Chain towers guard the harbor mouth. Beyond them lie islands, rival kingdoms, storms and fortunes.', [{ text: 'west to Saltmere Harbor', travelTime: 20 }, { text: 'by coastal road to Gullwatch', travelTime: 100 }], { danger: 40, prosperity: 67 }),
        loc('vs_gullwatch', 'Gullwatch', 'South Coast', 'building', 'A coastal castle overlooking reefs used by wreckers and privateers. Its beacon has gone dark twice this month.', [{ text: 'west to Sea Gate', travelTime: 100 }], { population: 410, prosperity: 45, danger: 61, food: 50, simulateSettlement: true, controlFactionId: 'fac_house_vale' }),
        loc('vs_ruins', 'Thorn King’s Ruins', 'The Alderwild', 'outdoor', 'Root-split walls of the realm before the realm, avoided by foresters after sunset. Old roads converge beneath the bracken.', [{ text: 'east to Alderwood Verge', travelTime: 75 }, { text: 'north to Wolfscar Pass', travelTime: 130 }], { danger: 70, prosperity: 5 })
