    const mallUnits = [
        ['department', 'Harrington Department Store', 'clothing, housewares and a cosmetics counter'], ['music', 'Sound Circuit', 'CD listening stations, band shirts and music arguments'], ['books', 'PageTurner Books', 'new releases, magazines and a café corner'], ['games', 'Game Galaxy', 'console games, strategy guides and trade-ins'], ['electronics', 'FutureNow Electronics', 'cameras, televisions, computers and extended warranties'], ['fashion', 'Mode 21', 'fast fashion under aggressively bright lighting'], ['denim', 'Blue Rail Outfitters', 'denim walls and carefully distressed displays'], ['shoes', 'Step Up Shoes', 'sneakers displayed like trophies'], ['sports', 'Varsity Sports', 'team gear, equipment and local league sponsorships'], ['jewelry', 'Golden Hour Jewelers', 'glass cases and nervous gift buyers'], ['photo', 'QuickPic Studio', 'family portraits and one-hour developing'], ['cell', 'Connect Wireless', 'flip phones, plans, accessories and coverage maps'], ['toys', 'Wonder Box Toys', 'action figures, dolls and birthday panic'], ['cards', 'Paper Moon Gifts', 'cards, candles and seasonal decorations'], ['salonmall', 'Cuts & Curls', 'walk-in haircuts and makeover promises'], ['pretzel', 'Twist Pretzels', 'butter, salt and the smell that reaches the escalator'], ['burger', 'Burger Barn Food Court', 'trays, booths and the cheap center of teenage social life'], ['noodles', 'Wok Express', 'steam-table noodles and reliable samples'], ['icecream', 'Polar Scoop', 'ice cream, birthday shifts and sticky counters'], ['security', 'Mall Security Office', 'monitors, lost-property shelves and incident forms'], ['loading', 'Mall Service Corridor', 'delivery doors, concrete halls and the unseen route behind every storefront'], ['fountain', 'Mall Fountain Court', 'benches, indoor trees and a fountain full of pennies and dares'], ['parking', 'Bellwether Mall Parking Lot', 'endless lanes, cart corrals and arguments about where the car was left'], ['bus', 'Mall Bus Stop', 'a shelter connecting the mall to downtown, apartments and schools']
    ];
