    const jobs = [
        ['bookkeeper','bw_bank'], ['nurse','bw_hospital'], ['line supervisor','bw_plant'], ['postal carrier','bw_post'], ['mechanic','bw_garage'], ['store manager','bw_grocery'], ['legal secretary','bw_townhall'], ['sales representative','bw_mall_department'], ['electrician','bw_hardware'], ['pharmacy technician','bw_drugstore'], ['reporter','bw_paper'], ['teacher','bw_school_high'], ['warehouse lead','bw_warehouse'], ['hair stylist','bw_salon'], ['police dispatcher','bw_police'], ['restaurant server','bw_diner']
    ];
