function normalizeWorldKernelConfig(world) {
    const raw = isPlainObject(world?.kernel) ? world.kernel : {};
    const config = {
        enabled: raw.enabled !== false,
        sceneLocationLimit: Math.max(8, Math.min(80, parseInt(raw.sceneLocationLimit) || 24)),
        memoryMode: ['ledger', 'semantic'].includes(raw.memoryMode) ? raw.memoryMode : 'ledger',
        repairMode: ['adaptive', 'always', 'never'].includes(raw.repairMode) ? raw.repairMode : 'adaptive',
        compactTools: raw.compactTools !== false
    };
    if (world) world.kernel = config;
    return config;
}

function normalizeWorldDiceConfig(world) {
    if (world) world.gameRules = isPlainObject(world.gameRules) ? world.gameRules : {};
    const raw = isPlainObject(world?.gameRules?.dice) ? world.gameRules.dice : {};
    const sides = [6, 10, 12, 20].includes(parseInt(raw.sides)) ? parseInt(raw.sides) : 20;
    const requestedVisibility = ['visible', 'hidden', 'player_triggered'].includes(raw.visibility) ? raw.visibility
        : (raw.resolution === 'player' ? 'player_triggered' : 'visible');
    const config = {
        // Existing worlds historically resolved checks immediately. Preserve
        // that behavior until an author deliberately switches to player rolls.
        resolution: requestedVisibility === 'player_triggered' ? 'player'
            : (['player', 'automatic'].includes(raw.resolution) ? raw.resolution : 'automatic'),
        sides,
        // `per_stat` is the safe modern mode. Legacy global formulas remain
        // import-compatible, but new and edited worlds use each stat's own
        // roll configuration instead of turning HP, money, XP, etc. into +10.
        modifierMode: ['per_stat', 'direct', 'ability', 'none'].includes(raw.modifierMode) ? raw.modifierMode : 'per_stat',
        defaultDifficulty: Math.max(2, Math.min(sides + 10, parseInt(raw.defaultDifficulty) || Math.ceil(sides * 0.55))),
        visibility: requestedVisibility,
        criticals: raw.criticals !== false
    };
    if (world) world.gameRules.dice = config;
    return config;
}

function normalizeWorldCapabilityEntry(raw, index, kind) {
    const value = typeof raw === 'string' ? { name: raw } : (isPlainObject(raw) ? raw : {});
    const name = String(value.name || value.label || '').trim().slice(0, 100);
    if (!name) return null;
    const id = String(value.id || `${kind}_${name.toLowerCase().replace(/[^a-z0-9]+/g, '_') || index + 1}`)
        .replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 80);
    return {
        id,
        name,
        description: String(value.description || '').trim().slice(0, 300),
        cost: Math.max(0, Math.min(20, parseInt(value.cost) || 1)),
        modifier: Math.max(-10, Math.min(10, value.modifier !== '' && value.modifier != null && Number.isFinite(Number(value.modifier))
            ? Math.trunc(Number(value.modifier)) : kind === 'flaw' ? -1 : kind === 'perk' ? 1 : 2))
    };
}

function parseWorldCapabilityLines(text, kind) {
    return String(text || '').split('\n').map((line, index) => {
        const [name, description = '', cost = '1', modifier = ''] = line.split('|').map(part => part.trim());
        return normalizeWorldCapabilityEntry({ name, description, cost, modifier }, index, kind);
    }).filter(Boolean).slice(0, 100);
}

function worldCapabilityLines(entries) {
    return (Array.isArray(entries) ? entries : []).map(entry => {
        const normalized = normalizeWorldCapabilityEntry(entry, 0, 'capability');
        return normalized ? `${normalized.name}${normalized.description ? ` | ${normalized.description}` : ''} | ${normalized.cost} | ${normalized.modifier}` : '';
    }).filter(Boolean).join('\n');
}

function resolveWorldCheckCapability(world, sess, requested) {
    const key = String(requested || '').trim().toLowerCase();
    if (!key) return null;
    const capabilities = normalizeWorldCapabilities(world);
    const all = [
        ...capabilities.skills.map(entry => ({ ...entry, kind: 'skill' })),
        ...capabilities.perks.map(entry => ({ ...entry, kind: 'perk' })),
        ...capabilities.flaws.map(entry => ({ ...entry, kind: 'flaw' }))
    ];
    const definition = all.find(entry => entry.id.toLowerCase() === key || entry.name.toLowerCase() === key);
    if (!definition) return null;
    const identity = isPlainObject(sess?.playerIdentity) ? sess.playerIdentity : {};
    const selected = definition.kind === 'skill' ? identity.skills
        : definition.kind === 'perk' ? identity.perks : identity.flaws;
    const owns = (Array.isArray(selected) ? selected : []).some(value => {
        const selectedKey = String(value || '').trim().toLowerCase();
        return selectedKey === definition.id.toLowerCase() || selectedKey === definition.name.toLowerCase();
    });
    const ranks = isPlainObject(identity.capabilityRanks) ? identity.capabilityRanks : {};
    const rank = owns ? Math.max(1, Math.min(10, parseInt(ranks[definition.id] ?? ranks[definition.name]) || 1)) : 0;
    return {
        ...definition,
        selected: owns,
        rank,
        appliedModifier: owns ? Math.max(-10, Math.min(10, definition.modifier + (rank - 1))) : 0
    };
}

function normalizeWorldCapabilities(world) {
    if (!world) return { customizable: true, startingPointBudget: 4, skills: [], perks: [], flaws: [], progression: { enabled: false, method: '' } };
    world.gameRules = isPlainObject(world.gameRules) ? world.gameRules : {};
    const raw = isPlainObject(world.gameRules.capabilities) ? world.gameRules.capabilities : {};
    const authoredSkills = Array.isArray(raw.skills) ? raw.skills : [];
    const authoredPerks = Array.isArray(raw.perks) ? raw.perks : [];
    const authoredFlaws = Array.isArray(raw.flaws) ? raw.flaws : [];
    const inferred = (field, source, kind) => {
        const entries = source.length ? source : [...new Set((world.startingLives || []).flatMap(life => life?.[field] || []))];
        const used = new Set();
        return entries.map((entry, index) => normalizeWorldCapabilityEntry(entry, index, kind)).filter(entry => {
            if (!entry || used.has(entry.id)) return false;
            used.add(entry.id);
            return true;
        }).slice(0, 100);
    };
    const inferredBudget = Math.max(4, ...(world.startingLives || []).map(life =>
        (life?.skills?.length || 0) + (life?.perks?.length || 0) - (life?.flaws?.length || 0)));
    const requestedBudget = raw.startingPointBudget == null ? inferredBudget : Number(raw.startingPointBudget);
    world.gameRules.capabilities = {
        customizable: raw.customizable !== false,
        startingPointBudget: Math.max(0, Math.min(100, Number.isFinite(requestedBudget) ? Math.trunc(requestedBudget) : inferredBudget)),
        skills: inferred('skills', authoredSkills, 'skill'),
        perks: inferred('perks', authoredPerks, 'perk'),
        flaws: inferred('flaws', authoredFlaws, 'flaw'),
        progression: {
            enabled: raw.progression?.enabled === true,
            method: String(raw.progression?.method || '').trim().slice(0, 240)
        }
    };
    return world.gameRules.capabilities;
}

function worldStatRollConfig(stat) {
    const raw = isPlainObject(stat?.roll) ? stat.roll : {};
    const resourceLike = /(?:hp|health|armor|armour|gold|coin|cash|money|xp|experience|level|stress|hunger|thirst|energy|stamina|mana|currency)/i
        .test(`${stat?.id || ''} ${stat?.name || ''}`);
    return {
        enabled: typeof raw.enabled === 'boolean' ? raw.enabled : !resourceLike,
        mode: ['normalized', 'ability', 'direct', 'fixed'].includes(raw.mode) ? raw.mode : 'normalized',
        direction: raw.direction === 'lower' ? 'lower' : 'higher',
        scale: Math.max(1, Math.min(1000, Number(raw.scale) || 10)),
        fixedModifier: Math.max(-10, Math.min(10, Math.trunc(Number(raw.fixedModifier) || 0)))
    };
}

function worldRuleProfileDescription(profileId) {
    if (profileId === 'custom') {
        return 'Choose each system independently. Existing saved data is preserved when a module is disabled.';
    }
    return WORLD_RULE_PROFILES[profileId]?.description || WORLD_RULE_PROFILES.adventure.description;
}

function applyWorldRuleProfile(world, profileId) {
    if (!world || !WORLD_RULE_PROFILES[profileId]) return normalizeWorldGameRules(world);
    world.gameRules = isPlainObject(world.gameRules) ? world.gameRules : {};
    world.gameRules.profileId = profileId;
    world.gameRules.modules = { ...WORLD_RULE_PROFILES[profileId].modules };
    world.hudConfig = isPlainObject(world.hudConfig) ? world.hudConfig : {};
    world.hudConfig.enableSchedules = !!world.gameRules.modules.schedules;
    world.hudConfig.showQuests = !!world.gameRules.modules.quests;
    world.hudConfig.showInventory = !!world.gameRules.modules.inventory;
    return normalizeWorldGameRules(world);
}

function normalizeWorldGameRules(world) {
    if (!world) {
        return {
            profileId: 'custom',
            modules: Object.fromEntries(WORLD_RULE_MODULE_KEYS.map(key => [key, true])),
            vitalStatId: '',
            zeroHpMode: 'fail_forward',
            currencyStatId: '',
            currencyName: 'coin'
        };
    }
    world.hudConfig = isPlainObject(world.hudConfig) ? world.hudConfig : {};
    world.hudConfig.stats = Array.isArray(world.hudConfig.stats) ? world.hudConfig.stats : [];
    const usedIds = new Set();
    world.hudConfig.stats = world.hudConfig.stats.filter(stat => isPlainObject(stat)).map((stat, index) => {
        let id = String(stat.id || `stat_${index + 1}`).trim().slice(0, 80) || `stat_${index + 1}`;
        let suffix = 2;
        const baseId = id;
        while (usedIds.has(id.toLowerCase())) id = `${baseId.slice(0, 72)}_${suffix++}`;
        usedIds.add(id.toLowerCase());
        const min = Number.isFinite(Number(stat.min)) ? Number(stat.min) : 0;
        let max = Number.isFinite(Number(stat.max)) ? Math.max(0, Number(stat.max)) : 0;
        if (max > 0 && max < min) max = min;
        let value = Number.isFinite(Number(stat.value)) ? Number(stat.value) : 0;
        value = Math.max(min, max > 0 ? Math.min(max, value) : value);
        const hadRollConfig = isPlainObject(stat.roll);
        const roll = worldStatRollConfig({ ...stat, id });
        return {
            ...stat,
            id,
            name: String(stat.name || id).slice(0, 120),
            value,
            min,
            max,
            color: cssColor(stat.color, 'var(--accent)'),
            ...(hadRollConfig ? { roll } : {})
        };
    });

    const stats = world.hudConfig.stats;
    const raw = isPlainObject(world.gameRules) ? world.gameRules : {};
    const diceRaw = isPlainObject(raw.dice) ? { ...raw.dice } : {};
    const legacyModules = {
        stats: true,
        health: true,
        conditions: true,
        checks: true,
        inventory: true,
        equipment: true,
        commerce: true,
        quests: true,
        relationships: true,
        schedules: !!world.hudConfig.enableSchedules,
        livingWorld: true
    };
    const requestedProfileId = String(raw.profileId || '').trim();
    const profileId = requestedProfileId === 'custom' || WORLD_RULE_PROFILES[requestedProfileId]
        ? requestedProfileId : 'custom';
    const profileDefaults = profileId !== 'custom'
        ? WORLD_RULE_PROFILES[profileId].modules : legacyModules;
    const rawModules = isPlainObject(raw.modules) ? raw.modules : {};
    const modules = Object.fromEntries(WORLD_RULE_MODULE_KEYS.map(key => [
        key,
        typeof rawModules[key] === 'boolean' ? rawModules[key] : !!profileDefaults[key]
    ]));
    if (!modules.stats) {
        modules.health = false;
        modules.commerce = false;
    }
    if (!modules.inventory) { modules.commerce = false; modules.equipment = false; }
    const exactStatId = ref => {
        const key = String(ref || '').trim().toLowerCase();
        return stats.find(stat => stat.id.toLowerCase() === key)?.id || '';
    };
    const inferredVital = stats.find(stat => /^(hp|health|hitpoints?|vitality)$/i.test(stat.id)
        || /^(hp|health|hit points?|vitality)$/i.test(stat.name))?.id || '';
    // Currency is auto-detected so most worlds need no configuration, but the
    // old exact-match list missed almost everything a real author writes — a
    // stat displayed as "$$$", "Cash on hand" or "Wallet" silently left the
    // world with NO currency, and every purchase failed as currency_not_configured.
    const currencyWord = /(?:^|\b)(gold|money|monies|coin|coins|credit|credits|currency|cash|funds|wallet|purse|savings|allowance|dollars?|bucks|pounds|euros?|yen|gp|gil|caps|septims|bits|chips|scrip)(?:\b|$)/i;
    const currencySymbol = /^[$£€¥₽₹¢]{1,3}$/;
    const looksLikeCurrency = stat => {
        const id = String(stat.id || '').trim();
        const name = String(stat.name || '').trim();
        return currencySymbol.test(id) || currencySymbol.test(name)
            || currencyWord.test(id.replace(/[_-]+/g, ' '))
            || currencyWord.test(name.replace(/[_-]+/g, ' '));
    };
    const inferredCurrency = stats.find(looksLikeCurrency)?.id || '';
    const currencyStatId = exactStatId(raw.currencyStatId) || inferredCurrency;
    const currencyDefinition = stats.find(stat => stat.id === currencyStatId);
    const rpgMechanics = globalThis.HordeRpgMechanics;
    world.gameRules = {
        profileId,
        modules,
        vitalStatId: exactStatId(raw.vitalStatId) || inferredVital,
        zeroHpMode: raw.zeroHpMode === 'lethal' ? 'lethal' : 'fail_forward',
        currencyStatId,
        currencyName: String(raw.currencyName || currencyDefinition?.name || 'coin').trim().slice(0, 60) || 'coin',
        equipmentSlots: [...new Set((Array.isArray(raw.equipmentSlots) ? raw.equipmentSlots : ['head', 'body', 'main-hand', 'off-hand', 'accessory'])
            .map(slot => String(slot || '').trim().toLowerCase().replace(/\s+/g, '-')).filter(Boolean))].slice(0, 30),
        itemCatalog: rpgMechanics ? rpgMechanics.normalizeInventory(raw.itemCatalog) : (Array.isArray(raw.itemCatalog) ? raw.itemCatalog : []),
        pausedMechanicalModules: isPlainObject(raw.pausedMechanicalModules)
            ? Object.fromEntries(WORLD_OPTIONAL_RPG_MODULE_KEYS.map(key => [key, !!raw.pausedMechanicalModules[key]])) : null,
        dice: diceRaw,
        capabilities: isPlainObject(raw.capabilities) ? raw.capabilities : {},
        consequences: {
            enabled: raw.consequences?.enabled !== false,
            maxActive: Math.max(10, Math.min(300, parseInt(raw.consequences?.maxActive) || 120)),
            escalationTurns: Math.max(0, Math.min(1000, parseInt(raw.consequences?.escalationTurns) || 4)),
            decayTurns: Math.max(0, Math.min(1000, parseInt(raw.consequences?.decayTurns) || 8))
        }
    };
    normalizeWorldDiceConfig(world);
    normalizeWorldCapabilities(world);
    world.hudConfig.enableSchedules = modules.schedules;
    return world.gameRules;
}

function normalizePlayerRulesState(world, sess) {
    if (!world || !sess) return null;
    const rules = normalizeWorldGameRules(world);
    if (!isPlainObject(sess.playerState)) sess.playerState = {};
    const playerState = sess.playerState;
    if (!['active', 'incapacitated', 'dead'].includes(playerState.status)) playerState.status = 'active';
    playerState.defeatCount = Math.max(0, parseInt(playerState.defeatCount) || 0);
    playerState.lastDefeatTurn = playerState.lastDefeatTurn == null ? null : Math.max(1, parseInt(playerState.lastDefeatTurn) || 1);
    playerState.lastDefeatCause = String(playerState.lastDefeatCause || '').slice(0, 240);
    playerState.conditions = [...new Set((Array.isArray(playerState.conditions) ? playerState.conditions : [])
        .map(condition => String(condition || '').trim().slice(0, 120))
        .filter(Boolean))].slice(0, 50);
    sess.checkHistory = (Array.isArray(sess.checkHistory) ? sess.checkHistory : []).slice(-100);
    if (globalThis.HordeRpgMechanics) {
        const catalog = rules.itemCatalog || [];
        sess.inventory = globalThis.HordeRpgMechanics.normalizeInventory((sess.inventory || []).map(value => {
            if (typeof value !== 'string') return value;
            return globalThis.HordeRpgMechanics.findItem(catalog, value) || value;
        }));
    }
    sess.equipment = isPlainObject(sess.equipment) ? sess.equipment : {};
    rules.equipmentSlots.forEach(slot => { if (!(slot in sess.equipment)) sess.equipment[slot] = null; });
    const validItemIds = new Set((sess.inventory || []).map(item => item?.id).filter(Boolean));
    Object.keys(sess.equipment).forEach(slot => { if (sess.equipment[slot] && !validItemIds.has(sess.equipment[slot])) sess.equipment[slot] = null; });
    if (!isPlainObject(sess.pendingCheck)) sess.pendingCheck = null;

    const vitalDef = (world.hudConfig?.stats || []).find(stat => stat.id === rules.vitalStatId);
    const vitalValue = vitalDef ? Number(sess.playerStats?.[vitalDef.id] ?? vitalDef.value) : null;
    if (!rules.modules.health) {
        playerState.status = 'active';
        playerState.conditions = playerState.conditions.filter(condition => condition.toLowerCase() !== 'incapacitated');
    } else if (vitalDef && Number.isFinite(vitalValue) && vitalValue <= vitalDef.min && playerState.status === 'active') {
        playerState.status = rules.zeroHpMode === 'lethal' ? 'dead' : 'incapacitated';
        if (playerState.status === 'incapacitated' && !playerState.conditions.includes('Incapacitated')) {
            playerState.conditions.push('Incapacitated');
        }
    }
    if (sess.economy && typeof sess.economy === 'object') sess.economy.currency = rules.currencyName;
    return playerState;
}

function worldEquipmentModifiers(world, sess) {
    const rules = normalizeWorldGameRules(world);
    if (!rules.modules.equipment || !globalThis.HordeRpgMechanics) return globalThis.HordeRpgMechanics?.modifiers({}) || { stats: {}, skills: {}, checks: 0 };
    normalizePlayerRulesState(world, sess);
    const equippedIds = new Set(Object.values(sess.equipment || {}).filter(Boolean));
    return globalThis.HordeRpgMechanics.combinedModifiers((sess.inventory || []).filter(item => item?.equipped || equippedIds.has(item?.id)));
}

function worldOptionalRpgEnabled(world) {
    const modules = normalizeWorldGameRules(world).modules;
    return WORLD_OPTIONAL_RPG_MODULE_KEYS.some(key => !!modules[key]);
}

async function toggleWorldOptionalRpg() {
    const world = state.worlds.find(item => item.id === state.activeWorldId);
    if (!world) return;
    const rules = normalizeWorldGameRules(world);
    const enabled = worldOptionalRpgEnabled(world);
    if (enabled) {
        rules.pausedMechanicalModules = Object.fromEntries(WORLD_OPTIONAL_RPG_MODULE_KEYS.map(key => [key, !!rules.modules[key]]));
        WORLD_OPTIONAL_RPG_MODULE_KEYS.forEach(key => { rules.modules[key] = false; });
        showToast('RPG mechanics paused. Stats, builds and items remain saved.', 'info');
    } else {
        const restore = isPlainObject(rules.pausedMechanicalModules)
            ? rules.pausedMechanicalModules : WORLD_RULE_PROFILES.adventure.modules;
        WORLD_OPTIONAL_RPG_MODULE_KEYS.forEach(key => { rules.modules[key] = !!restore[key]; });
        showToast('RPG mechanics restored for this world.', 'success');
    }
    rules.profileId = 'custom';
    world.gameRules = rules;
    await saveState();
    renderWorldPlayState();
}

function effectiveWorldStatValue(world, sess, stat) {
    const base = Number(sess.playerStats?.[stat.id] ?? stat.value ?? 0);
    const bonuses = worldEquipmentModifiers(world, sess);
    return base + Number(bonuses.stats?.[stat.id] || bonuses.stats?.[stat.name] || 0);
}

function applyPlayerStatChanges(world, sess, changes, options = {}) {
    const result = { success: false, applied: [], rejected: [], defeat: null, recovered: false };
    if (!world || !sess || !isPlainObject(changes)) {
        result.rejected.push({ reason: 'invalid_stat_changes' });
        return result;
    }
    const rules = normalizeWorldGameRules(world);
    if (!rules.modules.stats) {
        result.rejected.push({ reason: 'module_disabled', module: 'stats' });
        return result;
    }
    const playerState = normalizePlayerRulesState(world, sess);
    const definitions = world.hudConfig?.stats || [];
    const planned = [];
    Object.entries(changes).slice(0, 100).forEach(([requestedId, rawAmount]) => {
        const key = String(requestedId || '').trim().toLowerCase();
        const definition = definitions.find(stat => stat.id.toLowerCase() === key);
        const amount = Number(rawAmount);
        if (!definition) {
            result.rejected.push({ statId: requestedId, reason: 'unknown_stat' });
            return;
        }
        if (!Number.isFinite(amount) || Math.abs(amount) > 1e9) {
            result.rejected.push({ statId: definition.id, reason: 'invalid_amount' });
            return;
        }
        const current = Number(sess.playerStats?.[definition.id] ?? definition.value) || 0;
        let next = options.absolute ? amount : current + amount;
        next = Math.max(definition.min, definition.max > 0 ? Math.min(definition.max, next) : next);
        if (playerState?.status === 'dead' && definition.id === rules.vitalStatId
            && next > definition.min && !options.allowDeadRecovery) {
            result.rejected.push({ statId: definition.id, reason: 'timeline_ended' });
            return;
        }
        planned.push({ definition, amount, current, next });
    });
    if (result.rejected.length && options.atomic !== false) return result;
    if (options.dryRun) {
        result.applied = planned.map(change => ({
            statId: change.definition.id,
            previous: change.current,
            value: change.next,
            change: change.next - change.current
        }));
        result.success = result.applied.length > 0 && result.rejected.length === 0;
        return result;
    }
    if (!sess.playerStats || typeof sess.playerStats !== 'object') sess.playerStats = {};

    planned.forEach(change => {
        sess.playerStats[change.definition.id] = change.next;
        result.applied.push({
            statId: change.definition.id,
            previous: change.current,
            value: change.next,
            change: change.next - change.current
        });
        if (options.showToast !== false && change.next !== change.current) {
            const delta = change.next - change.current;
            showToast(`${change.definition.name} ${delta > 0 ? '+' : ''}${delta}`, delta > 0 ? 'success' : 'info');
        }
    });

    const vitalDef = definitions.find(stat => stat.id === rules.vitalStatId);
    const vitalChange = planned.find(change => change.definition.id === rules.vitalStatId);
    if (rules.modules.health && vitalDef && vitalChange) {
        if (vitalChange.next <= vitalDef.min && playerState.status === 'active') {
            const lethal = rules.zeroHpMode === 'lethal';
            playerState.status = lethal ? 'dead' : 'incapacitated';
            playerState.defeatCount++;
            playerState.lastDefeatTurn = sess.turnCount || 1;
            playerState.lastDefeatCause = String(options.cause || 'Health reached zero.').slice(0, 240);
            if (!lethal && !playerState.conditions.includes('Incapacitated')) playerState.conditions.push('Incapacitated');
            result.defeat = {
                mode: lethal ? 'game_over' : 'fail_forward',
                status: playerState.status,
                cause: playerState.lastDefeatCause
            };
            const eventText = lethal
                ? `The player has died. This timeline is over unless the turn is rerolled or a new timeline begins. Cause: ${playerState.lastDefeatCause}`
                : `The player is incapacitated at zero ${vitalDef.name}. Impose a serious fail-forward consequence—capture, rescue with debt, lasting injury, or lost resources—before recovery.`;
            queueEngineEvent(sess, eventText);
            appendWorldLedgerEntry(sess, lethal
                ? `The player died: ${playerState.lastDefeatCause}`
                : `The player was incapacitated after ${vitalDef.name} reached zero.`);
            showToast(lethal ? '☠️ Game Over — this timeline has ended' : '⚠️ Incapacitated — the story will fail forward', lethal ? 'error' : 'info');
        } else if (vitalChange.next > vitalDef.min && playerState.status === 'incapacitated') {
            playerState.status = 'active';
            playerState.conditions = playerState.conditions.filter(condition => condition !== 'Incapacitated');
            result.recovered = true;
            showToast('Recovered from incapacitation', 'success');
        } else if (vitalChange.next > vitalDef.min && playerState.status === 'dead' && options.allowDeadRecovery) {
            playerState.status = 'active';
            playerState.conditions = playerState.conditions.filter(condition => condition !== 'Incapacitated');
            result.recovered = true;
            showToast('Timeline restored by manual correction', 'success');
        }
    }
    result.success = result.applied.length > 0 && result.rejected.length === 0;
    return result;
}

function findInventoryMatchIndices(inventory, item, quantity = 1) {
    const itemName = value => globalThis.HordeRpgMechanics?.itemName(value) || String(value || '');
    const query = questTextKey(itemName(item));
    if (!query || !Array.isArray(inventory)) return [];
    const exact = [];
    const fuzzy = [];
    inventory.forEach((entry, index) => {
        const key = questTextKey(itemName(entry));
        if (key === query) exact.push(index);
        else if (key.includes(query) || query.includes(key)) fuzzy.push(index);
    });
    return [...exact, ...fuzzy].slice(0, Math.max(1, quantity));
}

function executeCommerceTransactions(world, sess, transactions) {
    normalizeLivingWorldState(world, sess);
    const rules = normalizeWorldGameRules(world);
    const results = [];
    if (!Array.isArray(transactions)) return results;
    if (!rules.modules.commerce) {
        return transactions.slice(0, 20).map((raw, index) => ({
            index,
            type: raw?.type || '',
            item: String(raw?.item || '').slice(0, 100),
            quantity: Math.max(1, Math.min(100, parseInt(raw?.quantity) || 1)),
            success: false,
            reason: 'module_disabled',
            module: 'commerce'
        }));
    }
    const currencyDef = (world.hudConfig?.stats || []).find(stat => stat.id === rules.currencyStatId);

    transactions.slice(0, 20).forEach((raw, index) => {
        const type = raw?.type === 'sell' ? 'sell' : raw?.type === 'buy' ? 'buy' : '';
        const quantity = Math.max(1, Math.min(100, parseInt(raw?.quantity) || 1));
        const location = getLocationRef(world, raw?.location_id || sess.playerLocation);
        const itemQuery = questTextKey(raw?.item);
        const base = { index, type, item: String(raw?.item || '').slice(0, 100), quantity, success: false };
        if (!type || !location || !itemQuery) return results.push({ ...base, reason: 'invalid_transaction' });
        if (!currencyDef) return results.push({ ...base, reason: 'currency_not_configured' });
        const market = sess.economy.markets[location.id];
        // Most worlds never define a market — nobody sets up stock tables for a
        // corner shop or a friend selling you a bike. When the DM states a price,
        // honour the trade against the purse directly instead of failing
        // with no_market and leaving the money untouched while the fiction says
        // it was spent. A defined market still wins: it keeps stock authoritative.
        const statedPrice = Number(raw?.price ?? raw?.unit_price ?? raw?.cost);
        if (!market) {
            if (!Number.isFinite(statedPrice) || statedPrice < 0) {
                return results.push({ ...base, reason: 'no_market_and_no_price' });
            }
            const itemName = String(raw?.item || '').trim().slice(0, 100);
            const total = Math.round(statedPrice * quantity);
            const funds = Number(sess.playerStats?.[currencyDef.id] ?? currencyDef.value) || 0;
            if (type === 'buy') {
                if (funds < total) return results.push({ ...base, item: itemName, reason: 'cannot_afford', cost: total, funds });
                const statResult = applyPlayerStatChanges(world, sess, { [currencyDef.id]: -total },
                    { showToast: false, cause: `Purchased ${itemName}.` });
                if (!statResult.success && total > 0) return results.push({ ...base, item: itemName, reason: 'currency_update_failed' });
                if (rules.modules.inventory) for (let count = 0; count < quantity; count++) sess.inventory.push(itemName);
                showToast(`Bought ${quantity} × ${itemName} for ${total} ${rules.currencyName}`, 'success');
                return results.push({ ...base, item: itemName, success: true, unitPrice: statedPrice, total, openMarket: true, balance: Number(sess.playerStats[currencyDef.id]) || 0 });
            }
            const indices = findInventoryMatchIndices(sess.inventory, itemName, quantity);
            if (rules.modules.inventory && indices.length < quantity) {
                return results.push({ ...base, item: itemName, reason: 'item_not_owned', owned: indices.length });
            }
            if (currencyDef.max > 0 && funds + total > currencyDef.max) {
                return results.push({ ...base, item: itemName, reason: 'currency_capacity', capacity: currencyDef.max });
            }
            indices.sort((a, b) => b - a).forEach(itemIndex => sess.inventory.splice(itemIndex, 1));
            const statResult = applyPlayerStatChanges(world, sess, { [currencyDef.id]: total }, { showToast: false });
            if (!statResult.success && total > 0) {
                for (let count = 0; count < quantity; count++) sess.inventory.push(itemName);
                return results.push({ ...base, item: itemName, reason: 'currency_update_failed' });
            }
            showToast(`Sold ${quantity} × ${itemName} for ${total} ${rules.currencyName}`, 'success');
            return results.push({ ...base, item: itemName, success: true, unitPrice: statedPrice, total, openMarket: true, balance: Number(sess.playerStats[currencyDef.id]) || 0 });
        }
        const candidates = Object.entries(market).filter(([key, stock]) => {
            const stockKey = questTextKey(stock?.item || key);
            return stockKey === itemQuery || stockKey.includes(itemQuery) || itemQuery.includes(stockKey);
        });
        const exact = candidates.filter(([key, stock]) => questTextKey(stock?.item || key) === itemQuery);
        const selected = exact.length === 1 ? exact[0] : candidates.length === 1 ? candidates[0] : null;
        if (!selected) return results.push({ ...base, reason: candidates.length ? 'ambiguous_item' : 'item_not_sold_here' });
        const [stockKey, stock] = selected;
        const unitPrice = Math.max(0, Number(stock.price) || 0);
        const total = unitPrice * quantity;
        const funds = Number(sess.playerStats?.[currencyDef.id] ?? currencyDef.value) || 0;

        if (type === 'buy') {
            if (stock.quantity < quantity) return results.push({ ...base, item: stock.item, reason: 'insufficient_stock', available: stock.quantity });
            if (funds < total) return results.push({ ...base, item: stock.item, reason: 'cannot_afford', cost: total, funds });
            const statResult = applyPlayerStatChanges(world, sess, { [currencyDef.id]: -total }, { showToast: false, cause: `Purchased ${stock.item}.` });
            if (!statResult.success && total > 0) return results.push({ ...base, item: stock.item, reason: 'currency_update_failed' });
            stock.quantity -= quantity;
            for (let count = 0; count < quantity; count++) sess.inventory.push(stock.item);
            results.push({ ...base, item: stock.item, success: true, unitPrice, total, balance: Number(sess.playerStats[currencyDef.id]) || 0, stock: stock.quantity });
            showToast(`Bought ${quantity} × ${stock.item} for ${total} ${rules.currencyName}`, 'success');
        } else {
            const indices = findInventoryMatchIndices(sess.inventory, stock.item, quantity);
            if (indices.length < quantity) return results.push({ ...base, item: stock.item, reason: 'item_not_owned', owned: indices.length });
            if (stock.maxQuantity > 0 && stock.quantity + quantity > stock.maxQuantity) {
                return results.push({ ...base, item: stock.item, reason: 'merchant_stock_full' });
            }
            if (currencyDef.max > 0 && funds + total > currencyDef.max) {
                return results.push({ ...base, item: stock.item, reason: 'currency_capacity', capacity: currencyDef.max });
            }
            indices.sort((a, b) => b - a).forEach(itemIndex => sess.inventory.splice(itemIndex, 1));
            stock.quantity += quantity;
            const statResult = applyPlayerStatChanges(world, sess, { [currencyDef.id]: total }, { showToast: false });
            if (!statResult.success && total > 0) {
                // Roll back the item side if an unexpected stat validation failure occurs.
                stock.quantity -= quantity;
                for (let count = 0; count < quantity; count++) sess.inventory.push(stock.item);
                return results.push({ ...base, item: stock.item, reason: 'currency_update_failed' });
            }
            results.push({ ...base, item: stock.item, success: true, unitPrice, total, balance: Number(sess.playerStats[currencyDef.id]) || 0, stock: stock.quantity });
            showToast(`Sold ${quantity} × ${stock.item} for ${total} ${rules.currencyName}`, 'success');
        }
        market[stockKey] = stock;
    });
    return results;
}

function performAuthoritativeChecks(world, sess, checks) {
    const results = [];
    if (!Array.isArray(checks)) return results;
    const rules = normalizeWorldGameRules(world);
    if (!rules.modules.checks) {
        return checks.slice(0, 10).map((raw, index) => ({
            id: String(raw?.id || `check_${index + 1}`).slice(0, 80),
            label: String(raw?.label || `Check ${index + 1}`).slice(0, 120),
            success: false,
            reason: 'module_disabled',
            module: 'checks'
        }));
    }
    if (!Array.isArray(sess.checkHistory)) sess.checkHistory = [];
    const dice = normalizeWorldDiceConfig(world);
    const definitions = world.hudConfig?.stats || [];
    checks.slice(0, 10).forEach((raw, index) => {
        const turn = sess.turnCount || 1;
        const label = String(raw?.label || `Check ${index + 1}`).trim().slice(0, 120);
        // Model wording and IDs may change on reroll; the mechanical slot does
        // not. Engine-authored IDs make a roll immutable for this turn/index.
        const checkId = String(raw?.force_resolve === true && raw?.id
            ? raw.id : `check_${turn}_${index + 1}`).slice(0, 80);
        let existing = null;
        for (let historyIndex = sess.checkHistory.length - 1; historyIndex >= 0; historyIndex--) {
            const candidate = sess.checkHistory[historyIndex];
            if (candidate?.turn === turn && candidate?.id === checkId) {
                existing = candidate;
                break;
            }
        }
        if (existing) {
            const replay = { ...existing, replayed: true };
            results.push(replay);
            if (dice.visibility !== 'hidden') showToast(`↻ ${existing.label}: keeping ${existing.roll} → ${existing.total}`, 'info');
            return;
        }
        const statId = String(raw?.stat_id || '').trim();
        const definition = definitions.find(stat => stat.id.toLowerCase() === statId.toLowerCase());
        const statModifier = worldCheckModifier(world, sess, definition?.id || '');
        const capability = resolveWorldCheckCapability(world, sess, raw?.capability_id);
        const capabilityModifier = capability?.appliedModifier || 0;
        const situationalModifier = Math.max(-5, Math.min(5, Math.trunc(Number(raw?.modifier) || 0)));
        let equipmentModifier = 0;
        if (rules.modules.equipment && globalThis.HordeRpgMechanics) {
            const equippedIds = new Set(Object.values(sess.equipment || {}).filter(Boolean));
            const equipped = (sess.inventory || []).filter(item => item?.equipped || equippedIds.has(item?.id));
            const bonuses = globalThis.HordeRpgMechanics.combinedModifiers(equipped);
            equipmentModifier = Number(bonuses.checks || 0)
                + Number(bonuses.stats?.[definition?.id] || bonuses.stats?.[definition?.name] || 0)
                + Number(bonuses.skills?.[capability?.id] || bonuses.skills?.[capability?.name] || 0);
        }
        const difficulty = Math.max(2, Math.min(dice.sides + 10,
            Math.trunc(Number(raw?.difficulty) || dice.defaultDifficulty)));

        if (dice.resolution === 'player' && !Number.isFinite(Number(raw?.provided_roll)) && raw?.force_resolve !== true) {
            const pendingRequest = {
                id: checkId, label, stat_id: definition?.id || '', capability_id: capability?.id || '', modifier: situationalModifier,
                difficulty, failure_cost: isPlainObject(raw?.failure_cost)
                    ? JSON.parse(JSON.stringify(raw.failure_cost)) : null,
                on_success: isPlainObject(raw?.on_success) ? safeJsonClone(raw.on_success) : null,
                on_failure: isPlainObject(raw?.on_failure) ? safeJsonClone(raw.on_failure) : null,
                requestedTurn: turn, requestedAt: Date.now()
            };
            if (!Array.isArray(sess.pendingChecks)) sess.pendingChecks = [];
            if (!sess.pendingChecks.some(item => item.id === checkId)) sess.pendingChecks.push(pendingRequest);
            sess.pendingChecks = sess.pendingChecks.slice(0, 10);
            sess.pendingCheck = sess.pendingChecks[0] || pendingRequest;
            results.push({ id: checkId, label, statId: definition?.id || '', capabilityId: capability?.id || '', difficulty, pending: true, success: null });
            showToast(`🎲 Check requested: ${label} · roll d${dice.sides} vs ${difficulty}`, 'info');
            return;
        }

        const provided = Number(raw?.provided_roll);
        const roll = Number.isFinite(provided)
            ? Math.max(1, Math.min(dice.sides, Math.trunc(provided)))
            : 1 + Math.floor(stableWorldRoll(`${world.id}|${sess.id}|${turn}|${checkId}`) * dice.sides);
        const total = roll + statModifier + capabilityModifier + situationalModifier + equipmentModifier;
        const criticalSuccess = dice.criticals && roll === dice.sides;
        const criticalFailure = dice.criticals && roll === 1;
        const success = criticalSuccess || (!criticalFailure && total >= difficulty);
        const result = {
            id: checkId,
            label,
            statId: definition?.id || '',
            capabilityId: capability?.id || '',
            capabilityName: capability?.name || '',
            capabilitySelected: capability?.selected === true,
            roll,
            statModifier,
            capabilityModifier,
            situationalModifier,
            equipmentModifier,
            total,
            difficulty,
            success,
            sides: dice.sides,
            critical: criticalSuccess ? 'success' : criticalFailure ? 'failure' : ''
        };
        if (!success && isPlainObject(raw?.failure_cost)) {
            const cost = raw.failure_cost;
            const statPreview = isPlainObject(cost.stat_changes)
                ? applyPlayerStatChanges(world, sess, cost.stat_changes, { dryRun: true })
                : { success: true, rejected: [] };
            const requestedItems = (Array.isArray(cost.inventory_remove) ? cost.inventory_remove : []).slice(0, 20);
            const reservedIndices = [];
            const unavailableItems = [];
            requestedItems.forEach(item => {
                const candidate = findInventoryMatchIndices(sess.inventory, item, sess.inventory.length)
                    .find(itemIndex => !reservedIndices.includes(itemIndex));
                if (candidate === undefined) unavailableItems.push(String(item));
                else reservedIndices.push(candidate);
            });
            if (statPreview.rejected.length || unavailableItems.length) {
                result.failureCost = {
                    applied: false,
                    reason: statPreview.rejected.length ? 'invalid_stat_cost' : 'missing_item_cost',
                    rejectedStats: statPreview.rejected,
                    unavailableItems
                };
            } else {
                result.failureCost = { applied: true };
                if (isPlainObject(cost.stat_changes) && Object.keys(cost.stat_changes).length) {
                    result.failureCost.stats = applyPlayerStatChanges(world, sess, cost.stat_changes, {
                        cause: String(cost.cause || `Failed check: ${label}`).slice(0, 240)
                    });
                }
                result.failureCost.itemsRemoved = [];
                reservedIndices.sort((a, b) => b - a).forEach(itemIndex => {
                    result.failureCost.itemsRemoved.unshift(sess.inventory.splice(itemIndex, 1)[0]);
                });
                const time = Math.max(0, Math.min(14400, parseInt(cost.time_skip_minutes) || 0));
                if (time > 0) {
                    sess.bonusTimeMinutes = (sess.bonusTimeMinutes || 0) + time;
                    result.failureCost.timeSkipped = time;
                }
                const condition = String(cost.condition || '').trim().slice(0, 120);
                if (condition) {
                    const state = normalizePlayerRulesState(world, sess);
                    if (!state.conditions.includes(condition)) state.conditions.push(condition);
                    result.failureCost.condition = condition;
                }
            }
        }
        sess.checkHistory.push({ ...result, turn });
        if (Array.isArray(sess.pendingChecks)) sess.pendingChecks = sess.pendingChecks.filter(item => item.id !== checkId);
        sess.pendingCheck = sess.pendingChecks?.[0] || null;
        results.push(result);
        if (dice.visibility !== 'hidden') {
            showToast(`${success ? '✓' : '×'} ${label}: ${roll}${statModifier || situationalModifier ? ` → ${total}` : ''} vs ${difficulty}`, success ? 'success' : 'info');
        }
    });
    if (sess.checkHistory.length > 100) sess.checkHistory.splice(0, sess.checkHistory.length - 100);
    return results;
}

function applyWorldCapabilityProgress(world, sess, updates) {
    const progression = normalizeWorldCapabilities(world).progression;
    const results = [];
    if (!Array.isArray(updates)) return results;
    if (!progression.enabled) return updates.slice(0, 20).map(raw => ({
        capabilityId: String(raw?.capability_id || '').slice(0, 80), success: false, reason: 'progression_disabled'
    }));
    sess.playerIdentity = isPlainObject(sess.playerIdentity) ? sess.playerIdentity : {};
    sess.playerIdentity.capabilityRanks = isPlainObject(sess.playerIdentity.capabilityRanks)
        ? sess.playerIdentity.capabilityRanks : {};
    updates.slice(0, 20).forEach(raw => {
        const capability = resolveWorldCheckCapability(world, sess, raw?.capability_id);
        if (!capability) return results.push({ capabilityId: String(raw?.capability_id || '').slice(0, 80), success: false, reason: 'unknown_capability' });
        if (!capability.selected) return results.push({ capabilityId: capability.id, success: false, reason: 'capability_not_selected' });
        const change = Math.max(-5, Math.min(5, Math.trunc(Number(raw?.change) || 0)));
        if (!change) return results.push({ capabilityId: capability.id, success: false, reason: 'zero_change' });
        const previous = capability.rank;
        const rank = Math.max(1, Math.min(10, previous + change));
        sess.playerIdentity.capabilityRanks[capability.id] = rank;
        results.push({ capabilityId: capability.id, name: capability.name, previous, rank, change: rank - previous,
            reason: String(raw?.reason || '').trim().slice(0, 240), success: rank !== previous });
    });
    return results;
}

function applyPlayerConditionUpdates(world, sess, updates) {
    const results = [];
    if (!Array.isArray(updates)) return results;
    const rules = normalizeWorldGameRules(world);
    if (!rules.modules.conditions) {
        return updates.slice(0, 50).map(raw => ({
            condition: String(raw?.condition || '').trim().slice(0, 120),
            action: raw?.action || '',
            success: false,
            reason: 'module_disabled',
            module: 'conditions'
        }));
    }
    const playerState = normalizePlayerRulesState(world, sess);
    const vitalDef = (world.hudConfig?.stats || []).find(stat => stat.id === rules.vitalStatId);
    const vitalValue = vitalDef ? Number(sess.playerStats?.[vitalDef.id] ?? vitalDef.value) : null;
    updates.slice(0, 50).forEach(raw => {
        const condition = String(raw?.condition || '').trim().slice(0, 120);
        const action = raw?.action === 'remove' ? 'remove' : raw?.action === 'add' ? 'add' : '';
        if (!condition || !action) return results.push({ condition, action, success: false, reason: 'invalid_condition_update' });
        if (action === 'remove' && condition.toLowerCase() === 'incapacitated'
            && vitalDef && Number.isFinite(vitalValue) && vitalValue <= vitalDef.min) {
            return results.push({ condition, action, success: false, reason: 'health_still_zero' });
        }
        if (action === 'add') {
            if (!playerState.conditions.some(existing => existing.toLowerCase() === condition.toLowerCase())) {
                playerState.conditions.push(condition);
            }
        } else {
            playerState.conditions = playerState.conditions.filter(existing =>
                existing.toLowerCase() !== condition.toLowerCase());
        }
        results.push({ condition, action, success: true });
    });
    return results;
}

const QUEST_STATUSES = new Set(['active', 'completed', 'failed', 'abandoned']);
const QUEST_OBJECTIVE_TYPES = new Set(['manual', 'location', 'inventory', 'stat', 'secret', 'npc_status', 'thread']);

function questTextKey(value) {
    return String(value || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

function makeQuestId(sess, title = 'quest', requestedId = '') {
    // Honour the id the caller supplied. The model is told to track quests by
    // exact id, so silently renaming its quest on creation broke every
    // follow-up it sent: the update matched nothing, the quest never advanced,
    // and declared rewards were never granted.
    const clean = String(requestedId || '').trim().slice(0, 160);
    if (clean && /^[A-Za-z0-9_-]+$/.test(clean)) {
        const taken = new Set((sess?.quests || []).map(quest => String(quest?.id || '').toLowerCase()));
        if (!taken.has(clean.toLowerCase())) return clean;
    }
    const slug = questTextKey(title).replace(/\s+/g, '_').slice(0, 42) || 'quest';
    const base = `quest_${slug}`;
    const used = new Set((sess?.quests || []).map(quest => String(quest?.id || '').toLowerCase()));
    if (!used.has(base.toLowerCase())) return base;
    let suffix = 2;
    while (used.has(`${base}_${suffix}`.toLowerCase())) suffix++;
    return `${base}_${suffix}`;
}

function normalizeQuestRewards(rawRewards) {
    const raw = isPlainObject(rawRewards) ? rawRewards : {};
    const items = [...new Set((Array.isArray(raw.items) ? raw.items : [])
        .map(item => String(item || '').trim().slice(0, 160))
        .filter(Boolean))].slice(0, 100);
    const stats = {};
    if (isPlainObject(raw.stats || raw.stat_changes)) {
        Object.entries(raw.stats || raw.stat_changes).slice(0, 100).forEach(([key, value]) => {
            const amount = Number(value);
            if (!key || !Number.isFinite(amount) || !amount) return;
            stats[String(key).slice(0, 80)] = Math.max(-1e9, Math.min(1e9, amount));
        });
    }
    const factionReputation = (Array.isArray(raw.factionReputation || raw.faction_reputation)
        ? (raw.factionReputation || raw.faction_reputation) : []).slice(0, 100).map(entry => ({
        factionId: String(entry?.factionId || entry?.faction_id || '').trim().slice(0, 80),
        change: Math.max(-100, Math.min(100, Number(entry?.change) || 0))
    })).filter(entry => entry.factionId && entry.change);
    return { items, stats, factionReputation };
}

function normalizeQuestObjective(rawObjective, index = 0, usedIds = new Set()) {
    const raw = isPlainObject(rawObjective) ? rawObjective : { text: String(rawObjective || '') };
    const text = String(raw.text || raw.description || raw.target || `Objective ${index + 1}`).trim().slice(0, 240);
    const baseId = String(raw.id || `obj_${questTextKey(text).replace(/\s+/g, '_').slice(0, 36) || index + 1}`).slice(0, 80);
    let id = baseId;
    let suffix = 2;
    while (usedIds.has(id.toLowerCase())) id = `${baseId.slice(0, 72)}_${suffix++}`;
    usedIds.add(id.toLowerCase());
    const type = QUEST_OBJECTIVE_TYPES.has(raw.type) ? raw.type : 'manual';
    const required = Math.max(1, Math.min(1e9, Number(raw.required) || 1));
    let current = Math.max(0, Math.min(1e9, Number(raw.current ?? raw.progress) || 0));
    let status = ['active', 'completed', 'failed'].includes(raw.status) ? raw.status : 'active';
    if (status === 'completed') current = Math.max(current, required);
    if (current >= required && status === 'active') status = 'completed';
    return {
        id,
        text,
        type,
        target: String(raw.target || '').trim().slice(0, 160),
        expected: String(raw.expected || raw.value || '').trim().slice(0, 80),
        required,
        current,
        status,
        optional: !!raw.optional
    };
}

function normalizeQuestState(world, sess) {
    if (!sess) return [];
    const rawQuests = Array.isArray(sess.quests) ? sess.quests.slice(0, 500) : [];
    const usedIds = new Set();
    sess.quests = rawQuests.filter(quest => isPlainObject(quest)).map((quest, index) => {
        const title = String(quest.title || `Quest ${index + 1}`).trim().slice(0, 200);
        const baseId = String(quest.id || makeQuestId({ quests: [...usedIds].map(id => ({ id })) }, title)).slice(0, 80);
        let id = baseId;
        let suffix = 2;
        while (usedIds.has(id.toLowerCase())) id = `${baseId.slice(0, 72)}_${suffix++}`;
        usedIds.add(id.toLowerCase());
        const objectiveIds = new Set();
        const objectives = (Array.isArray(quest.objectives) ? quest.objectives : [])
            .slice(0, 100)
            .map((objective, objectiveIndex) => normalizeQuestObjective(objective, objectiveIndex, objectiveIds));
        const status = QUEST_STATUSES.has(quest.status) ? quest.status : 'active';
        return {
            id,
            title,
            description: String(quest.description || '').trim().slice(0, 1000),
            giver: String(quest.giver || '').trim().slice(0, 160),
            status,
            objectives,
            rewards: normalizeQuestRewards(quest.rewards),
            rewardsGranted: !!quest.rewardsGranted,
            rewardReceipt: String(quest.rewardReceipt || '').slice(0, 500),
            createdTurn: Math.max(1, parseInt(quest.createdTurn) || 1),
            updatedTurn: Math.max(1, parseInt(quest.updatedTurn) || parseInt(quest.createdTurn) || 1),
            resolvedTurn: quest.resolvedTurn == null ? null : Math.max(1, parseInt(quest.resolvedTurn) || 1),
            rewardGrantedTurn: quest.rewardGrantedTurn == null ? null : Math.max(1, parseInt(quest.rewardGrantedTurn) || 1),
            completionNote: String(quest.completionNote || '').trim().slice(0, 500)
        };
    });
    return sess.quests;
}

function findSessionQuest(sess, idOrTitle, fallbackTitle = '') {
    const query = questTextKey(idOrTitle);
    const titleQuery = questTextKey(fallbackTitle);
    return (sess.quests || []).find(quest =>
        (query && questTextKey(quest.id) === query)
        || (query && questTextKey(quest.title) === query)
        || (titleQuery && questTextKey(quest.title) === titleQuery));
}

function formatQuestRewardSummary(quest) {
    const rewards = normalizeQuestRewards(quest?.rewards);
    const parts = [];
    if (rewards.items.length) parts.push(rewards.items.join(', '));
    Object.entries(rewards.stats).forEach(([key, value]) => parts.push(`${key} ${value > 0 ? '+' : ''}${value}`));
    rewards.factionReputation.forEach(entry => parts.push(`${entry.factionId} reputation ${entry.change > 0 ? '+' : ''}${entry.change}`));
    return parts.join(' · ');
}

function grantQuestRewards(world, sess, quest) {
    if (!quest || quest.status !== 'completed' || quest.rewardsGranted) return false;
    const modules = normalizeWorldGameRules(world).modules;
    const rewards = normalizeQuestRewards(quest.rewards);
    const receipt = [];
    if (!Array.isArray(sess.inventory)) sess.inventory = [];
    if (modules.inventory) {
        rewards.items.forEach(item => {
            if (!sess.inventory.some(existing => questTextKey(existing) === questTextKey(item))) {
                sess.inventory.push(item);
                receipt.push(item);
            }
        });
    }
    if (modules.stats) {
        const statRewards = applyPlayerStatChanges(world, sess, rewards.stats, {
            showToast: false,
            cause: `Quest reward settlement for ${quest.title}.`
        });
        statRewards.applied.forEach(applied => {
            const definition = (world?.hudConfig?.stats || []).find(stat => stat.id === applied.statId);
            receipt.push(`${definition?.name || applied.statId} ${applied.change > 0 ? '+' : ''}${applied.change}`);
        });
    }
    if (modules.relationships || modules.livingWorld) rewards.factionReputation.forEach(entry => {
        const query = questTextKey(entry.factionId);
        if (!Array.isArray(sess.factions)) sess.factions = [];
        let faction = sess.factions.find(item =>
            questTextKey(item.id) === query || questTextKey(item.name) === query);
        if (!faction && sess.factions.length < 200) {
            faction = {
                id: String(entry.factionId).slice(0, 80),
                name: String(entry.factionId).slice(0, 120),
                reputation: 0,
                influence: 50,
                resources: 50,
                goal: '',
                goalProgress: 0,
                status: 'active',
                territory: [],
                relations: []
            };
            sess.factions.push(faction);
        }
        if (!faction) return;
        faction.reputation = Math.max(-100, Math.min(100, (Number(faction.reputation) || 0) + entry.change));
        receipt.push(`${faction.name} reputation ${entry.change > 0 ? '+' : ''}${entry.change}`);
    });
    quest.rewardsGranted = true;
    quest.rewardGrantedTurn = sess.turnCount || 1;
    quest.rewardReceipt = receipt.join(' · ') || 'No material reward';
    if (receipt.length) showToast(`Quest rewards: ${receipt.join(', ')}`, 'success');
    return true;
}

function evaluateQuestObjective(world, sess, objective) {
    if (!objective || objective.status === 'failed') return false;
    let current = Number(objective.current) || 0;
    const targetKey = questTextKey(objective.target);
    if (objective.type !== 'manual' && !targetKey) current = 0;
    if (objective.type === 'location') {
        const target = getLocationRef(world, objective.target);
        current = target && sess.playerLocation === target.id ? objective.required : 0;
    } else if (objective.type === 'inventory') {
        current = targetKey ? (sess.inventory || []).filter(item => {
            const key = questTextKey(item);
            return key === targetKey || key.includes(targetKey) || targetKey.includes(key);
        }).length : 0;
    } else if (objective.type === 'stat') {
        current = Number(sess.playerStats?.[objective.target]) || 0;
    } else if (objective.type === 'secret') {
        const target = questTextKey(objective.target);
        current = (sess.revealedSecrets || []).some(label => questTextKey(label) === target) ? objective.required : 0;
    } else if (objective.type === 'npc_status') {
        const npcId = resolveNpcId(world, objective.target, sess);
        const expectedRaw = questTextKey(objective.expected || 'dead');
        const expected = expectedRaw === 'departed' ? 'gone' : expectedRaw;
        const actual = questTextKey(sess.entityStates?.[npcId]?.status || 'alive');
        current = npcId && actual === expected ? objective.required : 0;
    } else if (objective.type === 'thread') {
        const target = questTextKey(objective.target);
        const thread = (sess.threads || []).find(item =>
            questTextKey(item.id) === target || questTextKey(item.text) === target);
        current = thread?.status === 'resolved' ? objective.required : 0;
    }
    objective.current = Math.max(0, Math.min(1e9, current));
    if (objective.status !== 'failed') {
        objective.status = objective.current >= objective.required ? 'completed' : 'active';
    }
    return objective.status === 'completed';
}

function evaluateQuestProgress(world, sess, options = {}) {
    if (!normalizeWorldGameRules(world).modules.quests) {
        return { changed: false, completed: [], failed: [], rewardsGranted: [], disabled: true };
    }
    normalizeQuestState(world, sess);
    const result = { changed: false, completed: [], failed: [], rewardsGranted: [] };
    (sess.quests || []).forEach(quest => {
        const beforeStatus = quest.status;
        const beforeObjectives = JSON.stringify(quest.objectives);
        if (quest.status === 'active' && quest.objectives.length) {
            quest.objectives.forEach(objective => evaluateQuestObjective(world, sess, objective));
            const required = quest.objectives.filter(objective => !objective.optional);
            if (required.some(objective => objective.status === 'failed')) quest.status = 'failed';
            else if (required.length && required.every(objective => objective.status === 'completed')) quest.status = 'completed';
        }
        if (quest.status !== beforeStatus) {
            quest.updatedTurn = sess.turnCount || 1;
            quest.resolvedTurn = ['completed', 'failed', 'abandoned'].includes(quest.status) ? (sess.turnCount || 1) : null;
            result.changed = true;
            if (quest.status === 'completed') {
                result.completed.push(quest.id);
                showToast(`Quest completed: ${quest.title}`, 'success');
            } else if (quest.status === 'failed') {
                result.failed.push(quest.id);
                showToast(`Quest failed: ${quest.title}`, 'info');
            }
        }
        if (JSON.stringify(quest.objectives) !== beforeObjectives) result.changed = true;
        if (grantQuestRewards(world, sess, quest)) {
            result.rewardsGranted.push(quest.id);
            result.changed = true;
        }
    });
    return result;
}

function applyQuestUpdates(world, sess, updates) {
    if (!normalizeWorldGameRules(world).modules.quests) {
        return { changed: false, completed: [], failed: [], rewardsGranted: [], disabled: true };
    }
    normalizeQuestState(world, sess);
    if (!Array.isArray(updates)) return evaluateQuestProgress(world, sess);
    updates.slice(0, 100).forEach(rawUpdate => {
        if (!isPlainObject(rawUpdate)) return;
        let quest = findSessionQuest(sess, rawUpdate.id, rawUpdate.title);
        if (!quest) {
            const title = String(rawUpdate.title || '').trim().slice(0, 200);
            if (!title || sess.quests.length >= 500) return;
            quest = {
                id: makeQuestId(sess, title, rawUpdate.id),
                title,
                description: '',
                giver: '',
                status: 'active',
                objectives: [],
                rewards: normalizeQuestRewards(null),
                rewardsGranted: false,
                rewardReceipt: '',
                createdTurn: sess.turnCount || 1,
                updatedTurn: sess.turnCount || 1,
                resolvedTurn: null,
                rewardGrantedTurn: null,
                completionNote: ''
            };
            sess.quests.push(quest);
            showToast(`New quest: ${quest.title}`, 'success');
        }
        if (rawUpdate.title !== undefined) quest.title = String(rawUpdate.title || quest.title).trim().slice(0, 200);
        if (rawUpdate.description !== undefined) quest.description = String(rawUpdate.description || '').trim().slice(0, 1000);
        if (rawUpdate.giver !== undefined) quest.giver = String(rawUpdate.giver || '').trim().slice(0, 160);
        if (rawUpdate.completion_note !== undefined) quest.completionNote = String(rawUpdate.completion_note || '').trim().slice(0, 500);
        if (rawUpdate.rewards !== undefined && !quest.rewardsGranted) quest.rewards = normalizeQuestRewards(rawUpdate.rewards);
        if (Array.isArray(rawUpdate.objectives)) {
            rawUpdate.objectives.slice(0, 100).forEach((rawObjective, objectiveIndex) => {
                if (!isPlainObject(rawObjective)) return;
                let objective = quest.objectives.find(item =>
                    (rawObjective.id && questTextKey(item.id) === questTextKey(rawObjective.id))
                    || (rawObjective.text && questTextKey(item.text) === questTextKey(rawObjective.text)));
                if (!objective) {
                    if (quest.objectives.length >= 100) return;
                    const ids = new Set(quest.objectives.map(item => item.id.toLowerCase()));
                    objective = normalizeQuestObjective(rawObjective, objectiveIndex, ids);
                    quest.objectives.push(objective);
                } else {
                    if (rawObjective.text !== undefined) objective.text = String(rawObjective.text || objective.text).trim().slice(0, 240);
                    if (QUEST_OBJECTIVE_TYPES.has(rawObjective.type)) objective.type = rawObjective.type;
                    if (rawObjective.target !== undefined) objective.target = String(rawObjective.target || '').trim().slice(0, 160);
                    if (rawObjective.expected !== undefined || rawObjective.value !== undefined) {
                        objective.expected = String(rawObjective.expected || rawObjective.value || '').trim().slice(0, 80);
                    }
                    if (rawObjective.required !== undefined) objective.required = Math.max(1, Math.min(1e9, Number(rawObjective.required) || 1));
                    if (rawObjective.current !== undefined) objective.current = Math.max(0, Math.min(1e9, Number(rawObjective.current) || 0));
                    if (rawObjective.progress_change !== undefined) {
                        objective.current = Math.max(0, Math.min(1e9, objective.current + Number(rawObjective.progress_change || 0)));
                    }
                    if (['active', 'completed', 'failed'].includes(rawObjective.status)) objective.status = rawObjective.status;
                    if (rawObjective.optional !== undefined) objective.optional = !!rawObjective.optional;
                    if (objective.status === 'completed') objective.current = Math.max(objective.current, objective.required);
                }
            });
        }
        const previousStatus = quest.status;
        if (QUEST_STATUSES.has(rawUpdate.status)) quest.status = rawUpdate.status;
        if (quest.status !== previousStatus) {
            quest.resolvedTurn = ['completed', 'failed', 'abandoned'].includes(quest.status) ? (sess.turnCount || 1) : null;
        }
        quest.updatedTurn = sess.turnCount || 1;
    });
    normalizeQuestState(world, sess);
    return evaluateQuestProgress(world, sess);
}

function getQuestPrompt(world, sess) {
    if (!normalizeWorldGameRules(world).modules.quests) return '';
    normalizeQuestState(world, sess);
    const active = sess.quests.filter(quest => quest.status === 'active').slice(0, 50);
    const resolved = sess.quests.filter(quest => quest.status !== 'active').slice(-10);
    const lines = ['[PLAYER QUEST LEDGER — AUTHORITATIVE]'];
    if (!active.length) lines.push('No active quests.');
    active.forEach(quest => {
        lines.push(`- [${quest.id}] ${quest.title}${quest.giver ? ` (giver: ${quest.giver})` : ''}`);
        if (quest.description) lines.push(`  ${quest.description}`);
        quest.objectives.forEach(objective => {
            lines.push(`  - [${objective.id}] ${objective.status}: ${objective.text} (${objective.current}/${objective.required}; type=${objective.type}${objective.target ? `; target=${objective.target}` : ''})`);
        });
        const rewards = formatQuestRewardSummary(quest);
        if (rewards) lines.push(`  Promised rewards: ${rewards}`);
    });
    if (resolved.length) {
        lines.push('Recently resolved:');
        resolved.forEach(quest => lines.push(`- [${quest.id}] ${quest.status}: ${quest.title}${quest.rewardsGranted ? ' (rewards settled)' : ''}`));
    }
    // The ledger used to explain only how to UPDATE quests, so a DM with an
    // empty ledger had no reason to ever create one — the quest system simply
    // never started. State plainly when a quest comes into existence.
    lines.push('WHEN TO OPEN A QUEST: the moment the player takes on anything that outlives this scene — accepts a job, errand, favour or bargain; makes a promise; sets themselves a goal; is given a deadline, a debt, or a warning to act on — call quests_update with a title and, where the fiction supports it, concrete objectives. This is true of everyday obligations ("pick Emily up at six", "pay Greg back by Friday") as much as of grand adventures. Do not wait for the player to ask for a quest, and do not announce it as a game mechanic — record it and keep narrating.');
    lines.push('Use these exact quest and objective IDs in quests_update. Never recreate an existing quest under a new title. The engine evaluates structured objectives and grants declared rewards exactly once; do not duplicate declared rewards through inventory_add or stat_changes.');
    return `\n${lines.join('\n')}\n`;
}

function extractQuestUpdateDirective(text) {
    const source = String(text || '');
    const updates = [];
    const pattern = /<quest_updates_json>\s*([\s\S]*?)\s*<\/quest_updates_json>/gi;
    let match;
    while ((match = pattern.exec(source)) !== null) {
        try {
            const parsed = JSON.parse(match[1]);
            if (Array.isArray(parsed)) updates.push(...parsed);
        } catch (error) {
            console.warn('Horde Engine: ignored invalid fallback quest update JSON.', error);
        }
    }
    return {
        text: source.replace(pattern, '').trim(),
        updates: updates.slice(0, 100)
    };
}

function openWorldQuestManager(questId = '') {
    const world = state.worlds.find(item => item.id === state.activeWorldId);
    const sess = getCurrentWorldSession();
    const modal = document.getElementById('world-quest-modal-overlay');
    if (!world || !sess || !modal) return;
    normalizeQuestState(world, sess);
    const quest = questId ? findSessionQuest(sess, questId) : null;
    document.getElementById('m-quest-id').value = quest?.id || '';
    document.getElementById('m-quest-title').value = quest?.title || '';
    document.getElementById('m-quest-description').value = quest?.description || '';
    document.getElementById('m-quest-giver').value = quest?.giver || '';
    document.getElementById('m-quest-status').value = quest?.status || 'active';
    document.getElementById('m-quest-objective').value = '';
    document.getElementById('delete-world-quest-btn').style.visibility = quest ? 'visible' : 'hidden';
    const rewardItemsInput = document.getElementById('m-quest-reward-items');
    const rewardStatsInput = document.getElementById('m-quest-reward-stats');
    rewardItemsInput.value = quest?.rewards?.items?.join(', ') || '';
    rewardStatsInput.value = Object.entries(quest?.rewards?.stats || {})
        .map(([key, value]) => `${key}: ${value}`).join(', ');
    rewardItemsInput.disabled = !!quest?.rewardsGranted;
    rewardStatsInput.disabled = !!quest?.rewardsGranted;

    const objectives = document.getElementById('m-quest-objectives');
    objectives.innerHTML = '';
    if (!quest?.objectives?.length) {
        objectives.textContent = 'No structured objectives yet.';
    } else {
        quest.objectives.forEach(objective => {
            const row = document.createElement('div');
            row.className = 'quest-manager-objective';
            const label = document.createElement('div');
            const marker = objective.status === 'completed' ? '✓' : objective.status === 'failed' ? '×' : '○';
            label.textContent = `${marker} ${objective.text}`;
            row.appendChild(label);
            if (objective.type === 'manual') {
                const select = document.createElement('select');
                select.className = 'form-select m-quest-objective-status';
                select.dataset.objectiveId = objective.id;
                ['active', 'completed', 'failed'].forEach(status => {
                    const option = document.createElement('option');
                    option.value = status;
                    option.textContent = status[0].toUpperCase() + status.slice(1);
                    option.selected = objective.status === status;
                    select.appendChild(option);
                });
                row.appendChild(select);
            } else {
                const stateLabel = document.createElement('div');
                stateLabel.className = 'quest-manager-objective-state';
                stateLabel.textContent = `${objective.current}/${objective.required} · ${objective.type} · automatic`;
                row.appendChild(stateLabel);
            }
            objectives.appendChild(row);
        });
    }
    const rewardSummary = quest ? formatQuestRewardSummary(quest) : '';
    document.getElementById('m-quest-rewards').textContent = rewardSummary
        ? `${rewardSummary}${quest.rewardsGranted ? `\nGranted: ${quest.rewardReceipt}` : ''}`
        : 'No material reward declared.';
    modal.classList.remove('hidden');
    document.getElementById('m-quest-title').focus();
}

async function createNewWorldSession() {
    const world = state.worlds.find(w => w.id === state.activeWorldId);
    const inst = state.worldInstances[state.activeWorldId];
    if (!world || !inst) return;

    // Validation: Ensure startLocationId exists
    const defaultStartId = world.startLocationId || world.locations[0]?.id || null;

    const gameRules = normalizeWorldGameRules(world);
    const newSess = {
        id: 'wsess_' + Date.now(),
        name: 'New Timeline ' + (inst.sessions.length + 1),
        playerLocation: defaultStartId,
        inventory: [],
        ledger: "",
        ledgerRevision: 0,
        ledgerManualRevision: 0,
        ledgerManualOverrideText: "",
        ledgerDiagnostics: { turn: 0, status: 'not_checked', source: 'none' },
        entityStates: {},
        history: [],
        playerStats: {},
        playerState: { status: 'active', defeatCount: 0, lastDefeatTurn: null, lastDefeatCause: '', conditions: [] },
        checkHistory: [],
        pendingCheck: null,
        quests: [],
        revealedSecrets: [],
        bonusTimeMinutes: 0,
        scheduledEvents: JSON.parse(JSON.stringify(Array.isArray(world.scheduledEvents) ? world.scheduledEvents : [])),
        consequences: [],
        locationStates: seedLocationStatesFromWorld(world),
        npcRelationships: seedRelationshipsFromWorld(world),
        npcScheduleOverrides: {},
        dynamicExits: {},
        factions: seedFactionsFromWorld(world),
        economy: { currency: gameRules.currencyName, markets: seedMarketsFromWorld(world) },
        playstyle: {
            turnsObserved: 0,
            signals: {},
            preferences: {},
            dominant: [],
            summary: 'No clear playstyle pattern yet.'
        },
        worldNews: [],
        lastLivingWorldTick: 0,
        livingWorldActivity: {
            turn: 0, events: 0, goals: 0, factions: 0,
            markets: 0, scheduleMoves: 0, activeSchedules: 0
        },
        playerIdentity: {},
        personaId: state.activePersonaId || '',
        lifeSeed: null,
        legalStanding: {},
        society: null,
        setupComplete: false,
        pendingChecks: []
    };

    // Standardize playerLocation to ID immediately
    const startLoc = world.locations.find(l => l.id === newSess.playerLocation || l.name === newSess.playerLocation);
    if (startLoc) newSess.playerLocation = startLoc.id;

    // Setup initial NPC locations (ID-Strict Audit)
    sessionNpcs(world, newSess).forEach(ent => {
        if (ent.type === 'npc') {
            const loc = world.locations.find(l => l.name === ent.startLocation || l.id === ent.startLocation);
            newSess.entityStates[ent.id] = {
                location: loc ? loc.id : defaultStartId,
                observations: []
            };
        }
    });

    // Init stats from config
    (world.hudConfig?.stats || []).forEach(s => {
        newSess.playerStats[s.id] = s.value;
    });
    normalizePlayerRulesState(world, newSess);
    normalizeWorldSocietyState(world, newSess);

    inst.sessions.push(newSess);
    inst.activeSessionId = newSess.id;
    await saveState();
    renderWorldPlayState();
    openSessionZero(() => executeWorldTurn("init"));
    showToast('New Timeline Created');
}

/**
 * 🎬 New Session Setup: choose identity and story preferences before play.
 * Prefs live on the session and are injected into every DM generation.
 * `onDone` runs after the modal closes (used to chain the init turn).
 */
function sessionRoleSelections(world, sess) {
    const selected = id => [...document.querySelectorAll(`#${id} input[type="checkbox"]:checked`)].map(input => input.value);
    const stats = {};
    document.querySelectorAll('#sz-attribute-list [data-stat-id]').forEach(input => {
        if (Number.isFinite(Number(input.value))) stats[input.dataset.statId] = Number(input.value);
    });
    return {
        publicIdentity: String(document.getElementById('sz-public-identity')?.value || '').trim().slice(0, 240),
        reputation: String(document.getElementById('sz-reputation')?.value || '').trim().slice(0, 240),
        skills: selected('sz-skill-list'),
        perks: selected('sz-trait-list').filter(value => !value.startsWith('flaw:')),
        flaws: selected('sz-trait-list').filter(value => value.startsWith('flaw:')).map(value => value.slice(5)),
        inventory: selected('sz-equipment-list'),
        stats
    };
}

function renderSessionRoleSetup(world, sess, persona) {
    const section = document.getElementById('sz-role-section');
    if (!section || !world || !sess) return;
    const rules = normalizeWorldGameRules(world);
    const capabilities = normalizeWorldCapabilities(world);
    const life = (world.startingLives || []).find(item => item.id === sess.originId) || null;
    const hasSetup = rules.modules.stats || capabilities.skills.length || capabilities.perks.length
        || capabilities.flaws.length || (life?.inventory || []).length;
    section.classList.toggle('hidden', !hasSetup);
    if (!hasSetup) return;
    const publicIdentity = document.getElementById('sz-public-identity');
    const reputation = document.getElementById('sz-reputation');
    publicIdentity.value = sess.playerIdentity?.publicIdentity || persona?.publicIdentity || life?.role || '';
    reputation.value = sess.playerIdentity?.reputation || persona?.reputation || '';
    publicIdentity.disabled = !capabilities.customizable;
    reputation.disabled = !capabilities.customizable;

    const byName = values => new Set((values || []).map(value => String(value).toLowerCase()));
    const lifeSkills = byName(life?.skills);
    const lifePerks = byName(life?.perks);
    const lifeFlaws = byName(life?.flaws);
    const option = (entry, checked, prefix = '') => `<label class="session-role-option"><input type="checkbox" value="${escapeHTML(prefix + entry.name)}" ${checked ? 'checked' : ''} ${capabilities.customizable ? '' : 'disabled'}><span><strong>${escapeHTML(entry.name)}</strong>${entry.description ? `<small>${escapeHTML(entry.description)}</small>` : ''}</span><b>${prefix ? '+' : '−'}${entry.cost}</b></label>`;
    document.getElementById('sz-skill-list').innerHTML = capabilities.skills.length
        ? capabilities.skills.map(entry => option(entry, lifeSkills.has(entry.name.toLowerCase()))).join('')
        : '<span class="form-hint">This World defines no selectable skills.</span>';
    document.getElementById('sz-trait-list').innerHTML = capabilities.perks.map(entry => option(entry, lifePerks.has(entry.name.toLowerCase())))
        .concat(capabilities.flaws.map(entry => option(entry, lifeFlaws.has(entry.name.toLowerCase()), 'flaw:'))).join('')
        || '<span class="form-hint">This World defines no perks or flaws.</span>';
    document.getElementById('sz-equipment-list').innerHTML = (life?.inventory || []).length
        ? life.inventory.map(item => `<label class="session-role-option"><input type="checkbox" value="${escapeHTML(item)}" checked ${capabilities.customizable ? '' : 'disabled'}><span>${escapeHTML(item)}</span></label>`).join('')
        : '<span class="form-hint">No optional starting equipment.</span>';

    const attributeList = document.getElementById('sz-attribute-list');
    const rollable = rules.modules.stats ? (world.hudConfig?.stats || []).filter(stat => worldStatRollConfig(stat).enabled).slice(0, 20) : [];
    attributeList.innerHTML = rollable.length
        ? `<label class="form-label">Attributes</label>${rollable.map(stat => {
            const baseline = Number(life?.statOverrides?.[stat.id] ?? stat.value) || 0;
            const max = stat.max > 0 ? stat.max : baseline + capabilities.startingPointBudget;
            return `<label class="session-role-option"><span><strong>${escapeHTML(stat.name)}</strong><small>${stat.min}–${max}</small></span><input class="form-input" data-stat-id="${escapeHTML(stat.id)}" data-base="${baseline}" type="number" min="${stat.min}" max="${max}" value="${baseline}" ${capabilities.customizable ? '' : 'disabled'}></label>`;
        }).join('')}` : '';

    const updateSummary = () => {
        const selection = sessionRoleSelections(world, sess);
        const lookup = new Map([...capabilities.skills, ...capabilities.perks].map(item => [item.name, item.cost]));
        const flawLookup = new Map(capabilities.flaws.map(item => [item.name, item.cost]));
        let spent = [...selection.skills, ...selection.perks].reduce((sum, name) => sum + (lookup.get(name) || 1), 0);
        spent -= selection.flaws.reduce((sum, name) => sum + (flawLookup.get(name) || 1), 0);
        document.querySelectorAll('#sz-attribute-list [data-stat-id]').forEach(input => {
            spent += Math.max(0, (Number(input.value) || 0) - (Number(input.dataset.base) || 0));
        });
        const remaining = capabilities.startingPointBudget - spent;
        const points = document.getElementById('sz-points-status');
        points.textContent = capabilities.customizable ? `${remaining} point${Math.abs(remaining) === 1 ? '' : 's'} left` : 'Preset locked';
        points.style.color = remaining < 0 ? 'var(--red)' : '';
        document.getElementById('sz-role-summary').innerHTML = `<strong>${escapeHTML(life?.name || 'Custom role')}</strong> · ${escapeHTML(selection.publicIdentity || life?.role || 'unwritten public identity')}<br>${selection.skills.length ? `Skills: ${escapeHTML(selection.skills.join(', '))}. ` : ''}${selection.perks.length ? `Perks: ${escapeHTML(selection.perks.join(', '))}. ` : ''}${selection.flaws.length ? `Flaws: ${escapeHTML(selection.flaws.join(', '))}. ` : ''}${selection.inventory.length ? `Equipment: ${escapeHTML(selection.inventory.join(', '))}.` : ''}`;
        return remaining;
    };
    section.querySelectorAll('input').forEach(input => input.addEventListener('input', updateSummary));
    section.dataset.pointsValid = 'true';
    section._remainingPoints = updateSummary;
}

function openSessionZero(onDone) {
    const overlay = document.getElementById('world-session-zero-overlay');
    const sess = getCurrentWorldSession();
    if (!overlay || !sess) { if (onDone) onDone(); return; }

    const toneInput = document.getElementById('sz-tone');
    const focusInput = document.getElementById('sz-focus');
    const pacingInput = document.getElementById('sz-pacing');
    const notesInput = document.getElementById('sz-notes');
    const skipButton = document.getElementById('sz-skip-btn');
    const saveButton = document.getElementById('sz-begin-btn');
    const closeButton = document.getElementById('close-session-zero-btn');
    const saveStatus = document.getElementById('sz-save-status');
    const originSection = document.getElementById('sz-origin-section');
    const originList = document.getElementById('sz-origin-list');
    const personaSelect = document.getElementById('sz-persona-select');
    const personaPreview = document.getElementById('sz-persona-preview');
    const lifeSeedOption = document.getElementById('sz-life-seed-option');
    const lifeSeedEnabled = document.getElementById('sz-life-seed-enabled');
    const lifeSeedStatus = document.getElementById('sz-life-seed-status');
    const world = state.worlds.find(item => item.id === state.activeWorldId);
    const isFirstRun = typeof onDone === 'function';
    // Every control in this modal is provisional until an explicit Begin/Save.
    // Starting-Life cards update the session for a live preview, so snapshot the
    // complete timeline and restore it when X/Escape/Cancel dismisses the modal.
    const sessionSetupSnapshot = JSON.parse(JSON.stringify(sess));
    const prefs = sess.storyPrefs || {};
    toneInput.value = prefs.tone || '';
    focusInput.value = prefs.focus || '';
    pacingInput.value = prefs.pacing || '';
    notesInput.value = prefs.notes || '';
    skipButton.textContent = isFirstRun ? 'Start without life setup' : 'Cancel';
    saveButton.textContent = isFirstRun ? 'Begin Adventure' : 'Save Preferences';
    closeButton.title = 'Close without saving';
    saveStatus.textContent = Object.values(prefs).some(Boolean) ? 'Saved preferences loaded' : '';

    const storedPersonaId = sess.personaId !== undefined ? sess.personaId : (state.activePersonaId || '');
    personaSelect.innerHTML = '<option value="">No Persona — use only the Starting Life</option>'
        + state.personas.map(persona => `<option value="${escapeHTML(persona.id)}">${escapeHTML(persona.name || 'Unnamed Persona')}</option>`).join('');
    personaSelect.value = state.personas.some(persona => persona.id === storedPersonaId) ? storedPersonaId : '';
    const renderPersonaPreview = () => {
        const selected = state.personas.find(persona => persona.id === personaSelect.value);
        personaPreview.textContent = selected && personaPromptText(selected).trim()
            ? personaPromptText(selected)
            : 'No Persona selected. The Starting Life will be the only identity source.';
        renderSessionRoleSetup(world, sess, selected);
    };
    personaSelect.onchange = () => { renderPersonaPreview(); saveStatus.textContent = 'Unsaved identity change'; };
    renderPersonaPreview();
    const alreadyInitialized = !!sess.lifeSeed?.initialized;
    personaSelect.disabled = alreadyInitialized;
    personaSelect.title = alreadyInitialized
        ? 'This Persona is locked to the initialized timeline. Create a new timeline to seed a different life.' : '';
    lifeSeedEnabled.checked = !alreadyInitialized;
    lifeSeedEnabled.disabled = alreadyInitialized || !isFirstRun;
    lifeSeedOption.classList.toggle('hidden', alreadyInitialized || !isFirstRun);
    lifeSeedStatus.textContent = alreadyInitialized
        ? `Active life initialized: ${sess.lifeSeed.summary || `${sess.lifeSeed.people?.length || 0} persistent people`}`
        : isFirstRun ? `This runs once using ${structuredModelFor(world)}. If that model fails, a deterministic initializer preserves the core household facts. It will not regenerate or overwrite this timeline later.` : '';

    normalizeWorldSandboxConfig(world);
    const canChooseOrigin = !!(originSection && originList && world?.startingLives?.length
        && (!sess.history?.length || !sess.originId));
    originSection?.classList.toggle('hidden', !canChooseOrigin);
    if (canChooseOrigin) {
        if (!sess.originId || !world.startingLives.some(life => life.id === sess.originId)) {
            applyStartingLifeToSession(world, sess, world.startingLives[0].id);
        }
        const renderOrigins = () => {
            originList.innerHTML = '';
            world.startingLives.forEach(life => {
                const location = getLocationRef(world, life.startLocationId);
                const card = document.createElement('button');
                card.type = 'button';
                card.className = `session-origin-card${sess.originId === life.id ? ' selected' : ''}`;
                card.innerHTML = `
                    <span class="session-origin-icon">${escapeHTML(life.icon || '◈')}</span>
                    <span class="session-origin-copy">
                        <span class="session-origin-meta">${escapeHTML(life.socialRank || 'wanderer')}${location ? ` · ${escapeHTML(location.name)}` : ''}</span>
                        <strong>${escapeHTML(life.name)}</strong>
                        <small>${escapeHTML(life.description || life.role || '')}</small>
                        ${(life.skills?.length || life.perks?.length) ? `<small class="session-origin-capabilities">${escapeHTML([...(life.skills || []).slice(0, 3), ...(life.perks || []).slice(0, 2)].join(' · '))}</small>` : ''}
                    </span>`;
                card.onclick = () => {
                    applyStartingLifeToSession(world, sess, life.id);
                    renderOrigins();
                    renderSessionRoleSetup(world, sess, state.personas.find(persona => persona.id === personaSelect.value) || null);
                    saveStatus.textContent = `Starting as ${life.name}`;
                };
                originList.appendChild(card);
            });
        };
        renderOrigins();
        renderSessionRoleSetup(world, sess, state.personas.find(persona => persona.id === personaSelect.value) || null);
    }

    overlay.classList.remove('hidden');
    const close = () => overlay.classList.add('hidden');
    let finished = false;
    let saving = false;

    const dismiss = () => {
        if (saving || finished) return;
        Object.keys(sess).forEach(key => delete sess[key]);
        Object.assign(sess, JSON.parse(JSON.stringify(sessionSetupSnapshot)));
        finished = true;
        close();
        // A brand-new blank timeline is not valid gameplay state. Dismissing
        // setup returns to the world library instead of leaving a live input
        // that can start play without a chosen identity/start state.
        if (isFirstRun && !sess.history?.length && !sess.setupComplete) switchView('worlds');
    };

    const readPreferences = () => ({
        tone: toneInput.value,
        focus: focusInput.value,
        pacing: pacingInput.value,
        notes: notesInput.value.trim()
    });
    const markDirty = () => {
        if (!saving) saveStatus.textContent = 'Unsaved changes';
    };
    toneInput.onchange = markDirty;
    focusInput.onchange = markDirty;
    pacingInput.onchange = markDirty;
    notesInput.oninput = markDirty;

    const finish = () => {
        if (finished) return;
        finished = true;
        close();
        if (onDone) onDone();
    };
    const savePreferences = async (seedLife = true) => {
        if (saving) return false;
        saving = true;
        skipButton.disabled = true;
        saveButton.disabled = true;
        closeButton.disabled = true;
        saveStatus.textContent = 'Saving…';
        const s = getCurrentWorldSession();
        if (!s) {
            saveStatus.textContent = 'Save failed — timeline unavailable';
            saving = false;
            skipButton.disabled = false;
            saveButton.disabled = false;
            closeButton.disabled = false;
            return false;
        }
        s.storyPrefs = readPreferences();
        s.personaId = personaSelect.value || '';
        const selectedPersona = state.personas.find(persona => persona.id === s.personaId) || null;
        const roleSection = document.getElementById('sz-role-section');
        if (roleSection && !roleSection.classList.contains('hidden') && typeof roleSection._remainingPoints === 'function'
            && roleSection._remainingPoints() < 0) {
            saveStatus.textContent = 'Spend within the starting-point budget';
            showToast('Your role uses more points than this World allows.', 'error');
            saving = false;
            skipButton.disabled = false;
            saveButton.disabled = false;
            closeButton.disabled = false;
            return false;
        }
        const role = sessionRoleSelections(world, s);
        s.playerIdentity = isPlainObject(s.playerIdentity) ? s.playerIdentity : {};
        s.playerIdentity.personaName = selectedPersona?.name || '';
        s.playerIdentity.age = selectedPersona?.age || '';
        s.playerIdentity.pronouns = selectedPersona?.pronouns || '';
        s.playerIdentity.appearance = selectedPersona?.appearance || '';
        s.playerIdentity.publicIdentity = role.publicIdentity || selectedPersona?.publicIdentity || '';
        s.playerIdentity.reputation = role.reputation || selectedPersona?.reputation || '';
        if (!document.getElementById('sz-role-section')?.classList.contains('hidden')) {
            s.playerIdentity.skills = [...role.skills];
            s.playerIdentity.perks = [...role.perks];
            s.playerIdentity.flaws = [...role.flaws];
            const chosenCapabilities = [...role.skills, ...role.perks, ...role.flaws];
            s.playerIdentity.capabilityRanks = Object.fromEntries(chosenCapabilities.map(name => [name, 1]));
            s.inventory = [...role.inventory];
            Object.entries(role.stats).forEach(([id, value]) => { s.playerStats[id] = value; });
        }
        s.personaSnapshot = selectedPersona ? normalizePersona(JSON.parse(JSON.stringify(selectedPersona))) : null;
        s.setupSnapshot = {
            version: 1,
            createdAt: Date.now(),
            persona: s.personaSnapshot ? JSON.parse(JSON.stringify(s.personaSnapshot)) : null,
            originId: s.originId || '',
            playerIdentity: JSON.parse(JSON.stringify(s.playerIdentity)),
            playerStats: JSON.parse(JSON.stringify(s.playerStats || {})),
            inventory: [...(s.inventory || [])]
        };
        s.setupComplete = true;
        try {
            if (seedLife && isFirstRun && lifeSeedEnabled.checked && !s.lifeSeed?.initialized) {
                saveStatus.textContent = 'Initializing home and social life…';
                lifeSeedStatus.textContent = 'Building a validated household, routine and social graph from your selections…';
                const result = await initializeTimelineLife(world, s, selectedPersona);
                lifeSeedStatus.textContent = result.summary;
            }
            await saveState();
            saveStatus.textContent = 'Saved';
            return true;
        } catch (error) {
            console.error('New Session Setup failed to save:', error);
            saveStatus.textContent = 'Save failed — try again';
            showToast('Story preferences were not saved. Check available browser storage.', 'error');
            return false;
        } finally {
            saving = false;
            skipButton.disabled = false;
            saveButton.disabled = false;
            closeButton.disabled = false;
        }
    };
    const saveAndFinish = async (seedLife = true) => {
        if (await savePreferences(seedLife)) finish();
    };

    // Only the labeled action buttons commit. X and Escape are always safe,
    // reversible dismissal paths and never initialize a life behind the user's back.
    skipButton.onclick = isFirstRun ? () => saveAndFinish(false) : dismiss;
    closeButton.onclick = dismiss;
    saveButton.onclick = () => saveAndFinish(true);
}

/**
 * 📇 NPC Dossier: everything the engine believes about an NPC — status,
 * disposition, goal, activity, and memories (deletable, for pruning bad ones).
 */
function openNpcDossier(npcId) {
    const world = state.worlds.find(w => w.id === state.activeWorldId);
    const sess = getCurrentWorldSession();
    const npc = world ? world.entities.find(e => e.id === npcId) : null;
    const overlay = document.getElementById('npc-dossier-overlay');
    if (!world || !sess || !npc || !overlay) return;

    const entState = sess.entityStates[npc.id] || {};
    const status = entState.status || 'alive';
    const parsedDisposition = Number(entState.disposition);
    const dispo = Math.max(0, Math.min(100, Number.isFinite(parsedDisposition) ? parsedDisposition : 50));
    const dispoColor = dispo < 35 ? 'var(--red)' : (dispo < 65 ? 'var(--warning, #FF8C42)' : 'var(--success)');
    const locName = world.locations.find(l => l.id === entState.location)?.name || 'Unknown';
    const obs = (entState.observations || []).map(o => typeof o === 'string' ? { text: o } : o);
    const goalProgress = livingClamp(entState.goalProgress || 0, 0, 100);
    const goalAutonomy = ['paused', 'low', 'medium', 'high'].includes(entState.goalAutonomy) ? entState.goalAutonomy : 'medium';
    const relationships = Object.entries(sess.npcRelationships || {}).filter(([key]) => key.split('|').includes(npc.id));

    document.getElementById('npc-dossier-title').textContent = `📇 ${npc.name}`;
    const content = document.getElementById('npc-dossier-content');
    content.innerHTML = `
        <div style="display:flex; gap:8px; flex-wrap:wrap; margin-bottom:14px;">
            <span class="mini-tag">${status === 'alive' ? '🟢 alive' : (status === 'dead' ? '☠️ dead' : '🚪 gone')}</span>
            <span class="mini-tag">📍 ${escapeHTML(locName)}</span>
            ${npc.isMajor ? '<span class="mini-tag">⭐ major</span>' : ''}
            ${npc.sessionOrigin ? '<span class="mini-tag" title="Created by the story in this timeline">✨ story-born</span>' : ''}
            ${entState.relationshipToPlayer ? `<span class="mini-tag">🤝 ${escapeHTML(entState.relationshipToPlayer)}</span>` : ''}
            ${npc.role ? `<span class="mini-tag">💼 ${escapeHTML(npc.role)}</span>` : ''}
            ${entState.currentActivity ? `<span class="mini-tag">🕒 ${escapeHTML(entState.currentActivity)}</span>` : ''}
        </div>
        ${npc.description ? `<p style="font-size:0.85rem; color:var(--text-2); margin-bottom:12px;">${escapeHTML(npc.description)}</p>` : ''}
        ${npc.persona ? `<div class="form-section"><label class="form-label">Personality</label><p style="font-size:0.8rem; color:var(--text-2); white-space:pre-wrap;">${escapeHTML(npc.persona)}</p></div>` : ''}
        <div class="form-section">
            <label class="form-label">Disposition Toward You (drag to adjust)</label>
            <div style="display:flex; align-items:center; gap:10px;">
                <input type="range" id="dossier-dispo-slider" min="0" max="100" value="${dispo}" style="flex:1;">
                <span id="dossier-dispo-val" style="font-size:0.8rem; font-family:monospace; min-width:52px; text-align:right; color:${dispoColor};">${dispo}/100</span>
            </div>
        </div>
        <div class="form-section">
            <label class="form-label">Current Goal (editable)</label>
            <input type="text" id="dossier-goal" class="form-input" value="${escapeHTML(entState.goal || '')}" placeholder="What do they want? Leave empty for none — the DM will invent one when relevant.">
            <input type="text" id="dossier-goal-why" class="form-input" style="margin-top:6px;" value="${escapeHTML(entState.goalMotivation || '')}" placeholder="Why they want it (optional)">
            <div style="display:grid; grid-template-columns:1fr 130px; gap:8px; margin-top:8px; align-items:center;">
                <label style="font-size:0.72rem; color:var(--text-3);">Progress <span id="dossier-goal-progress-val">${goalProgress}%</span>
                    <input type="range" id="dossier-goal-progress" min="0" max="100" value="${goalProgress}" style="width:100%;">
                </label>
                <label style="font-size:0.72rem; color:var(--text-3);">Autonomy
                    <select id="dossier-goal-autonomy" class="form-select" style="padding:5px; font-size:0.72rem;">
                        ${['paused', 'low', 'medium', 'high'].map(level => `<option value="${level}" ${goalAutonomy === level ? 'selected' : ''}>${level}</option>`).join('')}
                    </select>
                </label>
            </div>
            ${entState.goal ? `<div style="font-size:0.7rem; color:var(--text-3); margin-top:6px;">Status: ${escapeHTML(entState.goalStatus || 'active')}${entState.goalSteps?.length ? ` · Step ${Math.min((entState.goalStepIndex || 0) + 1, entState.goalSteps.length)}/${entState.goalSteps.length}: ${escapeHTML(entState.goalSteps[entState.goalStepIndex || 0])}` : ''}${entState.goalDeadlineTurn ? ` · Deadline: turn ${entState.goalDeadlineTurn}` : ''}</div>` : ''}
            <button id="dossier-save-goal" class="btn btn-ghost" style="margin-top:8px; font-size:0.75rem;">💾 Save Goal</button>
        </div>
        ${relationships.length ? `<div class="form-section">
            <label class="form-label">Relationships</label>
            <div style="display:flex; flex-direction:column; gap:6px;">
                ${relationships.map(([key, rel]) => {
                    const otherId = key.split('|').find(id => id !== npc.id);
                    const other = world.entities.find(entity => entity.id === otherId);
                    return `<div style="font-size:0.76rem; color:var(--text-2); background:var(--surface2); padding:7px 9px; border-radius:7px;">${escapeHTML(other?.name || otherId || 'Unknown')}: ${escapeHTML(String(rel.score))}${rel.label ? ` (${escapeHTML(rel.label)})` : ''}${rel.reason ? ` — ${escapeHTML(rel.reason)}` : ''}</div>`;
                }).join('')}
            </div>
        </div>` : ''}
        <div class="form-section">
            <label class="form-label">Memories & Observations (${obs.length})</label>
            <div id="dossier-obs-list" style="display:flex; flex-direction:column; gap:6px; max-height:220px; overflow-y:auto;">
                ${obs.length === 0 ? '<div style="color:var(--text-3); font-size:0.75rem; font-style:italic;">Nothing witnessed yet.</div>' : ''}
            </div>
        </div>
    `;

    // Disposition slider: live label, debounced persist
    const slider = content.querySelector('#dossier-dispo-slider');
    const dispoVal = content.querySelector('#dossier-dispo-val');
    let dispoSaveTimer = null;
    slider.oninput = () => {
        const v = parseInt(slider.value);
        dispoVal.textContent = `${v}/100`;
        dispoVal.style.color = v < 35 ? 'var(--red)' : (v < 65 ? 'var(--warning, #FF8C42)' : 'var(--success)');
        clearTimeout(dispoSaveTimer);
        dispoSaveTimer = setTimeout(async () => {
            if (!sess.entityStates[npc.id]) sess.entityStates[npc.id] = { location: sess.playerLocation };
            sess.entityStates[npc.id].disposition = v;
            await saveState();
        }, 400);
    };

    // Goal editing
    const goalProgressInput = content.querySelector('#dossier-goal-progress');
    const goalProgressValue = content.querySelector('#dossier-goal-progress-val');
    goalProgressInput.oninput = () => { goalProgressValue.textContent = `${goalProgressInput.value}%`; };
    content.querySelector('#dossier-save-goal').onclick = async () => {
        if (!sess.entityStates[npc.id]) sess.entityStates[npc.id] = { location: sess.playerLocation };
        const es = sess.entityStates[npc.id];
        const goal = content.querySelector('#dossier-goal').value.trim();
        const why = content.querySelector('#dossier-goal-why').value.trim();
        const goalChanged = goal !== es.goal;
        es.goal = goal.slice(0, 200);
        if (goal) {
            if (why) es.goalMotivation = why.slice(0, 200);
            else delete es.goalMotivation;
            es.goalProgress = livingClamp(parseInt(goalProgressInput.value) || 0, 0, 100);
            es.goalAutonomy = content.querySelector('#dossier-goal-autonomy').value;
            es.goalDifficulty = livingClamp(es.goalDifficulty == null ? 50 : es.goalDifficulty, 0, 100);
            es.goalSteps = Array.isArray(es.goalSteps) ? es.goalSteps : [];
            if (goalChanged || !es.goalStatus) es.goalStatus = es.goalProgress >= 100 ? 'completed' : 'active';
        } else {
            delete es.goalMotivation;
            delete es.goalProgress;
            delete es.goalAutonomy;
            delete es.goalDifficulty;
            delete es.goalSteps;
            delete es.goalStepIndex;
            delete es.goalDeadlineTurn;
            delete es.goalStatus;
        }
        await saveState();
        showToast(goal ? `🎯 Goal set for ${npc.name}` : `Goal cleared for ${npc.name}`, 'success');
    };

    // Observation rows with delete (prune wrong/stale NPC memories)
    const obsList = content.querySelector('#dossier-obs-list');
    obs.forEach((o, idx) => {
        const row = document.createElement('div');
        row.style.cssText = 'display:flex; gap:8px; align-items:flex-start; background:var(--surface2); padding:8px 10px; border-radius:8px; border:1px solid var(--border);';
        row.innerHTML = `
            <div style="flex:1; font-size:0.78rem; color:var(--text-2);">${escapeHTML(o.text || '')}${o.turn ? ` <span style="font-size:0.65rem; color:var(--text-3);">(turn ${escapeHTML(String(o.turn))})</span>` : ''}</div>
            <button class="tool-btn tool-btn-danger" style="font-size:10px; padding:2px 6px;" title="Delete this memory">✕</button>
        `;
        row.querySelector('button').onclick = async () => {
            entState.observations.splice(idx, 1);
            await saveState();
            openNpcDossier(npcId); // re-render
        };
        obsList.appendChild(row);
    });

    document.getElementById('close-npc-dossier-btn').onclick = () => overlay.classList.add('hidden');
    overlay.classList.remove('hidden');
}

function enterWorld(worldId) {
    const world = state.worlds.find(w => w.id === worldId);
    if (!world) return;
    
    state.activeWorldId = worldId;
    
    // Init Instance if not present
    if (!state.worldInstances[worldId]) {
        state.worldInstances[worldId] = {
            sessions: [],
            activeSessionId: null
        };
        // This will trigger migration/init in getCurrentWorldSession()
    }
    
    const sess = getCurrentWorldSession();
    normalizeLivingWorldState(world, sess);
    const entryScheduleSync = syncNPCSchedules(world, sess);
    if (entryScheduleSync.moves > 0) saveState().catch(() => {});
    
    document.getElementById('world-active-name').textContent = 'Living world';
    renderWorldPlayState();
    switchView('worldPlay');
    
    // If history is empty, run New Session Setup then trigger the DM intro.
    if (sess.history.length === 0) {
        openSessionZero(() => executeWorldTurn("init"));
    }
}

function renderWorldPlayState() {
    const world = state.worlds.find(w => w.id === state.activeWorldId);
    const inst = state.worldInstances[state.activeWorldId];
    const sess = getCurrentWorldSession(); // Triggers Healing Pass
    if (!world || !inst || !sess) return;
    const ruleModules = normalizeWorldGameRules(world).modules;
    const questEvaluation = evaluateQuestProgress(world, sess);
    if (questEvaluation.changed) saveState().catch(() => {});

    // Auto-sync start location if history is empty (fixes workshop start location updates not applying)
    if (sess.history.length === 0) {
        const defaultStartId = world.startLocationId || (world.locations[0]?.id || null);
        if (defaultStartId && sess.playerLocation !== defaultStartId) {
            sess.playerLocation = defaultStartId;
        }
    }

    // 1. Core Header
    document.getElementById('world-dm-name').textContent = world.name || 'Untitled World';
    document.getElementById('world-active-name').textContent = 'Living world';
    const worldAvatar = document.getElementById('world-dm-avatar');
    if (worldAvatar) {
        worldAvatar.style.backgroundImage = world.banner ? `url('${cssUrl(world.banner)}')` : '';
        worldAvatar.textContent = world.banner ? '' : '🌐';
        worldAvatar.title = world.banner ? `${world.name || 'World'} artwork` : 'World';
    }
    const modelName = (world.model || state.globalSettings.defaultModel || 'Default').split('/').pop();
    document.getElementById('world-model-name').textContent = 'Model: ' + modelName;

    // Apply the optional presentation layer. Canonical location/session state
    // chooses the visual; the visual can never choose or mutate game state.
    const playView = document.getElementById('world-play-view');
    const presentation = normalizeWorldPresentation(world);
    const requestedPresentation = ['classic', 'cinematic'].includes(sess.presentationMode)
        ? sess.presentationMode : (presentation.enabled ? presentation.mode : 'classic');
    const visualLocation = world.locations.find(location => location.id === sess.playerLocation);
    const locationBackground = worldMediaSource(world, visualLocation?.visuals?.backgroundAssetId);
    const background = requestedPresentation === 'classic' ? world.banner : (locationBackground || world.banner);
    const activePresentation = requestedPresentation !== 'classic';
    const presentationButton = document.getElementById('world-presentation-btn');
    if (presentationButton) {
        presentationButton.style.display = presentation.playerCanOverride ? '' : 'none';
        presentationButton.textContent = requestedPresentation === 'classic' ? '🎨 Classic' : '🎨 Cinematic';
    }
    playView.classList.toggle('world-presentation-active', activePresentation);
    playView.dataset.presentation = requestedPresentation;
    playView.style.setProperty('--world-panel-opacity', String(presentation.panelOpacity / 100));
    playView.style.setProperty('--world-visual-accent', presentation.accent);
    if (activePresentation) playView.style.setProperty('--accent', presentation.accent);
    else playView.style.removeProperty('--accent');
    if (background) {
        const dim = activePresentation ? presentation.backgroundDim / 100 : 0.75;
        playView.style.backgroundImage = `linear-gradient(rgba(10,10,15,${dim}), rgba(10,10,15,${dim})), url('${cssUrl(background)}')`;
        playView.style.backgroundSize = 'cover';
        playView.style.backgroundPosition = visualLocation?.visuals?.backgroundPosition || 'center';
        playView.style.backgroundAttachment = 'local';
    } else {
        playView.style.backgroundImage = 'none';
    }

    // 2. Stats HUD
    const statsContainer = document.getElementById('world-stats-container');
    if (statsContainer) {
        statsContainer.innerHTML = '';
        statsContainer.style.display = (ruleModules.stats || ruleModules.conditions) ? 'flex' : 'none';
        const playerState = normalizePlayerRulesState(world, sess);
        if ((ruleModules.health && playerState.status !== 'active')
            || (ruleModules.conditions && playerState.conditions.length)) {
            const statusCard = document.createElement('div');
            statusCard.className = 'world-card';
            statusCard.style.padding = '8px 12px';
            statusCard.style.borderLeft = `3px solid ${playerState.status === 'dead' ? 'var(--red)' : 'var(--warning, #FF8C42)'}`;
            statusCard.innerHTML = `
                <div style="font-size:0.7rem; color:var(--text-3); text-transform:uppercase; font-weight:700;">Player State</div>
                <div style="font-size:0.85rem; font-weight:800;">${playerState.status === 'dead' ? '☠️ GAME OVER' : playerState.status === 'incapacitated' ? '⚠️ INCAPACITATED' : 'ACTIVE'}${playerState.conditions.length ? ` · ${escapeHTML(playerState.conditions.join(', '))}` : ''}</div>`;
            statsContainer.appendChild(statusCard);
        }
        (ruleModules.stats ? (world.hudConfig?.stats || []) : []).forEach(stat => {
            const baseVal = Number(sess.playerStats[stat.id] !== undefined ? sess.playerStats[stat.id] : stat.value);
            const val = effectiveWorldStatValue(world, sess, stat);
            const equipmentDelta = val - baseVal;
            const hasRange = Number(stat.max) > Number(stat.min);
            const fillPercent = hasRange
                ? livingClamp(((Number(val) - Number(stat.min)) / (Number(stat.max) - Number(stat.min))) * 100, 0, 100)
                : 0;
            const div = document.createElement('div');
            div.className = 'world-card';
            div.style.padding = '8px 12px';
            div.style.background = 'var(--surface2)';
            div.innerHTML = `
                <div style="display:flex; justify-content:space-between; align-items:center;">
                    <div style="font-size:0.75rem; color:var(--text-3); text-transform:uppercase; font-weight:700;">${escapeHTML(stat.name)}</div>
                    <div style="font-size:0.9rem; font-weight:700; color:${cssColor(stat.color)};">${escapeHTML(String(val))}${stat.max > 0 ? ` / ${escapeHTML(String(stat.max))}` : ''}${equipmentDelta ? ` <small title="Equipment bonus">(${equipmentDelta > 0 ? '+' : ''}${escapeHTML(String(equipmentDelta))} gear)</small>` : ''}</div>
                </div>
                ${hasRange ? `<div class="world-stat-track"><span style="width:${fillPercent}%; background:${cssColor(stat.color)};"></span></div>` : ''}`;
            statsContainer.appendChild(div);
        });
    }
    const editStatsButton = document.getElementById('edit-player-stats-btn');
    if (editStatsButton) editStatsButton.style.display = ruleModules.stats ? '' : 'none';
    const rollButton = document.getElementById('world-roll-btn');
    if (rollButton) {
        rollButton.style.display = ruleModules.checks ? '' : 'none';
        const pending = (Array.isArray(sess.pendingChecks) ? sess.pendingChecks[0] : null) || sess.pendingCheck;
        rollButton.textContent = pending ? `🎲 Roll: ${String(pending.label || 'check').slice(0, 24)}` : '🎲 Check';
        rollButton.classList.toggle('pending-check', !!pending);
        rollButton.title = pending
            ? `Resolve ${pending.label} against difficulty ${pending.difficulty}`
            : 'Create a check or roll one requested by the DM';
    }
    const mechanicsButton = document.getElementById('world-mechanics-toggle-btn');
    if (mechanicsButton) {
        const mechanicsEnabled = worldOptionalRpgEnabled(world);
        mechanicsButton.textContent = mechanicsEnabled ? '⚙ Mechanics: On' : '⚙ Mechanics: Off';
        mechanicsButton.classList.toggle('mechanics-off', !mechanicsEnabled);
        mechanicsButton.title = mechanicsEnabled
            ? 'Pause optional stats, checks, inventory and progression. Existing data will be preserved.'
            : 'Restore the last optional RPG configuration for this world.';
    }

    // 3. Location & Exits
    const loc = sessionLocations(world, sess).find(l => l.id === sess.playerLocation); // session-scoped geography
    document.getElementById('world-loc-name').textContent = loc ? loc.name : 'Unknown Realm';
    document.getElementById('world-loc-desc').textContent = loc ? loc.description : 'The surroundings are indistinct.';

    const exitList = document.getElementById('world-exits-list');
    exitList.innerHTML = '';
    if (loc && loc.exits) {
        loc.exits.forEach(exit => {
            const isObj = typeof exit === 'object';
            const exitText = isObj ? (exit.text || "") : exit;
            const oneWay = isObj ? exit.isOneWay : false;

            const btn = document.createElement('button');
            btn.className = 'btn btn-ghost btn-full';
            btn.style.textAlign = 'left'; btn.style.fontSize = '0.8rem';
            btn.textContent = '→ ' + exitText + (oneWay ? ' [One-Way]' : '');
            
            btn.onclick = () => {
                const playerState = normalizePlayerRulesState(world, sess);
                if (playerState.status !== 'active') {
                    showToast(playerState.status === 'dead'
                        ? 'Game Over — this timeline cannot continue.'
                        : 'You are incapacitated and cannot travel until you recover.', 'info');
                    return;
                }
                const targetLoc = resolveWorldExitTarget(world, exit);
                if (!targetLoc) {
                    showToast(`Broken exit: "${exitText}" does not resolve to one unique location.`, 'error');
                    return;
                }
                const movement = movePlayerAlongWorldPath(world, sess, targetLoc);
                if (!movement.ok || !movement.moved) {
                    showToast(movement.reason === 'already_there'
                        ? `You are already at ${targetLoc.name}.`
                        : `${targetLoc.name} is not reachable from here.`, 'info');
                    return;
                }
                rollForScenePopulation(targetLoc.id, false);
                evaluateQuestProgress(world, sess);
                addWorldMessage('system', `You move to ${targetLoc.name}.`);
                saveState().catch(() => {}); // PERSIST IMMEDIATELY
                renderWorldPlayState();
                executeWorldTurn("look");
            };
            const currentPlayerState = normalizePlayerRulesState(world, sess);
            if (!resolveWorldExitTarget(world, exit)) {
                btn.disabled = true;
                btn.title = 'Broken exit reference — repair it in World Studio';
            } else if (currentPlayerState.status !== 'active') {
                btn.disabled = true;
                btn.title = currentPlayerState.status === 'dead' ? 'Timeline ended' : 'Recover before travelling';
            }
            exitList.appendChild(btn);
        });
    }

    // 4. Inventory & Outfit
    const outfitContent = document.getElementById('world-outfit-content');
    if (outfitContent) outfitContent.textContent = sess.outfit || 'Standard attire.';

    // Apply studio HUD toggles that previously saved but never took effect
    const ledgerSection = document.getElementById('hud-section-ledger');
    if (ledgerSection) ledgerSection.style.display = (world.hudConfig?.showLedger !== false) ? 'block' : 'none';

    const invList = document.getElementById('world-inventory-list');
    invList.style.display = (ruleModules.inventory && world.hudConfig?.showInventory !== false) ? 'flex' : 'none';
    invList.innerHTML = '';
    if (!sess.inventory.length) {
        invList.innerHTML = '<div style="color:var(--text-3); font-size:0.8rem;">Empty</div>';
    } else {
        sess.inventory.forEach((item, idx) => {
            const itemName = globalThis.HordeRpgMechanics?.itemName(item) || String(item || 'Item');
            const detail = globalThis.HordeRpgMechanics?.describeModifiers(item) || '';
            const equipped = !!item?.equipped || Object.values(sess.equipment || {}).includes(item?.id);
            const chip = document.createElement('span');
            chip.className = `inv-chip${equipped ? ' equipped' : ''}`;
            chip.innerHTML = `
                <span class="inv-chip-name" title="${escapeHTML(detail || `Examine ${itemName}`)}">${escapeHTML(itemName)}${item?.quantity > 1 ? ` ×${item.quantity}` : ''}</span>
                ${ruleModules.equipment && item?.slot ? `<button class="inv-chip-btn inv-chip-equip" title="${equipped ? 'Unequip' : `Equip in ${escapeHTML(item.slot)}`}">${equipped ? '◆' : '◇'}</button>` : ''}
                <button class="inv-chip-btn" title="Use ${escapeHTML(itemName)}">▶</button>
                <button class="inv-chip-btn inv-chip-drop" title="Drop ${escapeHTML(itemName)}">✕</button>
            `;
            const inputEl = document.getElementById('world-user-input');
            const sendIntent = (text) => {
                if (worldTurnInProgress) return showToast('The DM is still responding — please wait.', 'info');
                inputEl.value = text;
                inputEl.focus();
            };
            chip.querySelector('.inv-chip-name').onclick = () => sendIntent(`I examine the ${itemName}.`);
            chip.querySelectorAll('.inv-chip-btn:not(.inv-chip-drop):not(.inv-chip-equip)').forEach(button => button.onclick = () => sendIntent(`I use the ${itemName}.`));
            chip.querySelector('.inv-chip-equip')?.addEventListener('click', async () => {
                const slot = item.slot;
                if (equipped) { if (sess.equipment?.[slot] === item.id) sess.equipment[slot] = null; item.equipped = false; }
                else {
                    const priorId = sess.equipment?.[slot]; const prior = sess.inventory.find(entry => entry?.id === priorId);
                    if (prior) prior.equipped = false;
                    sess.equipment[slot] = item.id; item.equipped = true;
                }
                await saveState(); renderWorldPlayState();
            });
            chip.querySelector('.inv-chip-drop').onclick = () => {
                showConfirmModal('Drop Item', `Drop "${itemName}" here? It will be removed from your pack.`, async () => {
                    Object.keys(sess.equipment || {}).forEach(slot => { if (sess.equipment[slot] === item?.id) sess.equipment[slot] = null; });
                    sess.inventory.splice(idx, 1);
                    addWorldMessage('system', `You drop the ${itemName}.`);
                    await saveState();
                    renderWorldPlayState();
                });
            };
            invList.appendChild(chip);
        });
    }

    // 5. Cast (NPCs Present)
    const presList = document.getElementById('world-present-list');
    presList.innerHTML = '';
    // Audit: Use fresh session reference to avoid stale UI
    const activeSess = getCurrentWorldSession();
    const presentNPCs = sessionNpcs(world, activeSess).filter(ent =>
        activeSess.entityStates[ent.id]?.location === activeSess.playerLocation && isNpcActive(activeSess.entityStates[ent.id]));

    if (presentNPCs.length) {
        presentNPCs.forEach(npc => {
            const div = document.createElement('div');
            div.className = 'world-present-npc';
            div.style.padding = '8px'; div.style.background = 'var(--surface2)'; div.style.borderRadius = '6px';
            div.style.marginBottom = '4px';
            div.style.fontSize = '0.85rem';
            div.style.borderLeft = '3px solid var(--accent)';
            div.style.cursor = 'pointer';
            div.title = 'Open dossier';
            const portrait = activePresentation ? worldMediaSource(world, npc.visuals?.portraitAssetId) : '';
            if (activePresentation) {
                const initials = String(npc.name || '?').split(/\s+/).map(part => part[0]).join('').slice(0, 2).toUpperCase();
                div.innerHTML = `<span class="world-present-npc-avatar" style="${portrait ? `background-image:url('${cssUrl(portrait)}')` : ''}">${portrait ? '' : escapeHTML(initials)}</span><span>${escapeHTML(npc.name)}</span>`;
            } else {
                div.textContent = npc.name;
            }
            div.onclick = () => openNpcDossier(npc.id);
            div.onmouseenter = () => { div.style.background = 'var(--surface3)'; };
            div.onmouseleave = () => { div.style.background = 'var(--surface2)'; };
            presList.appendChild(div);
        });
    } else {
        presList.innerHTML = '<div style="color:var(--text-3); font-size:0.8rem; padding: 4px;">No one here</div>';
    }

    // Render World Time (Clock Engine)
    if (!sess.turnCount) sess.turnCount = 1;
    const clockDisplay = document.getElementById('world-clock-display');
    const periodDisplay = document.getElementById('world-time-period');
    const clockSection = document.getElementById('hud-section-clock');
    if (clockSection) clockSection.style.display = world.hudConfig?.showClock ? 'block' : 'none';

    if (clockDisplay && world.hudConfig?.showClock) {
        const { days, hours24, mins } = getWorldTimeData(world, sess);
        const ampm = hours24 >= 12 ? 'PM' : 'AM';
        const hours12 = hours24 % 12 || 12;
        
        let timeStr = `${hours12}:${mins.toString().padStart(2, '0')} ${ampm}`;
        if (world.hudConfig?.showDays) {
            timeStr = `${getWorldWeekday(world, days)} • Day ${days} • ` + timeStr;
        }
        clockDisplay.textContent = timeStr;
        
        // Dynamic Period
        let period = 'Daylight';
        if (hours24 >= 20 || hours24 < 6) period = 'Nightfall';
        else if (hours24 >= 18) period = 'Sunset';
        else if (hours24 < 10) period = 'Morning';
        
        periodDisplay.textContent = period;
        periodDisplay.style.color = (period === 'Nightfall') ? '#8B5CF6' : (period === 'Sunset' ? '#F4A261' : 'var(--accent)');
    }

    // Weather display (click to override, Auto to resume the procedural sky)
    const weatherDisplay = document.getElementById('world-weather-display');
    if (weatherDisplay) {
        const cur = getWorldWeather(world, sess);
        weatherDisplay.innerHTML = `${cur.emoji} ${escapeHTML(cur.label)}${sess.weatherOverride ? ' <span style="opacity:0.55; font-size:0.65rem;">(manual)</span>' : ''}`;
        weatherDisplay.onclick = () => {
            weatherDisplay.onclick = null; // don't rebuild while the picker is open
            const sel = document.createElement('select');
            sel.className = 'form-select';
            sel.style.cssText = 'font-size:0.75rem; padding:4px;';
            sel.innerHTML = `<option value="">🔄 Auto (shifts with the hours)</option>` +
                WORLD_WEATHER_TYPES.map(w => `<option value="${w.id}" ${sess.weatherOverride === w.id ? 'selected' : ''}>${w.emoji} ${w.label}</option>`).join('');
            weatherDisplay.innerHTML = '';
            weatherDisplay.appendChild(sel);
            sel.focus();
            sel.onchange = async () => {
                sess.weatherOverride = sel.value || null;
                await saveState();
                renderWorldPlayState();
            };
            sel.onblur = () => renderWorldPlayState();
        };
    }

    // Render Quests
    const questList = document.getElementById('world-quest-list');
    const questCount = document.getElementById('quest-count');
    const questSection = document.getElementById('hud-section-quests'); 
    if (questSection) questSection.style.display = (ruleModules.quests && world.hudConfig?.showQuests) ? 'block' : 'none';
    
    if (questList && ruleModules.quests && world.hudConfig?.showQuests) {
        questList.innerHTML = '';
        normalizeQuestState(world, sess);
        const activeQuests = sess.quests.filter(quest => quest.status === 'active');
        const resolvedQuests = sess.quests.filter(quest => quest.status !== 'active').slice(-5).reverse();
        if (questCount) questCount.textContent = activeQuests.length;
        
        if (activeQuests.length === 0) {
            questList.innerHTML = '<div style="color:var(--text-3); font-size:0.75rem; font-style:italic;">No active quests.</div>';
        }
        activeQuests.forEach(quest => {
            const card = document.createElement('button');
            card.type = 'button';
            card.className = 'world-card quest-card';
            card.style.borderLeft = '3px solid var(--accent)';
            card.onclick = () => openWorldQuestManager(quest.id);

            const titleRow = document.createElement('div');
            titleRow.className = 'quest-card-title-row';
            const title = document.createElement('div');
            title.className = 'quest-card-title';
            title.textContent = quest.title;
            const progress = document.createElement('span');
            progress.className = 'mini-tag';
            const required = quest.objectives.filter(objective => !objective.optional);
            progress.textContent = required.length
                ? `${required.filter(objective => objective.status === 'completed').length}/${required.length}`
                : 'Active';
            titleRow.append(title, progress);
            card.appendChild(titleRow);

            if (quest.description) {
                const description = document.createElement('div');
                description.className = 'quest-card-description';
                description.textContent = quest.description;
                card.appendChild(description);
            }
            if (quest.giver) {
                const giver = document.createElement('div');
                giver.className = 'quest-card-meta';
                giver.textContent = `From ${quest.giver}`;
                card.appendChild(giver);
            }
            if (quest.objectives.length) {
                const list = document.createElement('div');
                list.className = 'quest-objectives';
                quest.objectives.slice(0, 6).forEach(objective => {
                    const row = document.createElement('div');
                    row.className = `quest-objective-row${objective.status === 'completed' ? ' is-complete' : ''}`;
                    const marker = document.createElement('span');
                    marker.textContent = objective.status === 'completed' ? '✓' : objective.status === 'failed' ? '×' : '○';
                    const label = document.createElement('span');
                    label.textContent = objective.text;
                    const count = document.createElement('span');
                    count.textContent = objective.required > 1 ? `${objective.current}/${objective.required}` : '';
                    row.append(marker, label, count);
                    list.appendChild(row);
                });
                card.appendChild(list);
            }
            const rewardSummary = formatQuestRewardSummary(quest);
            if (rewardSummary) {
                const reward = document.createElement('div');
                reward.className = 'quest-reward-line';
                reward.textContent = `Reward: ${rewardSummary}`;
                card.appendChild(reward);
            }
            questList.appendChild(card);
        });
        if (resolvedQuests.length) {
            const historyLabel = document.createElement('div');
            historyLabel.className = 'quest-history-label';
            historyLabel.textContent = 'Recent history';
            questList.appendChild(historyLabel);
            resolvedQuests.forEach(quest => {
                const row = document.createElement('button');
                row.type = 'button';
                row.className = 'quest-history-row';
                row.textContent = `${quest.status === 'completed' ? '✓' : '×'} ${quest.title} · ${quest.status}`;
                row.onclick = () => openWorldQuestManager(quest.id);
                questList.appendChild(row);
            });
        }
    }

    // Secrets Uncovered (auto-hides until the first discovery)
    const secretsSection = document.getElementById('hud-section-secrets');
    const secretsList = document.getElementById('world-secrets-list');
    if (secretsSection && secretsList) {
        const revealed = sess.revealedSecrets || [];
        secretsSection.style.display = revealed.length ? 'block' : 'none';
        const secretCount = document.getElementById('secret-count');
        if (secretCount) secretCount.textContent = revealed.length;
        secretsList.innerHTML = revealed.map(label =>
            `<span class="mini-tag" style="border-color:var(--warning, #F4A261);">🔑 ${escapeHTML(label)}</span>`).join('');
    }

    // Story Threads (open narrative loops the DM registered)
    const threadList = document.getElementById('world-thread-list');
    const threadCount = document.getElementById('thread-count');
    const threadSection = document.getElementById('hud-section-threads');
    if (threadList && threadSection) {
        const openThreads = (sess.threads || []).filter(t => t.status === 'open');
        threadSection.style.display = openThreads.length > 0 ? 'block' : 'none';
        if (threadCount) threadCount.textContent = openThreads.length;
        threadList.innerHTML = '';
        openThreads.forEach(t => {
            const div = document.createElement('div');
            div.className = 'world-card';
            div.style.padding = '8px 12px';
            div.style.fontSize = '0.75rem';
            div.style.borderLeft = '3px solid var(--warning, #FF8C42)';
            div.style.fontStyle = 'italic';
            div.textContent = '🧵 ' + t.text;
            threadList.appendChild(div);
        });
    }

    // Living World: a compact, player-facing window into persistent simulation.
    // Remote information is summarized as developments, not omniscient detail.
    const livingList = document.getElementById('world-living-world-list');
    const livingCount = document.getElementById('living-world-count');
    const livingSection = document.getElementById('hud-section-living-world');
    if (livingSection) livingSection.style.display = ruleModules.livingWorld ? 'block' : 'none';
    if (livingList && ruleModules.livingWorld) {
        normalizeLivingWorldState(world, sess);
        livingList.innerHTML = '';
        const cards = [];
        const worldAudit = sess.lastTurnAudit;
        if (worldAudit) {
            const rejected = worldAudit.rejected?.length || 0;
            cards.push(`${rejected ? '⚠️' : '⚙️'} Immersion Engine v${worldAudit.world_state_version} · ${worldAudit.accepted || 0} committed · ${worldAudit.informational || 0} tracked${rejected ? ` · ${rejected} unsafe proposal${rejected === 1 ? '' : 's'} rejected` : ' · scene reconciled'}`);
        }
        const locState = sess.locationStates[sess.playerLocation];
        if (locState) {
            const controller = sess.factions.find(faction => faction.id === locState.controlFactionId);
            const conditions = (locState.conditions || []).map(condition => condition.label);
            cards.push(`📍 ${conditions.length ? conditions.join(', ') : 'Stable'} · danger ${locState.danger} · prosperity ${locState.prosperity}${controller ? ` · ${controller.name} controls this area` : ''}`);
        }
        const activeSchedules = ruleModules.schedules
            ? sessionNpcs(world, sess).filter(npc => {
                const override = sess.npcScheduleOverrides?.[npc.id];
                return (Array.isArray(override) && override.length > 0)
                    || (world.hudConfig?.enableSchedules && Array.isArray(npc.schedule) && npc.schedule.length > 0);
            })
            : [];
        if (activeSchedules.length) {
            const moves = sess.livingWorldActivity.scheduleMoves || 0;
            cards.push(`🕒 ${activeSchedules.length} character routine${activeSchedules.length === 1 ? '' : 's'} active${moves ? ` · ${moves} schedule move${moves === 1 ? '' : 's'} this turn` : ''}`);
        }
        const activeGoals = sessionNpcs(world, sess).filter(npc => {
            const npcState = sess.entityStates?.[npc.id];
            return npcState?.goal && npcState.goalStatus === 'active' && npcState.goalAutonomy !== 'paused';
        });
        if (activeGoals.length) {
            const progressed = sess.livingWorldActivity.goals || 0;
            cards.push(`🎯 ${activeGoals.length} autonomous agenda${activeGoals.length === 1 ? '' : 's'} active${progressed ? ` · ${progressed} advanced this turn` : ''}`);
        }
        const upcoming = sess.scheduledEvents.filter(event => event.status === 'scheduled')
            .sort((a, b) => (a.dueTurn ?? 999999) - (b.dueTurn ?? 999999))
            .slice(0, 3);
        upcoming.forEach(event => {
            const due = event.dueTurn != null ? `turn ${event.dueTurn}` : 'clock-timed';
            cards.push(`⏳ ${event.title} · ${due}`);
        });
        sess.factions.filter(faction => !['defeated', 'disbanded'].includes(faction.status)).slice(0, 3).forEach(faction => {
            cards.push(`⚑ ${faction.name} · influence ${faction.influence}${faction.goal ? ` · ${faction.goalProgress}% toward its goal` : ''}`);
        });
        const market = ruleModules.commerce ? sess.economy.markets[sess.playerLocation] : null;
        if (market && Object.keys(market).length) {
            cards.push(`🪙 ${Object.values(market).slice(0, 5).map(stock =>
                `${stock.item} ×${stock.quantity} @ ${stock.price} ${sess.economy.currency}`).join(', ')}`);
        }
        sess.worldNews.filter(news => news.playerVisible !== false).slice(-3).reverse()
            .forEach(news => cards.push(`🗞️ ${news.text}`));
        if ((sess.playstyle.turnsObserved || 0) >= 3 && sess.playstyle.dominant.length) {
            cards.push(`🎭 The DM has noticed: ${sess.playstyle.dominant.join(', ')}`);
        }
        const identity = sess.playerIdentity || {};
        if (identity.role) {
            cards.push(`👤 ${identity.title ? `${identity.title} · ` : ''}${identity.role} · ${identity.socialRank || 'unranked'} · ${identity.legalStatus || 'free'}`);
        }
        if (sess.lifeSeed?.initialized) {
            const home = getLocationRef(world, sess.lifeSeed.homeLocationId);
            const household = (sess.lifeSeed.people || []).filter(person =>
                /parent|guardian|spouse|sibling|child|roommate|household|family/i.test(person.relationship));
            cards.push(`🏠 ${home?.name || 'Active home'} · ${household.length ? household.map(person => `${person.name} (${person.relationship})`).join(', ') : `${sess.lifeSeed.people?.length || 0} persistent social connections`}`);
        }
        const localSociety = getLocalSocietySettlement(world, sess);
        if (localSociety) {
            cards.push(`🏘️ ${sess.society.season}, Year ${sess.society.year} · ${localSociety.name}: ${localSociety.growth > 3 ? 'growing' : localSociety.growth < -3 ? 'declining' : 'stable'} · security ${localSociety.security} · unrest ${localSociety.unrest}`);
        }
        const activeWars = (sess.society?.conflicts || []).filter(conflict => conflict.status === 'war');
        if (activeWars.length) cards.push(`⚔️ ${activeWars.length} active conflict${activeWars.length === 1 ? '' : 's'} reshaping the world`);
        const lastActivity = sess.livingWorldActivity;
        const hiddenChanges = (lastActivity.factions || 0) + (lastActivity.markets || 0);
        if (hiddenChanges) {
            cards.push(`🌐 ${hiddenChanges} off-screen world change${hiddenChanges === 1 ? '' : 's'} advanced this turn`);
        }
        if (!cards.length) cards.push('🌐 Simulation active — no persistent developments are currently registered.');
        const visibleCards = cards.slice(0, 10);
        visibleCards.forEach(text => {
            const div = document.createElement('div');
            div.className = 'world-card';
            div.style.padding = '8px 12px';
            div.style.fontSize = '0.75rem';
            div.style.lineHeight = '1.4';
            div.textContent = text;
            livingList.appendChild(div);
        });
        if (livingCount) livingCount.textContent = visibleCards.length;
    }

    const worldInput = document.getElementById('world-user-input');
    const worldSend = document.getElementById('world-send-btn');
    const currentPlayerState = normalizePlayerRulesState(world, sess);
    if (worldInput && worldSend) {
        const ended = currentPlayerState.status === 'dead';
        worldInput.disabled = ended;
        worldSend.disabled = ended;
        worldInput.placeholder = ended
            ? 'Game Over — reroll the fatal turn or start a new timeline.'
            : currentPlayerState.status === 'incapacitated'
                ? 'You are incapacitated. Seek help, surrender, or use something that can restore health...'
                : 'What do you do?...';
    }

    // Update Session Selector
    const sessSelect = document.getElementById('world-session-select');
    if (sessSelect) {
        sessSelect.innerHTML = '';
        inst.sessions.forEach(s => {
            const opt = document.createElement('option');
            opt.value = s.id;
            opt.textContent = s.name;
            opt.selected = s.id === sess.id;
            sessSelect.appendChild(opt);
        });
    }

    // Render World Ledger
    const ledgerContent = document.getElementById('world-ledger-content');
    if (ledgerContent) {
        ledgerContent.textContent = sess.ledger || "No milestones recorded yet.";
    }
    const ledgerStatus = document.getElementById('world-ledger-status');
    if (ledgerStatus) {
        const diagnostic = sess.ledgerDiagnostics || {};
        const sourceLabels = {
            structured: 'structured state',
            tagged: 'DM memory',
            classifier: 'chronicle classifier',
            local: 'local recovery',
            manual: 'manual edit'
        };
        if (diagnostic.status === 'updated') {
            ledgerStatus.textContent = `Last update: turn ${diagnostic.turn || sess.turnCount || 1} · ${sourceLabels[diagnostic.source] || 'automatic'}`;
        } else if (diagnostic.status === 'no_change') {
            ledgerStatus.textContent = `Checked turn ${diagnostic.turn || sess.turnCount || 1} · no lasting canon change detected`;
        } else {
            ledgerStatus.textContent = 'Automatic and manual milestones persist in this timeline.';
        }
    }

    // Render history (Audit: Use appendWorldMessageUI for parity)
    const container = document.getElementById('world-messages-container');
    container.innerHTML = '';
    sess.history.forEach((msg, idx) => {
        appendWorldMessageUI(msg, idx);
    });
    container.scrollTop = container.scrollHeight;

    // Update Context Meter (Audit: Robust & Persistent)
    const historyText = (sess.history || []).map(m => m.text || "").join(' ');
    const worldText = (world.dmPrompt || '') + (world.authorNote || '') + (loc?.description || '')
        + (sess.ledger || '') + getLivingWorldPrompt(world, sess, presentNPCs) + getWorldSocietyPrompt(world, sess);
    const totalChars = historyText.length + worldText.length;
    const estTokens = Math.ceil(totalChars / 3.5);
    
    // Conflation Fix: Prioritize world.contextSize (Studio Config)
    let maxTokens = parseInt(world.contextSize) || 8192;
    if (!world.contextSize && world.maxTokens > 4096) {
        maxTokens = parseInt(world.maxTokens);
    }
    
    const percent = Math.min(100, (estTokens / maxTokens) * 100);
    
    const fill = document.getElementById('world-context-fill');
    const label = document.getElementById('world-context-label');
    if (fill) {
        fill.style.width = `${percent}%`;
        if (percent > 85) fill.style.background = '#E63946';
        else if (percent > 60) fill.style.background = '#FF8C42';
        else fill.style.background = '#00CC66';
    }
    if (label) {
        label.textContent = `${estTokens.toLocaleString()} / ${(maxTokens/1000).toFixed(0)}k`;
        label.style.color = percent > 85 ? '#E63946' : (percent > 60 ? '#FF8C42' : 'var(--text-2)');
    }
}

const WORLD_SPEECH_VERBS = 'says?|asks?|replies?|answers?|murmurs?|whispers?|shouts?|calls?|adds?|continues?|snaps?|laughs?|yells?|grunts?|mutters?|notes?|insists?|warns?|offers?|admits?|tells?|remarks?';

function worldSpeakerAliases(world) {
    const npcs = (world?.entities || []).filter(entity => entity?.type === 'npc' || !entity?.type);
    const firstNameCounts = new Map();
    npcs.forEach(entity => {
        const first = String(entity.name || '').trim().split(/\s+/)[0].toLowerCase();
        if (first) firstNameCounts.set(first, (firstNameCounts.get(first) || 0) + 1);
    });
    const aliases = [];
    npcs.forEach(entity => {
        const full = String(entity.name || '').trim();
        if (!full) return;
        aliases.push({ entity, value: full, specificity: 2 });
        const first = full.split(/\s+/)[0];
        if (first.length >= 2 && firstNameCounts.get(first.toLowerCase()) === 1 && first.toLowerCase() !== full.toLowerCase()) {
            aliases.push({ entity, value: first, specificity: 1 });
        }
    });
    return aliases.sort((a, b) => b.value.length - a.value.length || b.specificity - a.specificity);
}

function maskWorldQuotedText(text) {
    return String(text || '').replace(/“[^”\n]*”|"[^"\n]*"/g, match => ' '.repeat(match.length));
}

function worldNpcMentions(world, text, { ignoreDialogue = false } = {}) {
    const source = ignoreDialogue ? maskWorldQuotedText(text) : String(text || '');
    const mentions = [];
    worldSpeakerAliases(world).forEach(alias => {
        const escaped = alias.value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        for (const match of source.matchAll(new RegExp(`\\b${escaped}(?:'s|’s)?\\b`, 'gi'))) {
            mentions.push({
                entity: alias.entity,
                index: match.index || 0,
                end: (match.index || 0) + match[0].length,
                specificity: alias.specificity
            });
        }
    });
    const deduped = new Map();
    mentions.forEach(mention => {
        const key = `${mention.entity.id}:${mention.index}`;
        const previous = deduped.get(key);
        if (!previous || mention.specificity > previous.specificity) deduped.set(key, mention);
    });
    return [...deduped.values()].sort((a, b) => a.index - b.index || b.specificity - a.specificity);
}

function worldNarrativeFocus(world, prose, current = null) {
    const source = maskWorldQuotedText(prose).trim();
    if (!source) return current;
    const aliases = worldSpeakerAliases(world);
    const clauses = source.split(/(?:[.!?]\s+|\n+|;\s+)/).filter(Boolean);
    for (const clause of clauses) {
        let explicit = null;
        for (const alias of aliases) {
            const escaped = alias.value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            // Prefer a grammatical subject or an explicit speech tag. A name
            // merely mentioned as an object must not steal the next quote.
            const subject = new RegExp(`^\\s*(?:then\\s+|and\\s+|but\\s+)?${escaped}(?:'s|’s)?\\b`, 'i');
            const speech = new RegExp(`\\b${escaped}\\b.{0,48}?\\b(?:${WORLD_SPEECH_VERBS})\\b`, 'i');
            if (subject.test(clause) || speech.test(clause)) {
                explicit = alias.entity;
                break;
            }
        }
        if (explicit) current = explicit;
    }
    if (current) return current;
    const mentions = worldNpcMentions(world, source, { ignoreDialogue: true });
    const unique = [...new Set(mentions.map(mention => mention.entity.id))];
    return unique.length === 1 ? mentions[mentions.length - 1].entity : null;
}

function worldDialogueSpeaker(world, paragraph, quoteStart, quoteEnd, currentFocus = null) {
    if (!world || !paragraph) return null;
    const masked = maskWorldQuotedText(paragraph);
    const before = masked.slice(Math.max(0, quoteStart - 420), quoteStart);
    const after = masked.slice(quoteEnd, Math.min(masked.length, quoteEnd + 220));
    const aliases = worldSpeakerAliases(world);
    for (const alias of aliases) {
        const escaped = alias.value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const afterTag = new RegExp(`^\\s*[,—–-]?\\s*${escaped}\\s+(?:${WORLD_SPEECH_VERBS})\\b`, 'i');
        const beforeTag = new RegExp(`(?:\\b${escaped}\\b\\s*(?:${WORLD_SPEECH_VERBS})?\\s*[,—–:-]?\\s*)$`, 'i');
        if (afterTag.test(after) || beforeTag.test(before)) return alias.entity;
    }
    const focused = worldNarrativeFocus(world, before, currentFocus);
    const pronounTag = /^\s*[,—–-]?\s*(?:he|she|they)\s+(?:says?|asks?|replies?|answers?|murmurs?|whispers?|shouts?|calls?|adds?|continues?|snaps?|laughs?|yells?|grunts?|mutters?|notes?|insists?|warns?|offers?|admits?|remarks?)\b/i.test(after);
    if (pronounTag && focused) return focused;
    const precedingPronounTag = /\b(?:he|she|they)\s+(?:says?|asks?|replies?|answers?|murmurs?|whispers?|shouts?|calls?|adds?|continues?|snaps?|laughs?|yells?|grunts?|mutters?|notes?|insists?|warns?|offers?|admits?|remarks?)[^.!?]{0,100}[.!?]?\s*$/i.test(before);
    if (precedingPronounTag && focused) return focused;
    const nearby = worldNpcMentions(world, `${before.slice(-180)} ${after.slice(0, 120)}`, { ignoreDialogue: true });
    const unique = [...new Set(nearby.map(mention => mention.entity.id))];
    return unique.length === 1 ? nearby[nearby.length - 1].entity : null;
}

function renderWorldDialogueCard(world, speaker, dialogue, className = 'world-npc-dialogue') {
    const portrait = worldMediaSource(world, speaker?.visuals?.portraitAssetId);
    const initials = String(speaker?.name || '?').split(/\s+/).map(part => part[0]).join('').slice(0, 2).toUpperCase();
    const color = cssColor(speaker?.visuals?.dialogueColor || 'var(--accent)');
    return `<div class="${className}" data-speaker-id="${escapeHTML(speaker?.id || '')}" style="--speaker-color:${color}">
        <span class="world-npc-dialogue-avatar" style="${portrait ? `background-image:url('${cssUrl(portrait)}')` : ''}">${portrait ? '' : escapeHTML(initials)}</span>
        <span class="world-npc-dialogue-copy"><strong>${escapeHTML(speaker?.name || 'Unknown')}</strong><span>${parseHordeMarkdown(dialogue)}</span></span>
    </div>`;
}

function renderWorldNarrativeHtml(world, text) {
    const source = String(text || '');
    if (!world || !source) return parseHordeMarkdown(source);
    const paragraphs = source.split(/\n{2,}/);
    const quotePattern = /“([^”\n]+)”|"([^"\n]+)"/g;
    let recognized = 0;
    let carriedSpeaker = null;
    let carryAge = 99;
    const html = paragraphs.map(paragraph => {
        const mentions = worldNpcMentions(world, paragraph, { ignoreDialogue: true });
        const screenplay = /^\s*(?:\*\*)?([^:*\n]{2,60})(?:\*\*)?:\s+([\s\S]+)$/.exec(paragraph);
        if (screenplay) {
            const label = screenplay[1].trim().toLowerCase();
            const matchingAliases = worldSpeakerAliases(world).filter(alias => alias.value.toLowerCase() === label);
            const speaker = matchingAliases.length === 1 ? matchingAliases[0].entity : null;
            if (speaker) {
                carriedSpeaker = speaker;
                carryAge = 0;
                recognized++;
                return renderWorldDialogueCard(world, speaker, screenplay[2]);
            }
        }

        const matches = [...paragraph.matchAll(quotePattern)];
        if (!matches.length) {
            const nextFocus = worldNarrativeFocus(world, paragraph, carriedSpeaker);
            if (nextFocus) {
                carriedSpeaker = nextFocus;
                carryAge = 0;
            } else {
                carryAge++;
                if (carryAge > 2) carriedSpeaker = null;
            }
            return `<div class="world-narrative-prose">${parseHordeMarkdown(paragraph)}</div>`;
        }

        let cursor = 0;
        let paragraphHtml = '';
        matches.forEach(match => {
            const start = match.index || 0;
            const end = start + match[0].length;
            const lead = paragraph.slice(cursor, start);
            const leadFocus = worldNarrativeFocus(world, lead, carriedSpeaker);
            if (leadFocus) carriedSpeaker = leadFocus;
            let speaker = worldDialogueSpeaker(world, paragraph, start, end, carriedSpeaker);
            // Ambiguous dialogue remains ordinary prose. A missing portrait is
            // preferable to confidently putting another person's face/name on
            // the line.
            if (!speaker) return;
            if (lead.trim()) paragraphHtml += `<div class="world-narrative-prose">${parseHordeMarkdown(lead)}</div>`;
            paragraphHtml += renderWorldDialogueCard(world, speaker, match[1] ?? match[2] ?? '');
            cursor = end;
            carriedSpeaker = speaker;
            carryAge = 0;
            recognized++;
        });
        if (!paragraphHtml) {
            const nextFocus = worldNarrativeFocus(world, paragraph, carriedSpeaker);
            if (nextFocus) { carriedSpeaker = nextFocus; carryAge = 0; }
            else carryAge++;
            return `<div class="world-narrative-prose">${parseHordeMarkdown(paragraph)}</div>`;
        }
        const tail = paragraph.slice(cursor);
        if (tail.trim()) {
            paragraphHtml += `<div class="world-narrative-prose">${parseHordeMarkdown(tail)}</div>`;
            const tailFocus = worldNarrativeFocus(world, tail, carriedSpeaker);
            if (tailFocus) carriedSpeaker = tailFocus;
        }
        return paragraphHtml;
    }).join('');
    return recognized ? html : parseHordeMarkdown(source);
}

function renderWorldPlayerMessageHtml(sess, text) {
    const persona = state.personas.find(item => item.id === (sess?.personaId || state.activePersonaId));
    const name = persona?.name || 'You';
    const avatar = persona?.avatar || '';
    const initials = String(name).split(/\s+/).map(part => part[0]).join('').slice(0, 2).toUpperCase() || 'YOU';
    const color = cssColor(persona?.color || '#4A90E2', '#4A90E2');
    return `<div class="world-npc-dialogue world-player-dialogue" style="--speaker-color:${color}">
        <span class="world-npc-dialogue-avatar" style="${avatar ? `background-image:url('${cssUrl(avatar)}')` : ''}">${avatar ? '' : escapeHTML(initials)}</span>
        <span class="world-npc-dialogue-copy"><strong>${escapeHTML(name)}</strong><span>${parseHordeMarkdown(text)}</span></span>
    </div>`;
}

function appendWorldMessageUI(msg, index = null) {
    const container = document.getElementById('world-messages-container');
    const div = document.createElement('div');
    div.className = `msg msg-${msg.role}`;
    
    const versions = msg.versions || [msg.text];
    const currentVersionIdx = msg.currentVersion !== undefined ? msg.currentVersion : (versions.length - 1);
    const displayText = versions[currentVersionIdx] || msg.text;

    // Per-message metadata line (revealed by the 👁️ Metadata toggle)
    const world = state.worlds.find(w => w.id === state.activeWorldId);
    const activeSession = getCurrentWorldSession();
    const presentation = world ? normalizeWorldPresentation(world) : null;
    const presentationMode = ['classic', 'cinematic'].includes(activeSession?.presentationMode)
        ? activeSession.presentationMode
        : (presentation?.enabled ? presentation.mode : 'classic');
    const messageHtml = msg.role === 'dm' && presentationMode !== 'classic'
        ? renderWorldNarrativeHtml(world, displayText)
        : msg.role === 'user' && presentationMode !== 'classic'
            ? renderWorldPlayerMessageHtml(activeSession, displayText)
            : parseHordeMarkdown(displayText);
    const metaParts = [];
    if (msg.location) {
        const locObj = world ? world.locations.find(l => l.id === msg.location) : null;
        metaParts.push(`📍 ${escapeHTML(locObj ? locObj.name : msg.location)}`);
    }
    if (msg.command) metaParts.push(`⚙️ ${escapeHTML(msg.command)}`);
    if (versions.length > 1) metaParts.push(`🔄 take ${currentVersionIdx + 1}/${versions.length}`);
    if (msg.ledgerEntry) metaParts.push(`📜 ${escapeHTML(msg.ledgerEntry)}`);
    // Whether this turn's world state actually landed, and how. Without this a
    // model that narrates changes but never records them fails invisibly.
    if (msg.role === 'dm' && msg.stateSource) {
        metaParts.push(msg.stateSource === 'tool_call' ? '⚙️ canonical turn committed'
            : msg.stateSource === 'inline_rescue' ? '⚙️ tagged turn receipt recovered'
            : msg.stateSource === 'receipt_repair' ? '🩹 missing receipt repaired'
            : msg.stateSource === 'frozen_no_receipt' ? '🧊 unverified state frozen — receipt missing'
            : msg.stateSource === 'engine_intro' ? '⚙️ engine-authored scene committed'
            : msg.stateSource === 'local_intent' ? '🔧 state: applied from your action'
            : msg.stateFallbackArmed
                ? 'state: no persistent change recorded (tool + text failsafe were available)'
                : 'state: no persistent change recorded');
        if (msg.worldAudit) {
            metaParts.push(`🧾 world v${escapeHTML(msg.worldAudit.version)}: ${escapeHTML(msg.worldAudit.accepted)} committed, ${escapeHTML(msg.worldAudit.informational)} tracked, ${escapeHTML(msg.worldAudit.rejected)} rejected`);
            if (!msg.worldAudit.castChecksum) metaParts.push('⚠️ ending cast checksum disagreed with canonical presence');
        }
        if (msg.narrativeAuditWarnings) {
            metaParts.push(`⚠️ ${escapeHTML(msg.narrativeAuditWarnings)} prose/state contradiction${msg.narrativeAuditWarnings === 1 ? '' : 's'} frozen`);
        }
        if (msg.callAudit?.foregroundTotal) {
            const extras = [];
            if (msg.callAudit.providerFallback) extras.push('provider fallback');
            if (msg.callAudit.receiptRepair) extras.push('receipt repair');
            if (msg.callAudit.narrativeFollowUp) extras.push('dice/tool narration');
            if (msg.callAudit.chronicleClassifier) extras.push('chronicle classifier');
            metaParts.push(`🧮 ${escapeHTML(msg.callAudit.foregroundTotal)} foreground model call${msg.callAudit.foregroundTotal === 1 ? '' : 's'}${extras.length ? ` · ${escapeHTML(extras.join(', '))}` : ' · scene kernel'}`);
        }
        if (msg.narratedMove) {
            metaParts.push(`📍 followed the prose to ${escapeHTML(msg.narratedMove)} (no location_id was recorded)`);
        }
        if (msg.missingPlace) {
            metaParts.push(`🗺️ "${escapeHTML(msg.missingPlace)}" is not a location in this world — add it, or have the DM register it with location_introduced`);
        }
        if (msg.narratedPresence?.length) {
            metaParts.push(`👥 pulled into scene from the prose: ${escapeHTML(msg.narratedPresence.join(', '))}`);
        }
        if (msg.narratedOutfit) {
            metaParts.push(`👕 outfit read from the prose: ${escapeHTML(msg.narratedOutfit)} (no outfit_update was recorded)`);
        }
        if (!msg.ledgerEntry) {
            metaParts.push(msg.ledgerStatus === 'classifier_empty'
                ? '📜 chronicle: classifier returned nothing (see console)'
                : '📜 chronicle: judged not a milestone');
        }
    }
    const metaHtml = metaParts.length
        ? `<div class="world-msg-meta">${metaParts.join(' &nbsp;·&nbsp; ')}</div>`
        : '';

    // Version nav restores that take's world-state snapshot — only safe on the
    // LAST entry. Allowing it mid-history rewound stats/NPCs/ledger underneath
    // newer narrative (the "memory is iffy on rerolls" corruption).
    const navSess = getCurrentWorldSession();
    const isLastEntry = navSess && index !== null && index === navSess.history.length - 1;

    // Allow editing/deletion for parity
    div.innerHTML = `
        <div class="msg-bubble">
            <div class="msg-text">${messageHtml}</div>
            ${metaHtml}
            <textarea class="msg-edit-area hidden" style="width:100%; background:var(--surface); color:var(--text); border:1px solid var(--border); border-radius:4px; padding:8px; margin-top:8px; font-family:inherit; font-size:inherit;"></textarea>
            ${msg.role === 'dm' && versions.length > 1 && !isLastEntry ? `
                <div style="font-size:0.65rem; color:var(--text-3); margin-top:6px;" title="Takes can only be switched on the latest response — switching older ones would rewind the world state underneath everything that happened since.">🔒 take ${currentVersionIdx + 1}/${versions.length} (locked — older turn)</div>
            ` : ''}
            ${msg.role === 'dm' && versions.length > 1 && isLastEntry ? `
                <div class="reroll-nav">
                    <div class="reroll-nav-btn prev-ver">←</div>
                    <div class="reroll-count">${currentVersionIdx + 1} / ${versions.length}</div>
                    <div class="reroll-nav-btn next-ver">→</div>
                </div>
            ` : ''}

            <div class="msg-actions" style="display:flex; gap:8px; margin-top:8px; justify-content:flex-end;">
                ${index !== null ? `
                <button class="msg-edit-btn" style="background:none; border:none; color:var(--text-3); font-size:0.7rem; cursor:pointer;">✎ Edit</button>
                <button class="msg-del-btn" style="background:none; border:none; color:var(--text-3); font-size:0.7rem; cursor:pointer;">🗑️ Delete</button>
                ` : ''}
            </div>
        </div>
    `;

    if (index !== null) {
        const editBtn = div.querySelector('.msg-edit-btn');
        const delBtn = div.querySelector('.msg-del-btn');
        const editArea = div.querySelector('.msg-edit-area');
        const textDiv = div.querySelector('.msg-text');
        const sess = getCurrentWorldSession();

        if (msg.role === 'dm' && versions.length > 1 && isLastEntry) {
            div.querySelector('.prev-ver').onclick = async () => {
                msg.currentVersion = Math.max(0, currentVersionIdx - 1);
                msg.text = msg.versions[msg.currentVersion]; // keep canonical for API context
                const ledgerEntry = msg.versionLedgerEntries?.[msg.currentVersion] || null;
                if (ledgerEntry) msg.ledgerEntry = ledgerEntry;
                else delete msg.ledgerEntry;
                const sess = getCurrentWorldSession();
                const world = state.worlds.find(w => w.id === state.activeWorldId);
                const snapshot = msg.versionSnapshots?.[msg.currentVersion];
                if (world && snapshot) restoreWorldTurnState(world, sess, snapshot);
                if (sess) invalidateEpisodicFrom(sess, sess.history.indexOf(msg));
                await saveState();
                renderWorldPlayState();
            };
            div.querySelector('.next-ver').onclick = async () => {
                msg.currentVersion = Math.min(versions.length - 1, currentVersionIdx + 1);
                msg.text = msg.versions[msg.currentVersion]; // keep canonical for API context
                const ledgerEntry = msg.versionLedgerEntries?.[msg.currentVersion] || null;
                if (ledgerEntry) msg.ledgerEntry = ledgerEntry;
                else delete msg.ledgerEntry;
                const sess = getCurrentWorldSession();
                const world = state.worlds.find(w => w.id === state.activeWorldId);
                const snapshot = msg.versionSnapshots?.[msg.currentVersion];
                if (world && snapshot) restoreWorldTurnState(world, sess, snapshot);
                if (sess) invalidateEpisodicFrom(sess, sess.history.indexOf(msg));
                await saveState();
                renderWorldPlayState();
            };
        }

        delBtn.onclick = () => {
            showConfirmModal('Delete Timeline Entry', 'This entry and everything after it will be removed so world state stays consistent. Continue?', async () => {
                const deletedMsg = sess.history[index];
                const world = state.worlds.find(w => w.id === state.activeWorldId);
                const affectedDm = deletedMsg.role === 'dm'
                    ? deletedMsg
                    : sess.history.slice(index).find(entry => entry.role === 'dm' && entry.turnSnapshot);
                if (world && affectedDm?.turnSnapshot) restoreWorldTurnState(world, sess, affectedDm.turnSnapshot);
                invalidateEpisodicFrom(sess, index);
                sess.history.splice(index);
                await saveState();
                renderWorldPlayState();
            });
        };

        let isEditing = false;
        editBtn.onclick = async () => {
            if (!isEditing) {
                isEditing = true;
                textDiv.classList.add('hidden');
                editArea.classList.remove('hidden');
                editArea.value = displayText;
                editBtn.textContent = '💾 Save';
                editArea.focus();
            } else {
                if (msg.versions) {
                    msg.versions[currentVersionIdx] = editArea.value;
                    // Displayed version IS the active version — keep .text canonical
                    if (currentVersionIdx === (msg.currentVersion ?? msg.versions.length - 1)) {
                        msg.text = editArea.value;
                    }
                } else {
                    msg.text = editArea.value;
                }
                const sess = getCurrentWorldSession();
                if (sess) invalidateEpisodicFrom(sess, sess.history.indexOf(msg));
                await saveState();
                renderWorldPlayState();
                isEditing = false;
            }
        };
    }

    container.appendChild(div);
}

function captureWorldTurnState(world, sess) {
    const sessionState = {};
    Object.entries(sess).forEach(([key, value]) => {
        // Epochs must never be captured/restored: they are monotonic guards
        // against late background work committing into a rewound timeline.
        if (!['history', 'id', 'name', '_memEpoch', '_worldEpoch'].includes(key)) sessionState[key] = value;
    });
    // Authored geography and template characters belong to the world, not a
    // single timeline. A reroll must never replace them. Only story-born NPCs
    // are timeline-owned and therefore participate in rollback.
    const dynamicEntities = (world.entities || [])
        .filter(entity => entity?.sessionOrigin === sess.id);
    return safeJsonClone({
        schema: 2,
        session: sessionState,
        world: {
            dynamicEntities
        }
    });
}

function restoreWorldTurnState(world, sess, snapshot) {
    if (!snapshot || !isPlainObject(snapshot) || !isPlainObject(snapshot.session) || !isPlainObject(snapshot.world)) return false;
    const liveManualRevision = Number(sess.ledgerManualRevision) || 0;
    const liveLedgerRevision = Number(sess.ledgerRevision) || 0;
    const snapshotManualRevision = Number(snapshot.session.ledgerManualRevision) || 0;
    const liveManualLedger = String(sess.ledgerManualOverrideText ?? sess.ledger ?? '');
    const liveLedgerDiagnostics = safeJsonClone(sess.ledgerDiagnostics || {});
    const preserved = {
        id: sess.id,
        name: sess.name,
        history: sess.history,
        _memEpoch: sess._memEpoch,
        _worldEpoch: sess._worldEpoch
    };
    Object.keys(sess).forEach(key => {
        if (!['id', 'name', 'history', '_memEpoch', '_worldEpoch'].includes(key)) delete sess[key];
    });
    Object.assign(sess, safeJsonClone(snapshot.session), preserved);
    // A manual ledger save is an explicit source-of-truth correction. Rerolls
    // restore automated state, but must not silently erase a newer correction.
    if (liveManualRevision > snapshotManualRevision) {
        sess.ledger = liveManualLedger;
        sess.ledgerManualRevision = liveManualRevision;
        sess.ledgerManualOverrideText = liveManualLedger;
        sess.ledgerRevision = Math.max(Number(sess.ledgerRevision) || 0, liveLedgerRevision, liveManualRevision);
        sess.ledgerDiagnostics = liveLedgerDiagnostics;
    }
    // Schema 1 snapshots contained the entire shared world. Never restore those
    // arrays: doing so allowed a reroll in one timeline to erase another
    // timeline's NPCs, later Studio edits, or newly authored locations.
    const modernSnapshot = snapshot.schema >= 2 && Array.isArray(snapshot.world.dynamicEntities);
    const snapshotDynamic = modernSnapshot
        ? snapshot.world.dynamicEntities.filter(entity => entity?.sessionOrigin === sess.id)
        : [];
    if (modernSnapshot) {
        world.entities = (world.entities || []).filter(entity => entity?.sessionOrigin !== sess.id);
        world.entities.push(...safeJsonClone(snapshotDynamic));
    }
    bumpMemoryEpoch(sess); // any in-flight consolidation must now abort its commit
    if (typeof bumpWorldEpoch === 'function') bumpWorldEpoch(sess);  // and so must the asynchronous World Agent
    return true;
}

function addWorldMessage(role, text, metadata = {}) {
    const sess = getCurrentWorldSession();
    if (!sess) return;
    
    const msgId = Date.now().toString(36) + Math.random().toString(36).substring(2);

    let targetMsgRef = null;

    // Check if we should append as a version (Reroll)
    if (metadata.isReroll && sess.history.length > 0) {
        const lastMsg = sess.history[sess.history.length - 1];
        if (lastMsg.role === 'dm') {
            lastMsg.versions = lastMsg.versions || [lastMsg.text];
            lastMsg.versions.push(text);
            lastMsg.currentVersion = lastMsg.versions.length - 1;
            // CRITICAL: keep .text canonical — it's what gets sent to the API on
            // later turns. Without this, rerolled-away content bleeds back into context.
            lastMsg.text = text;
            
            // Scrub NPC observations for the previous version
            if (lastMsg.id) {
                const world = state.worlds.find(w => w.id === state.activeWorldId);
                if (world) {
                    world.entities.forEach(ent => {
                        if (ent.type === 'npc' && sess.entityStates[ent.id]) {
                            const entState = sess.entityStates[ent.id];
                            if (entState.observations) {
                                const obsIdx = entState.observations.findIndex(o => o.msgId === lastMsg.id);
                                if (obsIdx !== -1) {
                                    entState.observations[obsIdx].text = text;
                                } else if (metadata.location === entState.location) {
                                    entState.observations.push({ role, text, msgId: lastMsg.id });
                                }
                            } else if (metadata.location === entState.location) {
                                entState.observations = [{ role, text, msgId: lastMsg.id }];
                            }
                            if (entState.observations?.length > 50) entState.observations.splice(0, entState.observations.length - 50);
                        }
                    });
                }
            }
            
            // Chronicle metadata follows the selected reroll take just like its
            // narrative and state snapshot do.
            lastMsg.versionLedgerEntries = Array.isArray(lastMsg.versionLedgerEntries)
                ? lastMsg.versionLedgerEntries
                : lastMsg.versions.slice(0, -1).map((_, i, arr) => i === arr.length - 1 ? (lastMsg.ledgerEntry || null) : null);
            lastMsg.versionLedgerEntries.push(metadata.ledgerEntry || null);
            if (metadata.ledgerEntry) lastMsg.ledgerEntry = metadata.ledgerEntry;
            else delete lastMsg.ledgerEntry;
            if (metadata.turnSnapshot && !lastMsg.turnSnapshot) lastMsg.turnSnapshot = metadata.turnSnapshot;
            if (metadata.postSnapshot) {
                lastMsg.versionSnapshots = Array.isArray(lastMsg.versionSnapshots)
                    ? lastMsg.versionSnapshots
                    : [lastMsg.postSnapshot || null];
                lastMsg.versionSnapshots.push(metadata.postSnapshot);
                lastMsg.postSnapshot = metadata.postSnapshot;
            }
            targetMsgRef = lastMsg;

            // Canon text changed → drop any episodic memory covering this message
            invalidateEpisodicFrom(sess, sess.history.length - 1);

            if (!metadata.deferPersist) {
                saveState().catch(() => {});
                renderWorldPlayState();
            }
        }
    } else {
        const newMsg = { id: msgId, role, text, versions: [text], currentVersion: 0, ...metadata };
        sess.history.push(newMsg);
        targetMsgRef = newMsg;
        
        // NPC Observation Logic: NPCs only "observe" events in their current location
        const world = state.worlds.find(w => w.id === state.activeWorldId);
        if (world) {
            world.entities.forEach(ent => {
                if (ent.type === 'npc') {
                    const entState = sess.entityStates[ent.id];
                    if (entState) {
                        if (metadata.location === entState.location) {
                            entState.observations = entState.observations || [];
                            entState.observations.push({ role, text, msgId });
                            if (entState.observations.length > 50) entState.observations.shift(); // Memory cap
                        }
                    }
                }
            });
        }

        if (!metadata.deferPersist) {
            saveState().catch(() => {});
            renderWorldPlayState();
        }
    }

    // Background, non-blocking asynchronous embedding pre-computation for future world turns
    const embeddingWorld = state.worlds.find(w => w.id === state.activeWorldId);
    const shouldEmbedMessage = !embeddingWorld
        || !normalizeWorldKernelConfig(embeddingWorld).enabled
        || normalizeWorldKernelConfig(embeddingWorld).memoryMode === 'semantic';
    if (targetMsgRef && text && shouldEmbedMessage) {
        const msgText = text;
        const msgRef = targetMsgRef;
        (async () => {
            try {
                const emb = await HordeVectorMemory.getCachedEmbedding(msgText);
                if (emb) {
                    msgRef.embedding = emb;
                    await saveState();
                    console.log(`World Mode: Asynchronously generated/cached embedding for event.`);
                }
            } catch (err) {
                console.warn(`World Mode background embedding failed:`, err);
            }
        })();
    }
    return targetMsgRef;
}

async function getMemoryMatrixContext(world, sess, userInput) {
    if (!sess || !sess.history || sess.history.length < 5) return "";
    
    const currentLocationId = sess.playerLocation;
    const loc = world.locations.find(l => l.id === currentLocationId);
    const npcs = sessionNpcs(world, sess).filter(e =>
        sess.entityStates[e.id]?.location === currentLocationId && isNpcActive(sess.entityStates[e.id]));
    
    // 1. Prepare candidates from history (filter local/global and skip most recent 10 messages)
    const candidateHistory = sess.history
        .slice(0, Math.max(0, sess.history.length - 10))
        .filter(msg => {
            if (!msg || canonicalMsgText(msg).length <= 30) return false;
            const isLocal = msg.location === currentLocationId;
            const isGlobal = msg.location === 'global' || !msg.location;
            return isLocal || isGlobal;
        });

    // Treat ledger lines as candidates if they exist
    const candidateLedger = [];
    if (sess.ledger) {
        sess.ledger.split('\n')
            .filter(l => l.trim().length > 10)
            .forEach((line, idx) => {
                candidateLedger.push({
                    text: line,
                    id: `ledger_${idx}`,
                    isLedger: true
                });
            });
    }

    // Combine all spatial candidates
    const allCandidates = [
        ...candidateHistory.map(h => ({ text: canonicalMsgText(h), embedding: h.embedding, source: 'history' })),
        ...candidateLedger.map(l => ({ text: l.text, source: 'ledger' }))
    ];

    if (allCandidates.length === 0) return "";

    // 2. Perform hybrid search
    const thresh = state.globalSettings.memoryThreshold !== undefined ? state.globalSettings.memoryThreshold : 0.35;
    const topk = state.globalSettings.memoryTopK !== undefined ? state.globalSettings.memoryTopK : 8;
    
    let retrieved = [];
    const kernelMemoryMode = normalizeWorldKernelConfig(world).memoryMode;
    const useSemanticMemory = !normalizeWorldKernelConfig(world).enabled || kernelMemoryMode === 'semantic';
    if (useSemanticMemory && userInput && allCandidates.length > 0) {
        try {
            // Check cache for ledger lines or other missing embeddings to be fast
            for (const cand of allCandidates) {
                if (!cand.embedding) {
                    const key = HordeVectorMemory.hashText(cand.text);
                    if (HordeVectorMemory.cache.has(key)) {
                        cand.embedding = HordeVectorMemory.cache.get(key);
                    }
                }
            }

            retrieved = await HordeVectorMemory.search(allCandidates, userInput, topk, thresh);
        } catch (e) {
            console.warn("World mode hybrid search failed:", e);
        }
    }

    // 3. Fallback to keyword scan if vector search yielded nothing
    if (retrieved.length === 0 && allCandidates.length > 0) {
        console.log("World Mode: Falling back to legacy keyword concept search");
        const concepts = [
            ...(loc ? [loc.name] : []),
            ...npcs.map(n => n.name),
            ...(userInput ? userInput.split(' ').filter(w => w.length > 4) : [])
        ].map(c => c.toLowerCase());

        if (concepts.length > 0) {
            const scored = allCandidates.map(cand => {
                const textLower = cand.text.toLowerCase();
                let matches = 0;
                concepts.forEach(c => {
                    if (textLower.includes(c)) matches++;
                });
                return { block: cand, score: matches };
            }).filter(res => res.score > 0);

            scored.sort((a, b) => b.score - a.score);
            retrieved = scored.slice(0, topk).map(res => res.block);
        }
    }

    // 4. Perform vector search over episodic memories
    let retrievedEpisodic = [];
    if (useSemanticMemory && sess.episodicMemories && sess.episodicMemories.length > 0 && userInput) {
        try {
            retrievedEpisodic = await HordeVectorMemory.search(sess.episodicMemories, userInput, topk, thresh);
        } catch (e) {
            console.warn("World mode episodic search failed:", e);
        }
    }

    let result = "";
    if (retrieved.length > 0) {
        const formattedMemories = retrieved.map(m => {
            if (m.source === 'ledger') {
                return `[WORLD HISTORY]: ${m.text}`;
            } else {
                return `[LOCAL MEMORY]: "...${m.text.substring(0, 150)}..."`;
            }
        });
        result += `\n\n[MEMORY MATRIX: CONTEXTUAL FRAGMENTS]\nThese are relevant historical fragments observed by participants in ${loc ? loc.name : 'this area'}:\n${formattedMemories.join('\n')}`;
    }

    if (retrievedEpisodic.length > 0) {
        const formattedEpisodic = retrievedEpisodic.map(m => `[RECALLED HISTORY]: ${m.text}`);
        result += `\n\n[MEMORY MATRIX: RECALLED CONVERSATION EVENTS]\nThese are highly relevant past developments and actions from your shared history. Retain absolute narrative continuity for these facts:\n${formattedEpisodic.join('\n')}`;
    }

    return result;
}

function getObservationWindow(npcId) {
    const sess = getCurrentWorldSession();
    const entState = sess ? sess.entityStates[npcId] : null;
    if (!entState) return [];
    // Normalize: old sessions may hold raw strings (pre-fix tool handler)
    return (entState.observations || []).map(o => typeof o === 'string' ? { text: o } : o);
}

function extractUserMovementTarget(userInput) {
    const original = String(userInput || '').trim();
    if (!original) return '';
    const text = original.replace(/[*_~]/g, ' ').replace(/\s+/g, ' ').trim();
    // Dialogue between action clauses is not part of the movement grammar.
    // Replace it with a sentence boundary so a later explicit player action
    // (… "wait" I enter the bathroom) can still be examined.
    const actionText = text
        .replace(/[“"][^”"]*[”"]/g, '. ')
        .replace(/\s+/g, ' ')
        .trim();
    // Players narrate movement in past tense as often as present ("I stepped
    // outside", "we went to the docks"), so both forms are locomotion verbs.
    // The trailing \b keeps "stepped" from matching as "step" + garbage.
    // A destination is a short noun phrase. Everything a player writes after it
    // — spoken lines, stage business, a second clause — belongs to the DM, not
    // to the pathfinder. Without this, "I head to the bathroom gently pushing
    // Emily away \"first one out gets dips\"" is taken as one location name.
    const trimTarget = phrase => {
        let value = String(phrase || '').trim();
        const quote = value.search(/["'“”‘’]/);
        if (quote >= 0) value = value.slice(0, quote);           // dialogue starts here
        value = value.split(/\s+(?:while|as|and|then|so|but|because|before|after|with|without|to\s+see|in\s+order)\s+/i)[0];
        value = value.replace(/\s+(?:gently|quietly|slowly|quickly|carefully|softly|firmly|roughly)\b[\s\S]*$/i, '');
        value = value.replace(/\s+\w+ing\s+(?:(?:the|a|an|my|our|your|his|her|their|it|them)\b|[A-Z][a-z]+)[\s\S]*$/, match =>
            // Keep participles that are part of a name ("the Burning Hall"),
            // drop them when they open a new clause ("... pushing Emily away").
            /^\s+(?:burning|sunken|drowned|shattered|standing|winding|whispering|rising|falling)\b/i.test(match) ? match : '');
        return value.trim().split(/\s+/).slice(0, 8).join(' ').replace(/[.,;:!?]+$/, '').trim();
    };
    const resolveMatch = match => {
        const target = trimTarget(match[1] || '');
        const whole = String(match[0] || '');
        const verbRaw = match[0].match(/\b(exit(?:ed)?|leave|left)\b/i)?.[1]?.toLowerCase();
        const verb = verbRaw ? (verbRaw.startsWith('exit') ? 'exit' : 'leave') : '';
        // "out", "outside", "out of the room/the vault/here" are all the same
        // outward intent the resolver understands as 'out'.
        if (/^out(?:side)?(?:\s+of\s+\S.*)?$/i.test(target)) return 'out';
        if (!target && /\b(?:inside|indoors?|in)\s*$/i.test(whole)) return 'inside';
        if (!target && /\bthrough\s+(?:the\s+)?(?:door|doorway|entrance|gate)\s*$/i.test(whole)) return 'inside';
        if (verb && /^(?:the\s+)?(?:room|place|area|building|house|here)?$/i.test(target)) return verb;
        // A person/object pronoun is never a place. Keep scanning: prose often
        // contains a non-destination verb first ("I cross her") followed by
        // the real move ("I enter the bathroom").
        if (/^(?:(?:right|straight)\s+)?(?:past\s+)?(?:him|her|them|you|me|us|it|someone|somebody)$/i.test(target)) return '';
        if (target) return target;
        if (verb) return verb;
        return '';
    };
    const actorMovement = /(?:^|[.!?]\s+)(?:(?:then|so)\s+)?(?:(?:i|we)\s+|let'?s\s+)(?:go|went|walk(?:ed)?|head(?:ed)?|travel(?:l?ed)?|moved?|run|ran|ride|rode|climb(?:ed)?|return(?:ed)?|enter(?:ed)?|exit(?:ed)?|leave|left|step(?:ped)?|cross(?:ed)?|ma[dk]e\s+(?:my|our)\s+way|sleep|slept)\b\s*(?:(?:to|towards?|into|inside|through|across|up|down|for|in)\s+)?([^,.;!?]+)?/ig;
    for (const actorMatch of actionText.matchAll(actorMovement)) {
        const resolved = resolveMatch(actorMatch);
        if (resolved) return resolved;
    }

    // A first-person turn commonly begins with another action before moving:
    // "I yawn and step out", "I open the door, then walk into the hall".
    // The subject remains the player across that coordinated clause. Requiring
    // locomotion to be the first verb made the narration move while canonical
    // state stayed behind. Keep this actor-safe by requiring a coordinator
    // immediately before the movement verb; "I tell Emily to step out" and
    // "I watch as Emily leaves" therefore remain somebody else's movement.
    const continuedActorMovement = /(?:^|[.!?]\s+)(?:(?:then|so)\s+)?(?:i|we)\b[^.!?]{0,100}?(?:,\s*(?:and\s+|then\s+)?|\s+(?:and|then|so|before|after|as|while)\s+)(?:(?:i|we)\s+)?(?:go|went|walk(?:ed)?|head(?:ed)?|travel(?:l?ed)?|moved?|run|ran|ride|rode|climb(?:ed)?|return(?:ed)?|enter(?:ed)?|exit(?:ed)?|leave|left|step(?:ped)?|cross(?:ed)?|ma[dk]e\s+(?:my|our)\s+way)\b\s*(?:(?:to|towards?|into|inside|through|across|up|down|for|in)\s+)?([^,.;!?]+)?/ig;
    for (const continuedMatch of actionText.matchAll(continuedActorMovement)) {
        const resolved = resolveMatch(continuedMatch);
        if (resolved) return resolved;
    }

    // Bare commands are accepted only when the message is not quoted dialogue.
    // `"Go to the tower," I tell Rowan` must move Rowan, not the player.
    if (!/^["'“‘]/.test(original)) {
        const commandMovement = /^(?:(?:then|so)\s+)?(?:go|walk|head|travel|move|run|ride|climb|return|enter|exit|leave|step|cross)\b\s*(?:(?:to|towards?|into|inside|through|across|up|down|for|in)\s+)?([^,.;!?]+)?/i;
        const commandMatch = actionText.match(commandMovement);
        if (commandMatch) {
            const resolved = resolveMatch(commandMatch);
            if (resolved) return resolved;
        }
    }
    return '';
}

function buildWorldMicroFrameEnvelope(world, sess, userInput) {
    const view = typeof worldForSession === 'function' ? worldForSession(world, sess) : world;
    const locations = Array.isArray(view?.locations) ? view.locations : [];
    const current = locations.find(location => location.id === sess.playerLocation);
    const selectedLocations = new Map();
    const addLocation = location => {
        if (location?.id && !selectedLocations.has(location.id) && selectedLocations.size < 16) {
            selectedLocations.set(location.id, location);
        }
    };
    addLocation(current);
    (current?.exits || []).forEach(exit => addLocation(resolveWorldExitTarget(view, exit)));
    addLocation(resolveWorldContainmentParent(view, current));
    locations.forEach(location => {
        if (resolveWorldContainmentParent(view, location)?.id === current?.id) addLocation(location);
    });
    const normalizedInput = normalizeLocationSearchText(userInput);
    locations.forEach(location => {
        const name = normalizeLocationSearchText(location.name);
        if (name && ` ${normalizedInput} `.includes(` ${name} `)) addLocation(location);
    });

    const actors = new Map([['player', { id: 'player', name: 'Player' }]]);
    sessionNpcs(view, sess).filter(npc => sess.entityStates?.[npc.id]?.location === sess.playerLocation)
        .slice(0, 10).forEach(npc => actors.set(npc.id, { id: npc.id, name: npc.name }));
    findReferencedWorldNpcs(view, sess, userInput).slice(0, 6)
        .forEach(npc => actors.set(npc.id, { id: npc.id, name: npc.name }));
    const actorList = [...actors.values()];
    const locationList = [...selectedLocations.values()].map(location => ({
        id: location.id, name: location.name,
        kind: String(location.mapType || '').slice(0, 40)
    }));
    return {
        text: String(userInput || '').slice(0, 1400),
        currentLocationId: String(sess.playerLocation || ''),
        currentOutfit: String(sess.outfit || '').slice(0, 220),
        locations: locationList, actors: actorList,
        allowedActorIds: actorList.map(actor => actor.id),
        allowedTargetIds: actorList.map(actor => actor.id),
        allowedLocationIds: locationList.map(location => location.id)
    };
}

async function requestWorldMicroFrame(world, sess, userInput) {
    if (!userInput || !window.HordeLabs) return null;
    return labsProposal('world_micro_frame', buildWorldMicroFrameEnvelope(world, sess, userInput),
        'worlds', { priority: 135 });
}

function trustedWorldMicroMove(world, sess, userInput, candidate) {
    if (!candidate || candidate.actorId !== 'player' || candidate.intent !== 'move'
        || candidate.phase !== 'completed' || Number(candidate.confidence) < 0.72
        || !candidate.destinationId || !candidate.evidence) return null;
    const view = typeof worldForSession === 'function' ? worldForSession(world, sess) : world;
    const destination = view.locations.find(location => location.id === candidate.destinationId);
    if (!destination || !findWorldTravelPath(view, sess.playerLocation, destination.id)) return null;
    const evidencePhrase = extractUserMovementTarget(candidate.evidence);
    const evidenceTarget = evidencePhrase
        ? resolveWorldMovementTarget(view, sess.playerLocation, evidencePhrase) : null;
    const namedInEvidence = ` ${normalizeLocationSearchText(candidate.evidence)} `
        .includes(` ${normalizeLocationSearchText(destination.name)} `);
    return evidenceTarget?.id === destination.id || namedInEvidence ? destination : null;
}

function applyUserDirectedMovement(world, sess, userInput, microCandidate = null) {
    let targetPhrase = extractUserMovementTarget(userInput);
    const playerState = normalizePlayerRulesState(world, sess);
    if (playerState?.status !== 'active') {
        showToast(playerState.status === 'dead'
            ? 'This timeline has ended. Reroll the fatal turn or begin a new timeline.'
            : 'You are incapacitated and cannot travel until you recover.', 'info');
        return '';
    }
    const view = typeof worldForSession === 'function' ? worldForSession(world, sess) : world;
    let targetLoc = targetPhrase ? resolveWorldMovementTarget(view, sess.playerLocation, targetPhrase) : null;
    const exactDeterministicTarget = targetLoc && [targetLoc.id, targetLoc.name]
        .some(value => normalizeLocationSearchText(value) === normalizeLocationSearchText(targetPhrase));
    const microTarget = trustedWorldMicroMove(world, sess, userInput, microCandidate);
    if (microTarget && (!targetLoc || (!exactDeterministicTarget && microTarget.id !== targetLoc.id))) {
        console.log(`Horde Labs: Micro World Sensor resolved movement to ${microTarget.name}.`);
        targetLoc = microTarget;
        targetPhrase = candidateEvidenceMovementPhrase(microCandidate) || targetPhrase || microTarget.name;
    }
    if (!targetPhrase && !targetLoc) return '';
    if (!targetLoc) {
        const knownButBlocked = findFuzzyLocation(targetPhrase, world.locations);
        if (knownButBlocked) {
            showToast(`${knownButBlocked.name} has no valid route from here.`, 'info');
            return '';
        }
        // A line of roleplay is not a failed command. When the player is clearly
        // writing prose — dialogue, several clauses — the destination may simply
        // be somewhere the world has not registered yet. Say nothing, and let the
        // DM narrate it (and register it) instead of scolding them mid-scene.
        const looksLikeProse = /["'“”‘’]/.test(String(userInput || ''))
            || String(userInput || '').trim().split(/\s+/).length > 12;
        // Remember it either way: if the DM then narrates the scene as happening
        // there, the map has silently fallen behind the fiction and the player
        // deserves to know which place is missing rather than wonder why the
        // header never changed.
        sess.unresolvedDestination = targetPhrase.slice(0, 60);
        if (!looksLikeProse) {
            showToast(`No route from here to "${targetPhrase.slice(0, 60)}".`, 'info');
        } else {
            console.log(`Horde Engine: no registered location matches "${targetPhrase}" — leaving it to the DM.`);
        }
        return '';
    }
    const result = movePlayerAlongWorldPath(world, sess, targetLoc);
    if (!result.ok) {
        showToast(`${targetLoc.name} is not reachable from here.`, 'info');
        return '';
    }
    if (!result.moved) return '';
    console.log(`Horde Engine: User-Initiated Move — ${targetLoc.name}`);
    showToast(`Heading to ${targetLoc.name}...`, 'info');
    rollForScenePopulation(sess.playerLocation, false);
    const routeDescription = (result.travelLegs || []).map(describeWorldTravelLeg).filter(Boolean).join('; ');
    return `\n[SYSTEM: The player has just arrived at ${targetLoc.name}${routeDescription ? ` after travelling via ${routeDescription}` : ''}. ${result.travelMinutes ? `${result.travelMinutes} minutes elapsed.` : ''} Narrate the journey or arrival in a way that respects the transport mode, route, fare and elapsed time. Describe who they see there immediately.]`;
}

function candidateEvidenceMovementPhrase(candidate) {
    return extractUserMovementTarget(candidate?.evidence || '');
}

async function executeWorldTurn(commandOrReroll = null) {
    // Re-entry guard: a world turn mutates sess.history, the clock, and NPC
    // spawns — running two concurrently corrupts state. Block until the
    // in-flight turn finishes.
    if (worldTurnInProgress) {
        showToast('The DM is still responding — please wait.', 'info');
        return;
    }
    worldTurnInProgress = true;
    const worldSendBtn = document.getElementById('world-send-btn');
    if (worldSendBtn) {
        // Turn the send button into a Stop button for the duration of the turn
        worldSendBtn.classList.add('stop');
        worldSendBtn.innerHTML = '⏹';
    }

    let world = null;
    let sess = null;
    let locName = "Unknown";
    let locDesc = "";
    let command = (typeof commandOrReroll === 'string') ? commandOrReroll : null;
    let isReroll = commandOrReroll === true;
    let turnSnapshot = null;
    let historyStartLength = null;
    let submittedInput = '';
    let timeoutId = null;
    let generationTimedOut = false;
    let activeIdleTimeoutMs = 0;
    let restoredRerollSnapshot = false;
    let failureRestoreSnapshot = null;
    let committedMovement = null;
    let committedOutfit = null;
    let turnCallAudit = null;
    let labsWorldFrame = null;

    try {
        world = state.worlds.find(w => w.id === state.activeWorldId);
        sess = getCurrentWorldSession();
        
        if (!world || !sess) {
            throw new Error("World state not initialized. Please ensure a world is selected.");
        }
        normalizeLivingWorldState(world, sess);
        if (sess.pendingChecks?.length && !isReroll && command !== 'init') {
            showToast('Resolve the pending check before taking another action.', 'info');
            return;
        }
        if (!isReroll) bumpWorldEpoch(sess);
        turnCallAudit = {
            main: 0,
            providerFallback: 0,
            receiptRepair: 0,
            narrativeFollowUp: 0,
            chronicleClassifier: 0
        };
        // A failed reroll must restore the currently selected take's live
        // state, not the old turn's pre-action snapshot.
        failureRestoreSnapshot = captureWorldTurnState(world, sess);
        const turnRuleModules = normalizeWorldGameRules(world).modules;
        const playerState = normalizePlayerRulesState(world, sess);
        if (playerState?.status === 'dead' && !isReroll) {
            showToast('Game Over — reroll the fatal turn or begin a new timeline.', 'error');
            return;
        }

        // Authored intro: play it verbatim as the opening narration (no API call)
        const authoredOpening = String(sess.pendingOriginIntro || world.intro || '').trim();
        if (command === "init" && authoredOpening && sess.history.length === 0) {
            normalizeLivingWorldState(world, sess);
            syncNPCSchedules(world, sess);
            // An authored opening is trusted world data, not uncertain model
            // prose. Make explicitly present named NPCs canonical before the
            // no-op receipt snapshots the first scene.
            applyNarratedPresence(world, sess, authoredOpening);
            const introCommit = commitEngineWorldNoOp(world, sess, 'engine_intro', 'Authored world introduction.');
            const introSnapshot = captureWorldTurnState(world, sess);
            const introMsg = addWorldMessage('dm', authoredOpening, {
                location: sess.playerLocation,
                turnSnapshot: introSnapshot,
                stateSource: 'engine_intro',
                worldAudit: {
                    accepted: introCommit.audit.accepted,
                    informational: introCommit.audit.informational,
                    rejected: introCommit.audit.rejected.length,
                    version: introCommit.audit.world_state_version,
                    castChecksum: introCommit.audit.cast_checksum_match
                },
                deferPersist: true
            });
            introMsg.versionSnapshots = [captureWorldTurnState(world, sess)];
            delete introMsg.postSnapshot;
            delete sess.pendingOriginIntro;
            await saveState();
            renderWorldPlayState();
            return;
        }

        let userInput = '';
        let arrivalContext = '';
    console.log(`Horde Engine: Starting Turn — Command: ${command || 'None'}, Reroll: ${isReroll}`);

    if (isReroll) {
        if (sess.history.length === 0) return showToast('No history to reroll', 'info');
        const lastMsg = sess.history[sess.history.length - 1];
        if (lastMsg.role !== 'dm') return showToast('Can only reroll DM responses', 'info');
        if (!lastMsg.turnSnapshot) return showToast('This older response predates safe rerolls. Continue once, then reroll the new response.', 'info');
        restoredRerollSnapshot = !!lastMsg.turnSnapshot;
        turnSnapshot = lastMsg.turnSnapshot || captureWorldTurnState(world, sess);
        restoreWorldTurnState(world, sess, turnSnapshot);
        historyStartLength = sess.history.length;
        
        // Restore command context if present
        if (lastMsg.command) command = lastMsg.command;

        // Find last user input to "replay" it for context logic
        const lastUser = [...sess.history].reverse().find(m => m.role === 'user');
        userInput = lastUser ? lastUser.text : "Continue the adventure.";
        submittedInput = userInput;
    } else {
        userInput = command || document.getElementById('world-user-input').value.trim();
        if (command !== "init" && !userInput) return;
        submittedInput = userInput;

        turnSnapshot = captureWorldTurnState(world, sess);
        historyStartLength = sess.history.length;
        if (!command) document.getElementById('world-user-input').value = '';

        // ⏩ Continue: silent directive — no user bubble, no movement detection
        if (command === "continue") {
            userInput = "Continue the scene naturally from exactly where the narration left off. Do not repeat or summarize previous text.";
        }

        if (command !== "init" && command !== "look" && command !== "continue") {
            labsWorldFrame = await requestWorldMicroFrame(world, sess, userInput);
            const movementOrigin = sess.playerLocation;
            const originWitnesses = sessionNpcs(world, sess)
                .filter(npc => sess.entityStates?.[npc.id]?.location === movementOrigin && isNpcActive(sess.entityStates[npc.id]))
                .map(npc => npc.id);
            arrivalContext = applyUserDirectedMovement(world, sess, userInput, labsWorldFrame?.candidate);
            if (sess.playerLocation !== movementOrigin) {
                committedMovement = {
                    originId: movementOrigin,
                    destinationId: sess.playerLocation
                };
            }
            const outfitResult = applyPlayerOutfitIntent(sess, userInput)
                || (labsWorldFrame?.candidate?.intent === 'outfit'
                    && labsWorldFrame.candidate.phase === 'completed'
                    && Number(labsWorldFrame.candidate.confidence) >= 0.72
                    ? applyPlayerOutfitIntent(sess, labsWorldFrame.candidate.evidence) : null);
            if (outfitResult) committedOutfit = outfitResult;
            addWorldMessage('user', userInput, {
                location: movementOrigin,
                witnesses: originWitnesses,
                arrivalLocation: sess.playerLocation !== movementOrigin ? sess.playerLocation : undefined,
                deferPersist: true
            });
            // sess.turnCount increment moved to success block to prevent time-skip on failure
        }
    }

    if (isReroll && command !== "init" && command !== "look" && command !== "continue") {
        labsWorldFrame = await requestWorldMicroFrame(world, sess, userInput);
        arrivalContext = applyUserDirectedMovement(world, sess, userInput, labsWorldFrame?.candidate);
        applyPlayerOutfitIntent(sess, userInput)
            || (labsWorldFrame?.candidate?.intent === 'outfit'
                && labsWorldFrame.candidate.phase === 'completed'
                && Number(labsWorldFrame.candidate.confidence) >= 0.72
                ? applyPlayerOutfitIntent(sess, labsWorldFrame.candidate.evidence) : null);
    }

    // A turn-based living world advances exactly once per genuine player turn.
    // turnSnapshot was captured before this point, so rerolls restore and replay
    // the same deterministic tick instead of double-advancing the simulation.
    if (command !== "init" && command !== "look" && command !== "continue") {
        if (turnRuleModules.livingWorld) updatePlaystyleProfile(sess, userInput);
        runLivingWorldTick(world, sess);
    }

    const currentLocId = sess.playerLocation;
    syncNPCSchedules(world, sess);
    evaluateQuestProgress(world, sess);

    // --- The Engine Logic ---
    // Robust Lookup: Support both ID and Name for legacy compatibility
        const visibleLocations = sessionLocations(world, sess);
        const loc = visibleLocations.find(l => l.id === sess.playerLocation) || visibleLocations.find(l => l.name === sess.playerLocation);
        const allPresentNPCs = sessionNpcs(world, sess).filter(ent =>
            sess.entityStates[ent.id]?.location === sess.playerLocation && isNpcActive(sess.entityStates[ent.id]));
        const presentNPCs = selectForegroundNpcs(world, sess, allPresentNPCs, userInput, 16);
        // One compact, Micro-capable preflight replaces the old automatic
        // Small-only Event Lens. Rich continuity auditing remains available to
        // stronger local models without spamming Tiny Brain diagnostics.
        const labsWorldLens = labsWorldFrame;

        // KNOWLEDGE GRAPH: stamp the just-submitted player message with who
        // witnessed it. Every message's witness list is the ground truth for
        // "who knows what" — computed free, no AI involved.
        {
            const lastHistMsg = sess.history[sess.history.length - 1];
            if (lastHistMsg && lastHistMsg.role === 'user' && !lastHistMsg.witnesses) {
                lastHistMsg.witnesses = presentNPCs.map(n => n.id);
            }
        }

        locName = loc ? loc.name : "Unknown Location";
        locDesc = loc ? loc.description : "You are lost in the void.";
        if (allPresentNPCs.length > presentNPCs.length) {
            locDesc += ` The location is crowded: ${allPresentNPCs.length - presentNPCs.length} additional background people are present. Treat them as a crowd unless one becomes directly relevant; do not invent full profiles for them.`;
        }
        const currentLocationState = sess.locationStates?.[sess.playerLocation];
        if (turnRuleModules.livingWorld && currentLocationState?.conditions?.length) {
            locDesc += ` Current persistent conditions: ${currentLocationState.conditions.map(condition => condition.label).join(', ')}.`;
        }
        const locHidden = loc?.hiddenDescription ? `\n[DM-ONLY DETAILS (Secret facts/Vibes)]: ${loc.hiddenDescription}` : "";
        const locExits = loc ? (loc.exits || []).map(ex => {
            if (typeof ex === 'string') return ex;
            const target = getLocationRef(world, ex.targetLocationId || getExitTargetName(ex));
            const label = target ? `${getExitDirection(ex) ? `${getExitDirection(ex)} ` : ''}to ${target.name}` : ex.text;
            const routeDetails = [formatWorldTravelMode(ex.mode), ex.routeName || '', ex.travelTime ? `${ex.travelTime}m` : '', ex.cost ? `fare ${ex.cost}` : ''].filter(Boolean);
            return `${label}${routeDetails.length ? ` (${routeDetails.join(' · ')})` : ''}${ex.isOneWay ? ' [One-Way]' : ''}`;
        }).join(', ') : "None";

    const archiveQuery = [userInput, locName, locDesc,
        ...presentNPCs.map(npc => npc.name),
        ...(sess.quests || []).filter(quest => quest.status === 'active').map(quest => quest.title)
    ].join(' ');
    const recalledLedger = retrieveWorldLedgerArchive(sess, archiveQuery);
    const ledgerPrompt = (sess.ledger || recalledLedger)
        ? `\n\n[WORLD LEDGER: PERSISTENT HISTORY]\n${sess.ledger || ''}${recalledLedger ? `\n\n[RECALLED OLDER CANON — relevant to this scene]\n${recalledLedger}` : ''}\nUse this as the source of truth for past events. Older canon not recalled here still exists; do not contradict it.`
        : "";
    // World Lore Injection
    let relevantLore = "";
    if (world.lorebook) {
        const combinedContext = [
            userInput, locName, locDesc,
            ...presentNPCs.map(npc => `${npc.name} ${npc.role || ''}`),
            ...(sess.quests || []).filter(quest => quest.status === 'active').map(quest => `${quest.title} ${quest.description || ''}`),
            ...(sess.engineEvents || []).slice(-8)
        ].join(' ').toLowerCase();
        world.lorebook.forEach(entry => {
            if (!entry.keyword || !entry.text) return;
            const keywords = parseLoreKeywords(entry.keyword);
            if (keywords.some(keyword => loreKeywordMatches(combinedContext, keyword))) {
                relevantLore += `\n[LORE: ${entry.keyword}] ${entry.text}`;
            }
        });
    }

    const gameRules = normalizeWorldGameRules(world);
    const ruleModules = gameRules.modules;

    // Build isolated perspective for present NPCs
    let npcContext = "";
    const dispositionLabel = (score) => {
        if (score < 15) return 'hostile — wants the player gone or hurt';
        if (score < 35) return 'wary/distrustful';
        if (score < 50) return 'cool but civil';
        if (score < 65) return 'neutral';
        if (score < 80) return 'friendly';
        if (score < 92) return 'warm — genuinely cares';
        return 'devoted — deep loyalty or love';
    };
    presentNPCs.forEach(npc => {
        const entState = sess.entityStates[npc.id] || {};
        const obs = getObservationWindow(npc.id);
        const description = npc.description ? `\nPHYSICAL DESCRIPTION: ${npc.description}` : "";
        const depth = WORLD_DIRECTORY_DEPTHS.includes(npc.simulationDepth)
            ? npc.simulationDepth : (npc.isMajor ? 'core' : 'background');
        const personaStr = npc.persona ? `\nPERSONALITY & VOICE: ${npc.persona}` : "";
        const activity = ruleModules.schedules && entState.currentActivity ? `\nCurrently: ${entState.currentActivity}` : "";
        const dispo = entState.disposition !== undefined ? entState.disposition : 50;
        const dispoStr = ruleModules.relationships
            ? `\nDISPOSITION TOWARD PLAYER: ${dispo}/100 (${dispositionLabel(dispo)}) — let this color their tone, openness, and willingness to help.`
            : '';
        const priorRelationship = entState.relationshipToPlayer
            ? `\nESTABLISHED RELATIONSHIP TO PLAYER: ${entState.relationshipToPlayer}. This predates the opening scene; never introduce them as strangers.`
            : '';
        const goalStep = entState.goalSteps?.[entState.goalStepIndex || 0];
        const goalStr = ruleModules.livingWorld && entState.goal
            ? `\nCURRENT GOAL: ${entState.goal}${entState.goalMotivation ? ` (why: ${entState.goalMotivation})` : ''}. Status: ${entState.goalStatus || 'active'}, progress ${entState.goalProgress || 0}%${goalStep ? `, current step: ${goalStep}` : ''}${entState.goalDeadlineTurn ? `, deadline turn ${entState.goalDeadlineTurn}` : ''}. They actively pursue it through dialogue and action.`
            : '';

        // KNOWLEDGE BOUNDARY: recent events this NPC provably did NOT witness
        // (built from per-message witness stamps — the mechanical knowledge graph)
        const unwitnessed = sess.history.slice(-14)
            .filter(m => Array.isArray(m.witnesses) && !m.witnesses.includes(npc.id) && (m.role === 'dm' || m.role === 'user'))
            .slice(-5)
            .map(m => `"${canonicalMsgText(m).replace(/\s+/g, ' ').slice(0, 90)}..."`);
        const wasAsleep = /sleep|slumber|nap|in bed/i.test(entState.currentActivity || '');
        let boundaryStr = '';
        if (unwitnessed.length || wasAsleep) {
            boundaryStr = `\nKNOWLEDGE BOUNDARY — ${npc.name} did NOT witness and does NOT know about:${wasAsleep ? `\n  - anything that happened while they were asleep (they may have been woken by a loud noise — they know the NOISE, not its cause or story)` : ''}${unwitnessed.length ? '\n  - ' + unwitnessed.join('\n  - ') : ''}\n  They can learn these ONLY by being told or shown on-screen. When they enter a scene, they arrive ignorant and curious — asking, not explaining.`;
        }

        const groundedKnowledge = obs.slice(-7).map(o => {
            const source = o.sourceType || o.source || 'unknown';
            const certainty = Math.round(livingClamp(o.confidence == null ? 0.5 : o.confidence, 0, 1) * 100);
            const qualifier = o.contradicted ? 'CONTRADICTED' : `${source}, ${certainty}% confidence`;
            return `${o.text} [${qualifier}]`;
        });
        npcContext += `\n[NPC: ${npc.name}] [SIMULATION: ${depth.toUpperCase()}]${description}${personaStr}${activity}${dispoStr}${priorRelationship}${goalStr}${boundaryStr}\nGrounded knowledge: ${groundedKnowledge.join(' | ') || 'No persistent facts yet.'}\nNever upgrade hearsay, suspicion or belief into witnessed fact without new evidence.\n`;
    });

    // Absence manifest: every named NPC that is NOT in this scene (capped to keep tokens sane)
    const visibleNpcs = sessionNpcs(world, sess);
    const absentNpcManifest = visibleNpcs
        .filter(e => !presentNPCs.includes(e) && isNpcActive(sess.entityStates[e.id]))
        .slice(0, 20)
        .map(e => e.name)
        .join(', ');
    // If the player explicitly mentions an absent character, give the DM that
    // character's actual authored identity and current whereabouts. Previously
    // absent people were reduced to a comma-separated name, so the model often
    // substituted a generic stranger or failed to emit npc_moves.
    const referencedAbsentNpcs = findReferencedWorldNpcs(world, sess, userInput)
        .filter(npc => !presentNPCs.some(present => present.id === npc.id))
        .slice(0, 5);
    const referencedNpcContext = referencedAbsentNpcs.length
        ? `\n[PLAYER-REFERENCED CHARACTERS — NOT CURRENTLY PRESENT]\n${referencedAbsentNpcs.map(npc => {
            const npcState = sess.entityStates[npc.id] || {};
            const where = getLocationRef(world, npcState.location)?.name || 'unknown';
            return `- ${npc.name} [id: "${npc.id}"] — currently at ${where}${npcState.currentActivity ? `, ${npcState.currentActivity}` : ''}. ${String(npc.description || '').slice(0, 220)}${npc.persona ? ` Personality: ${String(npc.persona).slice(0, 180)}` : ''}`;
        }).join('\n')}\nThey remain absent unless the fiction actually brings them here. If one enters, record it with npc_moves using the exact id.`
        : '';
    // Permanence manifest: the dead do not walk back in
    const deadNpcManifest = visibleNpcs
        .filter(e => !isNpcActive(sess.entityStates[e.id]))
        .slice(0, 15)
        .map(e => `${e.name} (${sess.entityStates[e.id].status})`)
        .join(', ');

    // Engine events: schedule/population movements queued since last turn —
    // consumed here so arrivals and departures get narrated, never silent.
    let engineEventsPrompt = "";
    if (sess.engineEvents && sess.engineEvents.length > 0) {
        engineEventsPrompt = `\n[ENGINE EVENTS — WEAVE THESE INTO YOUR NARRATIVE THIS TURN]\n${sess.engineEvents.map(e => `- ${e}`).join('\n')}`;
        sess.engineEvents = [];
    }

    // Open story threads: dangling hooks the DM planted — with age, so long-idle
    // threads get nudged back into the narrative instead of evaporating.
    let threadsPrompt = "";
    const openThreads = (sess.threads || []).filter(t => t.status === 'open');
    if (openThreads.length > 0) {
        const turnNow = sess.turnCount || 1;
        threadsPrompt = `\n[OPEN STORY THREADS — unresolved hooks you planted]\n${openThreads.map(t => {
            const age = turnNow - (t.turnOpened || turnNow);
            return `- ${t.text}${age > 15 ? ' (long dormant — consider weaving it back in soon)' : ''}`;
        }).join('\n')}\nResolve threads through play ('threads_update' status: resolved) — do not let them evaporate.`;
    }
    const livingWorldPrompt = getLivingWorldPrompt(world, sess, presentNPCs);
    const societyPrompt = getWorldSocietyPrompt(world, sess);
    const questPrompt = getQuestPrompt(world, sess);

    const playerRulesState = normalizePlayerRulesState(world, sess);
    const diceConfig = normalizeWorldDiceConfig(world);
    const statContext = (ruleModules.stats ? (world.hudConfig?.stats || []) : []).map(s => {
        const val = effectiveWorldStatValue(world, sess, s);
        return `${s.name} [${s.id}]: ${val}${s.max > 0 ? `/${s.max}` : ''}`;
    }).join(' | ') || 'Disabled';

    const persona = getTimelinePersona(sess);
    let personaContext = persona ? `\n\n[PLAYER PERSONA — AUTHORITATIVE PLAYER IDENTITY]\n${personaPromptText(persona)}` : "";
    const playerIdentity = isPlainObject(sess.playerIdentity) ? sess.playerIdentity : {};
    const worldCapabilities = normalizeWorldCapabilities(world);
    const describeSelectedCapabilities = (names, definitions) => (Array.isArray(names) ? names : []).map(name => {
        const key = String(name || '').toLowerCase();
        const definition = definitions.find(entry => entry.id.toLowerCase() === key || entry.name.toLowerCase() === key);
        return definition ? `${definition.name} [${definition.id}; ${definition.modifier >= 0 ? '+' : ''}${definition.modifier}]` : String(name);
    });
    const capabilityLines = [
        playerIdentity.role ? `Starting role: ${playerIdentity.role}` : '',
        playerIdentity.socialRank ? `Social rank: ${playerIdentity.socialRank}` : '',
        playerIdentity.publicIdentity ? `Public identity: ${playerIdentity.publicIdentity}` : '',
        playerIdentity.reputation ? `Reputation: ${playerIdentity.reputation}` : '',
        playerIdentity.skills?.length ? `World-specific skills: ${describeSelectedCapabilities(playerIdentity.skills, worldCapabilities.skills).join('; ')}` : '',
        playerIdentity.perks?.length ? `Perks: ${describeSelectedCapabilities(playerIdentity.perks, worldCapabilities.perks).join('; ')}` : '',
        playerIdentity.flaws?.length ? `Flaws: ${describeSelectedCapabilities(playerIdentity.flaws, worldCapabilities.flaws).join('; ')}` : '',
        playerIdentity.privileges?.length ? `Privileges: ${playerIdentity.privileges.join('; ')}` : '',
        playerIdentity.obligations?.length ? `Obligations: ${playerIdentity.obligations.join('; ')}` : ''
    ].filter(Boolean);
    if (capabilityLines.length) personaContext += `\n\n[STARTING LIFE & CAPABILITIES — WORLD-SPECIFIC CANON]\n${capabilityLines.join('\n')}\nDo not grant abilities that are absent merely because the player attempts them. Use this world's configured check mode when an uncertain action matters.`;
    const progression = worldCapabilities.progression;
    if (progression.enabled) personaContext += `\nProgression is enabled${progression.method ? `: ${progression.method}` : ''}. Only award improvement through an explicit canonical consequence; never silently inflate capabilities.`;
    if (sess.lifeSeed?.initialized) {
        const seededHome = getLocationRef(world, sess.lifeSeed.homeLocationId);
        personaContext += `\n\n[INITIALIZED ACTIVE LIFE — AUTHORITATIVE STRUCTURED CANON]\nHome: ${seededHome?.name || 'not fixed'}\n${(sess.lifeSeed.people || []).map(person => `- ${person.name}: ${person.relationship}${person.role ? `; ${person.role}` : ''}`).join('\n')}\nThese people and relationships existed before the opening scene. They have their own locations, routines, memories and agency; never replace them with newly invented substitutes.`;
    }
    
    // Relationship Synchronizer: Cross-reference Persona with present NPCs
    if (persona && presentNPCs.length > 0) {
        let relNotes = "";
        const pDesc = personaPromptText(persona).toLowerCase();
        presentNPCs.forEach(npc => {
            const npcName = (npc.name || "").toLowerCase();
            if (npcName && pDesc.includes(npcName)) {
                relNotes += `\n- You have a pre-existing relationship with ${npc.name} described in your persona. Do NOT introduce yourselves as strangers.`;
            }
        });
        if (relNotes) personaContext += `\n\n[URGENT RELATIONSHIP SYNC]:${relNotes}`;
    }

    // --- SHADOW LEDGER: SECRET GATING ---
    let secretContext = "";
    const currentSecrets = [
        ...(loc?.secrets || []),
        ...presentNPCs.flatMap(n => n.secrets || [])
    ];
    
    currentSecrets.forEach(s => {
        const isRevealed = sess.revealedSecrets && sess.revealedSecrets.includes(s.label);
        if (isRevealed) {
            secretContext += `\n[REVEALED TRUTH: ${s.label}] ${s.truth}`;
        } else {
            secretContext += `\n[LOCKED SECRET: ${s.label}] Hint: ${s.hint || 'No hint provided.'}`;
        }
    });

    const locationManifest = buildKernelLocationManifest(world, sess, userInput);
    
    // --- MEMORY MATRIX INJECTION ---
    const memoryContext = await getMemoryMatrixContext(world, sess, userInput);

    // --- KNOWLEDGE BARRIER ---
    const knowledgeBarrier = `
[KNOWLEDGE BARRIER: EPISTEMIC SILOING]
Characters in this world are NOT omniscient. They only know what they have personally witnessed or what has been told to them in their presence. 
- NPCs at "${locName}" do NOT know what happened at other locations unless the player explicitly tells them.
- If the chat history shows events in a different location, treat those as "Out-of-Character" context that the current NPCs are unaware of. 
- Use the [NPC PERSPECTIVE] provided below as the absolute source of truth for an NPC's knowledge.`;

    // --- TIME CALCULATION FOR PROMPT INJECTION ---
    const { days, hours24, mins } = getWorldTimeData(world, sess);
    const ampm = hours24 >= 12 ? 'PM' : 'AM';
    const hours12 = hours24 % 12 || 12;
    const exactTimeStr = `${hours12}:${mins.toString().padStart(2, '0')} ${ampm}`;
    const weekdayName = getWorldWeekday(world, days);

    // Ambient weather: deterministic per world+day (stable within a day,
    // shifts across days) — flavor only, the DM decides how much it matters.
    const weather = getWorldWeather(world, sess).label;

    let period = 'Midday';
    if (hours24 >= 22 || hours24 < 5) period = 'Deep Night';
    else if (hours24 >= 5 && hours24 < 7) period = 'Dawn / Early Morning';
    else if (hours24 >= 7 && hours24 < 12) period = 'Morning';
    else if (hours24 >= 12 && hours24 < 14) period = 'Noon / Midday';
    else if (hours24 >= 14 && hours24 < 17) period = 'Afternoon';
    else if (hours24 >= 17 && hours24 < 19) period = 'Late Afternoon / Sunset';
    else if (hours24 >= 19 && hours24 < 22) period = 'Evening / Nightfall';

    // New Session Setup: the player's stated preferences for this timeline.
    let storyPrefsPrompt = '';
    {
        const prefs = sess.storyPrefs || {};
        const prefLines = [
            prefs.tone && `Tone: ${prefs.tone}`,
            prefs.focus && `Story focus: ${prefs.focus}`,
            prefs.pacing && `Pacing: ${prefs.pacing}`,
            prefs.notes && `Player notes: ${prefs.notes}`
        ].filter(Boolean);
        if (prefLines.length) {
            storyPrefsPrompt = `\n\n[SESSION PREFERENCES]\n${prefLines.join('\n')}\nHonor these throughout: they define what kind of story the player wants. Shape scene selection, tone, and emphasis accordingly.`;
        }
    }
    const canonicalSceneFrame = buildWorldSceneFrame(world, sess);
    const recentCanonicalEvents = (Array.isArray(sess.turnEvents) ? sess.turnEvents : [])
        .slice(-12)
        .map(event => ({
            type: event.type, actor_id: event.actor_id, status: event.status,
            from_location_id: event.from_location_id, to_location_id: event.to_location_id,
            activity: event.activity, item: event.item, turn: event.turn
        }));

    const labsWorldHint = labsWorldLens?.candidate && Number(labsWorldLens.candidate.confidence) >= 0.55
        ? `\n\n[PRIVATE MICRO WORLD SENSOR — VALIDATED CLASSIFICATION, NOT CANON]\n${JSON.stringify(labsWorldLens.candidate)}\nThis can clarify actor, intent, destination, outfit, explicit time and completion scope only. The graph still owns routes and travel time. It cannot create facts, replace commit_world_turn, or override canonical state. If it conflicts with the player's words or canonical frame, ignore it.`
        : '';

    let systemPrompt = `${world.dmPrompt}${personaContext}${storyPrefsPrompt}${knowledgeBarrier}${labsWorldHint}

${HORDE_NARRATIVE_RULES}
${state.globalSettings.immersionMode !== false ? '\n' + HORDE_IMMERSION_DIRECTIVE + '\n' : ''}
[ENGINE MANDATE: SHADOW LEDGER]
You are the DM. You have access to "Hints" about secrets in this scene. 
1. If a secret is [LOCKED SECRET], you only know the hint. You DO NOT know the actual truth.
2. If the player's action (investigating, searching, questioning) suggests they have discovered or are about to discover the secret, you MUST call the 'investigate_secret' tool with the corresponding label.
3. Once the tool returns the [TRUTH], you must incorporate it into your narrative.
4. Do NOT blurt out secrets prematurely. Use the hints to foreshadow them only.

[ENGINE MANDATE: CANONICAL TURN COMMIT]
Every response MUST submit exactly one commit_world_turn receipt, including pure dialogue and no-change turns.
- Dialogue attribution is part of the output contract, not decoration. Put every change of speaker in its own paragraph and identify that speaker by their exact full NPC name before the line (prefer Full Name: “dialogue”). Never introduce a new speaker with only he/she/they, and never leave alternating quoted lines unlabelled. Natural narration may surround those paragraphs.
- Models propose events; the engine commits reality.
- Every action names actor_id. NPC movement NEVER means player movement.
- "walks toward", "tries", "plans", "starts", and hypothetical actions are intended/attempted/in_progress, not completed.
- scene.player_location_id and entity_updates.location_id are checksums only. They cannot move anyone.
- A completed player move requires events[type=movement, actor_id=player] and must match the player's own intent, unless an explicit forced/carried/fall/vehicle event names its cause and responsible actor.
- A completed NPC arrival/departure requires its own movement event.
- Include the complete ending cast in scene.present_character_ids, even when it did not change.
- If the narrative visits a new place, register it with location_introduced in state_updates and use an actor-scoped movement event.
- When the player truly gains or loses a title, rank, allegiance, legal status, privilege, duty or holding, persist it with player_identity_update. Aspirations, disguises and rumors are not identity changes.

[LOCATION MANIFEST — use these exact IDs in commit_world_turn]
${locationManifest}

WORLD LORE:
${relevantLore || "No specific lore triggered."}${ledgerPrompt}
${memoryContext}

CURRENT WORLD STATE:
Location: ${locName} (id: "${sess.playerLocation}")
Canonical Scene Frame (authoritative): ${JSON.stringify(canonicalSceneFrame)}
Recent Committed/Tracked Events: ${recentCanonicalEvents.length ? JSON.stringify(recentCanonicalEvents) : 'None yet'}
Time: ${exactTimeStr} (${period}, ${weekdayName}, Day ${days})
Weather: ${weather} — weave it into descriptions where natural; it may subtly affect NPC moods and outdoor scenes.
Description: ${locDesc}${locHidden}
Exits: ${locExits}
NPCs Present: ${presentNPCs.map(n => n.name).join(', ') || 'None'}
NPCs NOT Present (ABSENT): ${absentNpcManifest || 'None'}${referencedNpcContext}
  ↳ ABSENT characters must NOT appear, speak, or act in this scene. If the story needs one of them here, move them with 'npc_moves' AND narrate their arrival — characters walk in, they do not materialize.${deadNpcManifest ? `
Dead / Departed (PERMANENT — they can NEVER appear again): ${deadNpcManifest}
  ↳ The dead stay dead. They may be mourned, mentioned, or found as remains — never walking, talking, or acting. Only an explicit resurrection story event (with 'npc_status_changes' setting them alive) can undo this.` : ''}
Inventory: ${ruleModules.inventory ? (sess.inventory.map(item => globalThis.HordeRpgMechanics?.itemName(item) || String(item || '')).filter(Boolean).join(', ') || 'None') : 'Disabled for this world'}
Equipped: ${ruleModules.equipment ? Object.entries(sess.equipment || {}).filter(([, itemId]) => itemId).map(([slot, itemId]) => `${slot}: ${globalThis.HordeRpgMechanics?.itemName((sess.inventory || []).find(item => item?.id === itemId)) || 'unknown item'}`).join(', ') || 'None' : 'Disabled for this world'}
Player Stats: ${statContext}
Player Condition: ${ruleModules.health || ruleModules.conditions
        ? `${playerRulesState.status}${playerRulesState.conditions.length ? ` — ${playerRulesState.conditions.join(', ')}` : ''}`
        : 'Disabled for this world'}
Rules Profile: ${gameRules.profileId}. Enabled modules: ${WORLD_RULE_MODULE_KEYS.filter(key => ruleModules[key]).join(', ') || 'none'}. Disabled modules: ${WORLD_RULE_MODULE_KEYS.filter(key => !ruleModules[key]).join(', ') || 'none'}.
Special rules: vital stat "${ruleModules.health ? (gameRules.vitalStatId || 'none') : 'disabled'}"; zero-health mode "${ruleModules.health ? gameRules.zeroHpMode : 'disabled'}"; currency stat "${ruleModules.commerce ? (gameRules.currencyStatId || 'none') : 'disabled'}" (${gameRules.currencyName}).
Check Engine: ${ruleModules.checks ? `d${diceConfig.sides}, ${diceConfig.resolution} resolution, ${diceConfig.visibility} visibility, default difficulty ${diceConfig.defaultDifficulty}, stat modifier ${diceConfig.modifierMode}. Submit at most ONE check and put every result-dependent persistent mutation inside its on_success/on_failure object; completed top-level consequences beside a check are rejected. ${diceConfig.resolution === 'player' ? 'End at the moment of uncertainty. The player must resolve the queued check before any other action; the next response receives the canonical result.' : 'The engine resolves it immediately; never invent a roll.'}${diceConfig.visibility === 'hidden' ? ' Keep the die, target and modifier out of narration; reveal only fictional consequences.' : ''}` : 'Disabled — resolve through fiction without dice.'}
Player Outfit: ${sess.outfit || 'Standard attire'}
${questPrompt}${npcContext}${engineEventsPrompt}${threadsPrompt}${livingWorldPrompt}${societyPrompt}`;
    
    if (command === "look") {
        systemPrompt += "\n\n[IMMEDIATE TASK]\nThe player has just arrived at the location listed in 'CURRENT WORLD STATE'. \n1. DESCRIBE the transition and the new surroundings in detail.\n2. The player is already there: assert the current ID in commit_world_turn but emit no new player movement event.\n3. Focus entirely on narrative and atmosphere.";
        userInput = "Describe what I see.";
    } else if (command === "init") {
        systemPrompt += "\n\nThis is the beginning of the journey. Introduce the world and the current scene.";
        userInput = "Begin the adventure.";
    }
    
    // --- Preset Modular Logic ---
    const allPresets = getAllPresets();
    const preset = allPresets.find(p => p.id === world.activePresetId);
    let injectedHistory = [];
    let directorNotesRequired = false;

    if (preset && preset.data && preset.data.prompts) {
        const overrides = (!world.presetOverridesFor || world.presetOverridesFor === preset.id)
            ? (world.presetOverrides || {})
            : {};
        const worldMacroContext = {
            ...world,
            scenario: world.description || '',
            personality: world.dmPrompt || '',
            desc: world.description || ''
        };
        getOrderedPresetPrompts(preset, false, true).forEach((p) => {
            const idx = preset.data.prompts.indexOf(p);
            const override = overrides[idx] || {};
            if (!isPresetPromptEnabled(preset, p, override)) return;

            const promptContent = override.prompt !== undefined ? override.prompt : (p.content || p.prompt || '');
            if (!promptContent.trim()) return;
            const resolvedContent = replaceMacros(promptContent, worldMacroContext);
            if (/<plot_tracking_module\b|<summary>\s*Plot Momentum\s*<\/summary>|Append_Hidden_Block/i.test(resolvedContent)) {
                directorNotesRequired = true;
            }

            // injection_position 1 = in-chat at depth; 0/undefined = system prompt.
            // (Previously only 0 and a bogus "4" matched — most preset prompts were dropped.)
            if (p.injection_position === 1) {
                injectedHistory.push({ role: p.role || 'system', content: resolvedContent, depth: p.injection_depth || 0 });
            } else {
                systemPrompt += '\n\n' + resolvedContent;
            }
        });
    }

    // Author's Note Injection
    if (world.authorNote) {
        systemPrompt += `\n\n[AUTHOR'S NOTE: ${world.authorNote}]`;
    }

    // Freaky Frankenstein's tracking block is meant to carry its chosen path
    // into the next turn. Preserve that one small block even when the enormous
    // preset leaves no room for ordinary chat history.
    if (directorNotesRequired) {
        const previousDirectorNotes = [...(sess.history || [])]
            .reverse()
            .filter(message => message.role === 'dm')
            .map(message => extractDirectorNotes(canonicalMsgText(message)))
            .find(Boolean);
        if (previousDirectorNotes) {
            systemPrompt += `\n\n[PREVIOUS DIRECTOR PLAN — execute this continuity before drafting the next beat]\n${previousDirectorNotes}`;
        }
    }

    // Show persistent typing indicator
    const dmTyping = document.getElementById('world-dm-typing');
    const dmTypingLabel = document.getElementById('world-dm-typing-label');
    if (dmTyping) { dmTypingLabel.textContent = 'DM is writing...'; dmTyping.style.display = 'flex'; }

    showToast('DM is thinking...', 'info');
    
        // --- History Truncation (Safety Audit: More Conservative) ---
        const CONTEXT_LIMIT = parseInt(world.contextSize) || 8192;
        const GEN_LIMIT = parseInt(world.maxTokens) || 2048;
        
        // Scale buffer with context size (0.5% or 1000, whichever is larger at scale)
        const SAFETY_BUFFER = Math.max(1000, Math.ceil(CONTEXT_LIMIT * 0.01)); 
        
        // Use a more conservative divider (3.2 instead of 3.5) to account for diverse tokenizers
        const TOKEN_DIVIDER = 3.2; 

        let systemTokens = Math.ceil(systemPrompt.length / TOKEN_DIVIDER);
        let injectedTokens = 0;
        injectedHistory.forEach(inj => injectedTokens += Math.ceil(inj.content.length / TOKEN_DIVIDER));
        
        let availableTokens = CONTEXT_LIMIT - systemTokens - injectedTokens - GEN_LIMIT - SAFETY_BUFFER;
        if (preset && availableTokens <= 0) {
            const recommendedContext = Math.ceil((systemTokens + injectedTokens + GEN_LIMIT + SAFETY_BUFFER + 2048) / 1024) * 1024;
            const warningKey = `${world.id}:${preset.id}:${CONTEXT_LIMIT}:${recommendedContext}`;
            if (lastPresetContextWarningKey !== warningKey) {
                lastPresetContextWarningKey = warningKey;
                showToast(`Preset context is too small (${CONTEXT_LIMIT} tokens). Raise World Context Size to at least ${recommendedContext}.`, 'warning');
            }
            console.warn(`Horde Engine: preset "${preset.name}" plus engine instructions exceed the configured context (${CONTEXT_LIMIT}); recommended minimum ${recommendedContext}.`);
        }
        
        let historyToSend = [];
        const startIdx = isReroll ? sess.history.length - 2 : sess.history.length - 1;
        for (let i = startIdx; i >= 0; i--) {
            const m = sess.history[i];
            // Version-aware read: never send a rerolled-away take to the API
            const canonText = canonicalMsgText(m);
            if (!canonText) continue;

            const isDistant = m.location && m.location !== sess.playerLocation;

            let content = canonText;
            if (isDistant) {
                const msgLoc = world.locations.find(l => l.id === m.location);
                const locLabel = msgLoc ? `[Loc: ${msgLoc.name}] ` : '';
                content = `[DISTANT EVENT (HIDDEN FROM PRESENT NPCs)]: ${locLabel}${content}`;
            }

            const tokens = Math.ceil(content.length / TOKEN_DIVIDER);
            if (availableTokens - tokens > 0) {
                const role = m.role === 'dm' ? 'assistant' : 'user';
                // Prevent consecutive identical roles
                if (historyToSend.length > 0 && historyToSend[0].role === role) {
                    historyToSend[0].content = content + "\n\n" + historyToSend[0].content;
                } else {
                    historyToSend.unshift({ role: role, content: content });
                }
                availableTokens -= tokens;
            } else {
                break;
            }
        }

        const modularMandate = [
            ruleModules.relationships
                ? "8. Living Relationships: Persist meaningful earned shifts as completed relationship events with actor_id, target_id, change and cause."
                : '8. Relationship scoring is DISABLED. Portray relationships naturally in prose and memory; do not invent numeric disposition or relationship updates.',
            ruleModules.livingWorld
                ? "9. Living World: NPC agendas, future developments, location conditions, factions, scarcity, and playstyle adaptation persist and may advance off-screen. Use their matching update fields whenever durable state changes."
                : '9. Off-screen simulation is DISABLED. Do not create autonomous goals, future events, faction simulation, market regeneration, or invisible world-state changes.',
            ruleModules.schedules
                ? "9a. NPC Schedules: Persist altered routines with 'schedule_updates'; characters follow their timetable unless the narrative pins them elsewhere."
                : '9a. NPC schedules are DISABLED. Move characters only when the on-screen narrative requires it.',
            ruleModules.quests
                ? "10b. QUESTS: When the player knowingly accepts an objective, use 'quests_update' with exact existing IDs, structured objectives, and promised rewards. The engine detects completion and grants rewards once."
                : '10b. The quest engine is DISABLED. Offer organic situations and personal aims without creating quest records, objectives, completion notices, or mechanical rewards.',
            ruleModules.inventory
                ? "12. Inventory is authoritative. Use completed inventory events with actor_id='player', action and item whenever an item is gained, consumed, given away, lost, dropped or destroyed."
                : '12. Inventory tracking is DISABLED. Objects may exist in the prose, but do not create or remove inventory records.',
            ruleModules.stats
                ? "12a. Player stats are authoritative. Apply every mechanical stat change with 'stat_changes'; never change a number only in prose."
                : '12a. Player stats are DISABLED. Resolve scenes through prose and enabled systems without inventing stat changes.',
            ruleModules.health
                ? "12b. Health & Defeat: Telegraph danger. Apply damage/healing with 'stat_changes' and 'stat_change_cause'. At zero health obey player_state: incapacitated fails forward; dead ends this timeline."
                : '12b. Health and defeat rules are DISABLED. Do not assign HP damage, incapacitation, death-as-game-over, or injury merely because an action fails.',
            ruleModules.conditions
                ? "12c. Conditions: Persist lasting injuries or statuses as completed condition events for the correct actor; remove them only when recovery is established."
                : '12c. Mechanical player conditions are DISABLED. Describe temporary feelings or discomfort in prose only.',
            ruleModules.commerce
                ? "12d. Commerce: Resolve every purchase or sale with 'transactions'. Never duplicate it through inventory, stats, or economy updates; rejected deals change nothing."
                : '12d. Mechanical commerce is DISABLED. Do not deduct currency, transfer shop inventory, or invent affordability checks.',
            ruleModules.checks
                ? "12e. Checks: For uncertain actions with meaningful failure, call 'checks' first with a fair difficulty and declared failure cost. The returned roll is binding and may resolve only once per turn."
                : '12e. Dice checks are DISABLED. Resolve uncertainty through fiction, established facts, and player choices; do not invent d20 rolls or DCs.'
        ].join('\n');

        const finalMandate = `\n\n[FINAL MANDATE]\n1. Stay in character as the DM. No OOC meta-talk.\n2. Current Environment: ${locName}. Exits: ${locExits}.\n3. NPC Integrity: honor each NPC's KNOWLEDGE BOUNDARY strictly. An NPC knows ONLY their listed observations and events they witnessed. Someone who just arrived or just woke perceived at most the trigger (a sound, a smell, a scream) — NEVER its cause, backstory, or details from scenes they missed. They enter asking questions, not reciting answers. Information moves between characters on-screen only.\n4. Turn Commit: Every response MUST emit one real commit_world_turn tool call. Even when nothing changes, submit the ending scene checksum with empty events and entity updates for the on-screen cast. Never print the receipt as ordinary prose.\n4a. Actor Integrity: Every durable action names its actor. NPC motion updates only that NPC. Never use a mentioned destination, another character's movement, or a scene-opening sentence to move the player.\n4b. Presence Is State: Record completed arrivals and departures as actor-scoped movement events and give the complete ending cast in scene.present_character_ids. Directional intention is not arrival.\n4c. Appearance Is State: Record dressing, stripping, equipment and lasting garment condition as outfit events for the correct actor. entity_updates reports what each on-screen person is wearing now.\n4d. Reality Levels: intended, attempted, in_progress and completed are different. Only completed events mutate reality. Dialogue, rumor, belief, plans and hypotheticals are not physical facts.\n4e. Movement Integrity: Known destinations require a valid route. New destinations must be introduced and connected first. Forced player movement must state its mode, cause and responsible actor.\n5. Narrative Requirement: ALWAYS include descriptive prose explaining what is happening. The receipt records the same reality as the prose.\n6. Chronological Integrity: Time is exactly ${exactTimeStr} (${period}). Do NOT describe lighting, meals, or events that contradict this exact time.\n7. Time Passage: Record meaningful elapsed time as a completed time event and in state_updates.time_skip_minutes when applicable.
${modularMandate}
10. Permanence & Threads: When an NPC dies or leaves the world permanently, call 'npc_status_changes' — death is real and permanent. When the story plants a hook (an unopened letter, an unanswered question, a promise), register it with 'threads_update' and pay it off later; never let a planted hook silently evaporate.
10a. CHRONICLE: Whenever canon changes, include one concise factual sentence in state_updates.ledger_update. Pure description, repetition, and small talk need no ledger entry. Never log plans as completed facts.
10aa. LEDGER FIDELITY: Facts in WORLD LEDGER: PERSISTENT HISTORY are established canon and override improvisation or conflicting older prose. Check them before writing; never contradict, undo, or forget them unless the current turn explicitly changes that fact.
11. Player Sovereignty: NEVER write the player's actions, dialogue, thoughts, or decisions. Describe the world's response to what they did, then stop at the moment of choice. If a beat needs the player's reaction, end your response and wait for it.
13. Hooks over Summaries: End most responses on something to react to — a question asked, a sound from the next room, a hand on a weapon — not a tidy summary of what just happened.
14. If the player supplies a die result while checks are enabled, adjudicate that existing roll rather than rolling again.${directorNotesRequired ? `
15. DIRECTOR MODE (ACTIVE PRESET — REQUIRED): Follow the active plot-tracking module and append exactly one <details><summary>Plot Momentum</summary>...</details> block after the narrative and any [MEMORY] line. It must be the final element of every response. Do not omit it when tools are used.` : ''}`;
        
        // Splice in-chat preset injections at their configured depth + role
        // (depth = messages from the end) rather than dumping them all up front.
        injectedHistory.forEach(inj => {
            const idx = Math.max(0, historyToSend.length - (inj.depth || 0));
            historyToSend.splice(idx, 0, { role: inj.role || 'system', content: inj.content });
        });

        const messages = [
            { role: 'system', content: systemPrompt + finalMandate },
            ...historyToSend
        ];

        // Stealth Injection: If there's an arrival context, append it to the last user message for the API only
        if (arrivalContext && messages.length > 0) {
            const lastMsg = messages[messages.length - 1];
            if (lastMsg.role === 'user') {
                lastMsg.content += "\n" + arrivalContext;
            } else {
                messages.push({ role: 'user', content: arrivalContext });
            }
        }

        // If it's a special command (look/init/continue) that wasn't added to history, append it now
        if (command === "init" || command === "look" || command === "continue") {
            const mandate = command === "init" ? "Introduce the world and current scene."
                : command === "continue" ? "Continue the scene naturally from exactly where the narration left off. Do not repeat or summarize previous text."
                : `Describe the transition to ${locName} and the new surroundings. Focus on atmosphere and sensory details.`;
            messages.push({ role: 'user', content: `[MANDATE: Respond with rich narrative prose only. No OOC talk.]\n\n${mandate}` });
        }

        // Reroll Anti-Cache & Variance Directive
        if (isReroll) {
            messages.push({ role: 'user', content: `[SYSTEM: Reroll requested. Generate a completely different narrative response. Change the prose, actions, and structural approach from the previous attempt. Break determinism. Anti-Cache Seed: ${Math.random()}]` });
        }

        const controller = new AbortController();
        worldGenController = controller; // expose for the user Stop button
        const configuredLocalIdleTimeout = isLocalProvider() ? localGenerationIdleTimeoutMs() : 45000;
        const armGenerationIdleTimeout = (overrideMs = configuredLocalIdleTimeout) => {
            if (timeoutId) clearTimeout(timeoutId);
            activeIdleTimeoutMs = Math.max(0, Number(overrideMs) || 0);
            if (!activeIdleTimeoutMs) {
                timeoutId = null;
                return;
            }
            timeoutId = setTimeout(() => {
                generationTimedOut = true;
                controller.abort();
            }, activeIdleTimeoutMs);
        };
        armGenerationIdleTimeout();

        const toolsConfig = [
        {
            type: "function",
            function: {
                name: "investigate_secret",
                description: "Call this when the player investigates, searches, or discovers a gated secret. This reveals the truth to the AI.",
                parameters: {
                    type: "object",
                    properties: {
                        label: { type: "string", description: "The unique ID/label of the secret (e.g. secret_wall)." }
                    },
                    required: ["label"]
                }
            }
        },
        {
            type: "function",
            function: {
                name: "commit_world_turn",
                description: "MANDATORY turn receipt. Propose actor-scoped events, assert the ending scene/cast, and submit persistent state updates. The engine validates every proposal before committing it.",
                parameters: {
                    type: "object",
                    properties: {
                        summary: { type: "string", description: "One factual sentence describing what actually completed this turn. Plans and attempts are not completed facts." },
                        scene: {
                            type: "object",
                            description: "Required ending-scene checksum. Assertions never move anyone; they are checked against committed events.",
                            properties: {
                                player_location_id: { type: "string", description: "Exact location ID where the player ends this response." },
                                player_location_changed: { type: "boolean" },
                                present_character_ids: { type: "array", items: { type: "string" }, description: "Complete list of NPC IDs physically present with the player at the end. Do not include absent, nearby, remembered, or merely mentioned characters." }
                            },
                            required: ["player_location_id", "player_location_changed", "present_character_ids"]
                        },
                        events: {
                            type: "array",
                            description: "Canonical events. Every physical or durable change needs an actor and completion status. 'toward', 'tries', plans and starts are intended/attempted/in_progress, never completed.",
                            items: {
                                type: "object",
                                properties: {
                                    id: { type: "string" },
                                    type: { type: "string", enum: ["movement", "activity", "interaction", "outfit", "inventory", "condition", "time", "observation", "status", "relationship", "quest", "discovery", "environment", "dialogue", "other"] },
                                    actor_id: { type: "string", description: "Exact NPC ID, or 'player'. Required for actor actions. NPC movement can never move the player." },
                                    participants: { type: "array", items: { type: "string" } },
                                    status: { type: "string", enum: ["intended", "attempted", "in_progress", "completed", "cancelled", "failed"] },
                                    from_location_id: { type: "string" },
                                    to_location_id: { type: "string" },
                                    movement_mode: { type: "string", enum: ["voluntary", "forced", "carried", "vehicle", "fall", "teleport"] },
                                    caused_by_actor_id: { type: "string", description: "Required with a non-voluntary player movement." },
                                    activity: { type: "string" },
                                    action: { type: "string" },
                                    target_id: { type: "string" },
                                    change: { type: "number" },
                                    label: { type: "string" },
                                    item: { type: "string" },
                                    outfit: { type: "string" },
                                    condition: { type: "string" },
                                    minutes_elapsed: { type: "integer" },
                                    observation: { type: "string" },
                                    source_type: { type: "string", enum: ["witnessed", "told", "public", "suspected", "believed"] },
                                    source_npc_id: { type: "string" },
                                    confidence: { type: "number" },
                                    visibility: { type: "string", enum: ["public", "private"] },
                                    contradicted: { type: "boolean" },
                                    allowed_to_share: { type: "boolean" },
                                    next_status: { type: "string", enum: ["alive", "dead", "gone"] },
                                    witnessed_by: { type: "array", items: { type: "string" }, description: "IDs of characters who directly witnessed this event. Include 'player' when applicable." },
                                    cause: { type: "string" },
                                    evidence: { type: "string", description: "Short phrase from the narrative proving this event; never dialogue speculation or a hypothetical." }
                                },
                                required: ["type", "status"]
                            }
                        },
                        entity_updates: {
                            type: "array",
                            description: "Ending state for relevant on-screen entities. location_id is an assertion only; movement must be an event.",
                            items: {
                                type: "object",
                                properties: {
                                    entity_id: { type: "string", description: "Exact NPC ID or 'player'." },
                                    location_id: { type: "string" },
                                    activity: { type: "string" },
                                    interacting_with: { type: "array", items: { type: "string" } },
                                    outfit: { type: "string" },
                                    conditions: { type: "array", items: { type: "string" } }
                                },
                                required: ["entity_id", "location_id", "activity", "interacting_with"]
                            }
                        },
                        state_updates: {
                            type: "object",
                            description: "Specialized enabled-module updates using the established fields below. Movement never belongs here; express it as an actor-scoped movement event.",
                            additionalProperties: true
                        },
                        location_id: { type: "string", description: "DEPRECATED AND IGNORED. Never use this naked field. Player movement requires an events[] movement with actor_id='player'." },
                        time_skip_minutes: { type: "integer", description: "Advance the world clock by this many minutes (e.g. 480 for 8 hours of sleep, 60 for waiting an hour). Use this when the player's action explicitly takes a long time." },
                        inventory_add: { type: "array", items: { anyOf: [
                            { type: "string" },
                            { type: "object", properties: {
                                name: { type: "string" }, type: { type: "string", enum: ["weapon", "armor", "clothing", "consumable", "tool", "cyberware", "treasure", "quest", "custom"] },
                                quantity: { type: "integer", minimum: 1 }, description: { type: "string" }, slot: { type: "string" },
                                damage: { type: "string" }, damage_type: { type: "string" }, armor: { type: "number" }, value: { type: "number" },
                                modifiers: { type: "object", additionalProperties: true }
                            }, required: ["name"] }
                        ] }, description: "Items added to inventory. Prefer an authored world item name. Use an object only when a newly discovered item needs persistent damage, armor, slot, value or bonuses." },
                        inventory_remove: { type: "array", items: { type: "string" }, description: "Items that leave the inventory: consumed, given away, sold, lost, destroyed, or used up. ALWAYS call this when the narrative removes an item from the player." },
                        stat_changes: { 
                            type: "object", 
                            description: "Changes to custom player stats. Positive for increase, negative for decrease.",
                            properties: (world.hudConfig?.stats || []).reduce((acc, s) => {
                                acc[s.id] = { type: "integer", description: `Change in ${s.name}` };
                                return acc;
                            }, {})
                        },
                        stat_change_cause: { type: "string", description: "Short factual cause for damage, healing, or another stat change; required when a vital stat may reach zero." },
                        capability_progress: {
                            type: "array",
                            maxItems: 10,
                            items: {
                                type: "object",
                                properties: {
                                    capability_id: { type: "string", description: "Exact selected skill, perk or flaw ID." },
                                    change: { type: "integer", minimum: -5, maximum: 5 },
                                    reason: { type: "string", description: "Concrete training, milestone or consequence that earned this change." }
                                },
                                required: ["capability_id", "change", "reason"]
                            },
                            description: "Change a selected capability rank only when this world's progression is enabled and the fiction explicitly earned it."
                        },
                        transactions: {
                            type: "array",
                            items: {
                                type: "object",
                                properties: {
                                    type: { type: "string", enum: ["buy", "sell"] },
                                    item: { type: "string" },
                                    quantity: { type: "integer", minimum: 1, maximum: 100 },
                                    price: { type: "number", description: "Price PER UNIT in the world's currency. REQUIRED unless this location has a defined market with this item in stock — without it a purchase cannot be settled and the money will not move." },
                                    location_id: { type: "string", description: "Market location. Omit to use the player's current location." }
                                },
                                required: ["type", "item", "price"]
                            },
                            description: "Authoritative purchases and sales — use this whenever money changes hands, from a corner-shop coffee to a warhorse. Give the price per unit; the engine atomically validates funds and ownership, deducts or credits currency, and moves the item. Never duplicate a settled transaction with inventory_add/remove or stat_changes."
                        },
                        checks: {
                            type: "array",
                            maxItems: 1,
                            items: {
                                type: "object",
                                properties: {
                                    id: { type: "string" },
                                    label: { type: "string" },
                                    stat_id: { type: "string", description: "Optional roll-enabled ability/skill stat. Never use health, money, XP, level, stress or another resource unless the author explicitly marked it rollable." },
                                    capability_id: { type: "string", description: "Optional exact world capability ID or name from the player's selected skills, perks or flaws. The engine applies its authored modifier only when this player actually selected it." },
                                    difficulty: { type: "integer", minimum: 2, maximum: 30 },
                                    modifier: { type: "integer", minimum: -5, maximum: 5, description: "Situational modifier only." },
                                    failure_cost: {
                                        type: "object",
                                        properties: {
                                            stat_changes: { type: "object", additionalProperties: { type: "number" } },
                                            inventory_remove: { type: "array", items: { type: "string" } },
                                            time_skip_minutes: { type: "integer", minimum: 0, maximum: 14400 },
                                            condition: { type: "string" },
                                            cause: { type: "string" }
                                        }
                                    },
                                    on_success: {
                                        type: "object",
                                        additionalProperties: true,
                                        description: "Persistent updates applied only if this check succeeds. Use the same state-update fields as commit_world_turn (inventory_add/remove, stat_changes, quests_update, npc_disposition_changes, etc.)."
                                    },
                                    on_failure: {
                                        type: "object",
                                        additionalProperties: true,
                                        description: "Persistent updates applied only if this check fails. Prefer this over failure_cost when the consequence includes quests, relationships, discoveries, identity, or other world state."
                                    }
                                },
                                required: ["label", "difficulty"]
                            },
                            description: "At most one authoritative check per turn. Put every result-dependent mutation inside on_success or on_failure; never place a completed consequence at the receipt top level."
                        },
                        player_condition_updates: {
                            type: "array",
                            items: {
                                type: "object",
                                properties: {
                                    condition: { type: "string" },
                                    action: { type: "string", enum: ["add", "remove"] }
                                },
                                required: ["condition", "action"]
                            },
                            description: "Add or remove lasting player conditions and injuries. Incapacitated cannot be removed while vital health remains at zero."
                        },
                        outfit_update: { type: "string", description: "A short description of the player's current outfit (if it changed)." },
                        ledger_update: { type: "string", description: "One concise factual sentence for the long-term chronicle when this turn permanently changes canon. Include it alongside any other state changes. Omit for pure description, repetition, or small talk." },
                        npc_observations: {
                            type: "array",
                            items: {
                                type: "object",
                                properties: {
                                    npc_id: { type: "string" },
                                    observation: { type: "string", description: "A permanent fact this NPC has learned or witnessed." },
                                    source_type: { type: "string", enum: ["witnessed", "told", "public", "suspected", "believed"], description: "How the NPC knows this. Never mark hearsay as witnessed." },
                                    source_npc_id: { type: "string", description: "Who told them, when source_type is told." },
                                    confidence: { type: "number", description: "Confidence from 0 to 1." },
                                    visibility: { type: "string", enum: ["public", "private"] },
                                    contradicted: { type: "boolean" },
                                    allowed_to_share: { type: "boolean", description: "Whether this NPC may pass the fact on through gossip." }
                                }
                            },
                            description: "Update the persistent memory/observations of specific NPCs."
                        },
                        quests_update: { 
                            type: "array", 
                            items: {
                                type: "object",
                                properties: {
                                    id: { type: "string", description: "Exact existing quest ID from PLAYER QUEST LEDGER. Omit only when creating a genuinely new quest." },
                                    title: { type: "string", description: "Stable player-facing quest title. Required for a new quest." },
                                    description: { type: "string", description: "What was asked, why it matters, and what success means." },
                                    giver: { type: "string", description: "NPC or faction that gave the quest, when applicable." },
                                    status: { type: "string", enum: ["active", "completed", "failed", "abandoned"] },
                                    completion_note: { type: "string", description: "Concise explanation of how the quest resolved." },
                                    objectives: {
                                        type: "array",
                                        description: "Structured objectives. Use exact objective IDs when updating. The engine automatically evaluates location, inventory, stat, secret, npc_status, and thread objectives.",
                                        items: {
                                            type: "object",
                                            properties: {
                                                id: { type: "string", description: "Exact existing objective ID. Omit when adding a new objective." },
                                                text: { type: "string", description: "Clear player-facing objective." },
                                                type: { type: "string", enum: ["manual", "location", "inventory", "stat", "secret", "npc_status", "thread"] },
                                                target: { type: "string", description: "Location/item/stat/secret/NPC/thread ID or exact name to observe." },
                                                expected: { type: "string", description: "Expected NPC status: alive, dead, or gone." },
                                                required: { type: "number", description: "Amount needed; defaults to 1." },
                                                current: { type: "number", description: "Absolute progress, normally only for a manual objective." },
                                                progress_change: { type: "number", description: "Incremental progress, normally only for a manual objective." },
                                                status: { type: "string", enum: ["active", "completed", "failed"] },
                                                optional: { type: "boolean" }
                                            }
                                        }
                                    },
                                    rewards: {
                                        type: "object",
                                        description: "Rewards promised by the quest. The engine grants these exactly once on completion.",
                                        properties: {
                                            items: { type: "array", items: { type: "string" } },
                                            stat_changes: { type: "object", additionalProperties: { type: "number" } },
                                            faction_reputation: {
                                                type: "array",
                                                items: {
                                                    type: "object",
                                                    properties: {
                                                        faction_id: { type: "string" },
                                                        change: { type: "number" }
                                                    },
                                                    required: ["faction_id", "change"]
                                                }
                                            }
                                        }
                                    }
                                }
                            },
                            description: "Create or update persistent player quests. Use exact IDs for existing quests; never duplicate a quest to change it."
                        },
                        npc_moves: {
                            type: "array",
                            items: {
                                type: "object",
                                properties: {
                                    npc_id: { type: "string", description: "ID or name of the NPC to move." },
                                    target_location_id: { type: "string", description: "ID of the destination location the NPC ends up in." },
                                    reason: { type: "string", description: "Optional: one short line on why they moved." }
                                },
                                required: ["npc_id", "target_location_id"]
                            },
                            description: "Move an NPC from wherever they are to another location. REQUIRED whenever you narrate a character arriving, entering, joining, or leaving the player's scene — otherwise the engine still believes they are elsewhere and the player's surroundings will show the room as empty."
                        },
                        npc_status_changes: {
                            type: "array",
                            items: {
                                type: "object",
                                properties: {
                                    npc_id: { type: "string", description: "ID or name of the NPC." },
                                    status: { type: "string", enum: ["alive", "dead", "gone"], description: "'dead' = killed (permanent). 'gone' = left the world/region permanently. 'alive' = ONLY for an explicit resurrection/return story event." },
                                    cause: { type: "string", description: "One line: how it happened." }
                                },
                                required: ["npc_id", "status"]
                            },
                            description: "Call when an NPC dies or permanently departs. The engine removes them from schedules, scenes, and population — permanently."
                        },
                        threads_update: {
                            type: "array",
                            items: {
                                type: "object",
                                properties: {
                                    id: { type: "string", description: "Stable id for the thread (e.g. 'thread_letter')." },
                                    text: { type: "string", description: "The open loop, phrased as a hook (e.g. 'The sealed letter from Mira remains unopened')." },
                                    status: { type: "string", enum: ["open", "resolved"], description: "Mark 'resolved' when the story answers it." }
                                },
                                required: ["id", "text"]
                            },
                            description: "Track dangling narrative threads — unopened letters, unanswered questions, promises made, mysteries glimpsed. Register hooks when they appear; resolve them when the story pays them off."
                        },
                        npc_goal_updates: {
                            type: "array",
                            items: {
                                type: "object",
                                properties: {
                                    npc_id: { type: "string", description: "ID or name of the NPC." },
                                    goal: { type: "string", description: "Their current personal goal, born from the story so far (e.g. 'convince the player to leave town before the marshal arrives'). Empty string to clear a completed/abandoned goal." },
                                    motivation: { type: "string", description: "One line: WHY they want this. Optional." },
                                    steps: { type: "array", items: { type: "string" }, description: "Concrete stages the NPC can pursue off-screen." },
                                    progress_change: { type: "number", description: "Immediate progress change from -100 to 100 when the scene helps or hinders the goal." },
                                    deadline_in_turns: { type: "integer", description: "Turns remaining before failure. Use 0 to clear a deadline." },
                                    difficulty: { type: "integer", description: "0 easy to 100 extremely difficult." },
                                    autonomy: { type: "string", enum: ["paused", "low", "medium", "high"], description: "How aggressively this goal advances while the NPC is off-screen." },
                                    status: { type: "string", enum: ["active", "completed", "failed", "blocked"] }
                                },
                                required: ["npc_id", "goal"]
                            },
                            description: "Assign or update an NPC agenda. Structured steps and autonomy let it progress between scenes."
                        },
                        schedule_updates: {
                            type: "array",
                            items: {
                                type: "object",
                                properties: {
                                    npc_id: { type: "string" },
                                    replace: { type: "boolean", description: "Replace the timeline schedule; false appends/overwrites matching times." },
                                    reason: { type: "string", description: "Why the routine changed." },
                                    blocks: {
                                        type: "array",
                                        items: {
                                            type: "object",
                                                properties: {
                                                    time: { type: "string", description: "24-hour HH:MM." },
                                                    location_id: { type: "string" },
                                                    activity: { type: "string" },
                                                    days: { type: "array", items: { type: "string" }, description: "Optional weekday names, 'weekday', or 'weekend'. Omit for every day." }
                                            },
                                            required: ["time", "location_id"]
                                        }
                                    }
                                },
                                required: ["npc_id", "blocks"]
                            },
                            description: "Change an NPC's daily or weekly routine for this timeline when story events alter their plans."
                        },
                        world_events: {
                            type: "array",
                            items: {
                                type: "object",
                                properties: {
                                    id: { type: "string", description: "Stable event id; reuse it to update/cancel." },
                                    title: { type: "string" },
                                    description: { type: "string" },
                                    status: { type: "string", enum: ["scheduled", "cancelled"] },
                                    due_in_turns: { type: "integer" },
                                    due_in_minutes: { type: "integer" },
                                    repeat_every_turns: { type: "integer" },
                                    repeat_every_minutes: { type: "integer" },
                                    location_id: { type: "string" },
                                    condition_on_trigger: { type: "string", description: "Persistent location condition created when it fires." },
                                    condition_duration_turns: { type: "integer" },
                                    faction_id: { type: "string" },
                                    influence_change: { type: "number" }
                                }
                            },
                            description: "Schedule, revise, repeat, or cancel future developments. They fire on later player turns."
                        },
                        location_state_updates: {
                            type: "array",
                            items: {
                                type: "object",
                                properties: {
                                    location_id: { type: "string" },
                                    set_conditions: { type: "array", items: { type: "string" } },
                                    add_conditions: { type: "array", items: { type: "string" } },
                                    remove_conditions: { type: "array", items: { type: "string" } },
                                    condition_duration_turns: { type: "integer" },
                                    control_faction_id: { type: "string", description: "Faction id/name, or empty to clear control." },
                                    danger_change: { type: "number" },
                                    prosperity_change: { type: "number" },
                                    resource_changes: { type: "object", additionalProperties: { type: "number" } }
                                },
                                required: ["location_id"]
                            },
                            description: "Persist destruction, repairs, hazards, prosperity, resources, and territorial control at locations."
                        },
                        npc_relationship_updates: {
                            type: "array",
                            items: {
                                type: "object",
                                properties: {
                                    source_npc_id: { type: "string" },
                                    target_npc_id: { type: "string" },
                                    change: { type: "number", description: "-30 to +30." },
                                    label: { type: "string", description: "e.g. allies, rivals, family, suspicious." },
                                    reason: { type: "string" }
                                },
                                required: ["source_npc_id", "target_npc_id"]
                            },
                            description: "Track relationships between NPCs, not just their feelings toward the player."
                        },
                        faction_updates: {
                            type: "array",
                            items: {
                                type: "object",
                                properties: {
                                    id: { type: "string" },
                                    name: { type: "string" },
                                    reputation_change: { type: "number" },
                                    influence_change: { type: "number" },
                                    resources_change: { type: "number" },
                                    goal: { type: "string" },
                                    goal_progress_change: { type: "number" },
                                    status: { type: "string", enum: ["active", "weakened", "defeated", "disbanded"] },
                                    territory_add: { type: "array", items: { type: "string" } },
                                    territory_remove: { type: "array", items: { type: "string" } },
                                    relations: {
                                        type: "array",
                                        items: {
                                            type: "object",
                                            properties: {
                                                faction_id: { type: "string" },
                                                change: { type: "number" }
                                            },
                                            required: ["faction_id", "change"]
                                        }
                                    }
                                }
                            },
                            description: "Create and evolve organizations, territory, resources, alliances, rivalries, and objectives."
                        },
                        economy_updates: {
                            type: "array",
                            items: {
                                type: "object",
                                properties: {
                                    location_id: { type: "string" },
                                    item: { type: "string" },
                                    quantity_change: { type: "number" },
                                    set_quantity: { type: "number" },
                                    price: { type: "number" },
                                    regen_per_turn: { type: "number" },
                                    max_quantity: { type: "number" }
                                },
                                required: ["location_id", "item"]
                            },
                            description: "Change local stock, scarcity, prices, and turn-based replenishment."
                        },
                        player_identity_update: {
                            type: "object",
                            properties: {
                                role: { type: "string", description: "Current occupation or social role, when it actually changed." },
                                social_rank: { type: "string", description: "Current social rank: peasant, citizen, outlaw, knight, noble, royalty, sovereign, etc." },
                                title: { type: "string", description: "Current formal title. Use an empty string when a title was explicitly lost or renounced." },
                                legal_status: { type: "string", description: "Current legal standing in the relevant jurisdiction: free, wanted, pardoned, imprisoned, protected, and so on." },
                                faction_id: { type: "string", description: "Exact faction ID newly joined or owed allegiance to; empty string for no allegiance." },
                                privileges_add: { type: "array", items: { type: "string" } },
                                privileges_remove: { type: "array", items: { type: "string" } },
                                obligations_add: { type: "array", items: { type: "string" } },
                                obligations_remove: { type: "array", items: { type: "string" } },
                                holdings_add: { type: "array", items: { type: "string" } },
                                holdings_remove: { type: "array", items: { type: "string" } },
                                heat_change: { type: "number", description: "Change in law-enforcement attention, -100 to +100." },
                                crime: { type: "string", description: "A concrete new alleged or proven offense to remember." },
                                reason: { type: "string", description: "Required factual reason for the durable status change." }
                            },
                            required: ["reason"],
                            description: "Persist a genuine change in the player's social identity: promotion, title, allegiance, outlawry, pardon, inheritance, loss of property, abdication, vows or duties. Do not use for disguise, aspiration, rumor, temporary scene roles, or an action that has not completed."
                        },
                        player_preference_updates: {
                            type: "array",
                            items: {
                                type: "object",
                                properties: {
                                    key: { type: "string" },
                                    value: { type: "string" },
                                    confidence: { type: "number" },
                                    source: { type: "string" }
                                },
                                required: ["key", "value"]
                            },
                            description: "Record explicit or strongly demonstrated play preferences. Never use this to railroad the player."
                        },
                        npc_disposition_changes: {
                            type: "array",
                            items: {
                                type: "object",
                                properties: {
                                    npc_id: { type: "string", description: "ID or name of the NPC whose feelings changed." },
                                    change: { type: "integer", description: "Shift in disposition toward the player, -20 to +20. Small for words, larger for deeds." },
                                    reason: { type: "string", description: "One short sentence: why their feelings shifted." }
                                },
                                required: ["npc_id", "change"]
                            },
                            description: "Call when the player's words or actions meaningfully change how an NPC feels about them (kindness, betrayal, gifts, threats, saving their life...)."
                        },
                        npc_introduced: {
                            type: "array",
                            items: {
                                type: "object",
                                properties: {
                                    name: { type: "string", description: "Name of the newly introduced character." },
                                    description: { type: "string", description: "A short physical description of the character." },
                                    persona: { type: "string", description: "Their personality, voice, and motivations — REQUIRED if this character will speak or recur. Without it they will be a cardboard extra." },
                                    home_location: { type: "string", description: "Where they LIVE or are usually found — ONLY if the narrative establishes it. Omit for travelers/strangers." }
                                },
                                required: ["name"]
                            },
                            description: "Any NEW characters/NPCs you just spontaneously introduced in the scene. Provide their name and a short physical description."
                        },
                        location_introduced: {
                            type: "array",
                            items: {
                                type: "object",
                                properties: {
                                    id: { type: "string", description: "Stable new location ID used by movement events in this same receipt." },
                                    name: { type: "string", description: "Name of the new location." },
                                    description: { type: "string", description: "What the player sees there." },
                                    region: { type: "string", description: "Region/district it belongs to, if any." },
                                    connects_to: { type: "string", description: "Name of the EXISTING location it connects to (defaults to the current location)." },
                                    map_type: { type: "string", enum: ["region", "route", "building", "outdoor", "room", "area"], description: "Optional semantic map role. The engine auto-detects it when omitted." },
                                    parent_location_id: { type: "string", description: "Existing building/area this location is inside or attached to." },
                                    floor: { type: "string", description: "Optional floor or level, e.g. ground, 2, basement." }
                                },
                                required: ["name"]
                            },
                            description: "Any NEW place the narrative visits that is NOT in the location manifest. The engine registers it and links exits both ways — then you can move the player there with location_id in the same call."
                        }
                    },
                    required: ["scene", "events", "entity_updates"]
                }
            }
        }];

        const worldStateTool = toolsConfig.find(tool => tool.function?.name === 'commit_world_turn');
        const worldStateProperties = worldStateTool.function.parameters.properties;
        worldStateTool.function.description = `MANDATORY canonical receipt for every response. Propose actor-scoped events, complete ending scene/cast, entity activity, and enabled module updates (${WORLD_RULE_MODULE_KEYS.filter(key => ruleModules[key]).join(', ') || 'narrative core only'}).`;
        const removeToolFields = fields => fields.forEach(field => delete worldStateProperties[field]);
        // Actorless legacy mutations are intentionally absent from the public
        // contract. Their replacements live in events[] and are validated by
        // the canonical reducer.
        removeToolFields(['location_id', 'npc_moves', 'outfit_update', 'inventory_add',
            'inventory_remove', 'player_condition_updates']);
        if (!ruleModules.stats) removeToolFields(['stat_changes', 'stat_change_cause']);
        if (!normalizeWorldCapabilities(world).progression.enabled) removeToolFields(['capability_progress']);
        if (!ruleModules.inventory) removeToolFields(['inventory_add', 'inventory_remove']);
        if (!ruleModules.commerce) removeToolFields(['transactions']);
        if (!ruleModules.checks) removeToolFields(['checks']);
        if (!ruleModules.conditions) removeToolFields(['player_condition_updates']);
        if (!ruleModules.quests) removeToolFields(['quests_update']);
        if (!ruleModules.relationships) removeToolFields(['npc_relationship_updates', 'npc_disposition_changes']);
        if (!ruleModules.schedules) removeToolFields(['schedule_updates']);
        if (!ruleModules.livingWorld) {
            removeToolFields(['npc_goal_updates', 'world_events', 'location_state_updates', 'faction_updates', 'player_preference_updates']);
        }
        if (!ruleModules.commerce && !ruleModules.livingWorld) removeToolFields(['economy_updates']);

        const failureCostProperties = worldStateProperties.checks?.items?.properties?.failure_cost?.properties;
        const checkSchema = worldStateProperties.checks;
        if (checkSchema) {
            checkSchema.description = diceConfig.resolution === 'player'
                ? `Request a d${diceConfig.sides} check only when failure is meaningfully possible. End the prose at the moment of uncertainty; the player rolls and the next turn narrates the locked result.`
                : `Request an authoritative d${diceConfig.sides} check. The engine rolls and persists it; never invent a roll value.`;
            const difficultySchema = checkSchema.items?.properties?.difficulty;
            if (difficultySchema) difficultySchema.maximum = diceConfig.sides + 10;
        }
        if (failureCostProperties) {
            if (!ruleModules.stats) delete failureCostProperties.stat_changes;
            if (!ruleModules.inventory) delete failureCostProperties.inventory_remove;
            if (!ruleModules.conditions) delete failureCostProperties.condition;
        }
        const questRewardProperties = worldStateProperties.quests_update?.items?.properties?.rewards?.properties;
        if (questRewardProperties) {
            if (!ruleModules.inventory) delete questRewardProperties.items;
            if (!ruleModules.stats) delete questRewardProperties.stat_changes;
            if (!ruleModules.relationships && !ruleModules.livingWorld) delete questRewardProperties.faction_reputation;
        }

        const modelId = world.model || state.globalSettings.defaultModel;

        // Tool calling across OpenAI-compatible providers is not uniform. Give
        // every action turn an explicit textual emergency channel from turn
        // one; proper tool callers still use the tool, while a tool-shy model
        // no longer gets two free turns in which state silently disappears.
        const knownToolShy = Array.isArray(state.globalSettings.toolShyModels)
            && state.globalSettings.toolShyModels.includes(modelId);
        if (command !== 'look' && command !== 'init') {
            const escapeHatch = `\n\n[TURN RECEIPT DELIVERY FAILSAFE]\nUse commit_world_turn as a real tool call. If and only if this provider cannot emit that tool call, append exactly one block at the end instead:\n<world_turn_receipt>{"scene":{"player_location_id":"${sess.playerLocation}","player_location_changed":false,"present_character_ids":[]},"events":[],"entity_updates":[],"state_updates":{}}</world_turn_receipt>\nThe receipt is mandatory even when nothing changes. Fill it with the same actor-scoped events, full ending cast and updates you would have sent to the tool. Never send both a successful tool call and the tagged block.${knownToolShy ? '\nThis model has previously failed to deliver tool calls, so use the tagged receipt rather than dropping state.' : ''}`;
            const lastSystem = [...messages].reverse().find(entry => entry.role === 'system');
            if (lastSystem) lastSystem.content += escapeHatch;
            else messages.push({ role: 'system', content: escapeHatch });
        }

        const requestBody = {
            model: modelId,
            messages: sanitizeMessagesForProvider(messages),
            stream: true,
            tool_choice: "auto",
            tools: toolsConfig
        };
        if (normalizeWorldKernelConfig(world).enabled && normalizeWorldKernelConfig(world).compactTools) {
            compactWorldToolContract(requestBody.tools);
            requestBody.parallel_tool_calls = false;
        }

        const supported = world.supportedParams || [];
        const hasSupported = supported.length > 0;
        const addParam = (apiName, value) => {
            if (!hasSupported || supported.includes(apiName)) {
                requestBody[apiName] = value;
            }
        };

        let temp = parseFloat(world.temp) || 0.9;
        // Introduce micro-jitter for rerolls to prevent exact caching
        if (isReroll) {
            temp = Math.min(2.0, temp + (Math.random() * 0.05));
            requestBody.seed = Math.floor(Math.random() * 1000000);
        }

        addParam('temperature', temp);
        addParam('max_tokens', parseInt(world.maxTokens) || 2048);
        addParam('top_p', world.topP || 1);
        if (world.freqPenalty) addParam('frequency_penalty', world.freqPenalty);
        if (world.presPenalty) addParam('presence_penalty', world.presPenalty);
        if (world.repPenalty && world.repPenalty !== 1.0) addParam('repetition_penalty', world.repPenalty);
        if (world.minP) addParam('min_p', world.minP);
        if (world.topK) addParam('top_k', world.topK);

        if (world.reasoning) {
            if (supported.includes('reasoning_effort') || modelId.includes('o1') || modelId.includes('o3') || modelId.includes('deepseek')) {
                requestBody.reasoning_effort = world.reasoningEffort || 'medium';
            } else {
                requestBody.reasoning = { effort: world.reasoningEffort || 'medium' };
            }
            if (world.includeReasoning) requestBody.include_reasoning = true;
        }

        let questFallbackMode = false;
        turnCallAudit.main++;
        let response = await fetch(apiBase() + '/chat/completions', {
            method: 'POST',
            signal: controller.signal,
            headers: {
                ...authHeaders(),
                'Content-Type': 'application/json',
                ...attributionHeaders()
            },
            body: JSON.stringify(requestBody)
        });

        if (!response.ok) {
            let errBody = await response.text();
            if (errBody.includes("tool use") || errBody.includes("commit_world_turn")) {
                console.warn("Horde Engine: Model does not support tools. Retrying in Narrative Rescue mode.");
                showToast("Model doesn't support tools. Using Narrative Fallback...", "info");
                // RETRY WITHOUT TOOLS
                delete requestBody.tools;
                requestBody.tool_choice = "none";
                questFallbackMode = ruleModules.quests;
                const fallbackPlacement = directorNotesRequired
                    ? 'immediately before the required final <details><summary>Plot Momentum</summary> block'
                    : 'after the prose';
                const fallbackInstruction = `\n\n[TOOL-FREE TURN RECEIPT — REQUIRED]\nThis provider rejected tool calling. Append exactly one <world_turn_receipt>{...}</world_turn_receipt> block ${fallbackPlacement}, even when nothing changed. It must contain scene, events, entity_updates, and state_updates using exact IDs. Movement is actor-scoped; NPC movement never moves the player. Put specialized persistent updates${questFallbackMode ? ', including quests_update,' : ''} inside state_updates.`;
                requestBody.messages = requestBody.messages.map((message, index) =>
                    index === 0 ? { ...message, content: String(message.content || '') + fallbackInstruction } : message);
                
                turnCallAudit.providerFallback++;
                response = await fetch(apiBase() + '/chat/completions', {
                    method: 'POST',
                    signal: controller.signal,
                    headers: { 'Content-Type': 'application/json', ...authHeaders() },
                    body: JSON.stringify(requestBody)
                });
                if (!response.ok) errBody = await response.text();
            }
            if (!response.ok) throw new Error(errBody || `API request failed (${response.status})`);
        }

        if (!response.body) throw new Error('No response body from API');

        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let fullText = "";
        const streamedToolCalls = new Map();
        let streamError = null;       // provider error delivered inside the stream
        let reasoningSeen = false;    // model emitted hidden reasoning deltas
        let lastFinishReason = null;  // e.g. 'length' = token budget exhausted

        // Create a temporary UI message for streaming
        const aiMsgDiv = document.createElement('div');
        aiMsgDiv.className = 'msg msg-dm';
        aiMsgDiv.innerHTML = `<div class="msg-bubble"><div class="msg-text"></div></div>`;
        document.getElementById('world-messages-container').appendChild(aiMsgDiv);
        const textTarget = aiMsgDiv.querySelector('.msg-text');

        let buffer = "";
        const processWorldStreamLine = line => {
            if (!line.startsWith('data:')) return;
            const data = line.slice(5).trimStart().replace(/\r$/, '');
            if (!data || data === '[DONE]') return;
            try {
                const json = JSON.parse(data);
                if (json.error) {
                    streamError = new Error(json.error.message || 'Provider error mid-stream');
                    return;
                }
                const choice = json.choices?.[0] || {};
                const delta = choice.delta || choice.message || {};
                if (choice.finish_reason) lastFinishReason = choice.finish_reason;
                if (delta.reasoning || delta.thought) {
                    reasoningSeen = true;
                    if (dmTypingLabel && !fullText) dmTypingLabel.textContent = 'DM is thinking deeply...';
                }
                const content = Array.isArray(delta.content)
                    ? delta.content.map(part => part?.text || '').join('')
                    : delta.content;
                if (content) {
                    fullText += content;
                    textTarget.innerHTML = parseHordeMarkdown(fullText);
                    const container = document.getElementById('world-messages-container');
                    container.scrollTop = container.scrollHeight;
                }
                const incomingCalls = delta.tool_calls || choice.message?.tool_calls || [];
                incomingCalls.forEach(tc => accumulateWorldToolCall(streamedToolCalls, tc));
                // Legacy OpenAI-compatible providers still use function_call.
                if (delta.function_call) {
                    accumulateWorldToolCall(streamedToolCalls, {
                        index: 0,
                        id: delta.function_call.id,
                        function: delta.function_call
                    });
                }
            } catch (error) {
                // One malformed provider event should not erase later valid
                // deltas. The completed buffer and tool parser get another
                // chance below.
                console.warn('Horde Engine: ignored malformed stream event', error.message);
            }
        };
        while (true) {
            const { done, value } = await reader.read();
            if (done) break;

            // IDLE timeout, not wall-clock: reasoning models (DeepSeek Pro, o-series)
            // legitimately think for 60s+ while streaming reasoning deltas. As long
            // as ANY data flows, keep the connection alive; only kill true stalls.
            armGenerationIdleTimeout();

            buffer += decoder.decode(value, { stream: true });
            const lines = buffer.split('\n');
            buffer = lines.pop();

            for (const line of lines) {
                processWorldStreamLine(line);
                if (streamError) break;
            }
            if (streamError) break;
        }
        // TextDecoder and SSE streams are not required to end with a newline.
        // The old loop silently lost that final event — frequently the closing
        // braces of a tool call.
        buffer += decoder.decode();
        if (buffer.trim()) processWorldStreamLine(buffer);

        // Remove the streaming temp div
        aiMsgDiv.remove();

        if (streamError) throw streamError;

        const toolCalls = [...streamedToolCalls.values()];
        const toolResponses = [];
        let structuredChronicle = null;
        let successfulStateCall = false;
        let resolvedCheckThisTurn = false;
        const receiptPlayerStart = String(turnSnapshot?.session?.playerLocation || sess.playerLocation);
        const receiptMovementPhrase = extractUserMovementTarget(submittedInput || userInput);
        const receiptAuthorizedTarget = receiptMovementPhrase
            ? resolveWorldMovementTarget(typeof worldForSession === 'function' ? worldForSession(world, sess) : world, receiptPlayerStart, receiptMovementPhrase) : null;
        const receiptContext = {
            playerStartLocationId: receiptPlayerStart,
            committedPlayerDestinationId: sess.playerLocation !== receiptPlayerStart ? sess.playerLocation : '',
            playerMovementAuthorized: !!receiptAuthorizedTarget,
            authorizedPlayerDestinationId: receiptAuthorizedTarget?.id || '',
            narrativeText: fullText
        };
        for (const call of toolCalls) {
            let responsePayload = { success: true, status: 'Action processed.' };
            try {
                const args = parseWorldToolArguments(call.function.arguments || '{}');
                if (call.function.name === 'investigate_secret') {
                    const secret = currentSecrets.find(item => item.label === args.label);
                    if (secret) {
                        const actionResult = processStructuredActions({ label: args.label });
                        if (actionResult?.ledgerEntry) structuredChronicle = actionResult.ledgerEntry;
                        responsePayload = { success: true, truth: secret.truth, status: 'SECRET UNLOCKED' };
                    } else {
                        responsePayload = { success: false, status: 'Secret not found' };
                    }
                } else if (call.function.name === 'commit_world_turn') {
                    const validEnvelope = isPlainObject(args.scene)
                        && Array.isArray(args.events) && Array.isArray(args.entity_updates);
                    if (!validEnvelope) throw new Error('Turn receipt must include scene, events, and entity_updates.');
                    const committed = commitWorldTurnReceipt(world, sess, args, receiptContext, 'tool_call');
                    const actionResult = committed.actionResult;
                    if (actionResult?.ledgerEntry) structuredChronicle = actionResult.ledgerEntry;
                    const updatedLoc = world.locations.find(location => location.id === sess.playerLocation);
                    const movement = actionResult?.movementResult;
                    const transactionResults = actionResult?.transactionResults || [];
                    const transactionsOk = transactionResults.every(result => result.success);
                    const checkResults = actionResult?.checkResults || [];
                    if (checkResults.some(result => !result.pending && !result.reason)) resolvedCheckThisTurn = true;
                    const checksOk = checkResults.every(result =>
                        result.success || (!result.reason && result.failureCost?.applied !== false));
                    const conditionResults = actionResult?.conditionResults || [];
                    const conditionsOk = conditionResults.every(result => result.success);
                    const statUpdatesOk = !actionResult?.statResult || actionResult.statResult.rejected.length === 0;
                    const moduleRejections = actionResult?.moduleRejections || [];
                    const modulesOk = moduleRejections.length === 0;
                    responsePayload = {
                        success: (movement ? movement.ok : true) && transactionsOk && statUpdatesOk && checksOk && conditionsOk && modulesOk,
                        new_location: updatedLoc?.name || 'Unknown',
                        movement_path: movement?.path || [],
                        quest_updates: actionResult?.questResult || null,
                        stat_updates: actionResult?.statResult || null,
                        transactions: transactionResults,
                        checks: checkResults,
                        capability_progress: actionResult?.capabilityProgressResults || [],
                        player_conditions: conditionResults,
                        disabled_actions: moduleRejections,
                        receipt_audit: committed.audit,
                        player_state: actionResult?.playerState || null,
                        status: movement && !movement.ok
                            ? `Movement rejected: ${movement.reason}. Use a destination connected through the exit graph.`
                            : !transactionsOk
                                ? 'One or more transactions were rejected. Narrate the refusal; do not give/take items or currency.'
                                : !statUpdatesOk
                                    ? 'One or more stat changes were rejected.'
                                    : !checksOk
                                        ? 'A check resolved, but its declared failure cost was invalid and was not applied.'
                                        : !conditionsOk
                                            ? 'One or more player condition updates were rejected.'
                                        : !modulesOk
                                            ? 'One or more requested mechanics are disabled by this world’s rules profile.'
                                    : committed.audit.rejected.length
                                        ? `Turn committed with ${committed.audit.rejected.length} rejected proposal(s).`
                                        : 'Canonical turn committed.'
                    };
                    successfulStateCall = true;
                } else {
                    responsePayload = { success: false, status: `Unknown tool "${call.function.name || '(missing name)'}".` };
                }
            } catch (error) {
                console.error('Horde Engine: Failed to parse tool call', error);
                responsePayload = { success: false, status: error.message };
            }
            toolResponses.push({ role: 'tool', tool_call_id: call.id, content: JSON.stringify(responsePayload) });
        }

        // --- TURN RECEIPT RESCUE ---
        // Providers that print the mandatory receipt instead of calling the
        // tool still pass through the same validator and reducer.
        let inlineStateApplied = false;
        if (!successfulStateCall) {
            const inlineReceipt = extractInlineWorldTurnReceipt(fullText);
            if (inlineReceipt) {
                try {
                    const committed = commitWorldTurnReceipt(world, sess, inlineReceipt, receiptContext, 'inline_receipt');
                    if (committed.actionResult?.ledgerEntry) structuredChronicle = committed.actionResult.ledgerEntry;
                    inlineStateApplied = true;
                    console.warn(`Horde Engine: model emitted its turn receipt as text — recovered and validated it.`);
                } catch (error) {
                    console.error('Horde Engine: inline turn receipt failed validation', error);
                }
            }
        }

        // A receipt is required even on a no-change conversation turn. Ask for
        // only the missing structured receipt; never regenerate or alter the
        // already-written narrative. This repair request runs only when the
        // provider failed the primary contract.
        let repairedReceiptApplied = false;
        const receiptRepairNeeded = shouldRepairMissingWorldReceipt(world, command, submittedInput || userInput, fullText);
        if (!successfulStateCall && !inlineStateApplied && fullText.trim() && receiptRepairNeeded) {
            try {
                if (dmTypingLabel) dmTypingLabel.textContent = 'DM is reconciling the world state...';
                const repairFrame = buildWorldSceneFrame(world, sess);
                const repairPrompt = `[WORLD TURN RECEIPT REPAIR]\nThe narrative below has already been shown and MUST NOT be rewritten. Return JSON only for one commit_world_turn receipt with required keys scene, events, entity_updates, state_updates, and summary.\n- Every action names actor_id.\n- NPC movement never changes player location.\n- Intent, attempts, movement toward somewhere, dialogue claims and hypotheticals are not completed events.\n- scene is the complete ENDING checksum.\n- If nothing persistent changed, use empty events/state_updates but still return the current scene.\nAuthoritative pre-repair scene: ${JSON.stringify(repairFrame)}\nPlayer input: ${JSON.stringify(String(submittedInput || userInput).slice(0, 1200))}\nNarrative: ${JSON.stringify(String(fullText).slice(0, 7000))}`;
                const repairBody = {
                    model: structuredModelFor(world),
                    stream: false,
                    max_tokens: 650,
                    temperature: 0,
                    messages: [{ role: 'system', content: repairPrompt }]
                };
                turnCallAudit.receiptRepair++;
                const repairResponse = await fetch(apiBase() + '/chat/completions', {
                    method: 'POST',
                    signal: controller.signal,
                    headers: { ...authHeaders(), 'Content-Type': 'application/json', ...attributionHeaders() },
                    body: JSON.stringify(repairBody)
                });
                if (repairResponse.ok) {
                    const repairData = await repairResponse.json();
                    const repairMessage = repairData.choices?.[0]?.message || {};
                    const repairCall = (repairMessage.tool_calls || []).find(call =>
                        call.function?.name === 'commit_world_turn');
                    let repairedReceipt = repairCall
                        ? parseWorldToolArguments(repairCall.function?.arguments || '{}')
                        : safeParseJSONRepair(String(repairMessage.content || '')
                            .replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, ''));
                    if (!repairedReceipt) repairedReceipt = extractInlineWorldTurnReceipt(repairMessage.content || '');
                    if (isPlainObject(repairedReceipt?.scene)
                        && Array.isArray(repairedReceipt.events)
                        && Array.isArray(repairedReceipt.entity_updates)) {
                        const committed = commitWorldTurnReceipt(world, sess, repairedReceipt, receiptContext, 'repair_receipt');
                        if (committed.actionResult?.ledgerEntry) structuredChronicle = committed.actionResult.ledgerEntry;
                        repairedReceiptApplied = true;
                        console.warn('Horde Engine: missing turn receipt repaired without regenerating the narrative.');
                    }
                }
            } catch (repairError) {
                if (repairError?.name === 'AbortError') throw repairError;
                console.warn('Horde Engine: receipt-only repair failed; freezing unverified state.', repairError.message);
            }
        }

        // Absolute safety floor: the narrative may remain visible, but no
        // unverified mutation is inferred from it. Record a canonical no-op
        // receipt and an audit failure so every turn still has a transaction.
        let frozenReceiptApplied = false;
        if (!successfulStateCall && !inlineStateApplied && !repairedReceiptApplied && fullText.trim()) {
            const frame = buildWorldSceneFrame(world, sess);
            const noOpReceipt = {
                summary: 'No model-authored state receipt was available; unverified state was frozen.',
                scene: {
                    player_location_id: frame.player_location_id,
                    player_location_changed: false,
                    present_character_ids: frame.present_character_ids
                },
                events: [],
                entity_updates: Object.entries(frame.activities).map(([entity_id, details]) => ({
                    entity_id,
                    location_id: frame.player_location_id,
                    activity: details.activity || '',
                    interacting_with: details.interacting_with || []
                })),
                state_updates: {}
            };
            const committed = commitWorldTurnReceipt(world, sess, noOpReceipt, receiptContext, 'frozen_no_receipt');
            committed.audit.rejected.push({
                index: -1, type: 'receipt', reason: 'missing_mandatory_receipt',
                actor_id: '', detail: 'Narrative preserved; unverified state mutations were frozen.'
            });
            frozenReceiptApplied = true;
        }
        sess.lastTurnStateSource = successfulStateCall ? 'tool_call'
            : inlineStateApplied ? 'inline_rescue'
                : repairedReceiptApplied ? 'receipt_repair'
                    : frozenReceiptApplied ? 'frozen_no_receipt' : 'none';

        // Track how often real action turns produce no state by any route. Two
        // in a row is a strong signal this model will not use tools, and opens
        // the plain-text channel on the next turn. A tool call clears it, so a
        // model that recovers stops being nagged.
        if (command !== 'init' && command !== 'look' && command !== 'continue') {
            const shyList = Array.isArray(state.globalSettings.toolShyModels)
                ? state.globalSettings.toolShyModels : [];
            if (successfulStateCall || inlineStateApplied || repairedReceiptApplied) {
                sess.toolCallMissStreak = 0;
                // It does call tools after all — stop pre-arming the text channel.
                if (shyList.includes(modelId)) {
                    state.globalSettings.toolShyModels = shyList.filter(id => id !== modelId);
                }
            } else {
                sess.toolCallMissStreak = (sess.toolCallMissStreak || 0) + 1;
                if (sess.toolCallMissStreak >= 2 && !shyList.includes(modelId)) {
                    state.globalSettings.toolShyModels = [...shyList, modelId].slice(-20);
                    console.warn(`Horde Engine: remembering that "${modelId}" does not emit tool calls; the text channel will open from turn one in future sessions.`);
                }
            }
        }

        // --- FOLLOW-UP LOOP ---
        // If the AI made a tool call but produced no narrative text,
        // we need a second API call to get the actual story response.
        const toolResultNeedsNarration = toolCalls.some(call => call.function?.name === 'investigate_secret');
        if (toolCalls.length > 0 && (!fullText.trim() || resolvedCheckThisTurn || toolResultNeedsNarration)) {
            console.log("Horde Engine: Tool call with no text — requesting narrative follow-up.");

            // Update label during follow-up call
            if (dmTyping) dmTypingLabel.textContent = 'DM is writing a follow-up...';

            try {
                const followUpMessages = [
                    ...messages,
                    { role: 'assistant', content: fullText.trim() || null, tool_calls: toolCalls },
                    ...toolResponses,
                    { role: 'user', content: `[SYSTEM: The requested tools have been processed. Now finish the response:\n1. Narrate the authoritative result in vivid, immersive prose.${resolvedCheckThisTurn ? ' A dice check was resolved by the engine: use the tool result exactly, never invent or reroll it, and do not repeat the pre-roll setup.' : ' If a secret was revealed, narrate its discovery.'}\n2. If canon changed and ledger_update was not already supplied, add a one-sentence [MEMORY] line.${directorNotesRequired ? '\n3. DIRECTOR MODE remains required: append the active preset\'s <details><summary>Plot Momentum</summary>...</details> block as the final element.' : ''}]` }
                ];

                const followUpBody = { ...requestBody, messages: sanitizeMessagesForProvider(followUpMessages), stream: false };
                delete followUpBody.tools;
                followUpBody.tool_choice = 'none';

                turnCallAudit.narrativeFollowUp++;
                const followUpResponse = await fetch(apiBase() + '/chat/completions', {
                    method: 'POST',
                    signal: controller.signal,
                    headers: { 
                        ...authHeaders(),
                        'Content-Type': 'application/json',
                        ...attributionHeaders()
                    },
                    body: JSON.stringify(followUpBody)
                });

                if (followUpResponse.ok) {
                    const followUpData = await followUpResponse.json();
                    fullText = followUpData.choices?.[0]?.message?.content || '';
                }
            } catch(followUpErr) {
                if (followUpErr?.name === 'AbortError') throw followUpErr;
                console.error("Horde Engine: Follow-up request failed", followUpErr);
            }
        }

        if (questFallbackMode && fullText.trim()) {
            const fallbackQuestUpdate = extractQuestUpdateDirective(fullText);
            fullText = fallbackQuestUpdate.text;
            if (fallbackQuestUpdate.updates.length) {
                applyQuestUpdates(world, sess, fallbackQuestUpdate.updates);
            }
            questFallbackMode = false;
        }

        // --- NARRATIVE RESCUE ---
        // Empty narrative with no provider error usually means a reasoning model
        // (e.g. DeepSeek Pro) spent its entire token budget thinking, or the
        // provider filtered the reply. One plain, tool-free retry with a bigger
        // budget rescues most of these before we give up.
        if (!fullText.trim() && command !== 'init') {
            console.warn(`Horde Engine: empty narrative (finish_reason=${lastFinishReason}, reasoning=${reasoningSeen}) — attempting rescue call.`);
            if (dmTyping) { dmTyping.style.display = 'flex'; if (dmTypingLabel) dmTypingLabel.textContent = 'DM lost their train of thought — retrying...'; }
            try {
                // Non-streaming call can't reset the idle timer — give it its own window
                armGenerationIdleTimeout(isLocalProvider() ? configuredLocalIdleTimeout : 90000);
                const rescueBody = {
                    model: modelId,
                    stream: false,
                    max_tokens: Math.max(1500, parseInt(world.maxTokens) || 2048),
                    messages: sanitizeMessagesForProvider([
                        ...messages,
                        { role: 'user', content: `[SYSTEM: Your previous attempt produced no readable prose${reasoningSeen ? ' — it was consumed by internal reasoning' : ''}. ${streamedToolCalls.size > 0 ? 'The engine has ALREADY applied your state changes — do not call tools again. ' : ''}Write the narrative response NOW. No tools, JSON, or OOC commentary.${directorNotesRequired ? ' After the prose, append the active preset\'s required <details><summary>Plot Momentum</summary>...</details> Director block.' : ''}]` }
                    ])
                };
                const rescueResp = await fetch(apiBase() + '/chat/completions', {
                    method: 'POST',
                    signal: controller.signal,
                    headers: { 'Content-Type': 'application/json', ...authHeaders(), ...attributionHeaders() },
                    body: JSON.stringify(rescueBody)
                });
                if (rescueResp.ok) {
                    const rescueData = await rescueResp.json();
                    fullText = rescueData.choices?.[0]?.message?.content || '';
                    if (fullText.trim()) console.log('Horde Engine: rescue call succeeded.');
                }
            } catch (rescueErr) {
                if (rescueErr?.name === 'AbortError') throw rescueErr;
                console.error('Horde Engine: rescue call failed', rescueErr);
            }
        }

        // When the first response was completely empty, receipt repair was
        // deliberately deferred until after narrative rescue. Reconcile the
        // final prose now so an emergency narrative cannot bypass the canonical
        // transaction layer.
        if (fullText.trim() && !successfulStateCall && !inlineStateApplied
            && !repairedReceiptApplied && !frozenReceiptApplied) {
            try {
                const finalFrame = buildWorldSceneFrame(world, sess);
                const finalRepairPrompt = `[WORLD TURN RECEIPT REPAIR]\nReturn JSON only. Do not rewrite the narrative. Produce one commit_world_turn receipt with scene, events, entity_updates, state_updates and summary. Actor-scope every action; NPC movement never moves the player; intent/attempt/in_progress does not mutate state; scene is the complete ending checksum.\nAuthoritative scene: ${JSON.stringify(finalFrame)}\nPlayer input: ${JSON.stringify(String(submittedInput || userInput).slice(0, 1200))}\nFinal narrative: ${JSON.stringify(String(fullText).slice(0, 7000))}`;
                turnCallAudit.receiptRepair++;
                const finalRepairResponse = await fetch(apiBase() + '/chat/completions', {
                    method: 'POST',
                    signal: controller.signal,
                    headers: { ...authHeaders(), 'Content-Type': 'application/json', ...attributionHeaders() },
                    body: JSON.stringify({
                        model: structuredModelFor(world), stream: false, max_tokens: 650, temperature: 0,
                        messages: [{ role: 'system', content: finalRepairPrompt }]
                    })
                });
                if (finalRepairResponse.ok) {
                    const data = await finalRepairResponse.json();
                    const message = data.choices?.[0]?.message || {};
                    let repaired = safeParseJSONRepair(String(message.content || '')
                        .replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, ''));
                    if (!repaired) repaired = extractInlineWorldTurnReceipt(message.content || '');
                    if (isPlainObject(repaired?.scene) && Array.isArray(repaired.events)
                        && Array.isArray(repaired.entity_updates)) {
                        const committed = commitWorldTurnReceipt(world, sess, repaired, receiptContext, 'repair_receipt');
                        if (committed.actionResult?.ledgerEntry) structuredChronicle = committed.actionResult.ledgerEntry;
                        repairedReceiptApplied = true;
                    }
                }
            } catch (error) {
                if (error?.name === 'AbortError') throw error;
                console.warn('Horde Engine: final narrative receipt repair failed.', error.message);
            }
            if (!repairedReceiptApplied) {
                const frame = buildWorldSceneFrame(world, sess);
                const committed = commitWorldTurnReceipt(world, sess, {
                    summary: 'No model-authored state receipt was available; unverified state was frozen.',
                    scene: {
                        player_location_id: frame.player_location_id,
                        player_location_changed: frame.player_location_id !== receiptPlayerStart,
                        present_character_ids: frame.present_character_ids
                    },
                    events: [],
                    entity_updates: [],
                    state_updates: {}
                }, receiptContext, 'frozen_no_receipt');
                committed.audit.rejected.push({
                    index: -1, type: 'receipt', reason: 'missing_mandatory_receipt',
                    actor_id: '', detail: 'Final narrative preserved; unverified state mutations were frozen.'
                });
                frozenReceiptApplied = true;
            }
            sess.lastTurnStateSource = repairedReceiptApplied ? 'receipt_repair' : 'frozen_no_receipt';
        }

        // Hide the persistent typing indicator
        if (dmTyping) dmTyping.style.display = 'none';

        // Successful turn: Increment world time ("continue" extends the same moment — no time passes)
        if (command !== "init" && command !== "look" && command !== "continue" && (!isReroll || restoredRerollSnapshot)) {
            if (!sess.turnCount) sess.turnCount = 1;
            sess.turnCount++;
            // The prompt used the start-of-turn cast. Re-sync after advancing
            // the clock so the persisted HUD/cast matches the displayed time.
            syncNPCSchedules(world, sess);
        }

        // Save the DM's narrative response
        if (fullText.trim()) {
            // Prefer the structured chronicle field, tolerate legacy [MEMORY]
            // syntax, then repair a missing update with a tiny classifier call.
            let cleanText = fullText;
            const taggedChronicle = extractWorldLedgerEntry(fullText);
            let extractedChronicle = structuredChronicle || null;
            let chronicleSource = structuredChronicle ? 'structured' : '';
            
            // Rerolls already restored turnSnapshot before any tools ran. Leave
            // the old message metadata intact until addWorldMessage archives it
            // in versionLedgerEntries; deleting by text here could also erase a
            // newly generated take that happened to produce the same milestone.

            if (!extractedChronicle && taggedChronicle) {
                extractedChronicle = appendWorldLedgerEntry(sess, taggedChronicle);
                if (extractedChronicle) chronicleSource = 'tagged';
            }
            cleanText = stripWorldLedgerDirective(fullText);

            const kernelConfig = normalizeWorldKernelConfig(world);
            if (!extractedChronicle && (!kernelConfig.enabled || kernelConfig.memoryMode === 'semantic')
                && command !== 'init' && command !== 'look') {
                turnCallAudit.chronicleClassifier++;
                const recovered = await recoverWorldLedgerEntry(structuredModelFor(world), submittedInput || userInput, cleanText, controller.signal);
                extractedChronicle = appendWorldLedgerEntry(sess, recovered);
                if (extractedChronicle) {
                    chronicleSource = 'classifier';
                    console.log(`Horde Engine: Chronicle recovered — ${extractedChronicle}`);
                }
            }
            if (!extractedChronicle && !kernelConfig.enabled && command !== 'init' && command !== 'look') {
                const localFallback = buildLocalNarrativeLedgerFallback(submittedInput || userInput, cleanText);
                extractedChronicle = appendWorldLedgerEntry(sess, localFallback);
                if (extractedChronicle) {
                    chronicleSource = 'local';
                    console.log(`Horde Engine: Chronicle recovered locally — ${extractedChronicle}`);
                }
            }
            if (extractedChronicle) {
                console.log(`Horde Engine: Chronicle Updated — ${extractedChronicle}`);
            }
            sess.ledgerDiagnostics = {
                turn: Math.max(1, parseInt(sess.turnCount) || 1),
                status: extractedChronicle ? 'updated' : 'no_change',
                source: chronicleSource || 'none'
            };

            // Scrubber: Remove any hallucinated location/system headers the AI might have copied from context
            cleanText = cleanText.replace(/\[Loc:.*?\]\s*/gi, '').replace(/\[DISTANT EVENT.*?\]:\s*/gi, '').trim();
            // Scrub tool/engine artifacts models emit as plain text (JSON payloads, tool-call wrappers)
            cleanText = scrubNarrativeArtifacts(cleanText);
            if (state.globalSettings.slopStripper) cleanText = stripSlop(cleanText);
            cleanText = applyRegexScripts(cleanText, 'ai');

            // Prose scanners are now auditors, never state authorities. A sentence
            // beginning with "The Chapel..." or describing Rowena walking there
            // must not teleport the player. Flag contradictions for Metadata while
            // leaving canonical state exactly where validated events put it.
            const startLocation = turnSnapshot?.session?.playerLocation;
            const movedThisTurn = !!startLocation && sess.playerLocation !== startLocation;
            const startOutfit = turnSnapshot?.session?.outfit;
            const outfitChangedThisTurn = startOutfit !== undefined && sess.outfit !== startOutfit;
            const narratedLocationCandidate = (command !== 'init' && !movedThisTurn)
                ? detectNarratedLocation(world, sess, cleanText) : null;
            const narratedPresenceCandidates = command !== 'init'
                ? detectNarratedPresence(world, sess, cleanText) : [];
            const narratedOutfitCandidate = (command !== 'init' && !outfitChangedThisTurn)
                ? detectNarratedOutfit(cleanText) : null;
            const audit = sess.lastTurnAudit;
            if (audit) {
                if (narratedLocationCandidate && narratedLocationCandidate.id !== sess.playerLocation) {
                    audit.rejected.push({
                        index: -1, type: 'narrative', reason: 'uncommitted_player_location_claim',
                        actor_id: 'player', detail: `Prose suggested ${narratedLocationCandidate.id}; canonical location remains ${sess.playerLocation}.`
                    });
                }
                narratedPresenceCandidates.forEach(hit => {
                    audit.rejected.push({
                        index: -1, type: 'narrative', reason: 'uncommitted_npc_presence_claim',
                        actor_id: hit.id, detail: hit.evidence
                    });
                });
                if (narratedOutfitCandidate && narratedOutfitCandidate.toLowerCase() !== String(sess.outfit || '').toLowerCase()) {
                    audit.rejected.push({
                        index: -1, type: 'narrative', reason: 'uncommitted_outfit_claim',
                        actor_id: 'player', detail: narratedOutfitCandidate
                    });
                }
            }
            if (sess.lastTurnStateSource === 'none' && (committedMovement || committedOutfit)) {
                sess.lastTurnStateSource = 'local_intent';
            }
            // The scene went somewhere this world has never heard of.
            const missingPlace = sess.unresolvedDestination || '';
            sess.unresolvedDestination = '';
            const endingWitnesses = sessionNpcs(world, sess)
                .filter(npc => sess.entityStates?.[npc.id]?.location === sess.playerLocation && isNpcActive(sess.entityStates[npc.id]))
                .map(npc => npc.id);

            const dmMsg = addWorldMessage('dm', cleanText, {
                location: sess.playerLocation,
                narrativeAuditWarnings: audit?.rejected?.filter(item => item.type === 'narrative').length || undefined,
                worldAudit: audit ? {
                    accepted: audit.accepted,
                    informational: audit.informational,
                    rejected: audit.rejected.length,
                    version: audit.world_state_version,
                    castChecksum: audit.cast_checksum_match
                } : undefined,
                missingPlace: missingPlace || undefined,
                isReroll,
                command,
                ledgerEntry: extractedChronicle,
                stateSource: sess.lastTurnStateSource || 'none',
                stateFallbackArmed: command !== 'look' && command !== 'init',
                ledgerStatus: sess.ledgerDiagnostics?.source === 'none' && !extractedChronicle
                    ? 'classifier_empty' : (sess.ledgerDiagnostics?.source || ''),
                callAudit: turnCallAudit ? {
                    ...turnCallAudit,
                    foregroundTotal: Object.values(turnCallAudit).reduce((sum, value) => sum + value, 0),
                    kernelMode: normalizeWorldKernelConfig(world).enabled ? 'scene_kernel' : 'legacy'
                } : undefined,
                turnSnapshot,
                witnesses: endingWitnesses,
                deferPersist: true
            });
            const postSnapshot = captureWorldTurnState(world, sess);
            if (isReroll) {
                dmMsg.versionSnapshots = Array.isArray(dmMsg.versionSnapshots)
                    ? dmMsg.versionSnapshots
                    : [dmMsg.postSnapshot || null];
                dmMsg.versionSnapshots.push(postSnapshot);
            } else {
                dmMsg.versionSnapshots = [postSnapshot];
            }
            // versionSnapshots is the single canonical store. Keeping an
            // identical postSnapshot beside it doubled every ordinary turn in
            // persisted timelines, especially painfully in large worlds.
            delete dmMsg.postSnapshot;
            const continuityCapability = window.HordeLabs?.taskCapabilities?.()
                .find(task => task.id === 'continuity_sentinel');
            if (window.HordeLabs?.policyFor('worlds') === 'audit' && continuityCapability?.available) {
                void window.HordeLabs.propose('continuity_sentinel', {
                    narrative: cleanText.slice(0, 6500),
                    preFrame: {
                        playerLocationId: startLocation || '',
                        outfit: startOutfit || '',
                        presentCharacterIds: turnSnapshot?.session?.presentCharacterIds || []
                    },
                    postFrame: buildWorldSceneFrame(world, sess),
                    proposedReceipt: sess.lastTurnAudit || {},
                    allowedEntityIds: ['player', ...sessionNpcs(world, sess).map(npc => npc.id)]
                }, { mode: 'worlds', background: true, priority: 15 }).catch(() => {});
            }
            await saveState();
        } else if (command === "init") {
            // INIT RESCUE: If the AI failed to introduce the world, provide a basic descriptive fallback
            const fallbackIntro = `You arrive at ${locName}. ${locDesc}\n\n[SYSTEM: The AI failed to generate a custom introduction. You can now take your first action.]`;
            const fallbackCommit = sess.lastTurnAudit
                ? { audit: sess.lastTurnAudit }
                : commitEngineWorldNoOp(world, sess, 'engine_intro', 'Engine fallback introduction.');
            const fallbackMsg = addWorldMessage('dm', fallbackIntro, {
                location: sess.playerLocation, turnSnapshot, stateSource: 'engine_intro',
                worldAudit: {
                    accepted: fallbackCommit.audit.accepted,
                    informational: fallbackCommit.audit.informational,
                    rejected: fallbackCommit.audit.rejected.length,
                    version: fallbackCommit.audit.world_state_version,
                    castChecksum: fallbackCommit.audit.cast_checksum_match
                },
                deferPersist: true
            });
            fallbackMsg.versionSnapshots = [captureWorldTurnState(world, sess)];
            delete fallbackMsg.postSnapshot;
            await saveState();
            fullText = fallbackIntro; // Set fullText so sync logic has something to work with if needed
        } else {
            const why = lastFinishReason === 'length'
                ? 'It hit its token limit — likely spending the whole budget on hidden reasoning. Raise Max Tokens in World Studio, or turn Reasoning off/down for this world.'
                : reasoningSeen
                    ? 'It produced only hidden reasoning and no prose. Try raising Max Tokens, lowering Reasoning effort, or Reroll.'
                    : 'The provider may have filtered or dropped the reply. Try Reroll, or a different model.';
            throw new Error(`The model returned no narrative response (even after a retry). ${why}`);
        }

        // NOTE: narrative-based position sync was removed. NPC movement is governed
        // by: tool calls (pinned) > schedules > scene population, with engine events
        // announcing any engine-driven arrival/departure to the DM for narration.

        renderWorldPlayState();

        // World imagination is a background replenishment pass, never part of
        // the blocking chat transaction. Deterministic schedules, events and
        // goals have already advanced locally; this call only seeds future
        // surprises when the configured interval says the queue needs it.
        if (command !== 'init' && !isReroll && shouldRunWorldAgent(world, sess) && hasApiCredentials()) {
            runWorldAgent(world, sess).then(async () => {
                await saveState();
                if (state.activeWorldId === world.id) renderWorldPlayState();
            }).catch(agentError => console.warn('Horde Engine: background world agent skipped —', agentError.message));
        }

        // Trigger non-blocking rolling episodic memory consolidation for World Mode
        if (!normalizeWorldKernelConfig(world).enabled
            || normalizeWorldKernelConfig(world).memoryMode === 'semantic') {
            consolidateSessionEpisodicMemory(sess, world).catch(err => {
                console.warn("World consolidation error in background:", err);
            });
        }

    } catch (err) {
        const dmTypingEl = document.getElementById('world-dm-typing');
        if (dmTypingEl) dmTypingEl.style.display = 'none';

        // Roll back generated consequences from the failed/aborted turn. A
        // failed reroll restores the previously selected take; a normal turn
        // returns to its pre-action snapshot.
        const rollbackSnapshot = isReroll ? failureRestoreSnapshot : turnSnapshot;
        if (world && sess && rollbackSnapshot) restoreWorldTurnState(world, sess, rollbackSnapshot);
        if (sess && !isReroll && historyStartLength !== null) sess.history.splice(historyStartLength);

        // Player-directed movement is deterministic and was validated against
        // the exit graph before generation began. Preserve it even when the DM
        // prose fails, just like clicking an exit already does. Also preserve
        // the submitted action in history so retrying cannot accidentally
        // execute "exit" a second time from the new destination.
        let movementPreserved = false;
        if (world && sess && committedMovement && !isReroll) {
            const target = world.locations.find(location => location.id === committedMovement.destinationId);
            const movement = target ? movePlayerAlongWorldPath(world, sess, target, { showTravelToast: false }) : null;
            if (movement?.ok && movement.moved) {
                movementPreserved = true;
                if (normalizeWorldGameRules(world).modules.livingWorld) {
                    updatePlaystyleProfile(sess, submittedInput);
                    runLivingWorldTick(world, sess);
                }
                sess.turnCount = Math.max(1, parseInt(sess.turnCount) || 1) + 1;
                syncNPCSchedules(world, sess);
                evaluateQuestProgress(world, sess);
                const destinationName = target.name || committedMovement.destinationId;
                addWorldMessage('user', submittedInput, {
                    location: sess.playerLocation,
                    deferPersist: true
                });
                addWorldMessage('system', `Movement completed to ${destinationName}. The DM narration did not complete; continue from here or try again.`, {
                    location: sess.playerLocation,
                    deferPersist: true
                });
                const input = document.getElementById('world-user-input');
                if (input) input.value = '';
            }
        }
        if (sess && committedOutfit && !isReroll) {
            sess.outfit = committedOutfit.to;
            // If movement already preserved the submitted action, its outfit
            // component belongs to that same action. Otherwise preserve a
            // clothing-only action on its own instead of returning it to the box.
            if (!movementPreserved) {
                addWorldMessage('user', submittedInput, {
                    location: sess.playerLocation,
                    deferPersist: true
                });
                addWorldMessage('system', `Outfit updated to ${committedOutfit.to}. The DM narration did not complete; continue from here or try again.`, {
                    location: sess.playerLocation,
                    deferPersist: true
                });
                const input = document.getElementById('world-user-input');
                if (input) input.value = '';
            }
        }
        if (!movementPreserved && !committedOutfit && !command && submittedInput) {
            const input = document.getElementById('world-user-input');
            if (input) input.value = submittedInput;
        }
        try { if (sess) await saveState(); } catch (saveErr) { console.error('Rollback persistence failed:', saveErr); }

        // A user stop is informational. A configured idle timeout is actionable:
        // the backend may still be working, so tell the user how to extend it.
        if (err.name === 'AbortError') {
            console.log('World turn aborted');
            if (generationTimedOut) {
                const seconds = Math.max(1, Math.round(activeIdleTimeoutMs / 1000));
                const prefix = movementPreserved ? 'Movement saved. ' : '';
                showToast(`${prefix}Generation received no data for ${seconds}s and was stopped. Increase or disable the local timeout in Settings → AI & Models.`, 'error');
            } else {
                showToast(movementPreserved ? 'Movement saved; DM generation stopped.' : 'Generation stopped.', 'info');
            }
            renderWorldPlayState();
            return;
        }

        console.error("Horde Engine: Fatal Error", err);
        const friendlyError = humanizeApiError(err) || "Unknown error";

        if (command === "init") {
            const fallbackIntro = `[ENGINE FALLBACK]\n\nYou arrive at ${locName}. ${locDesc}\n\n(Note: The AI failed to respond: ${friendlyError})`;
            if (sess) {
                const fallbackCommit = commitEngineWorldNoOp(world, sess, 'engine_intro', 'Engine error fallback introduction.');
                const fallbackSnapshot = captureWorldTurnState(world, sess);
                const fallbackMsg = addWorldMessage('dm', fallbackIntro, {
                    location: sess.playerLocation, turnSnapshot: fallbackSnapshot,
                    stateSource: 'engine_intro',
                    worldAudit: {
                        accepted: fallbackCommit.audit.accepted,
                        informational: fallbackCommit.audit.informational,
                        rejected: fallbackCommit.audit.rejected.length,
                        version: fallbackCommit.audit.world_state_version,
                        castChecksum: fallbackCommit.audit.cast_checksum_match
                    },
                    deferPersist: true
                });
                fallbackMsg.versionSnapshots = [captureWorldTurnState(world, sess)];
                delete fallbackMsg.postSnapshot;
                await saveState();
                renderWorldPlayState();
            }
        } else {
            showToast((movementPreserved ? 'Movement saved. ' : '') + 'Horde Engine Error: ' + friendlyError, 'error');
            renderWorldPlayState();
        }
    } finally {
        if (timeoutId) clearTimeout(timeoutId);
        worldTurnInProgress = false;
        worldGenController = null;
        const btn = document.getElementById('world-send-btn');
        if (btn) {
            const ended = world && sess && normalizePlayerRulesState(world, sess)?.status === 'dead';
            btn.disabled = !!ended;
            btn.classList.remove('stop');
            btn.innerHTML = `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>`;
        }
    }
}

/**
 * Narrated-presence safety net.
 *
 * The DM writes "Emily is right there, three feet away" and then forgets to
 * record it with npc_moves — so the engine still believes she is elsewhere and
 * the cast panel insists the room is empty. This reads the finished narration
 * and pulls in characters the prose clearly places in the scene.
 *
 * It is deliberately conservative, because a false positive teleports someone:
 *  - Names inside spoken dialogue never count. Talking ABOUT Emily is not Emily
 *    being here — that single rule removes most false positives.
 *  - A name needs a present-tense verb of presence or an explicit "here/there",
 *    not merely a mention ("whatever Greg did downstairs" places nobody).
 *  - A nearby elsewhere-marker ("upstairs", "in the kitchen") vetoes the match.
 *  - An NPC the narrative explicitly placed somewhere else (pinned) is never
 *    overridden: an actual npc_moves always outranks this inference.
 */
const PRESENCE_VERBS = 'is|s|stands|sits|leans|steps|walks|moves|enters|arrives|appears|freezes|pauses|turns|looks|watches|grins|smiles|laughs|nods|shrugs|reaches|holds|takes|blocks|waits|follows|lingers|hovers|crosses|slips|ducks|settles|glances|tilts|shifts|stares|hesitates|hovers|kneels|crouches|rises|stops';
// Deliberately specific. A bare "away" would veto "three feet away", which is
// as present as it gets, and a bare "left" would veto "her left hand".
const ELSEWHERE_MARKERS = /\b(?:downstairs|upstairs|outside|elsewhere|in the (?:kitchen|hall|garden|car|basement|yard|other room|distance)|from (?:the )?(?:other|another) room|(?:from|out of|through) (?:his|her|their|the) (?:office|room|hall|kitchen|basement|car|yard)|back (?:home|at work)|still (?:at|in) (?:the|her|his|work|school)|(?:had|has|have) (?:left|gone)|is gone|walks? away|walked away|turns? away|turned away|far away|miles away)\b/i;

// "Mrs. Harrington" must key on "Harrington", never on "Mrs." — otherwise one
// title would match every titled character in the cast.
const NAME_TITLES = /^(?:mr|mrs|ms|miss|dr|ser|sir|lord|lady|master|mistress|sister|brother|father|mother|captain|foreman|duchess|duke|thornmother)\.?$/i;

// A person's voice, hands or breath cannot be somewhere the person is not, so
// "Emily's voice cuts through the shower noise" places Emily in the room. Her
// *possessions* prove nothing — "Emily's boombox on the toilet tank" says only
// that the boombox is here. That distinction is the whole point of this list.
const PERSON_ATTRIBUTES = 'voice|hand|hands|fingers|arm|arms|elbow|shoulder|shoulders|face|eyes|gaze|mouth|lips|smile|grin|laugh|laughter|breath|breathing|hair|head|knee|knees|leg|legs|foot|feet|body|silhouette|shadow|weight|skin|throat|chin|jaw|brow|voice_';

function stripSpokenDialogue(text) {
    // Double and smart quotes only: apostrophes are possessives, not speech.
    return String(text || '')
        .replace(/```[\s\S]*?```/g, ' ')
        .replace(/<details[\s\S]*?<\/details>/gi, ' ')
        .replace(/"[^"]*"/g, ' ')
        .replace(/[“][^”]*[”]/g, ' ');
}

function detectNarratedPresence(world, sess, narrative) {
    const prose = stripSpokenDialogue(narrative);
    if (!prose.trim()) return [];
    const found = [];
    sessionNpcs(world, sess).forEach(npc => {
        const entState = sess.entityStates?.[npc.id];
        if (!entState || !isNpcActive(entState)) return;
        if (entState.location === sess.playerLocation) return;   // already here
        if (isNpcPinned(sess, entState)) return;                 // explicitly placed elsewhere

        const fullName = String(npc.name || '').trim();
        if (!fullName) return;
        const parts = fullName.split(/[\s,]+/).filter(Boolean);
        let firstName = parts[0] || '';
        if (NAME_TITLES.test(firstName) && parts[1]) firstName = parts[1];
        const variants = [...new Set([fullName, firstName])]
            .filter(name => name.length >= 3)
            .map(name => name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
        if (!variants.length) return;

        for (const variant of variants) {
            // "Emily's voice cuts through" — a person's own voice/hands/breath
            // place them here even when their name never governs a verb.
            const attributeMatch = prose.match(new RegExp(
                `\\b${variant}[’']s\\s+(?:${PERSON_ATTRIBUTES})\\b([^.!?\\n]{0,60})`, 'i'));
            if (attributeMatch && !ELSEWHERE_MARKERS.test(attributeMatch[1] || '')) {
                found.push({ id: npc.id, name: fullName, evidence: attributeMatch[0].trim().slice(0, 80) });
                break;
            }

            const pattern = new RegExp(
                `\\b${variant}\\b(?:[’']s)?\\s+(?:${PRESENCE_VERBS})\\b([^.!?\\n]{0,60})`, 'i');
            const match = prose.match(pattern);
            if (!match) continue;
            const tail = match[1] || '';
            if (ELSEWHERE_MARKERS.test(tail)) break;   // "Greg is downstairs"
            // "is/s" alone is weak — require it to land on an actual presence cue.
            const verb = match[0].slice(variant.replace(/\\/g, '').length).trim().split(/\s+/)[0].toLowerCase();
            if ((verb === 'is' || verb === 's')
                && !/\b(?:right )?(?:here|there|beside|next to|in front of|behind|across from|standing|sitting|leaning|waiting|already)\b/i.test(tail)) {
                break;
            }
            found.push({ id: npc.id, name: fullName, evidence: match[0].trim().slice(0, 80) });
            break;
        }
    });
    return found;
}

/**
 * The mirror of the presence scanner, for the player's own position: the prose
 * opens somewhere new ("The bathroom hits you like a wall of wet heat") but no
 * location_id was ever recorded, so the HUD still shows the old room.
 *
 * Only ever moves to a place that already exists and is reachable — it will not
 * invent geography from prose. Requires a scene-setting frame rather than a bare
 * mention, so "you can see the Great Hall from here" does not relocate anyone.
 */
function detectNarratedLocation(world, sess, narrative) {
    const opening = stripSpokenDialogue(narrative).slice(0, 400);
    if (!opening.trim()) return null;
    const contextualMove = opening.match(
        /\byou\b[^.!?]{0,20}\b(?:go|walk|head|move|run|ride|climb|return|enter|step|cross|duck|slip|arrive)(?:s|ed|ped)?\b\s*(?:(?:to|towards?|into|inside|through|across|up|down|in)\s+)?([^.!?;,]{1,80})/i);
    if (contextualMove) {
        const phrase = String(contextualMove[1] || '')
            .split(/\s+(?:and|then|while|as|where|before|after)\s+/i)[0]
            .trim();
        const contextualTarget = resolveWorldMovementTarget(typeof worldForSession === 'function' ? worldForSession(world, sess) : world, sess.playerLocation, phrase);
        if (contextualTarget) return contextualTarget;
    }
    for (const location of world.locations || []) {
        if (location.id === sess.playerLocation) continue;
        const name = String(location.name || '').trim();
        if (name.length < 4) continue;
        const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const framed = new RegExp(
            `(?:^|[.!?]\\s+)(?:the\\s+)?${escaped}\\b|` +                       // opens the scene
            `\\byou(?:'re| are)?\\s+(?:now\\s+)?(?:step|steps|stepped|walk|walks|walked|enter|enters|entered|move|moved|slip|slipped|duck|ducked|arrive|arrived|stand|standing)\\b[^.!?]{0,40}\\b${escaped}\\b`,
            'i');
        if (!framed.test(opening)) continue;
        if (!findWorldTravelPath(typeof worldForSession === 'function' ? worldForSession(world, sess) : world, sess.playerLocation, location.id)) continue;
        return location;
    }
    return null;
}

function applyNarratedLocation(world, sess, narrative) {
    const target = detectNarratedLocation(world, sess, narrative);
    if (!target) return null;
    const previous = sess.playerLocation;
    sess.playerLocation = target.id;
    console.warn(`Horde Engine: the scene reads as "${target.name}" but no location_id was recorded — moved the player there from ${previous}.`);
    return { from: previous, to: target.id, name: target.name };
}

// --- Narrated outfit --------------------------------------------------------
// The outfit field only ever changed when the model called the tool, and until
// now nothing in the prompt told it to — so the usual case, prose describing
// the player getting changed with no tool call, left the HUD showing whatever
// they wore an hour ago. This is the same last line of defence that presence
// and location already have: if the prose plainly says it, believe the prose.

// What counts as the player putting something on. Deliberately narrow: it must
// be the PLAYER (you/your), and it must be an act of dressing.
const OUTFIT_CHANGE_PATTERNS = Object.freeze([
    // "you change into the red dress", "you slip into your armour"
    /\byou\b[^.!?]{0,30}\b(?:change|changed|slip|slipped|dress|dressed|shrug|shrugged)\s+(?:in)?to\s+([^.!?;]{3,80})/i,
    // "you pull on your boots", "you put on the cloak", "you don the mask"
    /\byou\b[^.!?]{0,20}\b(?:put|pull|throw|tug)\s+on\s+([^.!?;]{3,80})/i,
    /\byou\b[^.!?]{0,20}\bdon(?:ned)?\s+([^.!?;]{3,80})/i,
    // "you are now wearing …", "you're dressed in …"
    /\byou(?:'re| are)\s+(?:now\s+)?(?:wearing|dressed\s+in|clad\s+in)\s+([^.!?;]{3,80})/i,
    // "you strip out of the gown and into …" — take the destination
    /\byou\b[^.!?]{0,40}\bout\s+of\s+[^.!?;]{3,40}\s+and\s+into\s+([^.!?;]{3,80})/i
]);

// Losing the outfit is a change too, and has no "into what" to capture.
const OUTFIT_REMOVAL_PATTERN =
    /\byou\b[^.!?]{0,30}\b(?:strip|stripped|undress|undressed|peel|peeled)\b[^.!?]{0,20}\b(?:off|out of|down|naked|bare)\b/i;

// A garment phrase is a noun phrase; the sentence carrying on past the clothes
// is not. Detecting that by "contains an -ing word" was wrong — half of what
// people wear is a participle ("riding breeches", "travelling leathers",
// "evening gown"). A clause gives itself away by STARTING with the participle,
// or by having a subject doing something.
// A participle only starts a clause when something follows it as an object —
// "folding YOUR clothes", "leaving THE room". Followed by a plain noun it is
// describing the garment: "travelling leathers", "evening gown".
const OUTFIT_CLAUSE_START = new RegExp(
    '^(?:and\\s+)?(?:' +
        '\\w+ing\\s+(?:the|a|an|your|his|her|their|its|my|our|it|them)\\b' +
        '|(?:he|she|they|it|you|his|her|their|its|the|a|an)\\b[^,]{0,60}?\\b' +
          '(?:is|are|was|were|says?|said|moves?|moved|turns?|turned|looks?|looked' +
          '|watches?|watched|steps?|stepped|leaves?|left|stands?|stood|feels?|felt|hangs?|hung)\\b' +
    ')', 'i');

// What the player does next, once dressed. "and belt on the sword", "and pull
// the hood up" — a garment list never continues with one of these.
const OUTFIT_NEXT_ACTION = new RegExp(
    '\\s+and\\s+(?=(?:' +
        '\\S+\\s+(?:on|off|onto|into|over|around|up|out|to|at|through)\\b' +
        '|(?:pull|put|belt|buckle|strap|sling|pick|take|grab|head|leave|step|walk|cross' +
        '|tie|lace|fasten|sheathe|draw|push|open|close|climb|descend|ring|wait|turn|look|follow' +
        '|disappear|vanish|stride|hurry|slip|move|go|set)\\b' +
    '))', 'i');

/**
 * Cut a captured phrase back to just the clothes.
 *
 * Real narration runs on — "the grey dress, folding your own clothes into the
 * sack", "the court gown, and the Duchess-Regent's eyes move over you". A list
 * of garments is worth keeping ("a white shirt, black breeches and boots"), so
 * segments are kept while they still read as garments and dropped from the
 * first one that reads as the story continuing.
 */
function trimOutfitPhrase(phrase) {
    let text = String(phrase || '');
    // Cut the trailing clauses FIRST, so the garment scan below is judging
    // clothes rather than the rest of the sentence.
    // The next action: "…leathers and belt on the sword" is one garment and one
    // thing done afterwards; the following preposition gives it away. "black
    // and gold doublet" has none, so it survives.
    text = text.split(OUTFIT_NEXT_ACTION)[0];
    // And why they put it on: "a heavy wool cloak against the rain".
    text = text.split(/\s+(?:against|despite|because|for\s+(?:the\s+)?(?:warmth|cold|rain|journey|road|night|evening|occasion)|to\s+(?:keep|ward|hide|cover|stave))\b/i)[0];

    // What is left may still be a list of garments, which is worth keeping.
    const kept = [];
    for (const rawSegment of text.split(',')) {
        const segment = rawSegment.trim();
        if (!segment) break;
        // Once at least one garment has been captured, a relative clause is
        // narration about it, not another item: "the dress, which Maera left
        // out". Keep "that black dress" valid when it is the actual first
        // garment rather than treating every demonstrative as a clause.
        if (kept.length && /^(?:which|who|that)\b/i.test(segment)) break;
        if (OUTFIT_CLAUSE_START.test(segment)) break;
        // Real outfits are often a coordinated list without commas ("a thin
        // pair of boxer shorts and an old tshirt"). Action/scene clauses have
        // already been cut by OUTFIT_NEXT_ACTION and OUTFIT_CLAUSE_START, so a
        // six-word ceiling discarded valid clothing far more often than it
        // protected us. Keep the capture bounded, but allow a natural outfit.
        if (segment.split(/\s+/).length > 14) break;
        kept.push(segment);
        if (kept.length >= 4) break;
    }
    return kept.join(', ').replace(/[,;:.\s]+$/, '').trim();
}

function normalizeOutfitItem(phrase) {
    const item = trimOutfitPhrase(String(phrase || '')
        .replace(/\s+/g, ' ')
        .replace(/^(?:my|your|the|a|an|some)\s+/i, '')
        .trim());
    if (item.length < 2 || item.length > 100) return '';
    if (/^(?:it|them|this|that|something|anything|nothing|clothes?)$/i.test(item)) return '';
    return item;
}

/**
 * Player-authored clothing is authoritative input, not something the model
 * should have to remember to repeat in a tool call. Return a small operation so
 * putting on boots adds boots, taking off a coat removes only the coat, while
 * changing into an outfit replaces the full description.
 */
function detectPlayerOutfitIntent(input) {
    const prose = stripSpokenDialogue(String(input || '')).replace(/[*_~]/g, ' ');
    if (!prose.trim()) return null;
    // Deterministic state only follows completed first-person actions. Attempts,
    // refusals, hypotheticals and explicit negation belong to narration.
    if (/\bI\b[^.!?]{0,35}\b(?:try|tries|tried|attempt|attempted|want|wanted|plan|planned|might|may|could|would|refuse|refused|don['’]?t|do not|didn['’]?t|did not|never)\b[^.!?]{0,40}\b(?:change|dress|slip|swap|put|pull|throw|tug|don|wrap|fasten|buckle|strap|take|peel|strip|undress)\b/i.test(prose)) {
        return null;
    }
    const replacePatterns = [
        /\bI\b[^.!?]{0,25}\b(?:change|changed|slip|slipped|dress|dressed)\s+(?:in)?to\s+([^.!?;]{2,100})/i,
        // Treat explicit first-person clothing declarations as authoritative.
        // Players routinely type contractions without apostrophes ("im wearing")
        // or with a curly apostrophe; neither should require the model to repeat
        // the same fact in a tool call before the HUD can reflect it.
        /\bI(?:\s+am|['’]?m)\s+(?:now\s+)?(?:wearing|dressed\s+in|clad\s+in)\s+([^.!?;]{2,100})/i,
        /\bI\s+have\s+([^.!?;]{2,100}?)\s+on\b/i,
        /\bmy\s+(?:current\s+)?outfit\s+is\s+([^.!?;]{2,100})/i,
        /\bI\b[^.!?]{0,25}\b(?:swap|swapped)\s+(?:my\s+)?(?:outfit|clothes?)\s+(?:for|to)\s+([^.!?;]{2,100})/i
    ];
    for (const pattern of replacePatterns) {
        const match = prose.match(pattern);
        const item = normalizeOutfitItem(match?.[1]);
        if (item) return { mode: 'replace', item };
    }
    const addPatterns = [
        /\bI\b[^.!?]{0,20}\b(?:put|pull|throw|tug|slip|slipped)\s+on\s+([^.!?;]{2,100})/i,
        /\bI\b[^.!?]{0,20}\bdon(?:ned)?\s+([^.!?;]{2,100})/i,
        /\bI\b[^.!?]{0,20}\b(?:wrap|wrapped|fasten|fastened|buckle|buckled|strap|strapped)\s+([^.!?;]{2,100}?)(?:\s+(?:around|over|onto)\b|$)/i
    ];
    for (const pattern of addPatterns) {
        const match = prose.match(pattern);
        const item = normalizeOutfitItem(match?.[1]);
        if (item) return { mode: 'add', item };
    }
    const remove = prose.match(
        /\bI\b[^.!?]{0,20}\b(?:take|took|pull|pulled|slip|slipped|peel|peeled|throw|threw)\s+off\s+([^.!?;]{2,100})/i);
    if (remove) {
        const item = normalizeOutfitItem(remove[1]);
        if (item) return { mode: 'remove', item };
    }
    if (/\bI\b[^.!?]{0,25}\b(?:strip|stripped|undress|undressed|get|got)\b[^.!?]{0,20}\b(?:naked|undressed|bare|out of my clothes)\b/i.test(prose)) {
        return { mode: 'clear', item: '' };
    }
    return null;
}

function applyPlayerOutfitIntent(sess, input) {
    const intent = detectPlayerOutfitIntent(input);
    if (!intent) return null;
    const previous = String(sess.outfit || '').trim();
    let next = previous;
    if (intent.mode === 'replace') {
        next = intent.item;
    } else if (intent.mode === 'clear') {
        next = 'Undressed.';
    } else if (intent.mode === 'add') {
        const alreadyWorn = previous.toLowerCase().includes(intent.item.toLowerCase());
        next = alreadyWorn ? previous : [previous, intent.item].filter(Boolean).join(', ');
    } else if (intent.mode === 'remove') {
        const escaped = intent.item.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        next = previous
            .replace(new RegExp(`(?:^|,|\\band\\b)\\s*(?:the\\s+|a\\s+|an\\s+)?${escaped}\\s*(?=,|\\band\\b|$)`, 'ig'), '')
            .replace(/\s*,\s*,+/g, ', ')
            .replace(/^\s*(?:,|and)\s*|\s*(?:,|and)\s*$/gi, '')
            .trim();
        if (next === previous && previous.toLowerCase().includes(intent.item.toLowerCase())) {
            next = previous.replace(new RegExp(escaped, 'ig'), '').replace(/\s*,\s*,+/g, ', ').trim();
        }
        if (!next) next = 'Undressed.';
    }
    next = String(next || '').replace(/\s+/g, ' ').replace(/^,\s*|\s*,$/g, '').slice(0, 240);
    if (!next || next.toLowerCase() === previous.toLowerCase()) return null;
    sess.outfit = next;
    console.log(`Horde Engine: Player-authored outfit ${intent.mode} — "${previous}" → "${next}".`);
    return { from: previous, to: next, mode: intent.mode, item: intent.item };
}

/**
 * Read a change of clothes out of the prose. Returns the new outfit text, or
 * null when the narration says nothing definite — a wrong guess here would
 * dress the player in something they never put on, so anything ambiguous is
 * left alone for the tool call to settle.
 */
function detectNarratedOutfit(narrative) {
    // Dialogue is somebody TALKING about clothes, not the player changing.
    const prose = stripSpokenDialogue(String(narrative || ''));
    if (!prose.trim()) return null;

    for (const pattern of OUTFIT_CHANGE_PATTERNS) {
        const match = pattern.exec(prose);
        if (!match) continue;
        let outfit = String(match[1] || '')
            .replace(/\s+/g, ' ')
            .replace(/^(?:your|the|a|an|some)\s+/i, '')
            .replace(/[,;:]\s*$/, '')
            .trim();
        outfit = trimOutfitPhrase(outfit);
        if (outfit.length < 3 || outfit.length > 80) continue;
        // A pronoun or a bare verb is not a garment.
        if (/^(?:it|them|this|that|him|her|something|anything|nothing)$/i.test(outfit)) continue;
        return outfit;
    }
    if (OUTFIT_REMOVAL_PATTERN.test(prose)) return 'Undressed.';
    return null;
}

function applyNarratedOutfit(sess, narrative) {
    const detected = detectNarratedOutfit(narrative);
    if (!detected) return null;
    const previous = String(sess.outfit || '');
    // Do not churn the field when the prose merely restates what they wear.
    if (previous.trim().toLowerCase() === detected.trim().toLowerCase()) return null;
    sess.outfit = detected;
    console.warn(`Horde Engine: the prose changed the player's outfit but no outfit_update was recorded — set to "${detected}".`);
    return { from: previous, to: detected };
}

function applyNarratedPresence(world, sess, narrative) {
    const detected = detectNarratedPresence(world, sess, narrative);
    detected.forEach(hit => {
        sess.entityStates[hit.id].location = sess.playerLocation;
        // The narration explicitly placed them here. Give that placement the
        // same authority as npc_moves so the next schedule sync cannot
        // immediately teleport them back out and make the cast flicker.
        sess.entityStates[hit.id].pinnedUntilTurn = (sess.turnCount || 1) + 6;
        console.warn(`Horde Engine: "${hit.name}" was narrated present but never recorded — pulled into the scene ("${hit.evidence}").`);
    });
    return detected;
}

function rollForScenePopulation(locationId, persist = true) {
    const world = state.worlds.find(w => w.id === state.activeWorldId);
    const sess = getCurrentWorldSession();
    if (!world || !sess) return;
    if (!normalizeWorldGameRules(world).modules.livingWorld) return;

    console.log(`Horde Engine: Rolling for scene density at ${locationId}`);

    // Every other subsystem draws from stableWorldRoll so that restoring a
    // snapshot and replaying a turn reproduces it exactly. Scene population is
    // replayed on reroll too (via applyUserDirectedMovement), so it seeds from
    // the same turn coordinates instead of Math.random — otherwise rerolling
    // silently rewrites who is standing in the room.
    const sceneSeed = `${world.id}|${sess.id}|${sess.turnCount || 1}|${locationId}`;

    // 1. Determine how many "extra" people should be here (0 to 3)
    const densityRoll = Math.floor(stableWorldRoll(`${sceneSeed}|density`) * 4); // 0, 1, 2, or 3
    if (densityRoll === 0) return;

    // 2. Get NPCs that are "eligible" to be in this room
    const availableNPCs = world.entities.filter(ent => {
        if (ent.type !== 'npc') return false;
        if (!isVisibleToSession(ent, sess)) return false; // other timeline's NPC
        const entState = sess.entityStates[ent.id];
        if (!entState) return false;
        if (!isNpcActive(entState)) return false;         // the dead don't wander

        // Don't pull NPCs already here
        if (entState.location === locationId) return false;

        // ARBITRATION: never randomly teleport an NPC the narrative placed somewhere,
        // and never override NPCs whose whereabouts a schedule governs.
        if (isNpcPinned(sess, entState)) return false;
        const hasTimelineSchedule = Object.prototype.hasOwnProperty.call(sess.npcScheduleOverrides || {}, ent.id)
            && sess.npcScheduleOverrides[ent.id].length > 0;
        if (hasTimelineSchedule || (world.hudConfig?.enableSchedules && ent.schedule && ent.schedule.length > 0)) return false;

        // Resident Logic: Are they "Home"?
        // Home may be written as an id or a name, in any casing, so resolve it
        // the same way every other location reference in the engine is.
        const homeRef = ent.homeLocation || ent.startLocation;
        const belongsHere = !!homeRef && getLocationRef(world, homeRef)?.id === locationId;
        const npcRoll = stableWorldRoll(`${sceneSeed}|${ent.id}`);

        if (belongsHere) {
            // Time-based probability
            const hour = getWorldTimeData(world, sess).hours24;
            const isNight = hour < 8 || hour >= 20; // 8 PM to 8 AM

            const homeChance = isNight ? 0.95 : 0.50; // 95% at night, 50% during day
            return npcRoll < homeChance;
        }

        // Wanderer Logic
        const isMentionedElsewhere = world.locations.some(l => l.description && l.description.toLowerCase().includes(ent.name.toLowerCase()));
        const isWanderer = !homeRef && !isMentionedElsewhere;

        // 15% chance for a wanderer to appear
        return isWanderer && npcRoll < 0.15;
    });

    // 3. Order deterministically and pick. (A `0.5 - random()` comparator is
    // both non-uniform and inconsistent, which some engines reject outright.)
    const selected = [...availableNPCs]
        .sort((a, b) => stableWorldRoll(`${sceneSeed}|pick|${a.id}`) - stableWorldRoll(`${sceneSeed}|pick|${b.id}`))
        .slice(0, densityRoll);

    selected.forEach(npc => {
        if (sess.entityStates[npc.id]) {
            sess.entityStates[npc.id].location = locationId;
            // Presence must be storytold, never silent — tell the DM they're here.
            queueEngineEvent(sess, `${npc.name} is present in this location — establish their presence naturally in the scene.`);
            console.log(`Horde Engine: Living World — ${npc.name} moved to scene.`);
        }
    });

    if (persist) saveState().catch(() => {});
}

// --- Session-scoped world views ---
// NPCs improvised mid-story (npc_introduced) belong to the timeline that created
// them; other timelines never see them. Template NPCs (no sessionOrigin) are
// global. Locations stay global by design: timelines share geography, not people.
function isVisibleToSession(item, sess) {
    return !item.sessionOrigin || !sess || item.sessionOrigin === sess.id;
}
function sessionNpcs(world, sess) {
    return world.entities.filter(e => e.type === 'npc' && isVisibleToSession(e, sess));
}

function sessionLocations(world, sess) {
    const extras = isPlainObject(sess?.dynamicExits) ? sess.dynamicExits : {};
    return (world.locations || []).filter(location => isVisibleToSession(location, sess)).map(location => {
        const added = Array.isArray(extras[location.id]) ? extras[location.id] : [];
        return added.length ? { ...location, exits: [...(Array.isArray(location.exits) ? location.exits : []), ...added] } : location;
    });
}

function worldForSession(world, sess) {
    return { ...world, locations: sessionLocations(world, sess), entities: world.entities };
}

function addSessionDynamicExit(sess, fromLocationId, targetName) {
    if (!sess || !fromLocationId || !targetName) return;
    if (!isPlainObject(sess.dynamicExits)) sess.dynamicExits = {};
    const exits = Array.isArray(sess.dynamicExits[fromLocationId]) ? sess.dynamicExits[fromLocationId] : [];
    const wanted = `to ${String(targetName).trim()}`;
    if (!exits.some(exit => getExitTargetName(exit).toLowerCase() === String(targetName).trim().toLowerCase())) exits.push(wanted);
    sess.dynamicExits[fromLocationId] = exits.slice(0, 100);
}

function rotatingWorldWindow(items, limit, turn = 0) {
    if (!Array.isArray(items) || items.length <= limit) return Array.isArray(items) ? [...items] : [];
    const start = Math.abs(Math.trunc(Number(turn) || 0) * Math.max(1, limit)) % items.length;
    return Array.from({ length: limit }, (_, index) => items[(start + index) % items.length]);
}

function selectForegroundNpcs(world, sess, allPresent, userInput, limit = 16) {
    if (allPresent.length <= limit) return allPresent;
    const input = String(userInput || '').toLowerCase();
    const scored = allPresent.map(npc => {
        const entState = sess.entityStates?.[npc.id] || {};
        let score = npc.isMajor ? 100 : 0;
        if (input && npcReferenceVariants(npc).some(name => name.length > 1 && input.includes(name))) score += 200;
        if (entState.relationshipToPlayer) score += 50;
        if (entState.interactingWith?.includes('player')) score += 80;
        score += Math.min(20, (entState.observations || []).length);
        return { npc, score };
    });
    const priority = scored.filter(item => item.score > 0).sort((a, b) => b.score - a.score).slice(0, limit);
    const chosen = new Set(priority.map(item => item.npc.id));
    const rotating = rotatingWorldWindow(scored.filter(item => !chosen.has(item.npc.id)), limit - priority.length, sess.turnCount || 0);
    return [...priority.map(item => item.npc), ...rotating.map(item => item.npc)];
}

function normalizedNpcNameParts(name) {
    const clean = String(name || '').toLowerCase()
        .replace(/[’']/g, '')
        .replace(/[^a-z0-9\s-]/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
    const parts = clean.split(/\s+/).filter(Boolean);
    while (parts.length > 1 && NAME_TITLES.test(parts[0])) parts.shift();
    return { clean, parts };
}

function npcReferenceVariants(npc) {
    const { clean, parts } = normalizedNpcNameParts(npc?.name);
    const aliases = Array.isArray(npc?.aliases) ? npc.aliases : [];
    return [...new Set([
        clean,
        parts.join(' '),
        parts[0],
        parts.length > 1 ? parts[parts.length - 1] : '',
        ...aliases.map(alias => normalizedNpcNameParts(alias).clean)
    ].filter(value => value && value.length >= 3))];
}

function findReferencedWorldNpcs(world, sess, text) {
    const haystack = ` ${normalizedNpcNameParts(text).clean} `;
    if (!haystack.trim()) return [];
    return sessionNpcs(world, sess).filter(npc =>
        npcReferenceVariants(npc).some(variant => haystack.includes(` ${variant} `)));
}

// Death is permanent: dead/gone NPCs are excluded from schedules, population,
// and scene presence until the DM explicitly changes their status back.
function isNpcActive(entState) {
    return !entState || (entState.status !== 'dead' && entState.status !== 'gone');
}

function resolveNpcId(world, llmNpcId, sess = null) {
    if (!llmNpcId) return null;
    const rawQuery = String(llmNpcId).trim().toLowerCase();
    const query = normalizedNpcNameParts(llmNpcId).clean;
    const pool = (sess ? world.entities.filter(e => isVisibleToSession(e, sess)) : world.entities)
        .filter(e => e.type === 'npc');

    // 1. Direct ID match
    let npc = pool.find(e => String(e.id || '').toLowerCase() === rawQuery);

    // 2. Exact full name or declared alias.
    if (!npc) {
        const exactMatches = pool.filter(e => npcReferenceVariants(e).includes(query));
        if (exactMatches.length === 1) npc = exactMatches[0];
    }

    // 3. A partial name is accepted only when it identifies one person.
    // `find()` used to send every "Sister" or shared surname to whichever NPC
    // happened to be first in the array.
    if (!npc) {
        const matches = pool.filter(e => npcReferenceVariants(e).some(variant =>
            variant.includes(query) || query.includes(variant)));
        if (matches.length === 1) npc = matches[0];
    }

    return npc ? npc.id : null;
}

const CHECK_GUARDED_ACTION_FIELDS = Object.freeze([
    'location_id', 'location_introduced', 'time_skip_minutes', 'transactions',
    'inventory_add', 'inventory_remove', 'stat_changes', 'capability_progress', 'player_condition_updates',
    'outfit_update', 'player_identity_update', 'quests_update', 'npc_moves',
    'npc_introduced', 'npc_goal_updates', 'npc_disposition_changes',
    'npc_relationship_updates', 'npc_observations', 'world_events',
    'location_state_updates', 'faction_updates', 'economy_updates',
    'schedule_updates', 'player_preference_updates', 'relationship_update',
    'relationship_event', 'memory_write', 'ledger_update'
]);

function sanitizeCheckOutcomeActions(raw) {
    if (!isPlainObject(raw)) return null;
    const clean = {};
    CHECK_GUARDED_ACTION_FIELDS.forEach(field => {
        if (raw[field] !== undefined) clean[field] = safeJsonClone(raw[field]);
    });
    return Object.keys(clean).length ? clean : null;
}

function processStructuredActions(args) {
    // Optional explicit targets let the background World Agent finish safely
    // even if the player switches sessions while its request is in flight.
    // Keep the public one-argument signature stable for extensions/audits.
    const explicitWorld = arguments[1] || null;
    const explicitSession = arguments[2] || null;
    const world = explicitWorld || state.worlds.find(w => w.id === state.activeWorldId);
    const sess = explicitSession || getCurrentWorldSession();
    if (!world || !sess) return null;
    normalizeLivingWorldState(world, sess);
    normalizePlayerRulesState(world, sess);
    const modules = normalizeWorldGameRules(world).modules;
    let ledgerEntry = null;
    let movementResult = null;
    let statResult = null;
    let transactionResults = [];
    let checkResults = [];
    let checkOutcomeResults = [];
    let capabilityProgressResults = [];
    let conditionResults = [];
    const moduleRejections = [];
    const rejectDisabledField = (field, module) => {
        if (args[field] !== undefined && args[field] !== null
            && (!Array.isArray(args[field]) || args[field].length > 0)) {
            moduleRejections.push({ field, module, reason: 'module_disabled' });
        }
    };

    // Resolve uncertainty before touching any result-dependent state. A model
    // must place those mutations in on_success/on_failure. Any guarded field at
    // the same level as a check is rejected, preventing a failed roll from
    // accidentally committing the successful outcome.
    if (Array.isArray(args.checks) && args.checks.length) {
        const requestedChecks = args.checks.slice(0, 10);
        checkResults = performAuthoritativeChecks(world, sess, requestedChecks);
        checkResults.forEach((result, index) => {
            if (result.pending || result.reason) return;
            const requested = requestedChecks[index] || {};
            const branch = sanitizeCheckOutcomeActions(result.success ? requested.on_success : requested.on_failure);
            if (branch) checkOutcomeResults.push(processStructuredActions(branch, world, sess));
        });
        const guarded = { ...args };
        delete guarded.checks;
        CHECK_GUARDED_ACTION_FIELDS.forEach(field => {
            if (guarded[field] !== undefined) {
                moduleRejections.push({ field, module: 'checks', reason: 'unconditional_update_beside_check' });
                delete guarded[field];
            }
        });
        args = guarded;
    }

    if (Array.isArray(args.capability_progress) && args.capability_progress.length) {
        capabilityProgressResults = applyWorldCapabilityProgress(world, sess, args.capability_progress);
    }

    // --- DYNAMIC WORLD GROWTH: register new locations FIRST so a move to
    // a just-introduced location in the same tool call resolves correctly.
    if (args.location_introduced && Array.isArray(args.location_introduced)) {
        args.location_introduced.forEach(li => {
            if (!li.name || findFuzzyLocation(li.name, sessionLocations(world, sess))) return; // already exists here
            const requestedId = String(li.id || '').trim().replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 100);
            const newLoc = {
                id: requestedId && !world.locations.some(location => location.id === requestedId)
                    ? requestedId : 'loc_' + Date.now() + Math.floor(Math.random() * 1000),
                name: li.name.trim(),
                region: (li.region || '').trim(),
                mapType: ['region', 'route', 'building', 'outdoor', 'room', 'area'].includes(li.map_type) ? li.map_type : '',
                parentLocationId: '',
                mapFloor: String(li.floor || '').trim().slice(0, 80),
                description: li.description || 'A newly discovered place.',
                hiddenDescription: '',
                exits: [],
                secrets: [],
                sessionOrigin: sess.id
            };
            // Link exits both ways to an anchor (stated connection, else current location)
            const visibleLocations = sessionLocations(world, sess);
            const anchor = (li.connects_to && findFuzzyLocation(li.connects_to, visibleLocations))
                || visibleLocations.find(l => l.id === sess.playerLocation);
            const mapParent = li.parent_location_id && findFuzzyLocation(li.parent_location_id, visibleLocations);
            if (mapParent) newLoc.parentLocationId = mapParent.id;
            if (anchor) {
                newLoc.exits.push(`to ${anchor.name}`);
                addSessionDynamicExit(sess, anchor.id, newLoc.name);
            }
            world.locations.push(newLoc);
            showToast(`🗺️ New location discovered: ${newLoc.name}`, 'success');
            if (document.getElementById('w-locations-list') && typeof renderWorldLocations === 'function' && state.editingWorld?.id === world.id) {
                renderWorldLocations();
            }
        });
    }

    if (args.location_id) {
        const playerState = normalizePlayerRulesState(world, sess);
        const targetLoc = findFuzzyLocation(args.location_id, sessionLocations(world, sess));
        if (playerState.status !== 'active') {
            movementResult = { ok: false, moved: false, reason: playerState.status, path: [] };
        } else if (targetLoc) {
            movementResult = movePlayerAlongWorldPath(world, sess, targetLoc);
            if (movementResult.moved) {
                showToast(`Moved to ${targetLoc.name}`, 'info');
            } else if (!movementResult.ok) {
                console.warn(`Horde Engine: rejected unreachable player move from ${sess.playerLocation} to ${targetLoc.id}`);
            }
        } else {
            movementResult = { ok: false, moved: false, reason: 'unknown_destination', path: [] };
            console.warn(`Horde Engine: LLM attempted to move player to unknown location_id: ${args.location_id}`);
        }
    }

    if (args.time_skip_minutes !== undefined && args.time_skip_minutes !== null) {
        const skip = parseInt(args.time_skip_minutes) || 0;
        if (skip > 0) {
            sess.bonusTimeMinutes = (sess.bonusTimeMinutes || 0) + skip;
            const hrs = Math.floor(skip / 60);
            const mins = skip % 60;
            let timeStr = hrs > 0 ? `${hrs}h${mins > 0 ? ` ${mins}m` : ''}` : `${mins}m`;
            showToast(`Time advanced by ${timeStr}`, 'info');
            // The clock just jumped past events scheduled inside the skipped
            // window (a dawn raid during an eight-hour sleep). Fire them now,
            // in the turn that skipped, rather than one action later.
            runLivingWorldTick(world, sess);
            syncNPCSchedules(world, sess);
        }
    }

    if (Array.isArray(args.transactions)) {
        transactionResults = executeCommerceTransactions(world, sess, args.transactions);
        // A refused trade used to vanish: the fiction said money changed hands
        // and the purse never moved. Say why, loudly enough to act on.
        transactionResults.filter(result => !result.success).forEach(result => {
            const explanation = {
                currency_not_configured: 'this world has no currency stat — set one in World Studio → HUD & Stats',
                no_market_and_no_price: 'no market here and the DM gave no price',
                item_not_sold_here: 'that item is not stocked at this location',
                ambiguous_item: 'the item name matched more than one thing in stock',
                cannot_afford: 'not enough funds',
                insufficient_stock: 'the seller does not have that many',
                item_not_owned: 'the player does not own that',
                module_disabled: 'the commerce module is off for this world'
            }[result.reason] || result.reason;
            console.warn(`Horde Engine: transaction refused (${result.type} ${result.item}) — ${explanation}.`);
            if (result.reason === 'currency_not_configured' || result.reason === 'no_market_and_no_price') {
                showToast(`Purchase not settled: ${explanation}.`, 'warning');
            }
        });
    }

    if (Array.isArray(args.player_condition_updates)) {
        conditionResults = applyPlayerConditionUpdates(world, sess, args.player_condition_updates);
    }
    
    if (modules.inventory && args.inventory_add && Array.isArray(args.inventory_add)) {
        args.inventory_add.forEach(value => {
            const item = globalThis.HordeRpgMechanics?.normalizeItem(value) || value;
            const name = globalThis.HordeRpgMechanics?.itemName(item) || String(item || '');
            if (!globalThis.HordeRpgMechanics?.findItem(sess.inventory, name)) {
                sess.inventory.push(item);
                showToast(`Item taken: ${name}`, 'info');
            }
        });
    }

    if (modules.inventory && args.inventory_remove && Array.isArray(args.inventory_remove)) {
        args.inventory_remove.forEach(item => {
            const target = String(item || '').trim().toLowerCase();
            if (!target) return;
            // Fuzzy match: the LLM may say "potion" for "healing potion"
            const nameOf = value => (globalThis.HordeRpgMechanics?.itemName(value) || String(value || '')).toLowerCase();
            let idx = sess.inventory.findIndex(i => nameOf(i) === target);
            if (idx === -1) idx = sess.inventory.findIndex(i => nameOf(i).includes(target) || target.includes(nameOf(i)));
            if (idx !== -1) {
                const removed = sess.inventory.splice(idx, 1)[0];
                Object.keys(sess.equipment || {}).forEach(slot => { if (sess.equipment[slot] === removed?.id) sess.equipment[slot] = null; });
                showToast(`Item removed: ${globalThis.HordeRpgMechanics?.itemName(removed) || removed}`, 'info');
            }
        });
    }

    if (args.stat_changes && typeof args.stat_changes === 'object') {
        statResult = applyPlayerStatChanges(world, sess, args.stat_changes, {
            cause: String(args.stat_change_cause || 'The player suffered a lasting consequence.').slice(0, 240)
        });
    }

    if (args.outfit_update) {
        sess.outfit = args.outfit_update;
        showToast('Outfit Updated', 'info');
    }

    if (isPlainObject(args.player_identity_update)) {
        const update = args.player_identity_update;
        const identity = isPlainObject(sess.playerIdentity) ? sess.playerIdentity : (sess.playerIdentity = {});
        if (!isPlainObject(sess.legalStanding)) sess.legalStanding = {};
        const setText = (source, target, limit) => {
            if (update[source] !== undefined) identity[target] = String(update[source] || '').slice(0, limit);
        };
        setText('role', 'role', 100);
        setText('social_rank', 'socialRank', 80);
        setText('title', 'title', 120);
        setText('legal_status', 'legalStatus', 100);
        if (update.faction_id !== undefined) {
            const query = String(update.faction_id || '').trim().toLowerCase();
            const faction = sess.factions.find(item =>
                item.id.toLowerCase() === query || item.name.toLowerCase() === query);
            identity.factionId = faction?.id || '';
        }
        const mutateList = (target, additions, removals) => {
            const current = new Set((Array.isArray(identity[target]) ? identity[target] : [])
                .map(item => String(item || '').trim()).filter(Boolean));
            (Array.isArray(additions) ? additions : []).forEach(item => {
                const value = String(item || '').trim();
                if (value) current.add(value.slice(0, 200));
            });
            const removeKeys = new Set((Array.isArray(removals) ? removals : [])
                .map(item => String(item || '').trim().toLowerCase()).filter(Boolean));
            identity[target] = [...current].filter(item => !removeKeys.has(item.toLowerCase())).slice(0, 40);
        };
        mutateList('privileges', update.privileges_add, update.privileges_remove);
        mutateList('obligations', update.obligations_add, update.obligations_remove);
        mutateList('holdings', update.holdings_add, update.holdings_remove);
        if (identity.factionId && update.legal_status !== undefined) {
            const standing = sess.legalStanding[identity.factionId] || {
                heat: 0, crimes: [], lastChangedTurn: 0
            };
            standing.status = identity.legalStatus;
            if (update.heat_change !== undefined) {
                standing.heat = livingClamp((standing.heat || 0) + Number(update.heat_change || 0), 0, 100);
            }
            if (update.crime) {
                standing.crimes = [...(Array.isArray(standing.crimes) ? standing.crimes : []),
                    String(update.crime).slice(0, 200)].slice(-30);
            }
            standing.lastChangedTurn = sess.turnCount || 1;
            sess.legalStanding[identity.factionId] = standing;
        }
        const reason = String(update.reason || '').trim().slice(0, 240);
        if (reason) {
            appendWorldLedgerEntry(sess, `Status changed: ${reason}`);
            showToast('Social position changed', 'info');
        }
    }

    if (args.ledger_update) {
        ledgerEntry = appendWorldLedgerEntry(sess, args.ledger_update);
        if (ledgerEntry) showToast('Ledger Updated', 'info');
    }

    if (args.label) {
        if (!sess.revealedSecrets) sess.revealedSecrets = [];
        if (!sess.revealedSecrets.includes(args.label)) {
            sess.revealedSecrets.push(args.label);
            showToast(`Secret Uncovered: ${args.label}`, 'success');
        }
    }

    if (args.threads_update && Array.isArray(args.threads_update)) {
        if (!sess.threads) sess.threads = [];
        args.threads_update.forEach(t => {
            if (!t.id || !t.text) return;
            const existing = sess.threads.find(x => x.id === t.id);
            if (existing) {
                existing.text = t.text;
                if (t.status) existing.status = t.status;
                if (t.status === 'resolved') showToast(`🧵 Thread resolved: ${t.text.slice(0, 50)}`, 'success');
            } else {
                sess.threads.push({ id: t.id, text: String(t.text).slice(0, 200), status: t.status || 'open', turnOpened: sess.turnCount || 1 });
                showToast(`🧵 New story thread`, 'info');
            }
        });
    }

    if (modules.schedules && args.schedule_updates && Array.isArray(args.schedule_updates)) {
        args.schedule_updates.forEach(update => {
            const npcId = resolveNpcId(world, update?.npc_id, sess);
            if (!npcId || !Array.isArray(update.blocks)) return;
            const validBlocks = update.blocks.map(block => {
                const location = getLocationRef(world, block?.location_id);
                const time = String(block?.time || '');
                if (!location || !/^([01]\d|2[0-3]):[0-5]\d$/.test(time)) return null;
                const days = (Array.isArray(block.days) ? block.days : (block.day ? [block.day] : []))
                    .map(day => String(day || '').trim()).filter(Boolean).slice(0, 7);
                return { time, locationId: location.id, activity: String(block.activity || '').slice(0, 160), ...(days.length ? { days } : {}) };
            }).filter(Boolean);
            const existing = Array.isArray(sess.npcScheduleOverrides[npcId]) ? sess.npcScheduleOverrides[npcId] : [];
            const combined = update.replace === false ? [...existing, ...validBlocks] : validBlocks;
            const byTime = new Map();
            combined.forEach(block => byTime.set(block.time, block));
            sess.npcScheduleOverrides[npcId] = [...byTime.values()]
                .sort((a, b) => a.time.localeCompare(b.time))
                .slice(0, 1000);
            if (update.reason) {
                const entState = sess.entityStates[npcId] || (sess.entityStates[npcId] = { location: sess.playerLocation, observations: [] });
                entState.observations = entState.observations || [];
                entState.observations.push({
                    id: livingId('obs', `${npcId}_schedule_${sess.turnCount || 1}`),
                    text: `[Schedule changed] ${String(update.reason).slice(0, 240)}`,
                    turn: sess.turnCount || 1
                });
            }
        });
    }

    if (modules.livingWorld && args.world_events && Array.isArray(args.world_events)) {
        const now = getWorldTimeData(world, sess);
        args.world_events.forEach(update => {
            if (!update || (!update.id && !update.title)) return;
            const id = String(update.id || livingId('event', update.title)).slice(0, 80);
            let event = sess.scheduledEvents.find(item => item.id === id);
            if (!event) {
                event = {
                    id,
                    title: String(update.title || 'Unnamed event').slice(0, 120),
                    description: String(update.description || update.title || 'Something changes in the world.').slice(0, 500),
                    status: 'scheduled',
                    dueTurn: update.due_in_turns !== undefined
                        ? (sess.turnCount || 1) + Math.max(1, parseInt(update.due_in_turns) || 1)
                        : (update.due_in_minutes !== undefined ? null : (sess.turnCount || 1) + 1),
                    dueMinute: update.due_in_minutes !== undefined
                        ? now.currentTotalMinutes + Math.max(1, parseInt(update.due_in_minutes) || 1)
                        : null,
                    repeatEveryTurns: 0,
                    repeatEveryMinutes: 0,
                    locationId: null,
                    conditionOnTrigger: '',
                    conditionDurationTurns: 0,
                    factionId: '',
                    influenceChange: 0,
                    lastTriggeredTurn: 0
                };
                sess.scheduledEvents.push(event);
            }
            if (update.title !== undefined) event.title = String(update.title).slice(0, 120);
            if (update.description !== undefined) event.description = String(update.description).slice(0, 500);
            if (['scheduled', 'cancelled'].includes(update.status)) event.status = update.status;
            if (update.due_in_turns !== undefined) {
                event.dueTurn = (sess.turnCount || 1) + Math.max(1, parseInt(update.due_in_turns) || 1);
                if (update.due_in_minutes === undefined) event.dueMinute = null;
            }
            if (update.due_in_minutes !== undefined) {
                event.dueMinute = now.currentTotalMinutes + Math.max(1, parseInt(update.due_in_minutes) || 1);
                if (update.due_in_turns === undefined) event.dueTurn = null;
            }
            if (update.repeat_every_turns !== undefined) event.repeatEveryTurns = Math.max(0, parseInt(update.repeat_every_turns) || 0);
            if (update.repeat_every_minutes !== undefined) event.repeatEveryMinutes = Math.max(0, parseInt(update.repeat_every_minutes) || 0);
            if (update.location_id !== undefined) event.locationId = getLocationRef(world, update.location_id)?.id || null;
            if (update.condition_on_trigger !== undefined) event.conditionOnTrigger = String(update.condition_on_trigger || '').slice(0, 120);
            if (update.condition_duration_turns !== undefined) event.conditionDurationTurns = Math.max(0, parseInt(update.condition_duration_turns) || 0);
            if (update.faction_id !== undefined) event.factionId = String(update.faction_id || '').slice(0, 80);
            if (update.influence_change !== undefined) event.influenceChange = livingClamp(update.influence_change, -20, 20);
        });
        sess.scheduledEvents = sess.scheduledEvents.slice(-500);
    }

    // Pre-register factions so one atomic tool call can also assign territory,
    // location control, event effects, and inter-faction relations to them.
    if (modules.livingWorld && args.faction_updates && Array.isArray(args.faction_updates)) {
        args.faction_updates.forEach(update => {
            if (!update || (!update.id && !update.name)) return;
            const query = String(update.id || update.name).toLowerCase();
            if (sess.factions.some(item => item.id.toLowerCase() === query || item.name.toLowerCase() === query)) return;
            sess.factions.push({
                id: String(update.id || livingId('faction', update.name)).slice(0, 80),
                name: String(update.name || update.id).slice(0, 120),
                reputation: 0, influence: 50, resources: 50,
                goal: '', goalProgress: 0, status: 'active', territory: [], relations: []
            });
        });
    }

    if (modules.livingWorld && args.location_state_updates && Array.isArray(args.location_state_updates)) {
        args.location_state_updates.forEach(update => {
            const location = getLocationRef(world, update?.location_id);
            if (!location) return;
            const locState = sess.locationStates[location.id] || {
                conditions: [], controlFactionId: '', danger: 0, prosperity: 50, resources: {}
            };
            const makeCondition = value => {
                const item = typeof value === 'string' ? { label: value } : (value || {});
                const label = String(item.label || '').trim().slice(0, 120);
                if (!label) return null;
                const duration = item.duration_turns !== undefined ? parseInt(item.duration_turns) : parseInt(update.condition_duration_turns);
                return {
                    id: String(item.id || livingId('condition', label)).slice(0, 80),
                    label,
                    expiresTurn: duration > 0 ? (sess.turnCount || 1) + duration : null
                };
            };
            if (Array.isArray(update.set_conditions)) locState.conditions = update.set_conditions.map(makeCondition).filter(Boolean);
            if (Array.isArray(update.add_conditions)) {
                update.add_conditions.map(makeCondition).filter(Boolean).forEach(condition => {
                    const existing = locState.conditions.find(item => item.id === condition.id);
                    if (existing) Object.assign(existing, condition);
                    else locState.conditions.push(condition);
                });
            }
            if (Array.isArray(update.remove_conditions)) {
                const removals = new Set(update.remove_conditions.map(value => String(value).toLowerCase()));
                locState.conditions = locState.conditions.filter(condition =>
                    !removals.has(condition.id.toLowerCase()) && !removals.has(condition.label.toLowerCase()));
            }
            if (update.control_faction_id !== undefined) {
                const query = String(update.control_faction_id || '').toLowerCase();
                const faction = sess.factions.find(item => item.id.toLowerCase() === query || item.name.toLowerCase() === query);
                locState.controlFactionId = faction?.id || '';
            }
            if (update.danger_change !== undefined) locState.danger = livingClamp(locState.danger + Number(update.danger_change || 0), 0, 100);
            if (update.prosperity_change !== undefined) locState.prosperity = livingClamp(locState.prosperity + Number(update.prosperity_change || 0), 0, 100);
            if (update.resource_changes && typeof update.resource_changes === 'object') {
                Object.entries(update.resource_changes).forEach(([key, change]) => {
                    locState.resources[String(key).slice(0, 80)] = livingClamp((locState.resources[key] || 0) + Number(change || 0), 0, 999999);
                });
            }
            locState.conditions = locState.conditions.slice(0, 50);
            sess.locationStates[location.id] = locState;
        });
    }

    if (modules.relationships && args.npc_relationship_updates && Array.isArray(args.npc_relationship_updates)) {
        args.npc_relationship_updates.forEach(update => {
            const sourceId = resolveNpcId(world, update?.source_npc_id, sess);
            const targetId = resolveNpcId(world, update?.target_npc_id, sess);
            if (!sourceId || !targetId || sourceId === targetId) return;
            const key = relationshipKey(sourceId, targetId);
            const rel = sess.npcRelationships[key] || { score: 0, label: '', reason: '', lastChangedTurn: 0 };
            if (update.change !== undefined) rel.score = livingClamp(rel.score + livingClamp(update.change, -30, 30), -100, 100);
            if (update.label !== undefined) rel.label = String(update.label || '').slice(0, 80);
            if (update.reason !== undefined) rel.reason = String(update.reason || '').slice(0, 240);
            rel.lastChangedTurn = sess.turnCount || 1;
            sess.npcRelationships[key] = rel;
        });
    }

    if (modules.livingWorld && args.faction_updates && Array.isArray(args.faction_updates)) {
        args.faction_updates.forEach(update => {
            if (!update || (!update.id && !update.name)) return;
            const query = String(update.id || update.name).toLowerCase();
            let faction = sess.factions.find(item => item.id.toLowerCase() === query || item.name.toLowerCase() === query);
            if (!faction) {
                faction = {
                    id: String(update.id || livingId('faction', update.name)).slice(0, 80),
                    name: String(update.name || update.id).slice(0, 120),
                    reputation: 0, influence: 50, resources: 50,
                    goal: '', goalProgress: 0, status: 'active', territory: [], relations: []
                };
                sess.factions.push(faction);
            }
            if (update.name !== undefined) faction.name = String(update.name).slice(0, 120);
            if (update.reputation_change !== undefined) faction.reputation = livingClamp(faction.reputation + Number(update.reputation_change || 0), -100, 100);
            if (update.influence_change !== undefined) faction.influence = livingClamp(faction.influence + Number(update.influence_change || 0), 0, 100);
            if (update.resources_change !== undefined) faction.resources = livingClamp(faction.resources + Number(update.resources_change || 0), 0, 999999);
            if (update.goal !== undefined) {
                const nextGoal = String(update.goal || '').slice(0, 240);
                if (nextGoal !== faction.goal) faction.goalProgress = 0;
                faction.goal = nextGoal;
            }
            if (update.goal_progress_change !== undefined) faction.goalProgress = livingClamp(faction.goalProgress + Number(update.goal_progress_change || 0), 0, 100);
            if (['active', 'weakened', 'defeated', 'disbanded'].includes(update.status)) faction.status = update.status;
            if (Array.isArray(update.territory_add)) {
                update.territory_add.forEach(ref => {
                    const location = getLocationRef(world, ref);
                    if (location && !faction.territory.includes(location.id)) faction.territory.push(location.id);
                });
            }
            if (Array.isArray(update.territory_remove)) {
                const removals = new Set(update.territory_remove.map(ref => getLocationRef(world, ref)?.id).filter(Boolean));
                faction.territory = faction.territory.filter(id => !removals.has(id));
            }
            if (Array.isArray(update.relations)) {
                update.relations.forEach(relationUpdate => {
                    const targetQuery = String(relationUpdate?.faction_id || '').toLowerCase();
                    const target = sess.factions.find(item => item.id.toLowerCase() === targetQuery || item.name.toLowerCase() === targetQuery);
                    if (!target || target.id === faction.id) return;
                    // Both sides, because standing is mutual everywhere else in
                    // the engine. Writing only one direction meant the DM could
                    // declare a war that the other faction never noticed: its
                    // standing showed no enemy, so it took no penalty for
                    // contested ground and read as calm in the prompt.
                    adjustFactionRelation(sess, faction, target, Number(relationUpdate.change || 0));
                });
            }
        });
        sess.factions = sess.factions.slice(0, 200);
    }

    if ((modules.commerce || modules.livingWorld) && args.economy_updates && Array.isArray(args.economy_updates)) {
        args.economy_updates.forEach(update => {
            const location = getLocationRef(world, update?.location_id);
            const item = String(update?.item || '').trim();
            if (!location || !item) return;
            const market = sess.economy.markets[location.id] || (sess.economy.markets[location.id] = {});
            const key = item.toLowerCase().replace(/[^a-z0-9]+/g, '_').slice(0, 80) || livingId('item', item);
            const stock = market[key] || { item: item.slice(0, 100), quantity: 0, price: 1, regenPerTurn: 0, maxQuantity: 100 };
            if (update.set_quantity !== undefined) stock.quantity = livingClamp(update.set_quantity, 0, 999999);
            else if (update.quantity_change !== undefined) stock.quantity = livingClamp(stock.quantity + Number(update.quantity_change || 0), 0, 999999);
            if (update.price !== undefined) stock.price = livingClamp(update.price, 0, 999999);
            if (update.regen_per_turn !== undefined) stock.regenPerTurn = livingClamp(update.regen_per_turn, 0, 9999);
            if (update.max_quantity !== undefined) stock.maxQuantity = livingClamp(update.max_quantity, 0, 999999);
            if (stock.quantity > stock.maxQuantity) stock.maxQuantity = stock.quantity;
            market[key] = stock;
        });
    }

    if (modules.livingWorld && args.player_preference_updates && Array.isArray(args.player_preference_updates)) {
        args.player_preference_updates.forEach(update => {
            const key = String(update?.key || '').trim().slice(0, 80);
            if (!key) return;
            sess.playstyle.preferences[key] = {
                value: String(update.value ?? '').slice(0, 240),
                confidence: livingClamp(update.confidence == null ? 0.7 : update.confidence, 0, 1),
                source: String(update.source || 'observed').slice(0, 120),
                turn: sess.turnCount || 1
            };
        });
    }

    if (args.npc_status_changes && Array.isArray(args.npc_status_changes)) {
        args.npc_status_changes.forEach(sc => {
            const rid = resolveNpcId(world, sc.npc_id, sess);
            if (!rid || !['alive', 'dead', 'gone'].includes(sc.status)) return;
            if (!sess.entityStates[rid]) sess.entityStates[rid] = { location: sess.playerLocation };
            const entState = sess.entityStates[rid];
            const prevStatus = entState.status || 'alive';
            if (prevStatus === sc.status) return;
            entState.status = sc.status;
            delete entState.pinnedUntilTurn; // pins die with the person
            if (!entState.observations) entState.observations = [];
            entState.observations.push({
                id: 'obs_' + Date.now() + Math.floor(Math.random() * 1000),
                text: `[STATUS: ${sc.status.toUpperCase()}]${sc.cause ? ' ' + sc.cause : ''}`,
                turn: sess.turnCount || 1
            });
            const npc = world.entities.find(e => e.id === rid);
            const icon = sc.status === 'dead' ? '☠️' : (sc.status === 'gone' ? '🚪' : '✨');
            showToast(`${icon} ${npc ? npc.name : 'NPC'} is now ${sc.status}`, 'info');
        });
    }

    if (args.npc_moves && Array.isArray(args.npc_moves)) {
        args.npc_moves.forEach(move => {
            const resolvedId = resolveNpcId(world, move?.npc_id, sess);
            const entState = sess.entityStates[resolvedId];
            if (entState && !isNpcActive(entState)) return; // corpses don't travel
            // Every other field in this tool names its destination `location_id`,
            // so a model writing that here is following the schema's own
            // convention. Accept the obvious spellings rather than silently
            // dropping the move and leaving the room reading as empty.
            const destinationRef = move?.target_location_id ?? move?.location_id
                ?? move?.to_location_id ?? move?.destination_id ?? move?.destination;
            const targetLoc = findFuzzyLocation(destinationRef, sessionLocations(world, sess));
            if (entState && targetLoc) {
                entState.location = targetLoc.id;
                // Narrative placement outranks schedules/population for the next few turns
                entState.pinnedUntilTurn = (sess.turnCount || 1) + 6;
                const npc = world.entities.find(e => e.id === resolvedId);
                showToast(`${npc ? npc.name : 'NPC'} moved to ${targetLoc.name}.`, 'info');
            } else {
                // Never fail silently here: an unapplied move is exactly the bug
                // where the DM narrates someone walking in and the HUD keeps
                // insisting the room is empty.
                moduleRejections.push({
                    field: 'npc_moves', module: 'livingWorld',
                    reason: !entState ? 'unknown_npc' : 'unknown_destination',
                    npc: move?.npc_id ?? null, destination: destinationRef ?? null
                });
                console.warn(`Horde Engine: npc_moves ignored — ${!entState
                    ? `unknown NPC "${move?.npc_id}"`
                    : `unknown destination "${destinationRef}"`}. The scene cast will not include them.`);
            }
        });
    }

    if (args.npc_introduced && Array.isArray(args.npc_introduced)) {
        args.npc_introduced.forEach(npc => {
            if (!npc.name) return;
            const existing = world.entities.find(e => isVisibleToSession(e, sess) && e.name.toLowerCase() === npc.name.trim().toLowerCase());
            if (!existing) {
                // Generate and inject a brand new NPC
                const newId = 'ent_' + Date.now() + Math.floor(Math.random() * 1000);
                // Home: only if the narrative states one — meeting someone at an inn
                // must NOT make them a resident of the inn. No home = wanderer.
                const statedHome = npc.home_location ? findFuzzyLocation(npc.home_location, sessionLocations(world, sess)) : null;
                const newNpc = {
                    id: newId,
                    type: 'npc',
                    name: npc.name.trim(),
                    description: npc.description || 'A person you just met.',
                    startLocation: sess.playerLocation,
                    homeLocation: statedHome ? statedHome.id : '',
                    isMajor: !!npc.persona, // a persona means they matter — keep it in context
                    persona: npc.persona || '',
                    secrets: [],
                    sessionOrigin: sess.id // timeline-scoped: other sessions never see them
                };
                world.entities.push(newNpc);

                // Set their initial state for this session (pinned: they were just
                // placed by the narrative — the engine may not shuffle them yet)
                sess.entityStates[newId] = {
                    location: sess.playerLocation,
                    pinnedUntilTurn: (sess.turnCount || 1) + 6,
                    observations: [{
                        id: 'obs_' + Date.now() + Math.floor(Math.random() * 1000),
                        text: `Encountered the player at ${world.locations.find(l => l.id === sess.playerLocation)?.name || 'this location'}.`,
                        turn: sess.turnCount || 1
                    }]
                };
                
                showToast(`New character introduced: ${newNpc.name}`, 'success');
                // Re-render studio entities if visible
                if (typeof renderWorldEntities === 'function' && document.getElementById('w-entities-list')) {
                    renderWorldEntities();
                }
            }
        });
    }

    if (modules.livingWorld && args.npc_goal_updates && Array.isArray(args.npc_goal_updates)) {
        args.npc_goal_updates.forEach(gu => {
            const rid = resolveNpcId(world, gu.npc_id, sess);
            if (!rid || gu.goal === undefined) return;
            if (!sess.entityStates[rid]) sess.entityStates[rid] = { location: sess.playerLocation };
            const entState = sess.entityStates[rid];
            const goal = String(gu.goal || '').trim();
            const goalChanged = goal !== entState.goal;
            entState.goal = goal ? goal.slice(0, 200) : '';
            if (goal && gu.motivation) entState.goalMotivation = String(gu.motivation).slice(0, 200);
            else if (!goal) {
                delete entState.goalMotivation;
                delete entState.goalSteps;
                delete entState.goalStepIndex;
                delete entState.goalProgress;
                delete entState.goalDeadlineTurn;
                delete entState.goalDifficulty;
                delete entState.goalAutonomy;
                delete entState.goalStatus;
            }
            if (goal) {
                if (goalChanged) entState.goalProgress = 0;
                if (Array.isArray(gu.steps)) {
                    entState.goalSteps = gu.steps.map(step => String(step).slice(0, 160)).filter(Boolean).slice(0, 20);
                    entState.goalStepIndex = 0;
                } else if (!Array.isArray(entState.goalSteps)) {
                    entState.goalSteps = [];
                }
                if (gu.progress_change !== undefined) entState.goalProgress = livingClamp((entState.goalProgress || 0) + Number(gu.progress_change || 0), 0, 100);
                if (gu.deadline_in_turns !== undefined) {
                    const deadline = parseInt(gu.deadline_in_turns) || 0;
                    entState.goalDeadlineTurn = deadline > 0 ? (sess.turnCount || 1) + deadline : null;
                }
                if (gu.difficulty !== undefined) entState.goalDifficulty = livingClamp(gu.difficulty, 0, 100);
                else if (entState.goalDifficulty === undefined) entState.goalDifficulty = 50;
                if (['paused', 'low', 'medium', 'high'].includes(gu.autonomy)) entState.goalAutonomy = gu.autonomy;
                else if (!entState.goalAutonomy) entState.goalAutonomy = 'medium';
                if (['active', 'completed', 'failed', 'blocked'].includes(gu.status)) entState.goalStatus = gu.status;
                else if (goalChanged || !entState.goalStatus) entState.goalStatus = 'active';
                if (entState.goalProgress >= 100 && !gu.status) entState.goalStatus = 'completed';
            }
            const npc = world.entities.find(e => e.id === rid);
            console.log(`Horde Engine: Goal ${goal ? 'set' : 'cleared'} for ${npc ? npc.name : rid}${goal ? ` — ${goal}` : ''}`);
            if (goal) showToast(`🎯 ${npc ? npc.name : 'An NPC'} has an agenda...`, 'info');
        });
    }

    if (modules.relationships && args.npc_disposition_changes && Array.isArray(args.npc_disposition_changes)) {
        args.npc_disposition_changes.forEach(dc => {
            const rid = resolveNpcId(world, dc.npc_id, sess);
            if (!rid) return;
            if (!sess.entityStates[rid]) sess.entityStates[rid] = { location: sess.playerLocation };
            const entState = sess.entityStates[rid];
            const change = Math.max(-20, Math.min(20, parseInt(dc.change) || 0));
            if (!change) return;
            const prev = entState.disposition !== undefined ? entState.disposition : 50;
            entState.disposition = Math.max(0, Math.min(100, prev + change));
            // The "why" becomes a permanent memory so the NPC can reference it later
            if (dc.reason) {
                if (!entState.observations) entState.observations = [];
                entState.observations.push({
                    id: 'obs_' + Date.now() + Math.floor(Math.random() * 1000),
                    text: `[Feelings shifted ${change > 0 ? '+' : ''}${change}] ${dc.reason}`,
                    turn: sess.turnCount || 1
                });
            }
            const npc = world.entities.find(e => e.id === rid);
            showToast(`${npc ? npc.name : 'NPC'} ${change > 0 ? '❤️ +' : '💔 '}${change}`, change > 0 ? 'success' : 'info');
        });
    }

    if (args.npc_observations && Array.isArray(args.npc_observations)) {
        args.npc_observations.forEach(obs => {
            if (!obs || !obs.observation) return;
            // The LLM usually passes a NAME here, not an ID — resolve it, and store
            // the same {id, text, turn} shape every consumer expects.
            const rid = resolveNpcId(world, obs.npc_id, sess);
            if (!rid) return console.warn(`Horde Engine: npc_observations — unknown NPC "${obs.npc_id}"`);
            if (!sess.entityStates[rid]) sess.entityStates[rid] = { location: sess.playerLocation };
            addNpcKnowledge(world, sess, rid, {
                id: 'obs_' + Date.now() + Math.floor(Math.random() * 1000),
                text: String(obs.observation),
                sourceType: obs.source_type || 'told',
                sourceNpcId: resolveNpcId(world, obs.source_npc_id, sess) || '',
                confidence: obs.confidence,
                visibility: obs.visibility,
                contradicted: obs.contradicted === true,
                allowedToShare: obs.allowed_to_share !== false,
                turn: sess.turnCount || 1,
                absoluteMinute: getWorldTimeData(world, sess).currentTotalMinutes
            });
            console.log(`Horde Engine: NPC Memory — ${rid} learned: ${obs.observation}`);
        });
    }

    if (!modules.inventory) {
        rejectDisabledField('inventory_add', 'inventory');
        rejectDisabledField('inventory_remove', 'inventory');
    }
    if (!modules.stats) rejectDisabledField('stat_changes', 'stats');
    if (!modules.schedules) rejectDisabledField('schedule_updates', 'schedules');
    if (!modules.quests) rejectDisabledField('quests_update', 'quests');
    if (!modules.relationships) {
        rejectDisabledField('npc_relationship_updates', 'relationships');
        rejectDisabledField('npc_disposition_changes', 'relationships');
    }
    if (!modules.livingWorld) {
        ['world_events', 'location_state_updates', 'faction_updates', 'player_preference_updates', 'npc_goal_updates']
            .forEach(field => rejectDisabledField(field, 'livingWorld'));
    }
    if (!modules.commerce && !modules.livingWorld) rejectDisabledField('economy_updates', 'commerce');

    const questResult = applyQuestUpdates(world, sess, args.quests_update);
    if (!ledgerEntry) {
        const ledgerArgs = { ...args };
        moduleRejections.forEach(rejection => delete ledgerArgs[rejection.field]);
        ledgerEntry = appendWorldLedgerEntry(sess, buildStructuredLedgerFallback(world, sess, ledgerArgs, questResult, {
            transactions: transactionResults,
            checks: checkResults,
            stats: statResult
        }));
    }
    return {
        ledgerEntry,
        questResult,
        movementResult,
        statResult,
        transactionResults,
        checkResults,
        checkOutcomeResults,
        capabilityProgressResults,
        conditionResults,
        moduleRejections,
        playerState: safeJsonClone(normalizePlayerRulesState(world, sess))
    };
}

// (removed: processAIActions — legacy [STATEUPDATE] text-tag parser, superseded
// by the update_world_state tool call pipeline and never invoked)

async function renderWorldMap() {
    const world = state.worlds.find(w => w.id === state.activeWorldId);
    if (!world) return;

    const modal = document.getElementById('map-modal');
    const container = document.getElementById('map-container');
    modal.classList.remove('hidden');

    try {
        const sess = getCurrentWorldSession();
        const presentation = normalizeWorldPresentation(world);
        const mapSkin = worldMediaSource(world, presentation.mapSkinAssetId);
        const effectiveMode = ['classic', 'cinematic'].includes(sess?.presentationMode)
            ? sess.presentationMode : (presentation.enabled ? presentation.mode : 'classic');
        container.style.backgroundImage = mapSkin && effectiveMode !== 'classic'
            ? `linear-gradient(rgba(8,8,12,.5),rgba(8,8,12,.5)),url('${cssUrl(mapSkin)}')` : 'none';
        container.style.backgroundSize = 'cover';
        container.style.backgroundPosition = 'center';
        renderSemanticWorldMap(container, worldForSession(world, sess), {
            currentLocationId: sess?.playerLocation || ''
        });
    } catch (err) {
        container.replaceChildren();
        const error = document.createElement('div');
        error.className = 'error';
        error.textContent = `Map Generation Error: ${err.message}`;
        container.appendChild(error);
        console.error(err);
    }
}

// Start
init().catch(error => {
    console.error('Initialization failed:', error);
    window.__hordeRuntimeErrors.push({ message: `Initialization failed: ${String(error?.message || error)}`, stack: String(error?.stack || '') });
    showToast(`Unable to start Horde Studio: ${error.message || error}`, 'error');
});

/** --- REFERENCE SANITIZER & SCHEDULER MODULE --- **/

function getLocationRef(world, ref) {
    if (!ref || !world.locations) return null;
    const clean = String(ref).trim().toLowerCase();
    return world.locations.find(location =>
        String(location.id || '').trim().toLowerCase() === clean
        || String(location.name || '').trim().toLowerCase() === clean) || null;
}

function getWorldTimeData(world, sess) {
    if (!sess.turnCount) sess.turnCount = 1;
    const timeStep = world.hudConfig?.timeStep !== undefined ? world.hudConfig.timeStep : 5;
    const startMinutes = (world.hudConfig?.startTimeHours !== undefined ? world.hudConfig.startTimeHours : 8) * 60
        + Math.max(0, Math.min(59, parseInt(world.hudConfig?.startTimeMinutes) || 0));
    const totalElapsedMinutes = (sess.turnCount - 1) * timeStep + (sess.bonusTimeMinutes || 0);
    const currentTotalMinutes = Math.max(0, startMinutes + totalElapsedMinutes);
    
    const days = Math.floor(currentTotalMinutes / (24 * 60)) + 1;
    const totalMinutesToday = ((currentTotalMinutes % (24 * 60)) + (24 * 60)) % (24 * 60);
    const hours24 = Math.floor(totalMinutesToday / 60);
    const mins = totalMinutesToday % 60;
    
    return { days, hours24, mins, totalMinutesToday, currentTotalMinutes, timeStep, startMinutes };
}

const WORLD_WEEKDAYS = Object.freeze(['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']);

function getWorldWeekday(world, dayNumber) {
    const authored = String(world?.hudConfig?.startWeekday || 'Monday').trim().toLowerCase();
    const startIndex = Math.max(0, WORLD_WEEKDAYS.findIndex(day => day.toLowerCase() === authored));
    const offset = Math.max(0, (parseInt(dayNumber) || 1) - 1);
    return WORLD_WEEKDAYS[(startIndex + offset) % WORLD_WEEKDAYS.length];
}

function isScheduleBlockForWorldDay(world, block, dayNumber) {
    const raw = block?.days ?? block?.day;
    if (raw == null || raw === '' || (Array.isArray(raw) && raw.length === 0)) return true;
    const wanted = new Set((Array.isArray(raw) ? raw : String(raw).split(','))
        .map(value => String(value || '').trim().toLowerCase()).filter(Boolean));
    const weekday = getWorldWeekday(world, dayNumber).toLowerCase();
    const short = weekday.slice(0, 3);
    const dayIndex = WORLD_WEEKDAYS.findIndex(day => day.toLowerCase() === weekday) + 1;
    return wanted.has(weekday) || wanted.has(short) || wanted.has(String(dayIndex))
        || (wanted.has('weekday') && dayIndex <= 5) || (wanted.has('weekend') && dayIndex >= 6)
        || (wanted.has('daily') || wanted.has('everyday'));
}

// --- Weather Engine ---
// Weighted toward mild skies, shifts every 3 in-game hours, manually overridable.
const WORLD_WEATHER_TYPES = [
    { id: 'clear',    label: 'clear skies',               emoji: '☀️', weight: 4 },
    { id: 'breeze',   label: 'a gentle breeze',           emoji: '🍃', weight: 2 },
    { id: 'crisp',    label: 'crisp, cold air',           emoji: '🌬️', weight: 1 },
    { id: 'overcast', label: 'overcast, muted light',     emoji: '☁️', weight: 2 },
    { id: 'fog',      label: 'thick fog rolling through', emoji: '🌫️', weight: 1 },
    { id: 'drizzle',  label: 'a light drizzle',           emoji: '🌦️', weight: 1 },
    { id: 'rain',     label: 'steady rain',               emoji: '🌧️', weight: 1 },
    { id: 'wind',     label: 'blustery wind',             emoji: '💨', weight: 1 },
    { id: 'storm',    label: 'a brewing storm',           emoji: '⛈️', weight: 1 }
];

function getWorldWeather(world, sess) {
    // Manual override wins until the player switches back to Auto
    if (sess && sess.weatherOverride) {
        const t = WORLD_WEATHER_TYPES.find(w => w.id === sess.weatherOverride);
        if (t) return t;
    }
    const time = getWorldTimeData(world, sess);
    // Shift every 3 in-game hours. (The old system keyed off the DAY number —
    // at 5 min/turn a day is ~288 turns, so weather froze on one sky forever.)
    const block = Math.floor(time.currentTotalMinutes / 180);
    let h = Math.imul(block + 1, 2654435761);
    for (let i = 0; i < (world.id || '').length; i++) h = (Math.imul(h, 31) + world.id.charCodeAt(i)) | 0;
    h = Math.abs(h ^ (h >>> 15));
    const totalWeight = WORLD_WEATHER_TYPES.reduce((s, w) => s + w.weight, 0);
    let roll = h % totalWeight;
    for (const w of WORLD_WEATHER_TYPES) {
        roll -= w.weight;
        if (roll < 0) return w;
    }
    return WORLD_WEATHER_TYPES[0];
}

/**
 * Travel time: exits can declare "takes Xm". Until now this was decorative —
 * these helpers make movement actually cost clock time on every path
 * (exit clicks, typed movement, and DM tool moves).
 */
function getExitTravelTime(world, fromId, toId) {
    const from = world.locations.find(l => l.id === fromId);
    const to = world.locations.find(l => l.id === toId);
    if (!from || !to || !Array.isArray(from.exits)) return 0;
    for (const ex of from.exits) {
        if (typeof ex !== 'object') continue;
        const t = parseInt(ex.travelTime) || 0;
        if (!t) continue;
        const target = (getExitTargetName(ex) || '').toLowerCase();
        if (target && (target === to.name.toLowerCase() || target === to.id.toLowerCase())) return t;
    }
    return 0;
}

function getWorldTravelLeg(world, fromId, toId) {
    const from = getLocationRef(world, fromId);
    const to = getLocationRef(world, toId);
    if (!from || !to) return null;
    const exit = (from.exits || []).find(candidate => {
        const target = getLocationRef(world, candidate?.targetLocationId || getExitTargetName(candidate));
        return target?.id === to.id;
    });
    const details = exit && typeof exit === 'object' ? exit : {};
    return {
        from, to,
        mode: normalizeWorldTravelMode(details.mode),
        travelTime: Math.max(0, Number(details.travelTime) || 0),
        routeName: String(details.routeName || '').trim(),
        cost: String(details.cost || '').trim()
    };
}

function describeWorldTravelLeg(leg) {
    if (!leg) return '';
    const mode = formatWorldTravelMode(leg.mode);
    const details = [mode, leg.routeName, leg.travelTime ? `${leg.travelTime} min` : '', leg.cost ? `fare ${leg.cost}` : ''].filter(Boolean);
    return `${leg.from.name} → ${leg.to.name}${details.length ? ` (${details.join(' · ')})` : ''}`;
}

function applyTravelTime(world, sess, fromId, toId) {
    const t = getExitTravelTime(world, fromId, toId);
    if (t > 0) {
        sess.bonusTimeMinutes = (sess.bonusTimeMinutes || 0) + t;
        showToast(`🕒 Travel time: +${t}m`, 'info');
    }
    return t;
}

function getWorldPathTravelTime(world, path) {
    if (!Array.isArray(path) || path.length < 2) return 0;
    let total = 0;
    for (let index = 1; index < path.length; index++) {
        total += getExitTravelTime(world, path[index - 1], path[index]);
    }
    return total;
}

function movePlayerAlongWorldPath(world, sess, targetLocation, options = {}) {
    if (!world || !sess || !targetLocation) return { ok: false, moved: false, reason: 'unknown_destination', path: [] };
    const path = findWorldTravelPath(typeof worldForSession === 'function' ? worldForSession(world, sess) : world, sess.playerLocation, targetLocation.id);
    if (!path) return { ok: false, moved: false, reason: 'unreachable', path: [] };
    if (path.length === 1) return { ok: true, moved: false, reason: 'already_there', path };

    const previousLocation = sess.playerLocation;
    const travelLegs = path.slice(1).map((toId, index) => getWorldTravelLeg(world, path[index], toId)).filter(Boolean);
    const travelMinutes = travelLegs.reduce((total, leg) => total + leg.travelTime, 0);
    sess.playerLocation = targetLocation.id;
    if (travelMinutes > 0) {
        sess.bonusTimeMinutes = (sess.bonusTimeMinutes || 0) + travelMinutes;
        if (options.showTravelToast !== false) showToast(`🕒 Travel time: +${travelMinutes}m`, 'info');
    }
    return {
        ok: true,
        moved: true,
        reason: '',
        previousLocation,
        destination: targetLocation.id,
        path,
        travelMinutes,
        travelLegs
    };
}

// An NPC moved by the narrative (npc_moves / npc_introduced) is "pinned":
// schedules and random population may not override them until the pin expires.
function isNpcPinned(sess, entState) {
    return !!(entState && entState.pinnedUntilTurn && (sess.turnCount || 1) < entState.pinnedUntilTurn);
}

// Queue a world event for the DM to narrate on the next generation
// (e.g. an NPC arriving because their schedule moved them into the scene).
function queueEngineEvent(sess, text) {
    if (!sess || !text) return;
    sess.engineEvents = sess.engineEvents || [];
    if (!sess.engineEvents.includes(text)) sess.engineEvents.push(text);
}

function livingClamp(value, min, max) {
    const n = Number(value);
    const fallback = min <= 0 && max >= 0 ? 0 : min;
    return Math.max(min, Math.min(max, Number.isFinite(n) ? n : fallback));
}

// Schedule blocks are selected by string comparison against the wall clock, and
// a block that can never compare <= "23:59" becomes the permanent pre-dawn
// fallback — silently overriding an NPC's real routine. Times must therefore be
// range-checked, not merely shaped like HH:MM.
function isValidScheduleTime(value) {
    return /^([01]\d|2[0-3]):[0-5]\d$/.test(String(value ?? ''));
}

function livingId(prefix, value) {
    const clean = String(value || '').trim().toLowerCase()
        .replace(/[^a-z0-9]+/g, '_')
        .replace(/^_+|_+$/g, '')
        .slice(0, 48);
    return `${prefix}_${clean || Math.random().toString(36).slice(2, 10)}`;
}

// --- Shops -----------------------------------------------------------------
// Markets existed only as timeline state, creatable solely by the AI, so an
// author had no way to say "the baker sells bread" at all. A stated price now
// settles one-off purchases, and these authored shops cover the standing case:
// persistent stock and prices the author controls, seeded into every timeline
// and visible to the DM as something the player can actually walk up and buy.

function normalizeShopStock(raw, index) {
    const item = String(raw?.item || `item_${index + 1}`).trim().slice(0, 100);
    const price = livingClamp(raw?.price == null ? 1 : raw.price, 0, 999999);
    return {
        item,
        price,
        // The rate this good settles at when nothing is pressing on it, so
        // scarcity drift oscillates around the author's figure.
        basePrice: livingClamp(raw?.basePrice == null ? price : raw.basePrice, 0, 999999),
        quantity: livingClamp(raw?.quantity == null ? 1 : raw.quantity, 0, 999999),
        maxQuantity: livingClamp(raw?.maxQuantity == null ? Math.max(1, Number(raw?.quantity) || 1) : raw.maxQuantity, 0, 999999),
        regenPerTurn: livingClamp(raw?.regenPerTurn || 0, 0, 9999)
    };
}

function normalizeWorldShops(world) {
    (world?.locations || []).forEach(location => {
        if (!Array.isArray(location.shop)) {
            if (location.shop) delete location.shop;
            return;
        }
        location.shop = location.shop
            .filter(entry => entry && String(entry.item || '').trim())
            .map(normalizeShopStock)
            .slice(0, 100);
        if (!location.shop.length) delete location.shop;
    });
    return world;
}

/**
 * Read a location's stock without touching it. Seeding runs while the author
 * may still be mid-edit — a row they have added but not yet named must not be
 * deleted out from under them just because a session started.
 */
function readWorldShop(location) {
    if (!Array.isArray(location?.shop)) return [];
    return location.shop
        .filter(entry => entry && String(entry.item || '').trim())
        .map(normalizeShopStock)
        .slice(0, 100);
}

// A stock key must be stable and match how transactions look items up.
function shopStockKey(item) {
    return questTextKey(item) || String(item || '').trim().toLowerCase();
}

function seedMarketsFromWorld(world) {
    const markets = {};
    (world?.locations || []).forEach(location => {
        const shop = readWorldShop(location);
        if (!shop.length) return;
        const market = {};
        shop.forEach(stock => {
            const key = shopStockKey(stock.item);
            if (key) market[key] = { ...stock };
        });
        if (Object.keys(market).length) markets[location.id] = market;
    });
    return markets;
}

/**
 * Bring an existing timeline up to date with shops authored after it began —
 * otherwise adding a shop mid-campaign would only affect brand new sessions,
 * which is not what anyone means by "the baker now sells bread". Never touches
 * a good the timeline already knows about: play has moved its stock and price.
 */
function syncMarketsWithWorldShops(world, sess) {
    if (!sess?.economy) return 0;
    if (!sess.economy.markets || typeof sess.economy.markets !== 'object') sess.economy.markets = {};
    let added = 0;
    (world?.locations || []).forEach(location => {
        const shop = readWorldShop(location);
        if (!shop.length) return;
        const market = sess.economy.markets[location.id] || (sess.economy.markets[location.id] = {});
        shop.forEach(stock => {
            const key = shopStockKey(stock.item);
            if (!key || market[key]) return;   // already trading — leave play alone
            market[key] = { ...stock };
            added++;
        });
    });
    return added;
}

// --- Factions --------------------------------------------------------------
// Factions lived only inside a timeline and only the AI could create one, so an
// author could describe a war in the lore and the engine would know nothing of
// the sides fighting it. Authored factions are the standing case: powers the
// author controls, seeded into every timeline, holding territory, standing in
// declared relation to each other, and with NPCs who actually belong to them.

const FACTION_STATUSES = ['active', 'weakened', 'defeated', 'disbanded'];

function normalizeWorldFaction(raw, index) {
    const name = String(raw?.name || `Faction ${index + 1}`).trim().slice(0, 120);
    const reputation = livingClamp(raw?.reputation == null ? 0 : raw.reputation, -100, 100);
    return {
        id: String(raw?.id || livingId('faction', name || index)).slice(0, 80),
        name,
        description: String(raw?.description || '').slice(0, 600),
        // How much the faction can make happen, and how the public regards it.
        influence: livingClamp(raw?.influence == null ? 50 : raw.influence, 0, 100),
        reputation,
        resources: livingClamp(raw?.resources == null ? 50 : raw.resources, 0, 999999),
        goal: String(raw?.goal || '').slice(0, 240),
        goalPool: (Array.isArray(raw?.goalPool) ? raw.goalPool : [])
            .map(entry => String(typeof entry === 'string' ? entry : entry?.goal || '').trim().slice(0, 240))
            .filter(Boolean).slice(0, 20),
        status: FACTION_STATUSES.includes(raw?.status) ? raw.status : 'active',
        territory: [...new Set((Array.isArray(raw?.territory) ? raw.territory : [])
            .map(ref => String(ref || '').trim()).filter(Boolean))].slice(0, 500),
        relations: (Array.isArray(raw?.relations) ? raw.relations : []).slice(0, 200).map(relation => ({
            factionId: String(relation?.factionId || '').slice(0, 80),
            score: livingClamp(relation?.score || 0, -100, 100)
        })).filter(relation => relation.factionId)
    };
}

/**
 * Repair stored factions and drop every reference that no longer resolves —
 * territory pointing at a deleted location, a relation or a membership naming
 * a faction that is gone. Mutating, so it belongs on the load and save paths
 * and never on the path that starts a session.
 */
function normalizeWorldFactions(world) {
    if (!world) return world;
    if (!Array.isArray(world.factions)) {
        if (world.factions) delete world.factions;
        if (!world.factions) world.factions = [];
    }
    world.factions = world.factions.slice(0, 200).map(normalizeWorldFaction);
    // Ids must be unique or relations and membership become ambiguous.
    const seen = new Set();
    world.factions.forEach((faction, index) => {
        while (seen.has(faction.id)) faction.id = `${faction.id}_${index + 1}`;
        seen.add(faction.id);
    });
    world.factions.forEach(faction => {
        faction.territory = faction.territory
            .map(ref => getLocationRef(world, ref)?.id).filter(Boolean);
        faction.territory = [...new Set(faction.territory)];
        faction.relations = faction.relations.filter(relation =>
            relation.factionId !== faction.id && seen.has(relation.factionId));
    });
    (world.entities || []).forEach(entity => {
        if (entity?.factionId && !seen.has(entity.factionId)) delete entity.factionId;
    });
    if (!world.factions.length) delete world.factions;
    return world;
}

// Non-destructive read, for the same reason shops have one: a session must
// never edit the world an author may still be part-way through writing.
function readWorldFactions(world) {
    if (!Array.isArray(world?.factions)) return [];
    const factions = world.factions
        .filter(entry => entry && String(entry.name || '').trim())
        .map(normalizeWorldFaction).slice(0, 200);
    const ids = new Set(factions.map(faction => faction.id));
    factions.forEach(faction => {
        faction.territory = [...new Set(faction.territory
            .map(ref => getLocationRef(world, ref)?.id).filter(Boolean))];
        faction.relations = faction.relations.filter(relation =>
            relation.factionId !== faction.id && ids.has(relation.factionId));
    });
    return factions;
}

// A faction enters play with its authored standing but no history: nothing has
// been achieved and no aim is part-done until the world actually turns.
function livingFactionFromWorld(faction) {
    return { ...faction, goalProgress: 0, achievements: [] };
}

function seedFactionsFromWorld(world) {
    return readWorldFactions(world).map(livingFactionFromWorld);
}

/**
 * Bring a running timeline up to date with factions authored after it began.
 * A faction already in play is left entirely alone — its influence, aim and
 * relations are the story so far, not something the editor should overwrite.
 */
function syncFactionsWithWorld(world, sess) {
    if (!sess) return 0;
    if (!Array.isArray(sess.factions)) sess.factions = [];
    const known = new Set(sess.factions.map(faction => String(faction?.id || '')));
    let added = 0;
    readWorldFactions(world).forEach(faction => {
        if (known.has(faction.id) || sess.factions.length >= 200) return;
        sess.factions.push(livingFactionFromWorld(faction));
        known.add(faction.id);
        added++;
    });
    return added;
}

// --- Society: standing relationships and the state of places ----------------
// Both lived only inside a timeline, so a world could open with a married
// couple who were strangers to the engine and a war-torn border that read as
// perfectly safe. Authored here, seeded into every timeline, and — because a
// world may hold hundreds of people — filled in by the Society calibration
// pass rather than by hand.

const RELATIONSHIP_CAP = 2000;

function normalizeWorldRelationship(raw) {
    const a = String(raw?.a || raw?.from || '').trim().slice(0, 80);
    const b = String(raw?.b || raw?.to || '').trim().slice(0, 80);
    return {
        a, b,
        label: String(raw?.label || '').trim().slice(0, 80),
        score: livingClamp(raw?.score == null ? 0 : raw.score, -100, 100),
        reason: String(raw?.reason || '').trim().slice(0, 240)
    };
}

/**
 * Repair stored relationships: drop any naming somebody who is gone or
 * themselves, and collapse duplicates so one pair cannot hold two standings.
 * Mutating — for the load and save paths only.
 */
function normalizeWorldRelationships(world) {
    if (!world) return world;
    if (!Array.isArray(world.relationships)) {
        if (world.relationships) delete world.relationships;
        if (!world.relationships) world.relationships = [];
    }
    const people = new Set((world.entities || []).map(entity => String(entity?.id || '')));
    const byPair = new Map();
    world.relationships.slice(0, RELATIONSHIP_CAP).map(normalizeWorldRelationship).forEach(relation => {
        if (!relation.a || !relation.b || relation.a === relation.b) return;
        if (!people.has(relation.a) || !people.has(relation.b)) return;
        byPair.set(relationshipKey(relation.a, relation.b), relation);   // last write wins
    });
    world.relationships = [...byPair.values()];
    if (!world.relationships.length) delete world.relationships;
    return world;
}

// Non-destructive read, for the same reason shops and factions have one.
function readWorldRelationships(world) {
    if (!Array.isArray(world?.relationships)) return [];
    const people = new Set((world.entities || []).map(entity => String(entity?.id || '')));
    const byPair = new Map();
    world.relationships.slice(0, RELATIONSHIP_CAP).map(normalizeWorldRelationship).forEach(relation => {
        if (!relation.a || !relation.b || relation.a === relation.b) return;
        if (!people.has(relation.a) || !people.has(relation.b)) return;
        byPair.set(relationshipKey(relation.a, relation.b), relation);
    });
    return [...byPair.values()];
}

function seedRelationshipsFromWorld(world) {
    const seeded = {};
    readWorldRelationships(world).forEach(relation => {
        seeded[relationshipKey(relation.a, relation.b)] = {
            score: relation.score, label: relation.label, reason: relation.reason
        };
    });
    return seeded;
}

/**
 * Bring a running timeline up to date with relationships authored after it
 * began. A pair the timeline already knows is left alone: play has moved that
 * standing, and the editor is not entitled to undo what happened at the table.
 */
function syncRelationshipsWithWorld(world, sess) {
    if (!sess) return 0;
    if (!sess.npcRelationships || typeof sess.npcRelationships !== 'object' || Array.isArray(sess.npcRelationships)) {
        sess.npcRelationships = {};
    }
    let added = 0;
    readWorldRelationships(world).forEach(relation => {
        const key = relationshipKey(relation.a, relation.b);
        if (sess.npcRelationships[key]) return;
        sess.npcRelationships[key] = {
            score: relation.score, label: relation.label, reason: relation.reason
        };
        added++;
    });
    return added;
}

// A location's opening condition. Absent means "unremarkable", which is why
// nothing is written onto a location that says nothing about itself.
function authoredLocationState(location) {
    if (!location) return null;
    const hasDanger = location.danger != null && location.danger !== '';
    const hasProsperity = location.prosperity != null && location.prosperity !== '';
    const conditions = (Array.isArray(location.conditions) ? location.conditions : [])
        .map(entry => String(typeof entry === 'string' ? entry : entry?.label || '').trim())
        .filter(Boolean).slice(0, 20);
    if (!hasDanger && !hasProsperity && !conditions.length) return null;
    return {
        conditions: conditions.map((label, index) => ({
            id: livingId('condition', `${location.id}_${label || index}`),
            label: label.slice(0, 120),
            expiresTurn: null            // authored conditions stand until play changes them
        })),
        controlFactionId: '',
        danger: livingClamp(hasDanger ? location.danger : 0, 0, 100),
        prosperity: livingClamp(hasProsperity ? location.prosperity : 50, 0, 100),
        resources: {}
    };
}

function seedLocationStatesFromWorld(world) {
    const states = {};
    (world?.locations || []).forEach(location => {
        const state = authoredLocationState(location);
        if (state) states[location.id] = state;
    });
    // Territory is a claim on the ground, so a holding opens under its holder.
    readWorldFactions(world).forEach(faction => {
        faction.territory.forEach(locId => {
            const state = states[locId] || (states[locId] = {
                conditions: [], controlFactionId: '', danger: 0, prosperity: 50, resources: {}
            });
            if (!state.controlFactionId) state.controlFactionId = faction.id;
        });
    });
    return states;
}

/**
 * Bring a running timeline up to date with places described after it began.
 * A location the timeline already tracks is left alone — its danger is the
 * story of what has happened there, not a figure the editor may reset.
 */
function syncLocationStatesWithWorld(world, sess) {
    if (!sess) return 0;
    if (!sess.locationStates || typeof sess.locationStates !== 'object' || Array.isArray(sess.locationStates)) {
        sess.locationStates = {};
    }
    let added = 0;
    Object.entries(seedLocationStatesFromWorld(world)).forEach(([locId, state]) => {
        if (sess.locationStates[locId]) return;
        sess.locationStates[locId] = state;
        added++;
    });
    return added;
}

/**
 * Repair everything an author can write into a world, and drop every reference
 * that no longer resolves.
 *
 * This used to run only when the app loaded stored state, which left three
 * ways to keep bad data: importing a .horde_world (never normalized at all, so
 * a half-formed faction crashed the Factions panel on open), saving from the
 * Studio (the editing clone went to storage as-is), and exporting (the same
 * clone went straight to a file). Deleting a person or a place in the Studio
 * also left standings and territory pointing at them until the next reload.
 *
 * So it runs on every path that produces or persists a world instead.
 */
function normalizeWorldSandboxConfig(world) {
    if (!world) return {};
    const raw = isPlainObject(world.sandboxConfig) ? world.sandboxConfig : {};
    world.sandboxConfig = {
        enabled: raw.enabled === true,
        scale: ['local', 'regional', 'kingdom', 'continent'].includes(raw.scale) ? raw.scale : 'regional',
        calendar: String(raw.calendar || 'Four seasonal quarters').slice(0, 120),
        seasonDays: livingClamp(raw.seasonDays == null ? 30 : raw.seasonDays, 1, 365),
        politics: raw.politics !== false,
        conflict: raw.conflict !== false,
        law: raw.law !== false,
        seasons: raw.seasons !== false,
        growth: raw.growth !== false,
        principles: String(raw.principles || '').slice(0, 4000)
    };
    const locationIds = new Set((world.locations || []).map(location => location.id));
    const factionIds = new Set((world.factions || []).map(faction => faction.id));
    const used = new Set();
    world.startingLives = (Array.isArray(world.startingLives) ? world.startingLives : [])
        .filter(isPlainObject).slice(0, 40).map((life, index) => {
            let id = String(life.id || livingId('origin', life.name || index)).replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 80);
            while (used.has(id)) id = `${id}_${index + 1}`;
            used.add(id);
            const startLocationId = locationIds.has(life.startLocationId)
                ? life.startLocationId : (world.startLocationId || world.locations?.[0]?.id || '');
            const factionId = factionIds.has(life.factionId) ? life.factionId : '';
            const statOverrides = {};
            if (isPlainObject(life.statOverrides)) {
                Object.entries(life.statOverrides).slice(0, 40).forEach(([key, value]) => {
                    if (Number.isFinite(Number(value))) statOverrides[String(key).slice(0, 80)] = Number(value);
                });
            }
            return {
                id,
                name: String(life.name || `Starting Life ${index + 1}`).slice(0, 100),
                icon: String(life.icon || '◈').slice(0, 8),
                role: String(life.role || life.name || 'wanderer').slice(0, 100),
                socialRank: String(life.socialRank || 'commoner').slice(0, 80),
                description: String(life.description || '').slice(0, 500),
                startLocationId,
                factionId,
                factionReputation: livingClamp(life.factionReputation || 0, -100, 100),
                title: String(life.title || '').slice(0, 120),
                outfit: String(life.outfit || '').slice(0, 300),
                inventory: (Array.isArray(life.inventory) ? life.inventory : String(life.inventory || '').split(','))
                    .map(item => String(item || '').trim()).filter(Boolean).slice(0, 60),
                obligations: (Array.isArray(life.obligations) ? life.obligations : String(life.obligations || '').split('\n'))
                    .map(item => String(item || '').trim()).filter(Boolean).slice(0, 30),
                privileges: (Array.isArray(life.privileges) ? life.privileges : String(life.privileges || '').split('\n'))
                    .map(item => String(item || '').trim()).filter(Boolean).slice(0, 30),
                skills: (Array.isArray(life.skills) ? life.skills : String(life.skills || '').split('\n'))
                    .map(item => String(item || '').trim()).filter(Boolean).slice(0, 40),
                perks: (Array.isArray(life.perks) ? life.perks : String(life.perks || '').split('\n'))
                    .map(item => String(item || '').trim()).filter(Boolean).slice(0, 40),
                legalStatus: String(life.legalStatus || 'free').slice(0, 100),
                holdings: (Array.isArray(life.holdings) ? life.holdings : String(life.holdings || '').split(','))
                    .map(item => String(item || '').trim()).filter(Boolean).slice(0, 30),
                statOverrides,
                intro: String(life.intro || '').slice(0, 6000)
            };
        });
    return world.sandboxConfig;
}

function seedWorldSocietyState(world) {
    const config = normalizeWorldSandboxConfig(world);
    const settlementTypes = new Set(['area', 'building', 'outdoor']);
    const settlements = {};
    (world.locations || []).forEach(location => {
        if (location.simulateSettlement === false) return;
        const isSettlement = location.simulateSettlement === true
            || settlementTypes.has(String(location.mapType || '').toLowerCase())
                && /(village|town|city|keep|castle|port|harbor|market|camp|fort|hold|court|abbey|farm|manor)/i.test(`${location.name} ${location.region || ''}`);
        if (!isSettlement) return;
        const prosperity = livingClamp(location.prosperity == null ? 50 : location.prosperity, 0, 100);
        const danger = livingClamp(location.danger == null ? 20 : location.danger, 0, 100);
        settlements[location.id] = {
            name: location.name,
            population: livingClamp(location.population == null ? ({ local: 120, regional: 500, kingdom: 1800, continent: 5000 }[config.scale] || 500) : location.population, 1, 10000000),
            food: livingClamp(location.food == null ? 60 : location.food, 0, 100),
            wealth: prosperity,
            security: livingClamp(100 - danger, 0, 100),
            unrest: livingClamp(location.unrest || Math.round(danger / 3), 0, 100),
            growth: 0,
            controlFactionId: String(location.controlFactionId || '')
        };
    });
    return {
        version: 1,
        season: 'Spring',
        year: 1,
        settlements,
        conflicts: [],
        developments: [],
        lastTickTurn: 0
    };
}

function normalizeWorldSocietyState(world, sess) {
    const config = normalizeWorldSandboxConfig(world);
    if (!config.enabled) return null;
    if (!isPlainObject(sess.society)) sess.society = seedWorldSocietyState(world);
    const seeded = seedWorldSocietyState(world);
    if (!isPlainObject(sess.society.settlements)) sess.society.settlements = {};
    Object.entries(seeded.settlements).forEach(([id, value]) => {
        if (!isPlainObject(sess.society.settlements[id])) sess.society.settlements[id] = value;
    });
    Object.keys(sess.society.settlements).forEach(id => {
        if (!world.locations.some(location => location.id === id)) {
            delete sess.society.settlements[id];
            return;
        }
        const settlement = sess.society.settlements[id];
        settlement.name = String(settlement.name || getLocationRef(world, id)?.name || id).slice(0, 120);
        settlement.population = livingClamp(settlement.population || 1, 1, 10000000);
        ['food', 'wealth', 'security', 'unrest'].forEach(key => {
            settlement[key] = livingClamp(settlement[key] == null ? 50 : settlement[key], 0, 100);
        });
        settlement.growth = livingClamp(settlement.growth || 0, -100, 100);
        settlement.controlFactionId = String(settlement.controlFactionId || sess.locationStates?.[id]?.controlFactionId || '');
    });
    if (!Array.isArray(sess.society.conflicts)) sess.society.conflicts = [];
    if (!Array.isArray(sess.society.developments)) sess.society.developments = [];
    sess.society.conflicts = sess.society.conflicts.slice(-60);
    sess.society.developments = sess.society.developments.slice(-80);
    sess.society.lastTickTurn = Math.max(0, parseInt(sess.society.lastTickTurn) || 0);
    const time = getWorldTimeData(world, sess);
    const seasons = ['Spring', 'Summer', 'Autumn', 'Winter'];
    const seasonIndex = Math.floor(Math.max(0, time.days - 1) / config.seasonDays);
    sess.society.season = seasons[seasonIndex % seasons.length];
    sess.society.year = Math.floor(seasonIndex / seasons.length) + 1;
    if (!isPlainObject(sess.playerIdentity)) sess.playerIdentity = {};
    if (!isPlainObject(sess.legalStanding)) sess.legalStanding = {};
    return sess.society;
}

function normalizeAuthoredWorld(world) {
    if (!world) return world;
    // A hand-edited or truncated file can carry holes in these arrays, and a
    // hole is not a place or a person — every pass below would throw on it.
    world.locations = (Array.isArray(world.locations) ? world.locations : []).filter(isPlainObject);
    world.entities = (Array.isArray(world.entities) ? world.entities : []).filter(isPlainObject);
    normalizeWorldPresentation(world);
    const validMediaIds = new Set(world.mediaAssets.map(asset => asset.id));
    if (world.presentation.mapSkinAssetId && !validMediaIds.has(world.presentation.mapSkinAssetId)) {
        world.presentation.mapSkinAssetId = '';
    }

    normalizeWorldShops(world);
    world.locations.forEach(location => {
        if (!isPlainObject(location.visuals)) location.visuals = {};
        location.visuals.backgroundAssetId = String(location.visuals.backgroundAssetId || '').slice(0, 160);
        location.visuals.backgroundPosition = String(location.visuals.backgroundPosition || 'center').slice(0, 80);
        if (location.visuals.backgroundAssetId && !validMediaIds.has(location.visuals.backgroundAssetId)) {
            location.visuals.backgroundAssetId = '';
        }
        if (location.danger != null && location.danger !== '') location.danger = livingClamp(location.danger, 0, 100);
        if (location.prosperity != null && location.prosperity !== '') location.prosperity = livingClamp(location.prosperity, 0, 100);
        if (location.conditions !== undefined) {
            const conditions = (Array.isArray(location.conditions) ? location.conditions : [])
                .map(entry => String(typeof entry === 'string' ? entry : entry?.label || '').trim())
                .filter(Boolean).slice(0, 20);
            if (conditions.length) location.conditions = conditions;
            else delete location.conditions;
        }
    });
    world.entities.forEach(entity => {
        if (!isPlainObject(entity.visuals)) entity.visuals = {};
        entity.visuals.portraitAssetId = String(entity.visuals.portraitAssetId || '').slice(0, 160);
        entity.visuals.portraitPosition = String(entity.visuals.portraitPosition || 'center').slice(0, 80);
        entity.visuals.dialogueColor = /^#[0-9a-f]{6}$/i.test(String(entity.visuals.dialogueColor || ''))
            ? String(entity.visuals.dialogueColor).toUpperCase() : '';
        if (entity.visuals.portraitAssetId && !validMediaIds.has(entity.visuals.portraitAssetId)) {
            entity.visuals.portraitAssetId = '';
        }
        // A vendor bound to a location that no longer exists is not a vendor.
        if (entity.vendorFor && !world.locations.some(l => l.id === entity.vendorFor)) {
            delete entity.vendorFor;
        }
    });
    normalizeWorldDirectoryData(world);
    // After locations and entities, so a membership, a standing or a claim on
    // ground that names something gone clears rather than reaching an export.
    normalizeWorldFactions(world);
    const authoredFactionIds = new Set((world.factions || []).map(faction => faction.id));
    world.locations.forEach(location => {
        if (location.population != null) location.population = livingClamp(location.population, 1, 10000000);
        if (location.food != null) location.food = livingClamp(location.food, 0, 100);
        if (location.unrest != null) location.unrest = livingClamp(location.unrest, 0, 100);
        if (location.controlFactionId && !authoredFactionIds.has(location.controlFactionId)) {
            delete location.controlFactionId;
        }
    });
    normalizeWorldRelationships(world);
    normalizeWorldSandboxConfig(world);
    normalizeWorldGameRules(world);
    normalizeWorldKernelConfig(world);
    world.worldAgent = normalizeWorldAgentConfig(world);
    return world;
}

const WORLD_KNOWLEDGE_SOURCES = new Set(['witnessed', 'told', 'public', 'suspected', 'believed', 'life_seed', 'unknown']);
const WORLD_CONSEQUENCE_STATES = new Set(['created', 'active', 'escalating', 'decaying', 'resolved']);

function normalizeNpcKnowledgeEntry(raw, defaults = {}) {
    const item = typeof raw === 'string' ? { text: raw } : (isPlainObject(raw) ? raw : {});
    const sourceType = WORLD_KNOWLEDGE_SOURCES.has(item.sourceType || item.source)
        ? (item.sourceType || item.source) : (defaults.sourceType || 'unknown');
    const confidence = livingClamp(item.confidence == null
        ? (sourceType === 'witnessed' ? 1 : sourceType === 'told' ? 0.72 : 0.55)
        : item.confidence, 0, 1);
    const turn = Math.max(0, parseInt(item.turn ?? defaults.turn) || 0);
    const text = String(item.text || item.observation || defaults.text || '').trim().slice(0, 500);
    if (!text) return null;
    return {
        id: String(item.id || defaults.id || livingId('obs', `${turn}_${text}`)).slice(0, 100),
        eventId: String(item.eventId || item.event_id || defaults.eventId || '').slice(0, 100),
        text,
        sourceType,
        source: sourceType,
        sourceNpcId: String(item.sourceNpcId || item.source_npc_id || defaults.sourceNpcId || '').slice(0, 100),
        evidenceMode: String(item.evidenceMode || item.evidence_mode || defaults.evidenceMode
            || (sourceType === 'witnessed' ? 'direct' : sourceType === 'told' ? 'hearsay' : 'inference')).slice(0, 40),
        confidence,
        visibility: ['public', 'private'].includes(item.visibility) ? item.visibility : (defaults.visibility || 'private'),
        contradicted: item.contradicted === true,
        allowedToShare: item.allowedToShare !== false && item.allowed_to_share !== false,
        learnedAt: {
            turn,
            absoluteMinute: Math.max(0, parseInt(item.learnedAt?.absoluteMinute ?? item.absoluteMinute ?? defaults.absoluteMinute) || 0)
        },
        turn
    };
}

function addNpcKnowledge(world, sess, npcRef, raw, defaults = {}) {
    const npcId = resolveNpcId(world, npcRef, sess) || String(npcRef || '');
    const entState = sess?.entityStates?.[npcId];
    if (!npcId || !entState) return null;
    const entry = normalizeNpcKnowledgeEntry(raw, defaults);
    if (!entry) return null;
    if (!Array.isArray(entState.observations)) entState.observations = [];
    const duplicate = entState.observations.find(item =>
        (entry.eventId && item.eventId === entry.eventId) || String(item.text || '').toLowerCase() === entry.text.toLowerCase());
    if (duplicate) {
        if (entry.confidence > Number(duplicate.confidence || 0)) Object.assign(duplicate, entry);
        return duplicate;
    }
    entState.observations.push(entry);
    entState.observations = entState.observations.slice(-100);
    return entry;
}

function normalizeWorldConsequences(world, sess) {
    if (!Array.isArray(sess.consequences)) sess.consequences = [];
    const locationIds = new Set((world.locations || []).map(location => location.id));
    const entityIds = new Set((world.entities || []).map(entity => entity.id));
    sess.consequences = sess.consequences.slice(-300).map((raw, index) => {
        const item = isPlainObject(raw) ? raw : { detail: String(raw || '') };
        const state = WORLD_CONSEQUENCE_STATES.has(item.state) ? item.state : 'created';
        const createdTurn = Math.max(1, parseInt(item.createdTurn) || 1);
        return {
            id: String(item.id || livingId('consequence', `${createdTurn}_${index}_${item.title || item.detail}`)).slice(0, 100),
            type: String(item.type || 'world').slice(0, 60),
            title: String(item.title || item.detail || 'Unresolved consequence').slice(0, 160),
            detail: String(item.detail || item.title || '').slice(0, 600),
            state,
            createdTurn,
            updatedTurn: Math.max(createdTurn, parseInt(item.updatedTurn) || createdTurn),
            locationId: locationIds.has(item.locationId) ? item.locationId : '',
            actorIds: [...new Set((Array.isArray(item.actorIds) ? item.actorIds : [])
                .filter(id => id === 'player' || entityIds.has(id)))].slice(0, 20),
            sourceEventId: String(item.sourceEventId || '').slice(0, 100),
            severity: livingClamp(item.severity == null ? 35 : item.severity, 0, 100),
            escalateAfterTurns: Math.max(0, parseInt(item.escalateAfterTurns) || 0),
            decayAfterTurns: Math.max(0, parseInt(item.decayAfterTurns) || 0),
            resolvedTurn: item.resolvedTurn == null ? null : Math.max(createdTurn, parseInt(item.resolvedTurn) || createdTurn),
            evidence: String(item.evidence || '').slice(0, 400),
            visibility: ['public', 'private', 'hidden'].includes(item.visibility) ? item.visibility : 'private'
        };
    });
    return sess.consequences;
}

function createWorldConsequence(world, sess, raw) {
    const policy = normalizeWorldGameRules(world).consequences;
    if (policy?.enabled === false) return null;
    normalizeWorldConsequences(world, sess);
    const turn = Math.max(1, parseInt(sess.turnCount) || 1);
    const sourceEventId = String(raw?.sourceEventId || '').slice(0, 100);
    const existing = sourceEventId && sess.consequences.find(item => item.sourceEventId === sourceEventId);
    if (existing) return existing;
    const entry = {
        ...raw,
        state: raw?.state || 'created',
        createdTurn: turn,
        updatedTurn: turn,
        escalateAfterTurns: raw?.escalateAfterTurns == null ? policy.escalationTurns : raw.escalateAfterTurns,
        decayAfterTurns: raw?.decayAfterTurns == null ? policy.decayTurns : raw.decayAfterTurns
    };
    sess.consequences.push(entry);
    normalizeWorldConsequences(world, sess);
    const maxActive = Math.max(10, parseInt(policy?.maxActive) || 120);
    const resolved = sess.consequences.filter(item => item.state === 'resolved');
    const active = sess.consequences.filter(item => item.state !== 'resolved');
    sess.consequences = [...resolved.slice(-100), ...active.slice(-maxActive)];
    return sess.consequences[sess.consequences.length - 1];
}

function advanceWorldConsequences(world, sess, turn) {
    const consequences = normalizeWorldConsequences(world, sess);
    let changed = 0;
    consequences.forEach(item => {
        if (item.state === 'resolved') return;
        const age = turn - item.createdTurn;
        let next = item.state;
        if (item.state === 'created') next = 'active';
        if (item.escalateAfterTurns > 0 && age >= item.escalateAfterTurns && item.severity >= 50) next = 'escalating';
        if (item.decayAfterTurns > 0 && age >= item.decayAfterTurns && item.severity < 50) next = 'decaying';
        if (next === 'decaying' && age >= item.decayAfterTurns + 3) {
            next = 'resolved';
            item.resolvedTurn = turn;
        }
        if (next !== item.state) {
            item.state = next;
            item.updatedTurn = turn;
            changed++;
        }
    });
    return changed;
}

function normalizeLivingWorldState(world, sess) {
    if (!world || !sess) return sess;
    // Canonical immersion-engine state. Older timelines migrate lazily: the
    // first committed turn starts versioning without rewriting their history.
    if (!Array.isArray(sess.turnEvents)) sess.turnEvents = [];
    if (!Array.isArray(sess.worldTurnReceipts)) sess.worldTurnReceipts = [];
    sess.turnEvents = sess.turnEvents.slice(-1200);
    sess.worldTurnReceipts = sess.worldTurnReceipts.slice(-120);
    sess.worldStateVersion = Math.max(0, parseInt(sess.worldStateVersion) || 0);
    if (!Array.isArray(sess.pendingChecks)) {
        sess.pendingChecks = sess.pendingCheck ? [sess.pendingCheck] : [];
    }
    sess.pendingChecks = sess.pendingChecks
        .filter(item => item && typeof item === 'object' && !Array.isArray(item)).slice(0, 10);
    sess.pendingCheck = sess.pendingChecks[0] || null;
    if (!isPlainObject(sess.lastTurnAudit)) sess.lastTurnAudit = null;
    if (!Array.isArray(sess.playerSceneConditions)) sess.playerSceneConditions = [];
    if (typeof sess.playerActivity !== 'string') sess.playerActivity = '';
    // Shops, factions and society authored since this timeline began take effect
    // now. Each only ever adds what the timeline has never seen.
    syncMarketsWithWorldShops(world, sess);
    syncFactionsWithWorld(world, sess);
    syncRelationshipsWithWorld(world, sess);
    syncLocationStatesWithWorld(world, sess);
    if (!Array.isArray(sess.scheduledEvents)) sess.scheduledEvents = [];
    if (!sess.locationStates || typeof sess.locationStates !== 'object' || Array.isArray(sess.locationStates)) sess.locationStates = {};
    if (!sess.npcRelationships || typeof sess.npcRelationships !== 'object' || Array.isArray(sess.npcRelationships)) sess.npcRelationships = {};
    if (!sess.npcScheduleOverrides || typeof sess.npcScheduleOverrides !== 'object' || Array.isArray(sess.npcScheduleOverrides)) sess.npcScheduleOverrides = {};
    if (!isPlainObject(sess.dynamicExits)) sess.dynamicExits = {};
    if (!Array.isArray(sess.factions)) sess.factions = [];
    if (!sess.economy || typeof sess.economy !== 'object' || Array.isArray(sess.economy)) sess.economy = {};
    if (!sess.economy.currency) sess.economy.currency = 'coin';
    if (!sess.economy.markets || typeof sess.economy.markets !== 'object' || Array.isArray(sess.economy.markets)) sess.economy.markets = {};
    if (!sess.playstyle || typeof sess.playstyle !== 'object' || Array.isArray(sess.playstyle)) sess.playstyle = {};
    if (!Number.isFinite(Number(sess.playstyle.turnsObserved))) sess.playstyle.turnsObserved = 0;
    if (!sess.playstyle.signals || typeof sess.playstyle.signals !== 'object' || Array.isArray(sess.playstyle.signals)) sess.playstyle.signals = {};
    if (!sess.playstyle.preferences || typeof sess.playstyle.preferences !== 'object' || Array.isArray(sess.playstyle.preferences)) sess.playstyle.preferences = {};
    if (!Array.isArray(sess.playstyle.dominant)) sess.playstyle.dominant = [];
    if (!sess.playstyle.summary) sess.playstyle.summary = 'No clear playstyle pattern yet.';
    if (!Array.isArray(sess.worldNews)) sess.worldNews = [];
    normalizeWorldConsequences(world, sess);
    Object.values(sess.entityStates || {}).forEach(entState => {
        entState.observations = (Array.isArray(entState.observations) ? entState.observations : [])
            .map(item => normalizeNpcKnowledgeEntry(item)).filter(Boolean).slice(-100);
    });
    normalizeWorldSocietyState(world, sess);
    // Knowledge tracking arrived after some timelines were saved; items with no
    // record of who knows them are treated as already-circulating common talk
    // rather than retroactively hidden from characters who plausibly heard.
    sess.worldNews = sess.worldNews.slice(-80).map(item => {
        const entry = (item && typeof item === 'object' && !Array.isArray(item))
            ? item : { text: String(item || '') };
        entry.knownBy = Array.isArray(entry.knownBy)
            ? [...new Set(entry.knownBy.map(id => String(id || '')).filter(Boolean))].slice(0, 40)
            : null;
        entry.playerWitnessed = entry.playerWitnessed === true;
        entry.transmissions = (Array.isArray(entry.transmissions) ? entry.transmissions : []).slice(-80).map(record => ({
            from: String(record?.from || '').slice(0, 100),
            to: String(record?.to || '').slice(0, 100),
            turn: Math.max(0, parseInt(record?.turn) || 0),
            locationId: String(record?.locationId || '').slice(0, 100),
            confidence: livingClamp(record?.confidence == null ? 0.7 : record.confidence, 0, 1)
        }));
        return entry;
    });
    sess.lastLivingWorldTick = Math.max(0, parseInt(sess.lastLivingWorldTick) || 0);
    sess.lastLivingWorldMinute = Math.max(0, parseInt(sess.lastLivingWorldMinute) || 0);
    sess.lastWorldAgentTurn = Math.max(0, parseInt(sess.lastWorldAgentTurn) || 0);
    if (!sess.livingWorldActivity || typeof sess.livingWorldActivity !== 'object' || Array.isArray(sess.livingWorldActivity)) {
        sess.livingWorldActivity = {};
    }
    ['turn', 'events', 'goals', 'factions', 'markets', 'scheduleMoves', 'activeSchedules'].forEach(key => {
        sess.livingWorldActivity[key] = Math.max(0, parseInt(sess.livingWorldActivity[key]) || 0);
    });

    // A living-world session must have something concrete to simulate and
    // display even before the model creates factions or future events. Seed
    // the player's current place as a persistent local-state record. Other
    // locations are initialized lazily when visited or changed.
    const currentLocation = getLocationRef(world, sess.playerLocation);
    if (currentLocation && !sess.locationStates[currentLocation.id]) {
        sess.locationStates[currentLocation.id] = {
            conditions: [],
            controlFactionId: '',
            danger: 0,
            prosperity: 50,
            resources: {}
        };
    }

    sess.scheduledEvents = sess.scheduledEvents.slice(0, 500).map((event, index) => ({
        id: String(event?.id || `event_${index + 1}`).slice(0, 80),
        title: String(event?.title || 'Unnamed event').slice(0, 120),
        description: String(event?.description || event?.title || 'Something changes in the world.').slice(0, 500),
        status: ['scheduled', 'triggered', 'cancelled'].includes(event?.status) ? event.status : 'scheduled',
        dueTurn: event?.dueTurn == null ? null : Math.max(1, parseInt(event.dueTurn) || 1),
        dueMinute: event?.dueMinute == null ? null : Math.max(0, parseInt(event.dueMinute) || 0),
        repeatEveryTurns: Math.max(0, parseInt(event?.repeatEveryTurns) || 0),
        repeatEveryMinutes: Math.max(0, parseInt(event?.repeatEveryMinutes) || 0),
        locationId: getLocationRef(world, event?.locationId)?.id || null,
        conditionOnTrigger: event?.conditionOnTrigger ? String(event.conditionOnTrigger).slice(0, 120) : '',
        conditionDurationTurns: Math.max(0, parseInt(event?.conditionDurationTurns) || 0),
        factionId: event?.factionId ? String(event.factionId).slice(0, 80) : '',
        influenceChange: livingClamp(event?.influenceChange || 0, -20, 20),
        lastTriggeredTurn: Math.max(0, parseInt(event?.lastTriggeredTurn) || 0)
    }));

    Object.keys(sess.locationStates).forEach(locId => {
        if (!world.locations.some(location => location.id === locId)) {
            delete sess.locationStates[locId];
            return;
        }
        const state = sess.locationStates[locId] || {};
        state.conditions = (Array.isArray(state.conditions) ? state.conditions : []).slice(0, 50).map((condition, index) => {
            const item = typeof condition === 'string' ? { label: condition } : (condition || {});
            return {
                id: String(item.id || livingId('condition', item.label || index)).slice(0, 80),
                label: String(item.label || 'Changed').slice(0, 120),
                expiresTurn: item.expiresTurn == null ? null : Math.max(1, parseInt(item.expiresTurn) || 1)
            };
        });
        state.controlFactionId = state.controlFactionId ? String(state.controlFactionId).slice(0, 80) : '';
        state.danger = livingClamp(state.danger == null ? 0 : state.danger, 0, 100);
        state.prosperity = livingClamp(state.prosperity == null ? 50 : state.prosperity, 0, 100);
        if (!state.resources || typeof state.resources !== 'object' || Array.isArray(state.resources)) state.resources = {};
        Object.keys(state.resources).forEach(key => {
            state.resources[key] = livingClamp(state.resources[key], 0, 999999);
        });
        sess.locationStates[locId] = state;
    });

    sess.factions = sess.factions.slice(0, 200).map((faction, index) => ({
        id: String(faction?.id || livingId('faction', faction?.name || index)).slice(0, 80),
        name: String(faction?.name || `Faction ${index + 1}`).slice(0, 120),
        reputation: livingClamp(faction?.reputation == null ? 0 : faction.reputation, -100, 100),
        influence: livingClamp(faction?.influence == null ? 50 : faction.influence, 0, 100),
        resources: livingClamp(faction?.resources == null ? 50 : faction.resources, 0, 999999),
        goal: String(faction?.goal || '').slice(0, 240),
        goalProgress: livingClamp(faction?.goalProgress || 0, 0, 100),
        status: ['active', 'weakened', 'defeated', 'disbanded'].includes(faction?.status) ? faction.status : 'active',
        territory: [...new Set((Array.isArray(faction?.territory) ? faction.territory : [])
            .map(ref => getLocationRef(world, ref)?.id)
            .filter(Boolean))].slice(0, 500),
        relations: (Array.isArray(faction?.relations) ? faction.relations : []).slice(0, 200).map(relation => ({
            factionId: String(relation?.factionId || '').slice(0, 80),
            score: livingClamp(relation?.score || 0, -100, 100)
        })),
        // Aims already achieved, so a victorious faction is not left inert and
        // the DM can refer to what it has actually accomplished.
        achievements: (Array.isArray(faction?.achievements) ? faction.achievements : [])
            .map(item => String(item || '').slice(0, 240)).filter(Boolean).slice(-10),
        // Authored follow-up aims, mirroring an NPC's goalPool.
        goalPool: (Array.isArray(faction?.goalPool) ? faction.goalPool : [])
            .map(entry => String(typeof entry === 'string' ? entry : entry?.goal || '').trim().slice(0, 240))
            .filter(Boolean).slice(0, 20)
    }));

    // Factions can be deleted by the narrative; every reference to a faction
    // that no longer exists is dropped here, the same way state for deleted
    // locations and NPCs is. Dangling ids otherwise accumulate forever and
    // travel into exports.
    const factionIds = new Set(sess.factions.map(faction => faction.id));
    sess.factions.forEach(faction => {
        faction.relations = faction.relations.filter(relation =>
            relation.factionId && relation.factionId !== faction.id && factionIds.has(relation.factionId));
    });
    Object.values(sess.locationStates).forEach(locState => {
        if (locState.controlFactionId && !factionIds.has(locState.controlFactionId)) locState.controlFactionId = '';
    });
    sess.scheduledEvents.forEach(event => {
        if (event.factionId && !factionIds.has(event.factionId)) {
            event.factionId = '';
            event.influenceChange = 0;
        }
    });

    Object.keys(sess.npcRelationships).forEach(key => {
        const rel = sess.npcRelationships[key] || {};
        rel.score = livingClamp(rel.score == null ? 0 : rel.score, -100, 100);
        rel.label = String(rel.label || '').slice(0, 80);
        rel.reason = String(rel.reason || '').slice(0, 240);
        rel.lastChangedTurn = Math.max(0, parseInt(rel.lastChangedTurn) || 0);
        // true only for relationships drift itself created; those are the only
        // ones whose label/reason drift may keep rewriting.
        rel.autoManaged = rel.autoManaged === true;
        sess.npcRelationships[key] = rel;
    });

    Object.keys(sess.npcScheduleOverrides).forEach(npcId => {
        if (!world.entities.some(npc => npc.id === npcId && npc.type === 'npc')) {
            delete sess.npcScheduleOverrides[npcId];
            return;
        }
        sess.npcScheduleOverrides[npcId] = (Array.isArray(sess.npcScheduleOverrides[npcId]) ? sess.npcScheduleOverrides[npcId] : [])
            .map(block => {
                const location = getLocationRef(world, block?.locationId);
                const time = isValidScheduleTime(block?.time) ? String(block.time) : '';
                if (!location || !time) return null;
                const days = (Array.isArray(block?.days) ? block.days : (block?.day ? [block.day] : []))
                    .map(day => String(day || '').trim()).filter(Boolean).slice(0, 7);
                return { time, locationId: location.id, activity: String(block?.activity || '').slice(0, 160), ...(days.length ? { days } : {}) };
            })
            .filter(Boolean)
            .sort((a, b) => a.time.localeCompare(b.time))
            .slice(0, 1000);
    });

    Object.keys(sess.economy.markets).forEach(locId => {
        if (!world.locations.some(location => location.id === locId)) {
            delete sess.economy.markets[locId];
            return;
        }
        const market = sess.economy.markets[locId];
        if (!market || typeof market !== 'object' || Array.isArray(market)) {
            delete sess.economy.markets[locId];
            return;
        }
        Object.keys(market).forEach(itemKey => {
            const stock = market[itemKey] || {};
            stock.item = String(stock.item || itemKey).slice(0, 100);
            stock.quantity = livingClamp(stock.quantity || 0, 0, 999999);
            stock.price = livingClamp(stock.price == null ? 1 : stock.price, 0, 999999);
            stock.regenPerTurn = livingClamp(stock.regenPerTurn || 0, 0, 9999);
            // The rate this good settles at when nothing is pressing on it.
            // Captured once so drift oscillates around a fixed anchor instead of
            // compounding away from its authored value.
            stock.basePrice = livingClamp(stock.basePrice == null ? stock.price : stock.basePrice, 0, 999999);
            stock.maxQuantity = livingClamp(stock.maxQuantity == null ? Math.max(stock.quantity, 100) : stock.maxQuantity, 0, 999999);
            market[itemKey] = stock;
        });
    });

    sessionNpcs(world, sess).forEach(npc => {
        const entState = sess.entityStates?.[npc.id];
        if (!entState) return;
        // World authors/importers can provide a starting agenda directly on
        // an NPC. It becomes timeline state once and is then free to evolve.
        const authoredGoal = String(npc.goal || npc.agenda || '').trim();
        if (!entState.goal && authoredGoal) {
            entState.goal = authoredGoal.slice(0, 200);
            entState.goalProgress = 0;
            entState.goalDifficulty = livingClamp(npc.goalDifficulty == null ? 50 : npc.goalDifficulty, 0, 100);
            entState.goalAutonomy = ['paused', 'low', 'medium', 'high'].includes(npc.goalAutonomy)
                ? npc.goalAutonomy : 'medium';
            entState.goalStatus = 'active';
            entState.goalSteps = (Array.isArray(npc.goalSteps) ? npc.goalSteps : [])
                .map(step => String(step).slice(0, 160)).filter(Boolean).slice(0, 20);
            entState.goalStepIndex = 0;
            entState.goalStepReported = -1;   // no beat announced yet
        } else if (entState.goal && entState.goal === authoredGoal
            && !(Array.isArray(entState.goalSteps) && entState.goalSteps.length)
            && Array.isArray(npc.goalSteps) && npc.goalSteps.length) {
            // This timeline adopted the agenda before it had authored beats.
            // Take them on now, and treat the beats already covered by existing
            // progress as water under the bridge so the feed isn't flooded with
            // a retroactive dump of everything the NPC "did" off-screen.
            entState.goalSteps = npc.goalSteps.map(step => String(step).slice(0, 160)).filter(Boolean).slice(0, 20);
            const stepSize = 100 / entState.goalSteps.length;
            const reachedIndex = livingClamp(
                Math.floor(Math.max(0, (entState.goalProgress || 0) - 0.001) / stepSize),
                0, entState.goalSteps.length - 1);
            entState.goalStepIndex = reachedIndex;
            entState.goalStepReported = (entState.goalProgress || 0) > 0 ? reachedIndex : -1;
        }
        if (entState.goal) {
            entState.goalProgress = livingClamp(entState.goalProgress || 0, 0, 100);
            entState.goalDifficulty = livingClamp(entState.goalDifficulty == null ? 50 : entState.goalDifficulty, 0, 100);
            entState.goalAutonomy = ['paused', 'low', 'medium', 'high'].includes(entState.goalAutonomy) ? entState.goalAutonomy : 'medium';
            entState.goalStatus = ['active', 'completed', 'failed', 'blocked'].includes(entState.goalStatus) ? entState.goalStatus : 'active';
            entState.goalSteps = (Array.isArray(entState.goalSteps) ? entState.goalSteps : []).map(step => String(step).slice(0, 160)).slice(0, 20);
            entState.goalStepIndex = livingClamp(entState.goalStepIndex || 0, 0, Math.max(0, entState.goalSteps.length - 1));
            // -1 means "nothing announced yet"; timelines saved before beats
            // existed adopt it so their opening beat still surfaces.
            entState.goalStepReported = Number.isFinite(entState.goalStepReported)
                ? livingClamp(entState.goalStepReported, -1, Math.max(0, entState.goalSteps.length - 1))
                : -1;
            if (entState.goalDeadlineTurn != null) entState.goalDeadlineTurn = Math.max(1, parseInt(entState.goalDeadlineTurn) || 1);
            entState.goalHistory = (Array.isArray(entState.goalHistory) ? entState.goalHistory : [])
                .map(item => String(item || '').trim().slice(0, 200)).filter(Boolean).slice(-10);
            if (entState.goalResolvedTurn != null) {
                entState.goalResolvedTurn = Math.max(1, parseInt(entState.goalResolvedTurn) || 1);
            }
        }
    });

    return sess;
}

function stableWorldRoll(seed) {
    let hash = 2166136261;
    const text = String(seed || '');
    for (let i = 0; i < text.length; i++) {
        hash ^= text.charCodeAt(i);
        hash = Math.imul(hash, 16777619);
    }
    hash += hash << 13;
    hash ^= hash >>> 7;
    hash += hash << 3;
    hash ^= hash >>> 17;
    hash += hash << 5;
    return (hash >>> 0) / 4294967296;
}

function getTimelinePersona(sess) {
    if (isPlainObject(sess?.personaSnapshot)) return sess.personaSnapshot;
    const selectedId = sess?.personaId !== undefined ? sess.personaId : state.activePersonaId;
    return state.personas.find(persona => persona.id === selectedId) || null;
}

function lifeSeedSlug(value) {
    return String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 46) || 'person';
}

function chooseTimelineHome(world, sourceText) {
    const text = String(sourceText || '').toLowerCase();
    const named = (world.locations || []).find(location =>
        location.name && text.includes(location.name.toLowerCase()));
    if (named) return named;
    const homes = (world.locations || []).filter(location =>
        /house|home|apartment|flat|manor|estate|farm|cottage|quarters|keep|castle|palace|hall|residence/i
            .test(`${location.name || ''} ${location.description || ''}`)
        && !/school|store|shop|office|hospital|clinic|station|classroom/i.test(location.name || ''));
    const pool = homes;
    const wantsWealth = /\b(rich|wealthy|affluent|upper[- ]class|privileged|luxury|estate)\b/i.test(text);
    const wantsStruggle = /\b(poor|working[- ]class|struggling|broke|tenement|peasant)\b/i.test(text);
    return [...pool].sort((a, b) => {
        const left = Number(a.prosperity == null ? 50 : a.prosperity);
        const right = Number(b.prosperity == null ? 50 : b.prosperity);
        if (wantsWealth) return right - left;
        if (wantsStruggle) return left - right;
        return stableWorldRoll(`${world.id}|home|${a.id}`) - stableWorldRoll(`${world.id}|home|${b.id}`);
    })[0] || null;
}

function fallbackTimelineLifePlan(world, sess, persona, origin) {
    const source = `${persona?.name || ''} ${persona?.text || ''} ${origin?.name || ''} ${origin?.role || ''} ${origin?.description || ''}`;
    const student = /student|school|new kid|teen|child|pupil|apprentice/i.test(source);
    const doctorFamily = /parents?.{0,24}(?:doctors?|dcotors?|physicians?|medical)|(?:doctor|physician|medical) parents?/i.test(source);
    const home = chooseTimelineHome(world, source);
    const school = (world.locations || []).find(location => /school|academy|college|classroom/i.test(`${location.name} ${location.description || ''}`));
    const hospital = (world.locations || []).find(location => /hospital|clinic|medical|infirmary|healer/i.test(`${location.name} ${location.description || ''}`));
    const modern = /200[0-9]|suburb|school|phone|mall|doctor|hospital/i.test(`${world.name} ${world.description}`);
    const surnames = modern ? ['Mercer', 'Bennett', 'Shah', 'Morales', 'Sullivan', 'Chen'] : ['Vale', 'Mere', 'Ashford', 'Thorne', 'Reed', 'Hale'];
    const firsts = modern ? ['Morgan', 'Alex', 'Dana', 'Jordan', 'Casey', 'Taylor', 'Jamie', 'Riley'] : ['Mara', 'Tomas', 'Elin', 'Rowan', 'Anwen', 'Gareth', 'Ilya', 'Mira'];
    const pick = (values, salt) => values[Math.floor(stableWorldRoll(`${world.id}|${sess.id}|${salt}`) * values.length) % values.length];
    const surname = String(persona?.name || '').trim().split(/\s+/).slice(-1)[0] || pick(surnames, 'surname');
    const people = [];
    if (student) {
        ['parent one', 'parent two'].forEach((relation, index) => people.push({
            id: `family_${index + 1}`,
            name: `${pick(firsts, `parent_${index}`)} ${surname}`,
            relationship_to_player: relation,
            role: doctorFamily ? 'doctor' : (modern ? (index ? 'office manager' : 'civil engineer') : (index ? 'household steward' : 'craftsperson')),
            description: `The player's ${relation}, with a life and responsibilities beyond the player.`,
            persona: index ? 'Warm, observant, firm about promises, and carrying private work pressure.' : 'Practical, protective, dryly funny, and reluctant to discuss money worries.',
            home_location_id: home?.id || '', disposition: 86,
            day_location_id: doctorFamily ? (hospital?.id || '') : '',
            goal: 'Keep the household stable without controlling the player.',
            schedule: [
                { time: '06:30', locationId: '$HOME', activity: 'getting the household ready', days: ['weekday'] },
                ...(doctorFamily && hospital ? [{ time: index ? '08:00' : '07:00', locationId: hospital.id, activity: 'working a medical shift', days: ['weekday'] }] : []),
                { time: '19:00', locationId: '$HOME', activity: 'handling dinner and family life', days: ['weekday'] }
            ]
        }));
        ['classmate', 'potential friend', 'social rival'].forEach((relation, index) => people.push({
            id: `peer_${index + 1}`,
            name: `${pick(firsts, `peer_${index}`)} ${pick(surnames, `peer_s_${index}`)}`,
            relationship_to_player: relation,
            role: modern ? 'student' : 'young local',
            description: `A ${relation} in the player's daily orbit.`,
            persona: ['Open and funny but unreliable under pressure.', 'Quietly ambitious, kind one-on-one, cautious in groups.', 'Confident, competitive, and more complicated than first impressions.'][index],
            home_location_id: '', disposition: [58, 66, 40][index],
            day_location_id: school?.id || '',
            goal: ['Find a place in the local social scene.', 'Protect a friendship while pursuing a private ambition.', 'Stay socially influential without showing insecurity.'][index],
            schedule: school ? [{ time: '08:00', locationId: school.id, activity: 'attending school', days: ['weekday'] }] : []
        }));
    } else {
        ['trusted local contact', 'neighbor', 'work or community acquaintance'].forEach((relation, index) => people.push({
            id: `anchor_${index + 1}`, name: `${pick(firsts, `adult_${index}`)} ${pick(surnames, `adult_s_${index}`)}`,
            relationship_to_player: relation, role: modern ? ['friend', 'neighbor', 'coworker'][index] : ['confidant', 'neighbor', 'local associate'][index],
            description: `A persistent ${relation} connected to the player's ordinary life.`,
            persona: ['Loyal, candid, and willing to challenge bad decisions.', 'Helpful, nosy, and deeply informed about the area.', 'Capable, busy, and balancing friendship against personal ambition.'][index],
            home_location_id: '', disposition: [76, 61, 55][index],
            goal: 'Pursue a personal goal that occasionally intersects the player’s life.',
            schedule: []
        }));
    }
    return {
        summary: `${student ? 'Household and school circle' : 'Home and local social circle'} initialized from the selected identity.`,
        home: home ? { location_id: home.id } : {
            name: `${surname} Home`,
            description: 'A household home grounded in the player’s stated background and starting circumstances.',
            connects_to: origin?.startLocationId || sess.playerLocation
        },
        people,
        relationships: student ? [{ a: 'family_1', b: 'family_2', label: 'co-parents', score: 72, reason: 'They share a household and responsibility for the player.' }] : []
    };
}

async function requestTimelineLifePlan(world, sess, persona, origin) {
    if (!hasApiCredentials()) throw new Error('No configured model credentials');
    const locations = (world.locations || []).slice(0, 350).map(location =>
        `${location.id} | ${location.name} | ${location.region || '-'} | ${location.mapType || '-'} | prosperity ${location.prosperity ?? 50}`).join('\n');
    const people = (world.entities || []).filter(entity => entity.type === 'npc' && !entity.sessionOrigin).slice(0, 240).map(entity =>
        `${entity.id} | ${entity.name} | ${String(entity.description || '').slice(0, 100)} | home ${entity.homeLocation || '-'} | at ${entity.startLocation || '-'}`).join('\n');
    const source = `PERSONA NAME: ${persona?.name || 'none'}\nPERSONA DETAILS:\n${persona?.text || 'none'}\n\nSTARTING LIFE: ${origin?.name || 'default'}\nROLE: ${origin?.role || 'unspecified'}\nSOCIAL RANK: ${origin?.socialRank || 'unspecified'}\nDETAILS: ${origin?.description || ''}\nOBLIGATIONS: ${(origin?.obligations || []).join('; ') || 'none stated'}\nPRIVILEGES: ${(origin?.privileges || []).join('; ') || 'none stated'}\nHOLDINGS: ${(origin?.holdings || []).join('; ') || 'none stated'}\nOUTFIT: ${origin?.outfit || 'unspecified'}\nOPENING: ${origin?.intro || 'world default'}\nSTART LOCATION: ${origin?.startLocationId || sess.playerLocation}`;
    const body = {
        model: structuredModelFor(world), max_tokens: 6500,
        messages: [
            { role: 'system', content: `You initialize a persistent life inside an existing sandbox world. Convert the player's Persona and Starting Life into concrete simulation state without contradicting either.

Reuse existing location_id and existing_npc_id whenever they genuinely fit. Create new people when the Persona states family or close relationships that do not already exist. A student should normally have a plausible household plus 3-6 school/social connections; an adult should have household/local/work anchors. Every recurring person needs a role, relationship to the player, distinct personality, personal goal, home when knowable, and a weekly routine using ONLY location IDs in the manifest. If the Persona says the parents are doctors and the family is wealthy, those exact facts must become structured people, workplaces, schedules and an affluent home—not flavor text.

Return only JSON:
{"summary":"...","home":{"location_id":"existing id or blank","name":"new home name only if needed","description":"...","connects_to":"existing id","parent_location_id":"existing id"},"people":[{"id":"temporary stable key","existing_npc_id":"optional existing id","name":"...","relationship_to_player":"mother/father/sibling/friend/classmate/rival/coworker/etc","role":"...","description":"...","persona":"...","home_location_id":"existing id or $HOME","day_location_id":"existing school/work id","goal":"...","disposition":0,"schedule":[{"time":"07:00","locationId":"existing id or $HOME","activity":"...","days":["weekday"]}]}],"relationships":[{"a":"temporary person id","b":"temporary person id","label":"...","score":0,"reason":"..."}]}

Disposition and relationship scores are -100..100. Generate 4-10 people, never an anonymous crowd. Do not create a new town or duplicate an existing suitable house, school, hospital or workplace.` },
            { role: 'user', content: `${source}\n\nWORLD: ${world.name}\n${world.description || ''}\n\nLOCATIONS:\n${locations}\n\nEXISTING PEOPLE AVAILABLE FOR REAL CONNECTIONS:\n${people || 'none'}` }
        ]
    };
    const modelInfo = openRouterModels.find(model => model.id === body.model);
    if (!isLocalProvider() && modelInfo?.supported_parameters?.some(parameter => STRUCTURED_PARAM_FLAGS.includes(parameter))) {
        body.response_format = { type: 'json_object' };
    }
    const response = await fetch(apiBase() + '/chat/completions', {
        method: 'POST', headers: { 'Content-Type': 'application/json', ...authHeaders(), ...attributionHeaders() },
        body: JSON.stringify(body)
    });
    if (!response.ok) throw new Error((await response.json().catch(() => ({})))?.error?.message || response.statusText);
    const message = (await response.json())?.choices?.[0]?.message || {};
    const content = Array.isArray(message.content) ? message.content.map(part => part?.text || '').join(' ') : (message.content || message.reasoning || '');
    const plan = extractJSON(String(content));
    if (!plan || !Array.isArray(plan.people) || plan.people.length < 1) throw new Error('Model returned no valid people array');
    return plan;
}

function applyTimelineLifePlan(world, sess, persona, origin, rawPlan, source = 'model') {
    const plan = isPlainObject(rawPlan) ? rawPlan : {};
    const sourceText = `${persona?.text || ''} ${origin?.description || ''}`;
    let home = getLocationRef(world, plan.home?.location_id || plan.home?.name) || chooseTimelineHome(world, sourceText);
    const createdLocationIds = [];
    if (!home && plan.home?.name) {
        const anchor = getLocationRef(world, plan.home.connects_to || plan.home.parent_location_id || origin?.startLocationId || sess.playerLocation);
        home = {
            id: `loc_life_${lifeSeedSlug(plan.home.name)}_${String(sess.id).slice(-6)}`,
            name: String(plan.home.name).slice(0, 120), region: String(plan.home.region || anchor?.region || '').slice(0, 120),
            mapType: 'building', parentLocationId: getLocationRef(world, plan.home.parent_location_id)?.id || '',
            description: String(plan.home.description || 'The player’s home and the center of their household life.').slice(0, 700),
            hiddenDescription: '', exits: anchor ? [`to ${anchor.name}`] : [], secrets: [], sessionOrigin: sess.id
        };
        if (anchor) {
            addSessionDynamicExit(sess, anchor.id, home.name);
        }
        world.locations.push(home);
        createdLocationIds.push(home.id);
    }
    home = home || getLocationRef(world, origin?.startLocationId || sess.playerLocation);
    const idMap = new Map();
    const seededPeople = [];
    const rawPeople = (Array.isArray(plan.people) ? plan.people : []).filter(isPlainObject).slice(0, 16);
    rawPeople.forEach((raw, index) => {
        const existing = raw.existing_npc_id ? world.entities.find(entity => entity.id === raw.existing_npc_id && entity.type === 'npc' && isVisibleToSession(entity, sess)) : null;
        const key = String(raw.id || `person_${index + 1}`);
        let npc = existing;
        if (!npc) {
            const baseId = `ent_life_${lifeSeedSlug(raw.name || key)}_${String(sess.id).slice(-6)}`;
            let id = baseId;
            let suffix = 2;
            while (world.entities.some(entity => entity.id === id)) id = `${baseId}_${suffix++}`;
            const relationship = String(raw.relationship_to_player || 'acquaintance');
            const sharesPlayerHome = /parent|guardian|spouse|sibling|child|roommate|household|family/i.test(relationship);
            const rawHome = raw.home_location_id === '$HOME' ? home : getLocationRef(world, raw.home_location_id);
            const defaultHome = sharesPlayerHome ? home : null;
            const rawDay = getLocationRef(world, raw.day_location_id);
            const resolveBlockLocation = ref => ref === '$HOME' ? home : getLocationRef(world, ref);
            const schedule = (Array.isArray(raw.schedule) ? raw.schedule : []).map(block => {
                const location = resolveBlockLocation(block?.locationId || block?.location_id);
                if (!location || !isValidScheduleTime(block?.time)) return null;
                const days = (Array.isArray(block.days) ? block.days : []).map(day => String(day).slice(0, 20)).filter(Boolean).slice(0, 7);
                return { time: String(block.time), locationId: location.id, activity: String(block.activity || raw.role || '').slice(0, 160), ...(days.length ? { days } : {}) };
            }).filter(Boolean).sort((a, b) => a.time.localeCompare(b.time)).slice(0, 16);
            npc = {
                id, type: 'npc', name: String(raw.name || `New Person ${index + 1}`).slice(0, 120),
                role: String(raw.role || '').slice(0, 120), relationshipToPlayer: relationship.slice(0, 100),
                aliases: [relationship, ...(/\bmother\b/i.test(relationship) ? ['mom', 'mum'] : []), ...(/\bfather\b/i.test(relationship) ? ['dad'] : [])]
                    .map(alias => String(alias).trim().slice(0, 80)).filter(Boolean),
                description: String(raw.description || `A persistent ${raw.relationship_to_player || 'person'} in the player's life.`).slice(0, 700),
                persona: String(raw.persona || '').slice(0, 1200), isMajor: true,
                homeLocation: (rawHome || defaultHome)?.id || '', startLocation: (rawDay || rawHome || defaultHome)?.id || sess.playerLocation,
                goal: String(raw.goal || 'Maintain their own life while responding honestly to the player.').slice(0, 240), goalAutonomy: 'medium',
                goalSteps: [], schedule, secrets: [], sessionOrigin: sess.id
            };
            world.entities.push(npc);
        }
        idMap.set(key, npc.id);
        const seededHome = raw.home_location_id === '$HOME' ? home : getLocationRef(world, raw.home_location_id);
        const seededDay = getLocationRef(world, raw.day_location_id);
        const location = seededDay || seededHome || getLocationRef(world, npc.startLocation || npc.homeLocation) || home || getLocationRef(world, sess.playerLocation);
        const relationship = String(raw.relationship_to_player || npc.relationshipToPlayer || 'acquaintance').slice(0, 100);
        const disposition = livingClamp(raw.disposition == null ? (/parent|guardian|spouse|sibling|close friend/i.test(relationship) ? 82 : 58) : raw.disposition, 0, 100);
        sess.entityStates[npc.id] = {
            ...(sess.entityStates[npc.id] || {}), location: location?.id || sess.playerLocation,
            disposition, relationshipToPlayer: relationship,
            observations: [{ id: `obs_seed_${npc.id}`, text: `Has an established ${relationship} relationship with the player from before this timeline began.`, source: 'life_seed', confidence: 1, turn: 0 }]
        };
        if (existing && Array.isArray(raw.schedule)) {
            const overrides = raw.schedule.map(block => {
                const scheduleLocation = (block?.locationId || block?.location_id) === '$HOME'
                    ? home : getLocationRef(world, block?.locationId || block?.location_id);
                if (!scheduleLocation || !isValidScheduleTime(block?.time)) return null;
                const days = (Array.isArray(block.days) ? block.days : []).map(day => String(day).slice(0, 20)).filter(Boolean).slice(0, 7);
                return { time: String(block.time), locationId: scheduleLocation.id, activity: String(block.activity || raw.role || '').slice(0, 160), ...(days.length ? { days } : {}) };
            }).filter(Boolean).sort((a, b) => a.time.localeCompare(b.time)).slice(0, 16);
            if (overrides.length) sess.npcScheduleOverrides[npc.id] = overrides;
        }
        seededPeople.push({ id: npc.id, name: npc.name, relationship, role: npc.role || raw.role || '', homeLocationId: seededHome?.id || npc.homeLocation || '', disposition });
    });
    (Array.isArray(plan.relationships) ? plan.relationships : []).slice(0, 60).forEach(raw => {
        const a = idMap.get(String(raw?.a || ''));
        const b = idMap.get(String(raw?.b || ''));
        if (!a || !b || a === b) return;
        sess.npcRelationships[relationshipKey(a, b)] = {
            score: livingClamp(raw.score || 0, -100, 100), label: String(raw.label || '').slice(0, 80),
            reason: String(raw.reason || '').slice(0, 240), lastChangedTurn: 0
        };
    });
    const household = seededPeople.filter(person => /parent|guardian|spouse|sibling|child|roommate|family/i.test(person.relationship));
    for (let a = 0; a < household.length; a++) for (let b = a + 1; b < household.length; b++) {
        const key = relationshipKey(household[a].id, household[b].id);
        if (!sess.npcRelationships[key]) sess.npcRelationships[key] = { score: 65, label: 'household family', reason: 'They share a home and history.', lastChangedTurn: 0 };
    }
    sess.playerIdentity = isPlainObject(sess.playerIdentity) ? sess.playerIdentity : {};
    sess.playerIdentity.homeLocationId = home?.id || '';
    sess.playerIdentity.householdNpcIds = household.map(person => person.id);
    sess.playerIdentity.socialNpcIds = seededPeople.map(person => person.id);
    sess.personaId = persona?.id || '';
    sess.lifeSeed = {
        version: 1, initialized: true, source, personaId: persona?.id || '', originId: origin?.id || sess.originId || '',
        homeLocationId: home?.id || '', people: seededPeople, locationIds: createdLocationIds,
        summary: String(plan.summary || `${seededPeople.length} persistent people and a home were connected to this life.`).slice(0, 500),
        generatedAt: Date.now()
    };
    const line = `Active life initialized: ${sess.lifeSeed.summary}`;
    appendWorldLedgerEntry(sess, line);
    normalizeAuthoredWorld(world);
    normalizeLivingWorldState(world, sess);
    return sess.lifeSeed;
}

async function initializeTimelineLife(world, sess, persona) {
    const origin = (world.startingLives || []).find(life => life.id === sess.originId) || null;
    let plan;
    let source = 'model';
    try {
        plan = await requestTimelineLifePlan(world, sess, persona, origin);
    } catch (error) {
        console.warn('Timeline life model generation failed; using deterministic initializer:', error.message);
        plan = fallbackTimelineLifePlan(world, sess, persona, origin);
        source = 'deterministic_fallback';
    }
    const result = applyTimelineLifePlan(world, sess, persona, origin, plan, source);
    showToast(`Active life initialized · ${result.people.length} persistent people`, 'success');
    return result;
}

function applyStartingLifeToSession(world, sess, originId) {
    normalizeWorldSandboxConfig(world);
    const life = world.startingLives.find(item => item.id === originId);
    if (!life || !sess) return null;
    sess.originId = life.id;
    sess.playerIdentity = {
        originId: life.id,
        role: life.role,
        socialRank: life.socialRank,
        title: life.title,
        factionId: life.factionId,
        legalStatus: life.legalStatus,
        privileges: [...life.privileges],
        obligations: [...life.obligations],
        skills: [...life.skills],
        perks: [...life.perks],
        holdings: [...life.holdings]
    };
    if (getLocationRef(world, life.startLocationId)) sess.playerLocation = life.startLocationId;
    sess.inventory = [...life.inventory];
    (world.hudConfig?.stats || []).forEach(stat => {
        sess.playerStats[stat.id] = stat.value;
    });
    // Browsing New Session Setup cards must not accumulate reputation or stat
    // overrides from every life previewed before the player presses Begin.
    sess.factions = seedFactionsFromWorld(world);
    sess.outfit = life.outfit || '';
    sess.currentOutfit = life.outfit || '';
    Object.entries(life.statOverrides).forEach(([statId, value]) => {
        if (sess.playerStats[statId] !== undefined || (world.hudConfig?.stats || []).some(stat => stat.id === statId)) {
            sess.playerStats[statId] = value;
        }
    });
    if (life.factionId) {
        const faction = sess.factions.find(item => item.id === life.factionId);
        if (faction) faction.reputation = life.factionReputation;
    }
    sess.legalStanding = {};
    if (life.factionId) {
        sess.legalStanding[life.factionId] = {
            status: life.legalStatus,
            heat: /outlaw|wanted|criminal/i.test(life.legalStatus) ? 55 : 0,
            crimes: [],
            lastChangedTurn: 0
        };
    }
    if (life.intro) sess.pendingOriginIntro = life.intro;
    else delete sess.pendingOriginIntro;
    const label = life.title ? `${life.title}, ${life.role}` : life.role;
    sess.ledger = `Began this life as ${label}${life.factionId ? `, aligned with ${sess.factions.find(f => f.id === life.factionId)?.name || life.factionId}` : ''}.`;
    return life;
}

function runSocietySimulationTick(world, sess, turn) {
    const config = normalizeWorldSandboxConfig(world);
    const society = normalizeWorldSocietyState(world, sess);
    if (!config.enabled || !society || society.lastTickTurn >= turn) return { changed: 0 };
    society.lastTickTurn = turn;
    let changed = 0;
    const seasonPressure = { Spring: 1, Summer: 2, Autumn: 4, Winter: -5 }[society.season] || 0;
    Object.entries(society.settlements).forEach(([locationId, settlement]) => {
        const locationState = sess.locationStates?.[locationId];
        const contested = sess.factions.filter(faction => faction.territory?.includes(locationId)).length > 1;
        const harvestRoll = stableWorldRoll(`${world.id}|${sess.id}|settlement|${locationId}|${turn}`);
        const foodDelta = config.seasons && turn % 3 === 0
            ? seasonPressure + (harvestRoll > .82 ? 3 : harvestRoll < .12 ? -4 : 0) : 0;
        const securityDelta = contested ? -2 : (locationState?.danger > 65 ? -1 : locationState?.danger < 25 ? 1 : 0);
        const wealthDelta = settlement.food < 25 ? -2 : settlement.security > 65 && settlement.food > 55 ? 1 : 0;
        const unrestDelta = settlement.food < 25 || settlement.security < 25 ? 2
            : settlement.food > 55 && settlement.security > 55 ? -1 : 0;
        [['food', foodDelta], ['security', securityDelta], ['wealth', wealthDelta], ['unrest', unrestDelta]]
            .forEach(([key, delta]) => {
                if (!delta) return;
                const before = settlement[key];
                settlement[key] = livingClamp(before + delta, 0, 100);
                if (settlement[key] !== before) changed++;
            });
        settlement.growth = livingClamp(Math.round((settlement.food + settlement.wealth + settlement.security - settlement.unrest - 140) / 6), -100, 100);
        if (turn % 12 === 0 && settlement.growth !== 0) {
            const before = settlement.population;
            settlement.population = livingClamp(Math.round(before * (1 + settlement.growth / 10000)), 1, 10000000);
            if (settlement.population !== before) changed++;
        }
        if (locationState) {
            locationState.prosperity = livingClamp(Math.round((locationState.prosperity * 3 + settlement.wealth) / 4), 0, 100);
            locationState.danger = livingClamp(Math.round((locationState.danger * 3 + (100 - settlement.security)) / 4), 0, 100);
        }
    });

    if (config.conflict && turn % 6 === 0) {
        const active = sess.factions.filter(faction => faction.status === 'active');
        for (let i = 0; i < active.length; i++) {
            const enemy = (active[i].relations || []).find(relation => relation.score <= FACTION_WAR_AT);
            if (!enemy) continue;
            const other = active.find(item => item.id === enemy.factionId);
            if (!other) continue;
            const conflictId = [active[i].id, other.id].sort().join('|');
            let conflict = society.conflicts.find(item => item.id === conflictId);
            if (!conflict) {
                conflict = { id: conflictId, sides: [active[i].id, other.id], status: 'war', intensity: 20, warScore: 0, startedTurn: turn };
                society.conflicts.push(conflict);
                addWorldNews(sess, `Open conflict has begun between ${active[i].name} and ${other.name}.`, {
                    id: `news_war_${livingId('', conflictId)}_${turn}`, type: 'faction', playerVisible: false,
                    knownBy: []
                });
                changed++;
            } else if (conflict.status === 'war') {
                const swing = stableWorldRoll(`${conflictId}|${turn}`) < .5 ? -2 : 2;
                conflict.warScore = livingClamp((conflict.warScore || 0) + swing, -100, 100);
                conflict.intensity = livingClamp((conflict.intensity || 20) + (Math.abs(swing) ? 1 : -1), 0, 100);
                changed++;
            }
        }
    }

    if (config.growth && turn % 10 === 0) {
        const candidates = Object.entries(society.settlements)
            .filter(([, settlement]) => Math.abs(settlement.growth) >= 4)
            .sort((a, b) => Math.abs(b[1].growth) - Math.abs(a[1].growth));
        if (candidates.length) {
            const [locationId, settlement] = candidates[0];
            const positive = settlement.growth > 0;
            const options = positive
                ? ['A new workshop has opened', 'A market quarter is expanding', 'New households have arrived', 'Road repairs have begun']
                : ['Families are leaving', 'A workshop has shuttered', 'Food queues have lengthened', 'Road maintenance has stopped'];
            const detail = options[Math.floor(stableWorldRoll(`${locationId}|development|${turn}`) * options.length)];
            const development = {
                id: `development_${turn}_${locationId}`, turn, locationId,
                text: `${detail} in ${settlement.name}.`, direction: positive ? 'growth' : 'decline'
            };
            society.developments.push(development);
            addWorldNews(sess, development.text, {
                id: development.id, locationId, type: 'society', playerVisible: false, knownBy: []
            });
            changed++;
        }
    }
    // Long-running sandboxes can cover years. Keep the structural record
    // useful and bounded just like worldNews; the newest developments retain
    // the current shape while the ledger/history preserve player-facing canon.
    society.developments = society.developments.slice(-80);
    society.conflicts = society.conflicts.slice(-60);
    return { changed, season: society.season, conflicts: society.conflicts.filter(item => item.status === 'war').length };
}

function getLocalSocietySettlement(world, sess) {
    const settlements = sess?.society?.settlements || {};
    if (settlements[sess?.playerLocation]) return settlements[sess.playerLocation];
    const location = getLocationRef(world, sess?.playerLocation);
    if (!location) return null;
    if (location.parentLocationId && settlements[location.parentLocationId]) {
        return settlements[location.parentLocationId];
    }
    const sameRegion = (world.locations || []).find(candidate =>
        candidate.id !== location.id && candidate.region === location.region && settlements[candidate.id]);
    return sameRegion ? settlements[sameRegion.id] : null;
}

function getWorldSocietyPrompt(world, sess) {
    const config = normalizeWorldSandboxConfig(world);
    const society = normalizeWorldSocietyState(world, sess);
    if (!config.enabled || !society) return '';
    const identity = sess.playerIdentity || {};
    const lines = ['[LIVING SOCIETY — causal macro-simulation; do not expose hidden numbers as UI]'];
    if (identity.role) {
        lines.push(`Player identity: ${identity.title ? `${identity.title}; ` : ''}${identity.role}; rank ${identity.socialRank || 'unspecified'}; legal status ${identity.legalStatus || 'free'}.`);
        if (identity.factionId) lines.push(`Player allegiance: ${sess.factions.find(item => item.id === identity.factionId)?.name || identity.factionId}.`);
        if (identity.privileges?.length) lines.push(`Privileges: ${identity.privileges.join('; ')}.`);
        if (identity.obligations?.length) lines.push(`Obligations: ${identity.obligations.join('; ')}. These are pressures and choices, not forced player actions.`);
        if (identity.holdings?.length) lines.push(`Holdings: ${identity.holdings.join('; ')}.`);
    }
    lines.push(`Calendar: ${society.season}, Year ${society.year} (${config.calendar}); scale: ${config.scale}.`);
    const local = getLocalSocietySettlement(world, sess);
    if (local) {
        lines.push(`Local society: population about ${local.population}; food ${local.food}/100; wealth ${local.wealth}/100; security ${local.security}/100; unrest ${local.unrest}/100; trend ${local.growth > 3 ? 'growing' : local.growth < -3 ? 'declining' : 'stable'}.`);
    }
    const wars = society.conflicts.filter(item => item.status === 'war').slice(0, 6).map(conflict => {
        const names = conflict.sides.map(id => sess.factions.find(faction => faction.id === id)?.name || id);
        return `${names.join(' vs ')} (intensity ${conflict.intensity}, balance ${conflict.warScore})`;
    });
    if (wars.length) lines.push(`Active conflicts: ${wars.join(' | ')}.`);
    const developments = society.developments.slice(-5).map(item => item.text);
    if (developments.length) lines.push(`Recent structural developments: ${developments.join(' | ')}.`);
    if (config.principles) lines.push(`Author's society principles: ${config.principles}`);
    lines.push('Status is real but not destiny. The player may rise, fall, abdicate, desert, inherit, conquer, build, reform, commit crimes, seek pardon, or leave it all. Never railroad them back into their starting role.');
    return `\n${lines.join('\n')}\n`;
}

function addWorldNews(sess, text, metadata = {}) {
    const clean = String(text || '').trim();
    if (!sess || !clean) return null;
    sess.worldNews = Array.isArray(sess.worldNews) ? sess.worldNews : [];
    const duplicate = sess.worldNews.find(item => item.text === clean && item.turn === (sess.turnCount || 1));
    if (duplicate) return duplicate;
    const item = {
        id: metadata.id || livingId('news', `${sess.turnCount || 1}_${clean}`),
        text: clean.slice(0, 400),
        turn: sess.turnCount || 1,
        locationId: metadata.locationId || null,
        factionId: metadata.factionId || null,
        type: metadata.type || 'world',
        playerVisible: metadata.playerVisible !== false,
        // Who currently carries this fact. Information reaches the player only
        // through a character who knows it (or by witnessing it firsthand), so
        // "don't reveal remote facts" becomes a mechanic instead of a request.
        knownBy: [...new Set((Array.isArray(metadata.knownBy) ? metadata.knownBy : [])
            .map(id => String(id || '')).filter(Boolean))].slice(0, 40),
        playerWitnessed: metadata.playerWitnessed === true,
        // New records start canonical so re-entering the same turn is a true
        // no-op instead of lazily adding this field on the second tick.
        transmissions: []
    };
    sess.worldNews.push(item);
    if (sess.worldNews.length > 80) sess.worldNews.splice(0, sess.worldNews.length - 80);
    return item;
}

// Who is standing where, built once per tick. Both witnessing and rumour need
// this, and rebuilding it per lookup turns the tick quadratic on large worlds.
// Occupancy is capped per location: a crowded room does not need every occupant
// individually simulated to behave believably.
const LIVING_ROOM_CAP = 12;
function buildNpcLocationIndex(world, sess) {
    const index = new Map();
    sessionNpcs(world, sess).forEach(npc => {
        const entState = sess.entityStates?.[npc.id];
        if (!entState?.location || !isNpcActive(entState)) return;
        let group = index.get(entState.location);
        if (!group) index.set(entState.location, group = []);
        group.push(npc.id);
    });
    index.forEach((group, locationId) => {
        if (group.length > LIVING_ROOM_CAP) {
            index.set(locationId, rotatingWorldWindow(group, LIVING_ROOM_CAP,
                (sess.turnCount || 0) + Math.floor(stableWorldRoll(locationId) * group.length)));
        }
    });
    return index;
}

// Who could have seen something happen at a location: the actor always knows,
// and anyone else present may have noticed. A public event (chance 1) is seen by
// the whole room; a furtive personal act is meant to be missable, so bystanders
// witness it on a seeded roll instead.
function witnessesAt(npcIndex, sess, locationId, actorId, turn, chance = 0.35) {
    const known = actorId ? [actorId] : [];
    if (!locationId) return known;
    (npcIndex.get(locationId) || []).forEach(npcId => {
        if (npcId === actorId) return;
        if (chance >= 1 || stableWorldRoll(`${sess.id}|witness|${locationId}|${actorId}|${npcId}|${turn}`) < chance) {
            known.push(npcId);
        }
    });
    return known;
}

// Rumour: characters who share a location trade what they know. This is what
// carries a remote fact toward the player over time — and what makes distance
// and isolation meaningful, since an unvisited fact simply never travels.
//
// Work per tick is bounded on every axis (items, rooms, occupants). On a world
// with more populated rooms than the per-tick budget, the rooms are visited in a
// rotating window keyed on the turn, so everywhere still gets its turn to talk.
const LIVING_GOSSIP_ITEMS = 12;
const LIVING_GOSSIP_ROOMS = 40;
function spreadWorldKnowledge(world, npcIndex, sess, turn) {
    // Backward-compatible direct calls from older extensions/tests used
    // (npcIndex, session, turn). The canonical tick supplies the world so a
    // transmission can also become provenance-backed NPC knowledge.
    if (world instanceof Map) {
        turn = sess;
        sess = npcIndex;
        npcIndex = world;
        world = null;
    }
    if (!Array.isArray(sess.worldNews) || !sess.worldNews.length) return 0;
    const circulating = sess.worldNews.slice(-LIVING_GOSSIP_ITEMS)
        .filter(item => Array.isArray(item.knownBy) && item.knownBy.length > 0 && item.knownBy.length < 40);
    if (!circulating.length) return 0;

    const rooms = [];
    npcIndex.forEach((npcIds, locationId) => {
        if (npcIds.length >= 2) rooms.push([locationId, npcIds]);
    });
    if (!rooms.length) return 0;
    const window = rooms.length <= LIVING_GOSSIP_ROOMS
        ? rooms
        : Array.from({ length: LIVING_GOSSIP_ROOMS },
            (_, offset) => rooms[(turn * LIVING_GOSSIP_ROOMS + offset) % rooms.length]);

    let spread = 0;
    for (const [locationId, npcIds] of window) {
        for (const item of circulating) {
            const knows = new Set(item.knownBy);
            if (!npcIds.some(id => knows.has(id))) continue;   // nobody here can tell it
            for (const listenerId of npcIds) {
                if (knows.has(listenerId) || item.knownBy.length >= 40) continue;
                if (stableWorldRoll(`${sess.id}|gossip|${item.id}|${listenerId}|${locationId}|${turn}`) < 0.4) {
                    const speakerId = npcIds.find(id => knows.has(id));
                    item.knownBy.push(listenerId);
                    knows.add(listenerId);
                    if (!Array.isArray(item.transmissions)) item.transmissions = [];
                    const priorConfidence = Number(sess.entityStates?.[speakerId]?.observations
                        ?.find(observation => observation.eventId === item.eventId || observation.eventId === item.id)?.confidence || 0.8);
                    const confidence = livingClamp(priorConfidence * 0.82, 0.2, 0.95);
                    item.transmissions.push({ from: speakerId, to: listenerId, turn, locationId, confidence });
                    item.transmissions = item.transmissions.slice(-80);
                    if (world) addNpcKnowledge(world, sess, listenerId, {
                        id: `obs_gossip_${item.id}_${listenerId}`,
                        eventId: item.eventId || item.id,
                        text: item.text,
                        sourceType: 'told',
                        sourceNpcId: speakerId,
                        evidenceMode: 'hearsay',
                        confidence,
                        visibility: 'private',
                        allowedToShare: true,
                        turn
                    });
                    spread++;
                }
            }
        }
    }
    return spread;
}

// Standing conditions mostly mean trouble, but not always — a harvest festival
// is a condition too. Unrecognized labels are treated as mild disruption, which
// is the safer default for something the narrative bothered to mark.
const CALMING_CONDITION = /\b(festival|feast|harvest|peace|celebration|blessing|blessed|consecrated|garrison|reinforced|repaired|rebuilt|market\s?day|prosper\w*|bountiful|sanctuary|amnesty)\b/i;
const HARMFUL_CONDITION = /\b(fire|burning|siege|besieged|plague|pestilence|famine|starv\w*|flood|riot|curfew|raid\w*|quarantine|blockade|haunt\w*|cursed|collapse|infest\w*|blight|war|unrest|lawless|ambush|bandit|occupied)\b/i;

function conditionPressure(label) {
    const text = String(label || '');
    if (CALMING_CONDITION.test(text)) return -12;
    // A siege or a plague should make a place properly dangerous on its own;
    // two such conditions together should make it dire.
    if (HARMFUL_CONDITION.test(text)) return 30;
    return 10;
}

// Where a place is being pulled, before reversion. Positive = toward danger.
function locationPressure(world, sess, locationId, locState) {
    let pressure = 0;
    (locState.conditions || []).forEach(condition => { pressure += conditionPressure(condition.label); });

    const factions = Array.isArray(sess.factions) ? sess.factions : [];
    const claimants = factions.filter(faction =>
        !['defeated', 'disbanded'].includes(faction.status)
        && Array.isArray(faction.territory) && faction.territory.includes(locationId));
    // Two powers pulling at the same ground is the definition of a dangerous
    // place, whatever either of them intends.
    if (claimants.length > 1) pressure += 8 + (claimants.length - 1) * 4;

    const holder = factions.find(faction => faction.id === locState.controlFactionId);
    if (holder && !['defeated', 'disbanded'].includes(holder.status)) {
        // Firm control settles a place; a weakened or waning holder invites trouble.
        if (holder.status === 'weakened') pressure += 10;
        else if (holder.influence >= 60) pressure -= 8;
        else if (holder.influence <= 30) pressure += 6;
    } else if (locState.controlFactionId) {
        pressure += 6;   // whoever held this is gone
    }
    return pressure;
}

// Danger and prosperity ease toward what the world justifies, one step a tick.
function driftLocationStates(world, sess, turn, npcIndex) {
    const occupancy = npcIndex || buildNpcLocationIndex(world, sess);
    let changed = 0;
    Object.entries(sess.locationStates || {}).forEach(([locationId, locState]) => {
        const pressure = locationPressure(world, sess, locationId, locState);
        // Whole numbers, so a settled place rests instead of oscillating around
        // a fractional target forever.
        const dangerTarget = Math.round(livingClamp(pressure, 0, 100));
        const prosperityTarget = Math.round(livingClamp(50 - pressure * 0.8, 0, 100));
        const previousDanger = locState.danger;
        const previousProsperity = locState.prosperity;

        // Slow and seeded: places change over a stay, not between two sentences.
        if (locState.danger !== dangerTarget
            && stableWorldRoll(`${sess.id}|danger|${locationId}|${turn}`) < 0.35) {
            locState.danger = livingClamp(locState.danger + Math.sign(dangerTarget - locState.danger), 0, 100);
        }
        if (locState.prosperity !== prosperityTarget
            && stableWorldRoll(`${sess.id}|prosperity|${locationId}|${turn}`) < 0.25) {
            locState.prosperity = livingClamp(locState.prosperity + Math.sign(prosperityTarget - locState.prosperity), 0, 100);
        }
        if (locState.danger === previousDanger && locState.prosperity === previousProsperity) return;
        changed++;

        // Only announce genuine turns of the tide, not every point.
        const band = value => value >= 70 ? 3 : value >= 40 ? 2 : value >= 15 ? 1 : 0;
        const place = world.locations.find(item => item.id === locationId);
        if (!place) return;
        const dangerBandChanged = band(previousDanger) !== band(locState.danger);
        const prosperityBandChanged = band(previousProsperity) !== band(locState.prosperity);
        if (!dangerBandChanged && !prosperityBandChanged) return;
        const rising = dangerBandChanged
            ? locState.danger > previousDanger
            : locState.prosperity < previousProsperity;
        addWorldNews(sess, dangerBandChanged
            ? (rising ? `${place.name} has become a more dangerous place to be.`
                      : `${place.name} has settled; people move more freely there again.`)
            : (rising ? `${place.name} is visibly poorer than it was.`
                      : `${place.name} is doing better than it was.`), {
            id: `news_place_${locationId}_${turn}`, locationId, type: 'world', playerVisible: false,
            // Whoever is standing there can see it for themselves.
            knownBy: occupancy.get(locationId) || []
        });
    });
    return changed;
}

function updatePlaystyleProfile(sess, input) {
    const text = String(input || '').toLowerCase();
    if (!sess || !text.trim()) return;
    const categories = {
        combat: /\b(attack|fight|shoot|stab|punch|kill|weapon|spell|ambush)\b/,
        social: /\b(talk|ask|tell|persuade|convince|negotiate|apologize|joke|comfort)\b/,
        exploration: /\b(explore|travel|go to|enter|climb|cross|map|look around|search the area)\b/,
        investigation: /\b(investigate|inspect|examine|clue|deduce|question|evidence|search for)\b/,
        stealth: /\b(sneak|hide|stealth|quietly|pickpocket|disguise|avoid notice)\b/,
        crafting: /\b(craft|build|repair|cook|brew|forge|make|harvest)\b/,
        romance: /\b(flirt|kiss|romance|embrace|date|seduce|hold hands)\b/,
        mercy: /\b(spare|forgive|mercy|help|heal|rescue|release)\b/,
        aggression: /\b(threaten|intimidate|torture|execute|betray|burn|destroy)\b/
    };
    sess.playstyle = sess.playstyle || { turnsObserved: 0, signals: {}, preferences: {}, dominant: [] };
    sess.playstyle.signals = sess.playstyle.signals || {};
    sess.playstyle.turnsObserved = (parseInt(sess.playstyle.turnsObserved) || 0) + 1;
    Object.entries(categories).forEach(([key, pattern]) => {
        if (pattern.test(text)) sess.playstyle.signals[key] = (parseInt(sess.playstyle.signals[key]) || 0) + 1;
    });
    sess.playstyle.dominant = Object.entries(sess.playstyle.signals)
        .filter(([, count]) => count > 0)
        .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
        .slice(0, 3)
        .map(([key]) => key);
    sess.playstyle.summary = sess.playstyle.dominant.length
        ? `Observed lean: ${sess.playstyle.dominant.join(', ')}. Treat this as a soft signal, not a restriction.`
        : 'No clear playstyle pattern yet.';
}

function relationshipKey(a, b) {
    return [String(a || ''), String(b || '')].sort().join('|');
}

// --- Faction causation -----------------------------------------------------
// Factions used to advance in complete isolation: `relations` was stored,
// displayed, and never read, so no alliance ever helped anyone and no rivalry
// ever cost anyone anything. These three functions make a faction's situation
// — who stands with it, who against it, and whose ground it is standing on —
// actually bear on what happens to it.
const FACTION_ALLY_AT = 30;
const FACTION_HOSTILE_AT = -30;
const FACTION_WAR_AT = -70;
const FACTION_AMBIENT_FLOOR = -60;   // coexistence alone cannot cause open war
const FACTION_PAIR_CAP = 12;   // bounded pair work; real worlds have a handful

// A power that has achieved its aim and has no authored follow-up does not
// simply stop existing. It takes the stance its situation dictates — derived
// from state, not invented lore, so the engine never fabricates fiction.
function nextFactionAim(sess, faction) {
    const standing = factionStanding(sess, faction);
    if (standing.contested) return 'secure its contested holdings';
    if (standing.enemies.length) return `gain the upper hand over ${standing.enemies[0].name}`;
    if (standing.allies.length) return `deepen its understanding with ${standing.allies[0].name}`;
    return 'extend its influence';
}

function livingFactionById(sess, id) {
    return (sess.factions || []).find(faction => faction.id === id) || null;
}

function factionRelationScore(faction, otherId) {
    const relation = (faction.relations || []).find(item => item.factionId === otherId);
    return relation ? (Number(relation.score) || 0) : 0;
}

// Relations are stored per-faction, so a one-sided edit produced a world where
// A hated B while B felt nothing. Always move both sides together.
function adjustFactionRelation(sess, a, b, delta) {
    if (!a || !b || a.id === b.id) return 0;
    let moved = 0;
    [[a, b], [b, a]].forEach(([from, to]) => {
        from.relations = Array.isArray(from.relations) ? from.relations : [];
        let relation = from.relations.find(item => item.factionId === to.id);
        if (!relation) {
            relation = { factionId: to.id, score: 0 };
            from.relations.push(relation);
        }
        const before = relation.score;
        relation.score = livingClamp(relation.score + delta, -100, 100);
        if (relation.score !== before) moved++;
    });
    return moved;
}

function factionStanding(sess, faction) {
    const others = (sess.factions || []).filter(item =>
        item.id !== faction.id && !['defeated', 'disbanded'].includes(item.status));
    const allies = others.filter(item => factionRelationScore(faction, item.id) >= FACTION_ALLY_AT);
    const enemies = others.filter(item => factionRelationScore(faction, item.id) <= FACTION_HOSTILE_AT);
    const territory = Array.isArray(faction.territory) ? faction.territory : [];
    const contested = enemies.reduce((total, enemy) =>
        total + (enemy.territory || []).filter(id => territory.includes(id)).length, 0);
    // Friends lend weight; enemies obstruct; ground you must hold against someone
    // slows everything down.
    const momentum = (allies.length * 0.04) - (enemies.length * 0.05) - (contested * 0.03);
    return { allies, enemies, contested, momentum };
}

function resolveFactionVictory(world, sess, faction, turn) {
    let changes = 0;
    const locName = id => world.locations.find(item => item.id === id)?.name || id;
    faction.influence = livingClamp(faction.influence + 8, 0, 100);
    addWorldNews(sess, `${faction.name} achieved its objective: ${faction.goal}.`, {
        id: `news_faction_${faction.id}_${turn}`, factionId: faction.id, type: 'faction'
    });
    changes++;

    const { enemies } = factionStanding(sess, faction);
    const rival = [...enemies].sort((a, b) => b.influence - a.influence)[0] || null;
    if (rival) {
        // Winning takes something from someone. Prefer ground they were both
        // standing on, otherwise the rival's most prized holding.
        const territory = Array.isArray(faction.territory) ? faction.territory : (faction.territory = []);
        const rivalTerritory = Array.isArray(rival.territory) ? rival.territory : (rival.territory = []);
        const seized = rivalTerritory.find(id => territory.includes(id)) || rivalTerritory[0] || '';
        if (seized) {
            rival.territory = rivalTerritory.filter(id => id !== seized);
            if (!territory.includes(seized)) territory.push(seized);
            const locState = sess.locationStates?.[seized];
            if (locState) locState.controlFactionId = faction.id;
            addWorldNews(sess, `${faction.name} has taken ${locName(seized)} from ${rival.name}.`, {
                id: `news_faction_seize_${faction.id}_${turn}`, locationId: seized,
                factionId: faction.id, type: 'faction'
            });
            changes++;
        }
        rival.influence = livingClamp(rival.influence - 6, 0, 100);
        if (rival.influence <= 15 && rival.status === 'active') {
            rival.status = 'weakened';
            addWorldNews(sess, `${rival.name} is visibly weakened.`, {
                id: `news_faction_weak_${rival.id}_${turn}`, factionId: rival.id, type: 'faction'
            });
        }
        changes += adjustFactionRelation(sess, faction, rival, -15);

        // The loser answers. A consequence the player can later run into.
        if ((sess.scheduledEvents || []).length < 500) {
            const eventId = livingId('event', `${rival.id}_answer_${turn}`);
            if (!sess.scheduledEvents.some(event => event.id === eventId)) {
                sess.scheduledEvents.push({
                    id: eventId,
                    title: `${rival.name} answers ${faction.name}`,
                    description: `Having lost ground to ${faction.name}, ${rival.name} moves to recover it.`,
                    status: 'scheduled',
                    dueTurn: turn + 3 + Math.floor(stableWorldRoll(`${rival.id}|answer|${turn}`) * 6),
                    dueMinute: null, repeatEveryTurns: 0, repeatEveryMinutes: 0,
                    locationId: seized || null,
                    conditionOnTrigger: seized ? 'Contested' : '',
                    conditionDurationTurns: seized ? 12 : 0,
                    factionId: rival.id, influenceChange: 4, lastTriggeredTurn: 0
                });
                changes++;
            }
        }
    }

    // An achieved aim must not leave the faction inert forever. Record it and
    // free the slot so a new goal can be taken up.
    faction.achievements = [...(Array.isArray(faction.achievements) ? faction.achievements : []), faction.goal]
        .filter(Boolean).slice(-10);
    const done = new Set(faction.achievements);
    // An authored continuation first; otherwise the stance its situation implies.
    const pooled = (Array.isArray(faction.goalPool) ? faction.goalPool : [])
        .map(entry => String(typeof entry === 'string' ? entry : entry?.goal || '').trim())
        .find(goal => goal && !done.has(goal));
    faction.goal = (pooled || nextFactionAim(sess, faction)).slice(0, 240);
    faction.goalProgress = 0;
    return changes;
}

function driftFactionRelations(world, sess, turn) {
    const activePool = (sess.factions || [])
        .filter(faction => !['defeated', 'disbanded'].includes(faction.status));
    const active = typeof rotatingWorldWindow === 'function'
        ? rotatingWorldWindow(activePool, FACTION_PAIR_CAP, turn)
        : activePool.slice(0, FACTION_PAIR_CAP);
    let changes = 0;
    for (let i = 0; i < active.length - 1; i++) {
        for (let j = i + 1; j < active.length; j++) {
            const a = active[i];
            const b = active[j];
            if (stableWorldRoll(`${sess.id}|frel|${a.id}|${b.id}|${turn}`) >= 0.12) continue;
            const before = factionRelationScore(a, b.id);

            const aTerritory = Array.isArray(a.territory) ? a.territory : [];
            const bTerritory = Array.isArray(b.territory) ? b.territory : [];
            const overlap = bTerritory.filter(id => aTerritory.includes(id)).length;
            // A common enemy is the oldest reason on earth to become friends.
            const sharedEnemies = active.filter(other =>
                other.id !== a.id && other.id !== b.id
                && factionRelationScore(a, other.id) <= FACTION_HOSTILE_AT
                && factionRelationScore(b, other.id) <= FACTION_HOSTILE_AT).length;

            let delta = 0;
            // Ambient friction takes a shared border as far as real hostility but
            // no further — open war should be caused by something happening (a
            // seizure, a betrayal), not by two powers merely coexisting long
            // enough. Without this floor, every campaign drifts into war on a
            // long enough timeline regardless of events.
            if (overlap > 0 && before > FACTION_AMBIENT_FLOOR) delta -= 1 + Math.min(2, overlap);
            if (sharedEnemies > 0) delta += 1;
            if (!delta) continue;
            changes += adjustFactionRelation(sess, a, b, delta);

            const after = factionRelationScore(a, b.id);
            // Only announce the moments that change the nature of the thing.
            const crossed = (mark) => (before > mark && after <= mark) || (before < mark && after >= mark);
            if (crossed(FACTION_WAR_AT)) {
                addWorldNews(sess, after <= FACTION_WAR_AT
                    ? `${a.name} and ${b.name} are now openly hostile.`
                    : `${a.name} and ${b.name} have pulled back from open hostility.`, {
                    id: `news_frel_war_${a.id}_${b.id}_${turn}`, factionId: a.id, type: 'faction'
                });
            } else if (crossed(FACTION_ALLY_AT)) {
                addWorldNews(sess, after >= FACTION_ALLY_AT
                    ? `${a.name} and ${b.name} have found common cause.`
                    : `The understanding between ${a.name} and ${b.name} has cooled.`, {
                    id: `news_frel_ally_${a.id}_${b.id}_${turn}`, factionId: a.id, type: 'faction'
                });
            }
        }
    }
    return changes;
}

function runLivingWorldTick(world, sess) {
    const modules = normalizeWorldGameRules(world).modules;
    if (!modules.livingWorld) {
        return { advanced: false, disabled: true, turn: Math.max(1, parseInt(sess?.turnCount) || 1), events: 0, goals: 0, factions: 0, markets: 0 };
    }
    normalizeLivingWorldState(world, sess);
    const turn = Math.max(1, parseInt(sess.turnCount) || 1);
    const time = getWorldTimeData(world, sess);
    // The turn-based simulation advances exactly once per turn. The world clock,
    // however, can jump mid-turn when the DM applies time_skip_minutes (sleep,
    // waiting, long travel). Re-entering after such a jump runs a clock-only
    // catch-up so events scheduled inside the skipped window fire during that
    // turn instead of surfacing one action late.
    const alreadyAdvanced = sess.lastLivingWorldTick >= turn;
    const clockAdvanced = time.currentTotalMinutes > (Number(sess.lastLivingWorldMinute) || 0);
    if (alreadyAdvanced && !clockAdvanced) {
        return {
            advanced: false,
            turn,
            events: sess.livingWorldActivity.events || 0,
            goals: sess.livingWorldActivity.goals || 0,
            factions: sess.livingWorldActivity.factions || 0,
            markets: sess.livingWorldActivity.markets || 0
        };
    }
    const clockCatchUpOnly = alreadyAdvanced;
    sess.lastLivingWorldTick = turn;
    sess.lastLivingWorldMinute = time.currentTotalMinutes;
    let eventCount = 0;
    let goalCount = 0;
    let factionCount = 0;
    let marketCount = 0;
    // Built once: witnessing and rumour both need to know who is standing where.
    const npcIndex = buildNpcLocationIndex(world, sess);

    if (!clockCatchUpOnly) {
        Object.values(sess.locationStates).forEach(locState => {
            locState.conditions = (locState.conditions || []).filter(condition =>
                condition.expiresTurn == null || condition.expiresTurn > turn);
        });
    }

    sess.scheduledEvents.forEach(event => {
        if (event.status !== 'scheduled') return;
        const turnDue = !clockCatchUpOnly && event.dueTurn != null && turn >= event.dueTurn;
        const minuteDue = event.dueMinute != null && time.currentTotalMinutes >= event.dueMinute;
        if (!turnDue && !minuteDue) return;
        event.lastTriggeredTurn = turn;
        eventCount++;
        const location = world.locations.find(item => item.id === event.locationId);
        const where = location ? ` at ${location.name}` : '';
        const newsText = `${event.title}${where}: ${event.description}`;
        // Anyone standing where it happened knows it happened. A worldwide event
        // (no location) is public by nature and needs no carrier to travel.
        const atPlayer = !event.locationId || event.locationId === sess.playerLocation;
        addWorldNews(sess, newsText, {
            id: `news_${event.id}_${turn}`, locationId: event.locationId,
            factionId: event.factionId, type: 'event',
            knownBy: event.locationId ? witnessesAt(npcIndex, sess, event.locationId, '', turn, 1) : [],
            playerWitnessed: atPlayer
        });

        if (event.conditionOnTrigger && event.locationId) {
            const locState = sess.locationStates[event.locationId] || {
                conditions: [], controlFactionId: '', danger: 0, prosperity: 50, resources: {}
            };
            const conditionId = livingId('condition', `${event.id}_${event.conditionOnTrigger}`);
            const existing = locState.conditions.find(condition => condition.id === conditionId);
            const expiresTurn = event.conditionDurationTurns > 0 ? turn + event.conditionDurationTurns : null;
            if (existing) existing.expiresTurn = expiresTurn;
            else locState.conditions.push({ id: conditionId, label: event.conditionOnTrigger, expiresTurn });
            sess.locationStates[event.locationId] = locState;
        }
        if (event.factionId && event.influenceChange) {
            const faction = sess.factions.find(item => item.id === event.factionId);
            if (faction) faction.influence = livingClamp(faction.influence + event.influenceChange, 0, 100);
        }
        if (!event.locationId || event.locationId === sess.playerLocation) {
            queueEngineEvent(sess, `${newsText} Narrate its immediate, observable consequences.`);
        }

        if (event.repeatEveryTurns > 0 || event.repeatEveryMinutes > 0) {
            if (event.repeatEveryTurns > 0) event.dueTurn = turn + event.repeatEveryTurns;
            else event.dueTurn = null;
            if (event.repeatEveryMinutes > 0) event.dueMinute = time.currentTotalMinutes + event.repeatEveryMinutes;
            else event.dueMinute = null;
        } else {
            event.status = 'triggered';
        }
    });

    sessionNpcs(world, sess).forEach(npc => {
        if (clockCatchUpOnly) return;   // agendas advance per turn, not per clock jump
        const entState = sess.entityStates?.[npc.id];
        if (!entState?.goal || !isNpcActive(entState)) return;
        if (entState.location === sess.playerLocation) return;   // on-screen: the DM's domain

        // A finished agenda is not the end of a life. After a rest, an NPC with
        // authored follow-ups (goalPool) takes up the next unused one, so the
        // world does not quietly run down as goals resolve. NPCs without a pool
        // stay resolved until the DM hands them something new.
        if (entState.goalStatus === 'completed' || entState.goalStatus === 'failed') {
            if (!Array.isArray(npc.goalPool) || !npc.goalPool.length) return;
            if (!entState.goalResolvedTurn) { entState.goalResolvedTurn = turn; return; }
            if (turn - entState.goalResolvedTurn < 8) return;   // let the dust settle
            const done = new Set([...(Array.isArray(entState.goalHistory) ? entState.goalHistory : []), entState.goal]);
            const next = npc.goalPool
                .map(entry => (typeof entry === 'string' ? { goal: entry } : (entry || {})))
                .find(entry => entry.goal && !done.has(String(entry.goal).trim().slice(0, 200)));
            if (!next) return;   // pool exhausted: this life's stories are told
            entState.goalHistory = [...done].slice(-10);
            entState.goal = String(next.goal).trim().slice(0, 200);
            entState.goalProgress = 0;
            entState.goalStatus = 'active';
            entState.goalDifficulty = livingClamp(next.difficulty == null ? (entState.goalDifficulty ?? 50) : next.difficulty, 0, 100);
            entState.goalAutonomy = ['paused', 'low', 'medium', 'high'].includes(next.autonomy)
                ? next.autonomy : (entState.goalAutonomy || 'medium');
            entState.goalSteps = (Array.isArray(next.steps) ? next.steps : [])
                .map(step => String(step).slice(0, 160)).filter(Boolean).slice(0, 20);
            entState.goalStepIndex = 0;
            entState.goalStepReported = -1;
            delete entState.goalDeadlineTurn;
            delete entState.goalResolvedTurn;
            goalCount++;
            addWorldNews(sess, `${npc.name} has set their mind to something new: ${entState.goal}`, {
                id: `news_goal_new_${npc.id}_${turn}`, locationId: entState.location,
                type: 'npc_goal', playerVisible: false, knownBy: [npc.id]
            });
            return;
        }
        if (entState.goalStatus !== 'active' || entState.goalAutonomy === 'paused') return;
        if (entState.goalDeadlineTurn && turn > entState.goalDeadlineTurn) {
            entState.goalStatus = 'failed';
            entState.goalResolvedTurn = turn;
            addWorldNews(sess, `${npc.name}'s effort to ${entState.goal} failed when time ran out.`, {
                id: `news_goal_failed_${npc.id}_${turn}`, locationId: entState.location, type: 'npc_goal', playerVisible: false
            });
            goalCount++;
            return;
        }
        const autonomyRate = { low: 0.28, medium: 0.52, high: 0.78 }[entState.goalAutonomy] || 0.52;
        const difficultyPenalty = (entState.goalDifficulty || 50) / 250;
        const roll = stableWorldRoll(`${world.id}|${sess.id}|${npc.id}|goal|${turn}`);
        if (roll > Math.max(0.08, autonomyRate - difficultyPenalty)) return;
        const gain = 1 + Math.floor(stableWorldRoll(`${npc.id}|gain|${turn}`) * (entState.goalAutonomy === 'high' ? 5 : 3));
        const previous = entState.goalProgress || 0;
        entState.goalProgress = livingClamp(previous + gain, 0, 100);
        goalCount++;

        // An advancing agenda must leave a CONCRETE trace, not a progress bar.
        // Authored goalSteps are the beats of that agenda; each beat is reported
        // exactly once, in order, as the specific thing the NPC did — so it can
        // be discovered later as a fact rather than improvised on the spot.
        // goalStepReported tracks the last beat announced (-1 = none yet), which
        // is what lets the opening beat surface at all.
        const lastReported = Number.isFinite(entState.goalStepReported) ? entState.goalStepReported : -1;
        const freshSteps = [];
        if (entState.goalSteps.length > 0) {
            const stepSize = 100 / entState.goalSteps.length;
            entState.goalStepIndex = livingClamp(Math.floor(Math.max(0, entState.goalProgress - 0.001) / stepSize), 0, entState.goalSteps.length - 1);
            for (let index = lastReported + 1; index <= entState.goalStepIndex; index++) {
                if (entState.goalSteps[index]) freshSteps.push({ index, text: entState.goalSteps[index] });
            }
        }
        const crossedMilestone = Math.floor(previous / 25) < Math.floor(entState.goalProgress / 25);
        const stepLocation = world.locations.find(item => item.id === entState.location);
        const whereabouts = stepLocation ? ` at ${stepLocation.name}` : '';
        const finalIndex = entState.goalSteps.length - 1;
        const completing = entState.goalProgress >= 100;

        // Beats that landed this tick. On the completing tick the last beat is
        // folded into the completion line instead of being announced twice.
        // The actor always knows what they did; anyone sharing the room may have
        // seen it, which is where the rumour starts.
        const beatWitnesses = witnessesAt(npcIndex, sess, entState.location, npc.id, turn);
        freshSteps
            .filter(step => !(completing && step.index === finalIndex))
            .forEach(step => {
                addWorldNews(sess, `${npc.name}${whereabouts}: ${step.text}`, {
                    id: `news_goal_step_${npc.id}_${step.index}_${turn}`,
                    locationId: entState.location, type: 'npc_goal', playerVisible: false,
                    knownBy: beatWitnesses
                });
            });
        if (entState.goalSteps.length > 0) {
            entState.goalStepReported = completing ? finalIndex : Math.max(lastReported, entState.goalStepIndex);
        }

        if (completing) {
            entState.goalStatus = 'completed';
            entState.goalResolvedTurn = turn;
            // Fold the closing beat into the completion line only when it lands
            // on this same tick; otherwise it was already reported and repeating
            // it verbatim reads as an echo in the news feed.
            const finalStep = entState.goalSteps.length ? entState.goalSteps[finalIndex] : '';
            const closedNow = freshSteps.some(step => step.index === finalIndex);
            addWorldNews(sess, finalStep && closedNow
                ? `${npc.name}${whereabouts}: ${finalStep} — completing their aim to ${entState.goal}.`
                : `${npc.name}${whereabouts} finished what they set out to do: ${entState.goal}.`, {
                id: `news_goal_complete_${npc.id}_${turn}`, locationId: entState.location, type: 'npc_goal', playerVisible: false,
                knownBy: beatWitnesses
            });
        } else if (crossedMilestone && entState.goalSteps.length === 0) {
            // Only agendas with no authored beats fall back to the vague line.
            addWorldNews(sess, `${npc.name} made significant off-screen progress toward: ${entState.goal}.`, {
                id: `news_goal_${npc.id}_${turn}`, locationId: entState.location, type: 'npc_goal', playerVisible: false,
                knownBy: beatWitnesses
            });
        }
    });

    // Relationship drift: people who share a room do not come out of fifty
    // turns together unchanged. Familiarity mostly warms, friction sometimes
    // cools, and standing hostility festers. The DM's authored labels are never
    // overwritten — drift only owns relationships it created (autoManaged).
    // Rooms containing the player are skipped: on-screen bonds are played out,
    // not simulated.
    let relationshipCount = 0;
    if (!clockCatchUpOnly && modules.relationships) {
        npcIndex.forEach((npcIds, locationId) => {
            if (npcIds.length < 2 || locationId === sess.playerLocation) return;
            for (let a = 0; a < npcIds.length - 1; a++) {
                for (let b = a + 1; b < npcIds.length; b++) {
                    const key = relationshipKey(npcIds[a], npcIds[b]);
                    if (stableWorldRoll(`${sess.id}|drift|${key}|${turn}`) >= 0.1) continue;
                    const rel = sess.npcRelationships[key]
                        || (sess.npcRelationships[key] = {
                            score: 0, label: '', reason: '', lastChangedTurn: 0, autoManaged: true
                        });
                    const previousScore = rel.score || 0;
                    const warm = stableWorldRoll(`${sess.id}|driftdir|${key}|${turn}`) < 0.75;
                    // Hostile pairs read every gesture badly: their drift inverts.
                    const delta = previousScore <= -15 ? (warm ? -1 : 1) : (warm ? 1 : -1);
                    rel.score = livingClamp(previousScore + delta, -100, 100);
                    rel.lastChangedTurn = turn;
                    relationshipCount++;
                    if (rel.autoManaged) {
                        rel.label = rel.score >= 50 ? 'close' : rel.score >= 20 ? 'friendly'
                            : rel.score <= -50 ? 'bitter enemies' : rel.score <= -20 ? 'strained'
                            : 'acquaintances';
                        if (!rel.reason) {
                            const room = world.locations.find(item => item.id === locationId);
                            rel.reason = `time shared at ${room ? room.name : 'the same place'}`;
                        }
                    }
                    if (Math.floor(previousScore / 25) !== Math.floor(rel.score / 25)) {
                        const nameA = world.entities.find(item => item.id === npcIds[a])?.name || npcIds[a];
                        const nameB = world.entities.find(item => item.id === npcIds[b])?.name || npcIds[b];
                        addWorldNews(sess, rel.score > previousScore
                            ? `${nameA} and ${nameB} have grown noticeably closer.`
                            : `Relations between ${nameA} and ${nameB} have soured.`, {
                            id: `news_rel_${key}_${turn}`, locationId, type: 'npc_goal', playerVisible: false,
                            knownBy: [npcIds[a], npcIds[b]]
                        });
                    }
                }
            }
        });
    }

    sess.factions.forEach(faction => {
        if (clockCatchUpOnly) return;   // faction drift is per turn, not per clock jump
        if (faction.status !== 'active' || !faction.goal || faction.goalProgress >= 100) return;

        // A faction does not pursue its aims in a vacuum. Allies lend weight,
        // enemies obstruct, and a power stretched across contested ground makes
        // slower progress than one working unopposed.
        const standing = factionStanding(sess, faction);
        const chance = livingClamp(0.18 + (faction.influence / 250) + standing.momentum, 0.03, 0.9);
        if (stableWorldRoll(`${world.id}|${sess.id}|${faction.id}|faction|${turn}`) > chance) return;
        const previous = faction.goalProgress;
        faction.goalProgress = livingClamp(previous + 1 + Math.floor(stableWorldRoll(`${faction.id}|gain|${turn}`) * 3), 0, 100);
        factionCount++;

        if (faction.goalProgress >= 100) {
            // Achieving an aim is a CAUSE, not just a headline. It takes ground,
            // shifts the balance of power, and provokes whoever it was aimed at.
            factionCount += resolveFactionVictory(world, sess, faction, turn);
        }
    });

    // Powers with a shared border and no shared cause drift apart; powers with a
    // common enemy drift together. This is what eventually produces alliances
    // and open hostility without anyone scripting them.
    if (!clockCatchUpOnly && sess.factions.length > 1) {
        factionCount += driftFactionRelations(world, sess, turn);
    }

    // Places have their own momentum. Danger and prosperity answer to what is
    // actually true of a location — its standing conditions, whether one faction
    // holds it or several are pulling at it — and, absent any of that, they ease
    // back toward normal. Without that reversion a world only ever ratchets
    // worse, because every source of pressure is additive.
    const placeCount = clockCatchUpOnly ? 0 : driftLocationStates(world, sess, turn, npcIndex);
    const societyResult = clockCatchUpOnly ? { changed: 0, conflicts: 0 }
        : runSocietySimulationTick(world, sess, turn);

    if (modules.commerce && !clockCatchUpOnly) {
        Object.entries(sess.economy.markets).forEach(([locationId, market]) => {
            const locState = sess.locationStates[locationId];
            Object.values(market).forEach(stock => {
                if (stock.regenPerTurn > 0 && stock.quantity < stock.maxQuantity) {
                    const previousQuantity = stock.quantity;
                    // A frightened, failing place restocks worse than a thriving one.
                    const supplyFactor = locState
                        ? livingClamp(0.4 + (locState.prosperity / 100) - (locState.danger / 200), 0.2, 1.6)
                        : 1;
                    const regen = Math.max(1, Math.round(stock.regenPerTurn * supplyFactor));
                    stock.quantity = livingClamp(stock.quantity + regen, 0, stock.maxQuantity);
                    if (stock.quantity !== previousQuantity) marketCount++;
                }
                // Scarcity and risk price themselves in, drifting a step at a
                // time around the item's established base rather than swinging.
                if (locState && stock.basePrice > 0) {
                    const scarcity = stock.maxQuantity > 0 ? 1 - (stock.quantity / stock.maxQuantity) : 0;
                    const pressure = (locState.danger / 100) * 0.35 + scarcity * 0.4 - (locState.prosperity / 100) * 0.25;
                    const target = livingClamp(Math.round(stock.basePrice * (1 + pressure)),
                        Math.max(1, Math.floor(stock.basePrice * 0.5)), Math.ceil(stock.basePrice * 2));
                    if (stock.price !== target) {
                        stock.price = livingClamp(stock.price + Math.sign(target - stock.price), 0, 999999);
                        marketCount++;
                    }
                }
            });
        });
    }

    // Word travels between characters who share a room. This is the step that
    // eventually carries a remote fact within earshot of the player.
    const rumoursSpread = clockCatchUpOnly ? 0 : spreadWorldKnowledge(world, npcIndex, sess, turn);
    const consequenceChanges = clockCatchUpOnly ? 0 : advanceWorldConsequences(world, sess, turn);

    // A catch-up pass only adds events; it must not erase the turn's tallies.
    Object.assign(sess.livingWorldActivity, clockCatchUpOnly ? {
        turn,
        events: (sess.livingWorldActivity.events || 0) + eventCount
    } : {
        turn,
        events: eventCount,
        goals: goalCount,
        factions: factionCount,
        markets: marketCount,
        rumours: rumoursSpread,
        relationships: relationshipCount,
        places: placeCount,
        society: societyResult.changed || 0,
        conflicts: societyResult.conflicts || 0,
        consequences: consequenceChanges
    });
    return {
        advanced: true,
        clockCatchUpOnly,
        turn,
        events: eventCount,
        goals: goalCount,
        factions: factionCount,
        markets: marketCount,
        rumours: rumoursSpread,
        relationships: relationshipCount,
        places: placeCount,
        society: societyResult.changed || 0,
        conflicts: societyResult.conflicts || 0,
        consequences: consequenceChanges
    };
}

function getLivingWorldPrompt(world, sess, presentNPCs = []) {
    const modules = normalizeWorldGameRules(world).modules;
    if (!modules.livingWorld) return '';
    normalizeLivingWorldState(world, sess);
    const lines = ['[LIVING WORLD — persistent simulation; DM-only knowledge unless plausibly observed or learned]'];
    const locState = sess.locationStates[sess.playerLocation];
    if (locState) {
        const faction = sess.factions.find(item => item.id === locState.controlFactionId);
        const conditions = (locState.conditions || []).map(item => item.label).join(', ');
        lines.push(`Current location state: danger ${locState.danger}/100; prosperity ${locState.prosperity}/100${faction ? `; controlled by ${faction.name}` : ''}${conditions ? `; conditions: ${conditions}` : ''}.`);
        const resources = Object.entries(locState.resources || {}).slice(0, 8).map(([key, value]) => `${key} ${value}`).join(', ');
        if (resources) lines.push(`Local resources: ${resources}.`);
    }
    const market = modules.commerce ? sess.economy.markets[sess.playerLocation] : null;
    if (market) {
        const stock = Object.values(market).slice(0, 10).map(item => `${item.item} x${item.quantity} @ ${item.price} ${sess.economy.currency}`).join(', ');
        if (stock) {
            // Name the trader when there is one, so buying happens through a
            // person rather than from thin air.
            const vendors = (world.entities || [])
                .filter(entity => entity.type === 'npc' && entity.vendorFor === sess.playerLocation
                    && isVisibleToSession(entity, sess) && isNpcActive(sess.entityStates?.[entity.id]))
                .map(entity => entity.name);
            lines.push(`Local market: ${stock}.${vendors.length ? ` Traded by ${vendors.join(', ')}.` : ''} Record any purchase or sale with the transactions field so the money and goods actually move.`);
        }
    }
    const upcoming = sess.scheduledEvents.filter(event => event.status === 'scheduled')
        .sort((a, b) => (a.dueTurn ?? 999999) - (b.dueTurn ?? 999999))
        .slice(0, 6);
    if (upcoming.length) lines.push(`Future events: ${upcoming.map(event => `${event.title} (turn ${event.dueTurn ?? '?'})`).join('; ')}.`);
    const activeConsequences = (sess.consequences || [])
        .filter(item => item.state !== 'resolved' && item.visibility !== 'hidden').slice(-8);
    if (activeConsequences.length) {
        lines.push(`Active consequences: ${activeConsequences.map(item =>
            `${item.title} [${item.state}, severity ${item.severity}/100]${item.detail && item.detail !== item.title ? ` — ${item.detail}` : ''}`
        ).join(' | ')}. Do not silently erase these; escalate, decay or resolve them only through causally relevant play.`);
    }
    const activeFactions = sess.factions.filter(faction => !['defeated', 'disbanded'].includes(faction.status)).slice(0, 8);
    if (activeFactions.length) {
        // Who stands with whom matters to how scenes play, so state it rather
        // than leaving the DM to guess from a number it never sees.
        const factionLine = faction => {
            const standing = factionStanding(sess, faction);
            const nameOfFaction = id => sess.factions.find(item => item.id === id)?.name || id;
            const parts = [`${faction.name} [influence ${faction.influence}, reputation ${faction.reputation}]`];
            if (faction.goal) parts.push(`seeks "${faction.goal}" (${faction.goalProgress}%)`);
            if (standing.allies.length) parts.push(`allied with ${standing.allies.map(a => nameOfFaction(a.id)).slice(0, 3).join(', ')}`);
            if (standing.enemies.length) {
                const atWar = standing.enemies.filter(e => factionRelationScore(faction, e.id) <= FACTION_WAR_AT);
                parts.push(`${atWar.length ? 'openly hostile to' : 'at odds with'} ${(atWar.length ? atWar : standing.enemies).map(e => nameOfFaction(e.id)).slice(0, 3).join(', ')}`);
            }
            if (standing.contested) parts.push(`${standing.contested} contested holding(s)`);
            if (faction.achievements?.length) parts.push(`has already achieved: ${faction.achievements.slice(-2).join('; ')}`);
            return parts.join(' — ');
        };
        lines.push(`Factions: ${activeFactions.map(factionLine).join(' | ')}.`);
        // A faction only reaches the scene through the people in it. Without
        // this the DM knows two powers are at war and still has no idea that
        // the man pouring the drinks is sworn to one of them.
        const affiliated = presentNPCs
            .map(npc => {
                const entity = world.entities.find(item => item.id === npc.id) || npc;
                const faction = entity.factionId && activeFactions.find(item => item.id === entity.factionId);
                return faction ? `${npc.name} of ${faction.name}` : null;
            })
            .filter(Boolean).slice(0, 8);
        if (affiliated.length) {
            lines.push(`Affiliations present: ${affiliated.join('; ')}. They act for their faction's interests, and what they see here can reach it.`);
        }
    }
    const presentIds = new Set(presentNPCs.map(npc => npc.id));
    const relevantRelationships = (modules.relationships ? Object.entries(sess.npcRelationships) : []).filter(([key]) =>
        key.split('|').some(id => presentIds.has(id))).slice(0, 8);
    if (relevantRelationships.length) {
        lines.push(`Relevant NPC relationships: ${relevantRelationships.map(([key, rel]) => {
            const names = key.split('|').map(id => world.entities.find(npc => npc.id === id)?.name || id).join(' ↔ ');
            return `${names}: ${rel.score}${rel.label ? ` (${rel.label})` : ''}${rel.reason ? ` — ${rel.reason}` : ''}`;
        }).join('; ')}.`);
    }
    if (sess.playstyle?.summary) lines.push(`Playstyle adaptation: ${sess.playstyle.summary} Offer compatible opportunities, but keep challenge, surprise, and player freedom.`);
    const explicitPreferences = Object.entries(sess.playstyle?.preferences || {}).slice(0, 10);
    if (explicitPreferences.length) {
        lines.push(`Recorded player preferences: ${explicitPreferences.map(([key, pref]) => `${key}=${pref.value} (confidence ${pref.confidence})`).join('; ')}.`);
    }
    // Information reaching the player is now a mechanic, not an honour system.
    // A development is tellable only through someone in the scene who actually
    // knows it (or because the player was there). Everything else is background
    // the DM may shape the world with, but may not speak aloud.
    const recentNews = sess.worldNews.slice(-16);
    const nameOf = id => world.entities.find(npc => npc.id === id)?.name || id;
    const tellable = [];
    const dark = [];
    recentNews.forEach(item => {
        if (item.playerWitnessed) {
            tellable.push(`${item.text} (the player saw this happen)`);
            return;
        }
        // null knownBy = recorded before knowledge tracking existed; treat as
        // common talk rather than retroactively sealing it away.
        if (item.knownBy === null) {
            tellable.push(`${item.text} (common talk)`);
            return;
        }
        const carriers = (item.knownBy || []).filter(id => presentIds.has(id));
        if (carriers.length) {
            tellable.push(`${item.text} — known here by ${carriers.slice(0, 3).map(nameOf).join(', ')}`);
        } else {
            dark.push(item.text);
        }
    });
    if (tellable.length) {
        lines.push(`Developments reachable in this scene — someone present knows each of these and may reveal it if the conversation earns it (in their own voice, with their own slant; they need not volunteer it): ${tellable.slice(-8).join(' | ')}.`);
    }
    if (dark.length) {
        lines.push(`Developments NOT yet reachable — nobody present knows these and the player has not witnessed them. Use them to shape the world's mood and consequences, but no character may mention, hint at, or act on them: ${dark.slice(-8).join(' | ')}.`);
    }
    return lines.length > 1 ? `\n${lines.join('\n')}` : '';
}

// --- World Agent -----------------------------------------------------------
// The deterministic tick keeps the world consistent; it cannot invent. The world
// agent is the one place the simulation is allowed to surprise you: on a long
// interval it reads a compact digest and proposes developments that follow from
// what is already in motion.
//
// It shapes the WORLD ONLY. Every field that touches the player — position,
// stats, inventory, dice, money, time, quests — is stripped before anything is
// applied, so an off-screen simulation can never reach in and edit the person
// playing. What survives goes through the same validated handlers the DM uses.
const WORLD_AGENT_FIELDS = Object.freeze([
    'world_events', 'npc_goal_updates', 'npc_moves', 'faction_updates',
    'location_state_updates', 'npc_relationship_updates', 'economy_updates',
    'schedule_updates'
]);

function normalizeWorldAgentConfig(world) {
    const raw = (world && typeof world.worldAgent === 'object' && !Array.isArray(world.worldAgent))
        ? world.worldAgent : {};
    return {
        enabled: raw.enabled === true,
        intervalTurns: Math.max(8, Math.min(200, parseInt(raw.intervalTurns) || 24)),
        model: String(raw.model || '').trim().slice(0, 160)
    };
}

function shouldRunWorldAgent(world, sess, options = {}) {
    if (!world || !sess) return false;
    if (options.isReroll) return false;            // replays must not re-roll the dice
    if (!normalizeWorldGameRules(world).modules.livingWorld) return false;
    const config = normalizeWorldAgentConfig(world);
    if (!config.enabled) return false;
    const turn = Math.max(1, parseInt(sess.turnCount) || 1);
    const last = Math.max(0, parseInt(sess.lastWorldAgentTurn) || 0);
    const elapsed = last === 0 ? turn : turn - last;
    if (elapsed < config.intervalTurns) return false;
    if (elapsed >= config.intervalTurns * 2) return true; // eventual momentum guarantee
    const queued = (sess.scheduledEvents || []).filter(event => event.status === 'scheduled'
        && (event.dueTurn == null || event.dueTurn >= turn)).length;
    const activeGoals = sessionNpcs(world, sess).filter(npc => {
        const npcState = sess.entityStates?.[npc.id];
        return npcState?.goal && ['active', 'blocked'].includes(npcState.goalStatus || 'active');
    }).length;
    // Ask for invention only when the deterministic kernel is running out of
    // future material. A populated event queue already keeps the world alive.
    return queued < Math.max(2, Math.min(6, Math.ceil(activeGoals / 4)));
}

// Compact enough to stay cheap: what is in motion, not the whole world.
function buildWorldAgentDigest(world, sess) {
    const time = getWorldTimeData(world, sess);
    const nameOf = id => world.entities.find(item => item.id === id)?.name || id;
    const locName = id => world.locations.find(item => item.id === id)?.name || id;
    const lines = [];
    lines.push(`WORLD: ${world.name}`);
    lines.push(`TIME: day ${time.days}, ${String(time.hours24).padStart(2, '0')}:${String(time.mins).padStart(2, '0')} (turn ${sess.turnCount || 1})`);
    lines.push(`PLAYER IS AT: ${locName(sess.playerLocation)} — do not move, harm, reward, or otherwise touch the player.`);

    const agendaPool = sessionNpcs(world, sess).map(npc => {
        const entState = sess.entityStates?.[npc.id];
        if (!entState?.goal || !isNpcActive(entState)) return null;
        const step = entState.goalSteps?.[entState.goalStepIndex || 0];
        return `- ${npc.name} [${npc.id}] at ${locName(entState.location)} — ${entState.goalStatus} "${entState.goal}" ${entState.goalProgress || 0}%${step ? ` (currently: ${step})` : ''}`;
    }).filter(Boolean);
    const agendas = rotatingWorldWindow(agendaPool, 20, sess.turnCount || 0);
    if (agendas.length) lines.push(`NPC AGENDAS IN MOTION:\n${agendas.join('\n')}`);

    const factions = rotatingWorldWindow((sess.factions || []).filter(f => !['defeated', 'disbanded'].includes(f.status)), 10, sess.turnCount || 0)
        .map(f => `- ${f.name} [${f.id}] influence ${f.influence}, reputation ${f.reputation}${f.goal ? ` — "${f.goal}" ${f.goalProgress}%` : ''}`);
    if (factions.length) lines.push(`FACTIONS:\n${factions.join('\n')}`);

    const pending = (sess.scheduledEvents || []).filter(e => e.status === 'scheduled').slice(0, 10)
        .map(e => `- ${e.title} (turn ${e.dueTurn ?? '?'}${e.locationId ? ` at ${locName(e.locationId)}` : ''})`);
    if (pending.length) lines.push(`ALREADY SCHEDULED (do not duplicate):\n${pending.join('\n')}`);

    const notable = rotatingWorldWindow(Object.entries(sess.locationStates || {})
        .filter(([, s]) => (s.conditions || []).length || s.danger > 30), 10, sess.turnCount || 0)
        .map(([id, s]) => `- ${locName(id)} [${id}]: danger ${s.danger}, prosperity ${s.prosperity}${(s.conditions || []).length ? `, ${s.conditions.map(c => c.label).join('/')}` : ''}`);
    if (notable.length) lines.push(`LOCATION STATES:\n${notable.join('\n')}`);

    const news = (sess.worldNews || []).slice(-12).map(item => `- ${item.text}`);
    if (news.length) lines.push(`RECENT DEVELOPMENTS:\n${news.join('\n')}`);

    const acted = (sess.history || []).filter(m => m.role === 'user').slice(-5).map(m => `- ${String(m.text || '').slice(0, 160)}`);
    if (acted.length) lines.push(`WHAT THE PLAYER HAS BEEN DOING:\n${acted.join('\n')}`);

    lines.push(`PLACES: ${rotatingWorldWindow(sessionLocations(world, sess), 60, sess.turnCount || 0).map(l => `${l.name} [${l.id}]`).join(', ')}`);
    return lines.join('\n\n');
}

function bumpWorldEpoch(session) {
    if (session) session._worldEpoch = (Number(session._worldEpoch) || 0) + 1;
    return Number(session?._worldEpoch) || 0;
}

// Strip anything that would let an off-screen simulation edit the player.
function sanitizeWorldAgentActions(raw) {
    const source = (raw && typeof raw === 'object' && !Array.isArray(raw)) ? raw : {};
    const actions = {};
    let dropped = 0;
    Object.keys(source).forEach(key => {
        if (WORLD_AGENT_FIELDS.includes(key)) {
            const value = source[key];
            if (Array.isArray(value) ? value.length : value != null) actions[key] = value;
        } else {
            dropped++;
        }
    });
    return { actions, dropped, applied: Object.keys(actions).length > 0 };
}

async function runWorldAgent(world, sess) {
    const config = normalizeWorldAgentConfig(world);
    const turn = Math.max(1, parseInt(sess.turnCount) || 1);
    const startEpoch = Number(sess._worldEpoch) || 0;
    sess.lastWorldAgentTurn = turn;   // set first: a failure must not retry every turn

    const system = `You are the WORLD AGENT for a persistent roleplay world. Between the player's scenes you decide what the rest of the world does.

Your job is CONSEQUENCE and MOMENTUM, not spectacle:
- Advance what is already in motion. Every development must follow from an existing agenda, faction, tension, or recent event in the digest.
- Prefer the small and concrete over the world-shaking: a debt called in, a door found open, a rumour reaching the wrong ear, a routine quietly changed.
- Let consequences land off-screen. People react to what has happened; they do not wait politely for the player.
- Do not repeat anything under ALREADY SCHEDULED.

ABSOLUTE LIMITS — you control the world, never the player:
- Never move, injure, heal, reward, rob, or otherwise affect the player character.
- Never invent player actions, decisions, or dialogue.
- Never create locations or people that do not appear in the digest; work with who and what exists.
- Never narrate prose. You emit state changes only.

Propose 1 to 3 developments. Return ONLY this JSON, no prose or fences:
{"developments":[{"summary":"<one sentence, for the author's log>"}],
 "world_events":[{"id":"<slug>","title":"<short>","description":"<one or two sentences>","due_turn":<integer turn>,"location_id":"<id or omit>","condition_on_trigger":"<optional short condition label>","condition_duration_turns":<optional integer>}],
 "npc_goal_updates":[{"npc_id":"<id>","goal":"<new goal, only to redirect someone>","goal_progress_change":<integer>,"status":"active|blocked|completed|failed"}],
 "npc_moves":[{"npc_id":"<id>","location_id":"<id>","reason":"<short>"}],
 "faction_updates":[{"id":"<id>","name":"<name>","influence_change":<integer>,"reputation_change":<integer>,"goal":"<optional>","goal_progress_change":<integer>}],
 "location_state_updates":[{"location_id":"<id>","danger_change":<integer>,"prosperity_change":<integer>,"conditions_add":["<label>"]}],
 "npc_relationship_updates":[{"source_npc_id":"<id>","target_npc_id":"<id>","change":<integer>,"reason":"<short>"}]}
Omit any array you are not using. Current turn is ${turn}; schedule events a few turns out, not in the past.`;

    const response = await fetch(apiBase() + '/chat/completions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...authHeaders() },
        body: JSON.stringify({
            model: config.model || structuredModelFor(world),
            max_tokens: 1200,
            messages: [
                { role: 'system', content: system },
                { role: 'user', content: buildWorldAgentDigest(world, sess) }
            ]
        })
    });
    if (!response.ok) {
        throw new Error((await response.json().catch(() => ({})))?.error?.message || response.statusText);
    }
    const content = (await response.json())?.choices?.[0]?.message?.content || '';
    const parsed = parseWorldAgentPayload(content);
    if (!parsed) throw new Error('World agent returned no usable JSON');

    // The player may have rerolled, reset, deleted this timeline, or advanced
    // it while the background request was in flight. Never apply a development
    // authored against a state that no longer exists.
    const liveInstance = state.worldInstances?.[world.id];
    const timelineStillExists = liveInstance?.sessions?.includes(sess);
    if (!timelineStillExists || (Number(sess._worldEpoch) || 0) !== startEpoch
        || Math.max(1, parseInt(sess.turnCount) || 1) !== turn) {
        console.warn('Horde Engine: discarded stale World Agent response after timeline changed.');
        return { applied: false, stale: true, turn, developments: [] };
    }

    const { actions, dropped } = sanitizeWorldAgentActions(parsed);
    if (dropped) console.warn(`Horde Engine: world agent proposed ${dropped} out-of-scope field(s); ignored.`);
    if (!Object.keys(actions).length) return { applied: false, turn, developments: [] };

    processStructuredActions(actions, world, sess);

    const developments = (Array.isArray(parsed.developments) ? parsed.developments : [])
        .map(item => String(item?.summary || item || '').trim()).filter(Boolean).slice(0, 5);
    developments.forEach((summary, index) => {
        addWorldNews(sess, summary, {
            id: `news_agent_${turn}_${index}`, type: 'world', playerVisible: false,
            knownBy: []   // nobody has heard yet; it must reach the player like anything else
        });
    });
    console.log(`Horde Engine: World Agent applied ${Object.keys(actions).join(', ')} on turn ${turn}`);
    return { applied: true, turn, developments, fields: Object.keys(actions) };
}

function parseWorldAgentPayload(raw) {
    const text = String(raw || '').trim();
    if (!text) return null;
    const candidates = [];
    const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
    if (fenced) candidates.push(fenced[1]);
    const first = text.indexOf('{');
    const last = text.lastIndexOf('}');
    if (first >= 0 && last > first) candidates.push(text.slice(first, last + 1));
    candidates.push(text);
    for (const candidate of candidates) {
        try {
            const parsed = JSON.parse(candidate);
            if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
        } catch (error) { /* try the next shape */ }
    }
    return null;
}

function syncNPCSchedules(world, sess) {
    if (!normalizeWorldGameRules(world).modules.schedules) {
        return { moves: 0, active: 0 };
    }
    normalizeLivingWorldState(world, sess);
    const time = getWorldTimeData(world, sess);
    const currentTimeStr = `${time.hours24.toString().padStart(2, '0')}:${time.mins.toString().padStart(2, '0')}`;
    let moveCount = 0;
    let activeCount = 0;

    world.entities.forEach(ent => {
        const hasTimelineOverride = Object.prototype.hasOwnProperty.call(sess.npcScheduleOverrides || {}, ent.id);
        if (!world.hudConfig?.enableSchedules && !hasTimelineOverride) return;
        const schedule = hasTimelineOverride
            ? sess.npcScheduleOverrides[ent.id]
            : ent.schedule;
        if (ent.type !== 'npc' || !schedule || schedule.length === 0) return;
        if (!isVisibleToSession(ent, sess)) return;               // other timeline's NPC
        if (!isNpcActive(sess.entityStates[ent.id])) return;      // the dead keep no appointments

        // Authored/imported world templates never pass through session
        // normalization, so an out-of-range time reaches the clock comparison
        // raw. Drop malformed blocks rather than let one become the fallback.
        const usable = schedule.filter(block => isValidScheduleTime(block?.time));
        if (usable.length === 0) return;

        // Weekly routines are first-class. A block without `days` remains a
        // daily block for backwards compatibility; weekday/weekend and named
        // days let school, work, worship and leisure stop happening every day.
        const today = usable.filter(block => isScheduleBlockForWorldDay(world, block, time.days));
        const yesterday = usable.filter(block => isScheduleBlockForWorldDay(world, block, Math.max(1, time.days - 1)));
        const sorted = [...today].sort((a, b) => a.time.localeCompare(b.time));
        let activeBlock = null;

        for (const block of sorted) {
            if (block.time <= currentTimeStr) {
                activeBlock = block;
            } else {
                break;
            }
        }

        if (!activeBlock) {
            const prior = [...yesterday].sort((a, b) => a.time.localeCompare(b.time));
            activeBlock = prior[prior.length - 1] || sorted[sorted.length - 1] || null;
        }

        if (activeBlock) {
            if (!sess.entityStates[ent.id]) sess.entityStates[ent.id] = { location: ent.startLocation || world.startLocationId };
            const entState = sess.entityStates[ent.id];

            // ARBITRATION: the narrative outranks the timetable. If the DM moved
            // this NPC recently, the schedule may not teleport them away.
            if (isNpcPinned(sess, entState)) return;

            const loc = getLocationRef(world, activeBlock.locationId);
            if (loc) activeCount++;
            if (loc && entState.location !== loc.id) {
                const prevLoc = entState.location;
                entState.location = loc.id;
                entState.currentActivity = activeBlock.activity || "";
                moveCount++;
                // If this move crosses the player's scene, the DM must narrate it —
                // characters walk in and out, they don't blink in and out.
                if (loc.id === sess.playerLocation) {
                    queueEngineEvent(sess, `${ent.name} has just arrived here${activeBlock.activity ? ` (${activeBlock.activity})` : ''} — narrate their entrance.`);
                } else if (prevLoc === sess.playerLocation) {
                    queueEngineEvent(sess, `${ent.name} is leaving${activeBlock.activity ? ` to ${activeBlock.activity}` : ''} — narrate their departure.`);
                }
            } else if (loc) {
                entState.currentActivity = activeBlock.activity || "";
            }
        }
    });
    Object.assign(sess.livingWorldActivity, {
        turn: Math.max(sess.livingWorldActivity.turn || 0, Math.max(1, parseInt(sess.turnCount) || 1)),
        scheduleMoves: moveCount,
        activeSchedules: activeCount
    });
    return { moves: moveCount, active: activeCount };
}

function validateWorldReferences(world) {
    const report = { broken: [], suggestions: {} };
    if (!world) return report;

    const locIds = world.locations.map(l => l.id ? l.id.toLowerCase() : '').filter(Boolean);
    const locNames = world.locations.map(l => l.name ? l.name.toLowerCase() : "").filter(Boolean);

    const check = (ref, source) => {
        if (!ref) return;
        const clean = ref.toLowerCase().trim();
        if (!locIds.includes(clean) && !locNames.includes(clean)) {
            report.broken.push({ ref, source });
            const best = world.locations.find(l => l.name && (l.name.toLowerCase().includes(clean) || clean.includes(l.name.toLowerCase())));
            if (best) report.suggestions[ref] = best.id;
        }
    };

    world.entities.forEach(ent => {
        check(ent.startLocation, `NPC ${ent.name} Start`);
        check(ent.homeLocation, `NPC ${ent.name} Home`);
        (ent.schedule || []).forEach(s => check(s.locationId, `NPC ${ent.name} Schedule @ ${s.time}`));
    });

    world.locations.forEach(loc => {
        (loc.exits || []).forEach(ex => {
            const target = getExitTargetName(ex);
            if (target) {
                check(target, `Location ${loc.name} Exit`);
            }
        });
    });

    return report;
}

/**
 * ✨ AI Schedule Generator: builds a daily or weekly routine for an NPC from their
 * personality and the world's geography. Optional — manual editing still works.
 * Returns true on success.
 */
async function generateNpcSchedule(npc, world) {
    if (!hasApiCredentials()) { showToast('API Key missing (Settings).', 'error'); return false; }
    if (!world.locations || world.locations.length === 0) { showToast('Add locations first.', 'error'); return false; }

    const locManifest = world.locations
        .map(l => `- id: "${l.id}" | ${l.name}${l.description ? ` — ${l.description.slice(0, 80)}` : ''}`)
        .join('\n');
    const homeLoc = world.locations.find(l => l.id === npc.homeLocation || l.name === npc.homeLocation);

    const prompt = `WORLD: ${world.name} — ${world.description || ''}

NPC: ${npc.name}
Description: ${npc.description || 'Unknown'}
${npc.persona ? `Personality: ${npc.persona}` : ''}
${homeLoc ? `Home: ${homeLoc.name}` : 'No fixed home.'}

AVAILABLE LOCATIONS (you MUST use only these ids):
${locManifest}

Design this NPC's believable weekly routine: 5-10 time blocks covering ordinary weekdays plus any meaningfully different weekend behavior. Use days:["weekday"], days:["weekend"], or named weekdays where needed; omit days only for something that happens every day. Include waking/home, work or school, and evening behavior. Activities should be specific and in-world, not generic.

Return ONLY this JSON, nothing else:
{"schedule": [{"time": "07:00", "locationId": "<id from list>", "activity": "<short specific activity>", "days": ["weekday"]}]}`;

    const response = await fetch(apiBase() + '/chat/completions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...authHeaders() },
        body: JSON.stringify({
            model: world.model || state.globalSettings.defaultModel,
            max_tokens: 900,
            messages: [
                { role: 'system', content: 'You are a world-simulation designer. You output only valid JSON.' },
                { role: 'user', content: prompt }
            ]
        })
    });
    if (!response.ok) throw new Error((await response.json().catch(() => ({}))).error?.message || response.statusText);
    const raw = (await response.json()).choices?.[0]?.message?.content || '';
    const parsed = extractJSON(raw);
    const blocks = Array.isArray(parsed) ? parsed : parsed.schedule;
    if (!Array.isArray(blocks) || blocks.length === 0) throw new Error('Model returned no schedule blocks');

    // Validate: real times, real locations (fuzzy-heal bad ids), chronological order
    const cleaned = blocks
        .map(b => {
            const time = /^([01]\d|2[0-3]):[0-5]\d$/.test(b.time || '') ? b.time : null;
            const loc = world.locations.find(l => l.id === b.locationId) || findFuzzyLocation(b.locationId || '', world.locations);
            if (!time || !loc) return null;
            const days = (Array.isArray(b.days) ? b.days : (b.day ? [b.day] : []))
                .map(day => String(day || '').trim()).filter(Boolean).slice(0, 7);
            return { time, locationId: loc.id, activity: (b.activity || '').slice(0, 120), ...(days.length ? { days } : {}) };
        })
        .filter(Boolean)
        .sort((a, b) => a.time.localeCompare(b.time));

    if (cleaned.length === 0) throw new Error('No valid blocks after validation');
    npc.schedule = cleaned;
    return true;
}

function renderWorldScheduler() {
    const world = state.editingWorld;
    const container = document.getElementById('scheduler-npc-list');
    if (!world || !container) return;

    container.innerHTML = '';
    const npcs = world.entities.filter(e => e.type === 'npc');

    if (npcs.length === 0) {
        container.innerHTML = '<div style="text-align:center; padding:40px; color:var(--text-3);">No NPCs found in this world. Add NPCs first to set their schedules.</div>';
        return;
    }

    npcs.forEach(npc => {
        const div = document.createElement('div');
        div.className = 'studio-card';
        div.style.padding = '20px';
        div.style.background = 'var(--surface2)';

        div.innerHTML = `
            <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:15px;">
                <h3 style="margin:0; color:var(--accent);">${escapeHTML(npc.name)}</h3>
                <div style="display:flex; gap:8px;">
                    <button class="btn btn-ghost gen-sched-btn" style="font-size:0.75rem; color:var(--accent);">✨ Auto-Generate</button>
                    <button class="btn btn-ghost add-block-btn" style="font-size:0.75rem;">+ Add Time Block</button>
                </div>
            </div>
            <div class="blocks-container" style="display:flex; flex-direction:column; gap:10px;">
                ${(npc.schedule || []).map((block, idx) => {
                    const selectedDays = (Array.isArray(block.days) ? block.days : (block.day ? [block.day] : []))
                        .map(day => String(day || '').trim().toLowerCase()).filter(Boolean);
                    const everyDay = !selectedDays.length || selectedDays.some(day => /^(daily|everyday)$/.test(day));
                    const dayChoices = [
                        ['weekday', 'Weekdays'], ['weekend', 'Weekend'], ['monday', 'Mon'], ['tuesday', 'Tue'],
                        ['wednesday', 'Wed'], ['thursday', 'Thu'], ['friday', 'Fri'], ['saturday', 'Sat'], ['sunday', 'Sun']
                    ];
                    return `
                    <div class="world-schedule-block">
                        <div style="flex:1">
                            <label style="font-size:10px; opacity:0.6; display:block; margin-bottom:4px;">Start Time</label>
                            <input type="time" class="form-input block-time" value="${escapeHTML(block.time)}" data-idx="${idx}">
                        </div>
                        <div class="world-schedule-days">
                            <label style="font-size:10px; opacity:0.6; display:block; margin-bottom:4px;">Days</label>
                            <div class="smart-chip-picker" role="group" aria-label="Schedule days">
                                <label><input type="checkbox" class="block-day" data-idx="${idx}" data-day="daily" ${everyDay ? 'checked' : ''}><span>Every day</span></label>
                                ${dayChoices.map(([value, label]) => `<label><input type="checkbox" class="block-day" data-idx="${idx}" data-day="${value}" ${!everyDay && selectedDays.includes(value) ? 'checked' : ''}><span>${label}</span></label>`).join('')}
                            </div>
                        </div>
                        <div style="flex:2">
                            <label style="font-size:10px; opacity:0.6; display:block; margin-bottom:4px;">Location</label>
                            <select class="form-select block-loc" data-idx="${idx}">
                                <option value="">Select Location...</option>
                                ${world.locations.map(l => `<option value="${escapeHTML(l.id)}" ${l.id === block.locationId ? 'selected' : ''}>${escapeHTML(l.name)}</option>`).join('')}
                            </select>
                        </div>
                        <div style="flex:3">
                            <label style="font-size:10px; opacity:0.6; display:block; margin-bottom:4px;">Activity / Intent</label>
                            <input type="text" class="form-input block-act" placeholder="e.g. Sleeping, Patrolling..." value="${escapeHTML(block.activity || '')}" data-idx="${idx}">
                        </div>
                        <button class="tool-btn del-block-btn" data-idx="${idx}" style="align-self:flex-end; margin-bottom:5px;">✕</button>
                    </div>
                `; }).join('')}
            </div>
        `;

        div.querySelector('.add-block-btn').onclick = () => {
            if (!npc.schedule) npc.schedule = [];
            npc.schedule.push({ time: '08:00', locationId: '', activity: '' });
            renderWorldScheduler();
        };

        div.querySelector('.gen-sched-btn').onclick = async (e) => {
            const btn = e.target;
            if (npc.schedule && npc.schedule.length > 0 && !confirm(`${npc.name} already has a schedule. Replace it?`)) return;
            btn.disabled = true;
            btn.textContent = '⏳ Designing...';
            try {
                await generateNpcSchedule(npc, world);
                showToast(`Schedule generated for ${npc.name}`, 'success');
                renderWorldScheduler();
            } catch (err) {
                showToast(`Generation failed: ${err.message}`, 'error');
                btn.disabled = false;
                btn.textContent = '✨ Auto-Generate';
            }
        };

        div.querySelectorAll('.block-time').forEach(inp => {
            inp.onchange = (e) => { npc.schedule[e.target.dataset.idx].time = e.target.value; };
        });
        div.querySelectorAll('.block-loc').forEach(sel => {
            sel.onchange = (e) => { npc.schedule[e.target.dataset.idx].locationId = e.target.value; };
        });
        div.querySelectorAll('.block-day').forEach(input => {
            input.onchange = event => {
                const index = Number(event.target.dataset.idx);
                const group = [...div.querySelectorAll(`.block-day[data-idx="${index}"]`)];
                const daily = group.find(control => control.dataset.day === 'daily');
                if (event.target.dataset.day === 'daily' && event.target.checked) {
                    group.forEach(control => { if (control !== daily) control.checked = false; });
                    delete npc.schedule[index].days;
                    return;
                }
                if (event.target.dataset.day !== 'daily' && event.target.checked && daily) daily.checked = false;
                const days = group.filter(control => control.dataset.day !== 'daily' && control.checked)
                    .map(control => control.dataset.day);
                if (days.length) npc.schedule[index].days = days;
                else {
                    if (daily) daily.checked = true;
                    delete npc.schedule[index].days;
                }
            };
        });
        div.querySelectorAll('.block-act').forEach(inp => {
            inp.oninput = (e) => { npc.schedule[e.target.dataset.idx].activity = e.target.value; };
        });
        div.querySelectorAll('.del-block-btn').forEach(btn => {
            btn.onclick = () => {
                npc.schedule.splice(btn.dataset.idx, 1);
                renderWorldScheduler();
            };
        });

        container.appendChild(div);
    });
}

/**
 * 🔎 Deterministic world lint: structural problems findable without AI —
 * dead-end locations, unreachable rooms, hollow secrets, mute lorebook
 * entries, cardboard NPCs, colliding labels. Free and instant.
 */
function buildWorldLintReport(world) {
    const findings = [];
    const locs = world.locations || [];
    const push = (sev, area, msg) => findings.push({ sev, area, msg });

    // Duplicate location names (references resolve by name — collisions misroute)
    const nameCount = {};
    locs.forEach(l => { const n = (l.name || '').trim().toLowerCase(); if (n) nameCount[n] = (nameCount[n] || 0) + 1; });
    Object.entries(nameCount).filter(([, c]) => c > 1).forEach(([n, c]) =>
        push('warning', 'Locations', `Location name "${n}" is used ${c}× — exits and NPC references may resolve to the wrong one.`));

    const locByKey = {};
    locs.forEach(l => { if (l.id) locByKey[l.id.toLowerCase()] = l; if (l.name) locByKey[l.name.trim().toLowerCase()] = l; });

    // Per-location checks + exit graph
    const adj = {};
    locs.forEach(l => {
        adj[l.id] = [];
        const exits = Array.isArray(l.exits) ? l.exits : [];
        // A room attached to a parent is never a dead end: containment is a real
        // route back out, so only genuinely unattached places are trapped.
        const attachedTo = String(l.parentLocationId || l.region || '').trim().toLowerCase();
        const hasContainer = !!attachedTo && !!locByKey[attachedTo] && locByKey[attachedTo].id !== l.id;
        if (exits.length === 0 && !hasContainer) push('warning', 'Locations', `"${l.name || l.id}" has no exits — a dead end the player can never leave (or unreachable scenery).`);
        if (!l.description || !l.description.trim()) push('warning', 'Locations', `"${l.name || l.id}" has an empty visible description.`);
        exits.forEach(ex => {
            const target = (getExitTargetName(ex) || '').trim().toLowerCase();
            const t = locByKey[target];
            if (t) adj[l.id].push(t.id);
        });
        // An exit the author drew as two-way but which only exists on one side.
        // The Studio creates the reciprocal exit when you edit it by hand, but a
        // room from the AI Builder, an import, or location_introduced never gets
        // one — and the connection silently works in one direction only.
        exits.forEach(ex => {
            if (ex && typeof ex === 'object' && ex.isOneWay) return;   // deliberate
            const target = (getExitTargetName(ex) || '').trim().toLowerCase();
            const t = locByKey[target];
            if (!t || t.id === l.id) return;
            const backReferences = (Array.isArray(t.exits) ? t.exits : []).some(back => {
                const backTarget = (getExitTargetName(back) || '').trim().toLowerCase();
                return backTarget === (l.id || '').toLowerCase()
                    || backTarget === (l.name || '').trim().toLowerCase();
            });
            const contains = String(l.parentLocationId || l.region || '').trim().toLowerCase();
            const isChildOfTarget = contains === (t.id || '').toLowerCase()
                || contains === (t.name || '').trim().toLowerCase();
            if (!backReferences && !isChildOfTarget) {
                push('warning', 'Locations',
                    `"${l.name || l.id}" leads to "${t.name || t.id}", but "${t.name || t.id}" has no way back — the connection works in one direction only. Add the return exit, or tick 1-Way if that is intended.`);
            }
        });

        (l.secrets || []).forEach(s => {
            if (!s.label) push('warning', 'Secrets', `A secret in "${l.name}" has no label — it can never be revealed.`);
            if (s.label && !s.hint) push('warning', 'Secrets', `Secret "${s.label}" (${l.name}) has no hint — the DM has nothing to foreshadow with.`);
            if (s.label && !s.truth) push('critical', 'Secrets', `Secret "${s.label}" (${l.name}) has no truth — investigating reveals nothing.`);
        });
    });

    // Reachability sweep from the start location. Containment counts as a route
    // in both directions here for the same reason it does in pathfinding — a
    // room inside a building is reachable from it — otherwise the audit reports
    // every authored sub-room as unreachable when the engine can walk there fine.
    locs.forEach(l => {
        const parentRef = String(l.parentLocationId || l.region || '').trim().toLowerCase();
        if (!parentRef) return;
        const parent = locByKey[parentRef];
        if (!parent || parent.id === l.id) return;
        adj[l.id] = adj[l.id] || [];
        adj[parent.id] = adj[parent.id] || [];
        if (!adj[l.id].includes(parent.id)) adj[l.id].push(parent.id);
        if (!adj[parent.id].includes(l.id)) adj[parent.id].push(l.id);
    });

    const startId = world.startLocationId || locs[0]?.id;
    (world.startingLives || []).forEach(life => {
        if (!life.name) push('warning', 'Starting Lives', 'A starting life has no player-facing name.');
        if (!locs.some(location => location.id === life.startLocationId)) {
            push('critical', 'Starting Lives', `"${life.name || life.id}" has no valid starting location.`);
        }
        if (life.factionId && !(world.factions || []).some(faction => faction.id === life.factionId)) {
            push('warning', 'Starting Lives', `"${life.name || life.id}" points to a missing faction.`);
        }
        Object.keys(life.statOverrides || {}).forEach(statId => {
            if (!(world.hudConfig?.stats || []).some(stat => stat.id === statId)) {
                push('warning', 'Starting Lives', `"${life.name || life.id}" overrides unknown stat "${statId}".`);
            }
        });
    });
    if (startId && locs.length > 1) {
        const seen = new Set([startId]);
        const q = [startId];
        while (q.length) {
            const cur = q.shift();
            (adj[cur] || []).forEach(n => { if (!seen.has(n)) { seen.add(n); q.push(n); } });
        }
        locs.filter(l => !seen.has(l.id)).forEach(l =>
            push('warning', 'Map', `"${l.name || l.id}" is unreachable — no chain of exits leads there from the start location.`));
    }

    // NPCs
    (world.entities || []).forEach(e => {
        if (e.type !== 'npc') return;
        if (!e.description && !e.persona) push('suggestion', 'NPCs', `"${e.name}" has no description or persona — they will play as a cardboard extra.`);
        if (e.isMajor && !e.persona) push('warning', 'NPCs', `"${e.name}" is marked MAJOR but has no persona — the flag does nothing without one.`);
        (e.secrets || []).forEach(s => {
            if (s.label && !s.hint) push('warning', 'Secrets', `Secret "${s.label}" (${e.name}) has no hint.`);
            if (s.label && !s.truth) push('critical', 'Secrets', `Secret "${s.label}" (${e.name}) has no truth.`);
        });
    });

    // Lorebook
    (world.lorebook || []).forEach((l, i) => {
        if (!l.keyword || !l.keyword.trim()) push('critical', 'Lorebook', `Lore entry #${i + 1} has no keyword — it can never trigger.`);
        else if (!l.text || !l.text.trim()) push('warning', 'Lorebook', `Lore entry "${l.keyword}" has no text.`);
    });

    // Colliding secret labels across the whole world
    const labels = {};
    [...locs, ...(world.entities || [])].forEach(o => (o.secrets || []).forEach(s => { if (s.label) labels[s.label] = (labels[s.label] || 0) + 1; }));
    Object.entries(labels).filter(([, c]) => c > 1).forEach(([lab, c]) =>
        push('warning', 'Secrets', `Secret label "${lab}" is used ${c}× — reveals will collide.`));

    return findings;
}

// --- World Calibration -----------------------------------------------------
// A hand-authored world leaves most of the engine asleep: no stats, no NPC
// homes, no schedules, no relationships, no markets, no travel times, rooms that
// cannot be re-entered and places nothing links to. Calibration wakes it up.
//
// Tier 0 is everything the engine can repair on its own, with no API call and
// no judgement: facts that are simply missing or self-contradictory. Findings
// are proposed as data and applied only on request, so nothing changes under
// the author without their say-so.

function estimateWorldPromptTokens(world, preset) {
    const parts = [world.dmPrompt, world.authorNote, world.intro, world.description];
    (world.locations || []).forEach(location => {
        parts.push(location.description, location.hiddenDetails);
        (location.secrets || []).forEach(secret => parts.push(secret.label, secret.hint, secret.truth));
    });
    (world.entities || []).forEach(entity => parts.push(entity.description, entity.persona));
    (world.lorebook || []).forEach(entry => parts.push(entry.keyword, entry.text));
    // Authored society reaches the prompt too, so it has to be counted or the
    // recommended context size comes out short on a world with a lot of it.
    (world.locations || []).forEach(location => {
        (location.shop || []).forEach(stock => parts.push(stock.item));
        (location.conditions || []).forEach(condition => parts.push(String(condition?.label ?? condition ?? '')));
    });
    (world.factions || []).forEach(faction => parts.push(faction.name, faction.description, faction.goal));
    (world.relationships || []).forEach(relation => parts.push(relation.label, relation.reason));
    (preset?.data?.prompts || []).forEach(prompt => {
        if (prompt && prompt.enabled !== false) parts.push(prompt.content);
    });
    const characters = parts.filter(Boolean).join(' ').length;
    return Math.ceil(characters / 3.2);
}

function worldDirectoryHealth(world) {
    const locations = Array.isArray(world?.locations) ? world.locations : [];
    const regions = Array.isArray(world?.regions) ? world.regions : [];
    const people = (world?.entities || []).filter(entity => entity?.type === 'npc');
    const items = (world?.entities || []).filter(entity => entity?.type === 'item');
    const groups = Array.isArray(world?.groups) ? world.groups : [];
    const issues = [];
    const count = (list, test) => list.filter(test).length;
    const thinRegions = count(regions, region => !String(region.description || '').trim() || !(region.tags || []).length);
    const thinLocations = count(locations, location => !String(location.description || '').trim() || !(location.tags || []).length);
    const unstructuredLocations = count(locations, location => !location.regionId || !location.mapType);
    const thinPeople = count(people, person => !String(person.description || '').trim() || !String(person.persona || '').trim());
    const unplacedPeople = count(people, person => !person.startLocation || !person.homeLocation);
    const unsimulatedPeople = count(people, person => !(person.schedule || []).length || !String(person.goal || '').trim());
    const ungroupedPeople = count(people, person => !(person.groupIds || []).length && !person.householdId);
    const thinItems = count(items, item => !String(item.description || '').trim() || !item.startLocation);
    const thinGroups = count(groups, group => !String(group.description || '').trim() || !(group.tags || []).length);
    const emptyRegions = count(regions, region => !locations.some(location => location.regionId === region.id));
    const buildingLikeRegions = count(regions, region =>
        /\b(?:house|shop|store|inn|tavern|keep|castle|tower|office|school|hospital|station|temple|church|building)\b/i.test(region.name || '')
        && locations.filter(location => location.regionId === region.id).some(location => ['room', 'area'].includes(location.mapType)));
    const invalidContainment = count(locations, location => {
        if (!location.parentLocationId) return false;
        const parent = getLocationRef(world, location.parentLocationId);
        return !parent || parent.id === location.id || (parent.regionId && location.regionId && parent.regionId !== location.regionId);
    });
    const incompleteTravel = locations.reduce((total, location) => total + (location.exits || []).filter(exit => {
        const target = getLocationRef(world, exit?.targetLocationId || getExitTargetName(exit));
        return !target || !String(exit?.mode || '').trim() || !(Number(exit?.travelTime) > 0);
    }).length, 0);
    const isolatedRegions = regions.length > 1 ? count(regions, region => {
        const hasLocations = locations.some(location => location.regionId === region.id);
        return hasLocations && worldRegionTravelLinks(world, region.id).length === 0;
    }) : 0;
    if (thinRegions) issues.push({ area: 'Regions', count: thinRegions, detail: 'missing a regional description or search tags', pass: 'Structure' });
    if (thinLocations) issues.push({ area: 'Locations', count: thinLocations, detail: 'missing a player-facing description or search tags', pass: 'Structure' });
    if (unstructuredLocations) issues.push({ area: 'Map', count: unstructuredLocations, detail: 'still rely on inferred region or map roles', pass: 'Structure' });
    if (thinPeople) issues.push({ area: 'People', count: thinPeople, detail: 'missing a public impression or persona', pass: 'People' });
    if (unplacedPeople) issues.push({ area: 'People', count: unplacedPeople, detail: 'missing a starting place or home', pass: 'People' });
    if (unsimulatedPeople) issues.push({ area: 'Living world', count: unsimulatedPeople, detail: 'missing a schedule or off-screen agenda', pass: 'People' });
    if (ungroupedPeople) issues.push({ area: 'Households', count: ungroupedPeople, detail: 'not linked to a household, family or organization', pass: 'People' });
    if (thinItems) issues.push({ area: 'Items', count: thinItems, detail: 'missing a description or starting location', pass: 'Items' });
    if (thinGroups) issues.push({ area: 'Groups', count: thinGroups, detail: 'missing a description or classification tags', pass: 'People' });
    if (emptyRegions) issues.push({ area: 'Regions', count: emptyRegions, detail: 'contain no playable locations', pass: 'Structure' });
    if (buildingLikeRegions) issues.push({ area: 'Hierarchy', count: buildingLikeRegions, detail: 'look like buildings modeled as regions; keep the geographic region and make rooms child locations instead', pass: 'Structure' });
    if (invalidContainment) issues.push({ area: 'Hierarchy', count: invalidContainment, detail: 'have a missing, self-referential or cross-region parent location', pass: 'Structure' });
    if (isolatedRegions) issues.push({ area: 'Travel', count: isolatedRegions, detail: 'cannot be reached from another region through a canonical location link', pass: 'Structure' });
    if (incompleteTravel) issues.push({ area: 'Travel', count: incompleteTravel, detail: 'connections lack a valid target, mode or positive travel time', pass: 'Structure' });
    const possible = Math.max(1, locations.length * 3 + regions.length * 3 + people.length * 4 + items.length * 2 + groups.length * 2);
    const missing = thinRegions + thinLocations + unstructuredLocations + thinPeople + unplacedPeople + unsimulatedPeople + ungroupedPeople + thinItems + thinGroups + emptyRegions + buildingLikeRegions + invalidContainment + isolatedRegions + incompleteTravel;
    return { score: Math.max(0, Math.round((1 - missing / possible) * 100)), issues, counts: { regions: regions.length, locations: locations.length, people: people.length, items: items.length, groups: groups.length } };
}

function calibrateStructuralFindings(world, preset) {
    const findings = [];
    const locations = Array.isArray(world.locations) ? world.locations : [];
    const add = finding => findings.push({ tier: 'structure', ...finding });
    const byKey = new Map();
    locations.forEach(location => {
        if (location.id) byKey.set(String(location.id).toLowerCase(), location);
        if (location.name) byKey.set(String(location.name).trim().toLowerCase(), location);
    });

    // 1. A start location, so play does not begin wherever the list happens to start.
    if (!world.startLocationId || !locations.some(l => l.id === world.startLocationId)) {
        const first = locations[0];
        if (first) {
            add({
                id: 'start_location', type: 'set_start_location', severity: 'warning',
                title: 'No starting location is set',
                detail: `Play would begin at "${first.name || first.id}" only because it is first in the list. Setting it explicitly makes that a decision rather than an accident.`,
                patch: { startLocationId: first.id }
            });
        }
    }

    // 2. Context large enough for the preset plus the world's own text.
    const needed = estimateWorldPromptTokens(world, preset) + (parseInt(world.maxTokens) || 2048) + 2048;
    const recommended = Math.max(8192, Math.ceil(needed / 1024) * 1024);
    const current = parseInt(world.contextSize) || 0;
    if (current < recommended) {
        add({
            id: 'context_size', type: 'raise_context_size', severity: current ? 'warning' : 'critical',
            title: current ? `Context size ${current} is too small` : 'No context size set',
            detail: `This world's text plus its preset needs about ${recommended} tokens. Below that the engine drops history mid-scene and the DM forgets what just happened.`,
            patch: { contextSize: recommended }
        });
    }

    // 3. Exits that only exist on one side. The Studio writes the return exit
    //    when you edit one by hand, but nothing else does — so imported, built
    //    or AI-introduced rooms become one-way traps.
    locations.forEach(location => {
        (Array.isArray(location.exits) ? location.exits : []).forEach(exit => {
            if (exit && typeof exit === 'object' && exit.isOneWay) return;
            const targetName = getExitTargetName(exit);
            const target = byKey.get(String(targetName || '').trim().toLowerCase());
            if (!target || target.id === location.id) return;
            const hasReturn = (Array.isArray(target.exits) ? target.exits : []).some(back => {
                const backTarget = String(getExitTargetName(back) || '').trim().toLowerCase();
                return backTarget === String(location.id || '').toLowerCase()
                    || backTarget === String(location.name || '').trim().toLowerCase();
            });
            const containedByTarget = [location.parentLocationId, location.region]
                .some(ref => String(ref || '').trim().toLowerCase() === String(target.id || '').toLowerCase()
                    || String(ref || '').trim().toLowerCase() === String(target.name || '').trim().toLowerCase());
            if (hasReturn || containedByTarget) return;
            const direction = getExitDirection(exit);
            const back = direction ? `${getOppositeDirection(direction)} to ${location.name}` : `to ${location.name}`;
            add({
                id: `reciprocal_${target.id}_${location.id}`, type: 'add_reciprocal_exit', severity: 'critical',
                title: `"${target.name || target.id}" has no way back to "${location.name || location.id}"`,
                detail: `You can walk in and never walk out. Adds the return exit "${back}".`,
                patch: { locationId: target.id, exitText: back,
                         travelTime: (exit && typeof exit === 'object' && exit.travelTime) || 0 }
            });
        });
    });

    // 4. Places nothing leads to. Connecting them needs judgement, so this is
    //    reported for the structure pass to resolve rather than guessed at.
    const startId = world.startLocationId || locations[0]?.id;
    if (startId && locations.length > 1) {
        const adjacency = new Map(locations.map(l => [l.id, []]));
        locations.forEach(location => {
            (location.exits || []).forEach(exit => {
                const target = byKey.get(String(getExitTargetName(exit) || '').trim().toLowerCase());
                if (target) adjacency.get(location.id)?.push(target.id);
            });
            const parentRef = String(location.parentLocationId || location.region || '').trim().toLowerCase();
            const parent = parentRef ? byKey.get(parentRef) : null;
            if (parent && parent.id !== location.id) {
                adjacency.get(location.id)?.push(parent.id);
                adjacency.get(parent.id)?.push(location.id);
            }
        });
        const seen = new Set([startId]);
        const queue = [startId];
        while (queue.length) {
            (adjacency.get(queue.shift()) || []).forEach(next => {
                if (!seen.has(next)) { seen.add(next); queue.push(next); }
            });
        }
        locations.filter(location => !seen.has(location.id)).forEach(location => {
            add({
                id: `orphan_${location.id}`, type: 'report_orphan', severity: 'critical',
                title: `"${location.name || location.id}" cannot be reached`,
                detail: 'No chain of exits or containment leads here from the start. The structure pass will propose how it connects.',
                patch: { locationId: location.id }
            });
        });
    }

    // 5. Names that collide, because references resolve by name.
    const nameCounts = {};
    locations.forEach(location => {
        const key = String(location.name || '').trim().toLowerCase();
        if (key) nameCounts[key] = (nameCounts[key] || 0) + 1;
    });
    Object.entries(nameCounts).filter(([, count]) => count > 1).forEach(([name, count]) => {
        add({
            id: `dupname_${name}`, type: 'report_duplicate_name', severity: 'warning',
            title: `${count} locations are called "${name}"`,
            detail: 'Exits and NPC placements resolve by name, so these will send people to the wrong one. Rename all but one.',
            patch: { name }
        });
    });

    // 6. Authored society that will not do what the author thinks it does.
    // None of these are repairable automatically — each is a judgement the
    // author has to make — so they report rather than carry a patch.
    const factions = Array.isArray(world.factions) ? world.factions : [];
    const npcs = (world.entities || []).filter(entity => entity?.type === 'npc');

    factions.forEach(faction => {
        const members = npcs.filter(entity => entity.factionId === faction.id).length;
        const holdings = (faction.territory || []).length;
        if (!members && !holdings) {
            add({
                id: `faction_inert_${faction.id}`, type: 'report_faction_inert', severity: 'suggestion',
                title: `"${faction.name}" has no members and holds no ground`,
                detail: 'It can still be named in narration, but nothing anchors it to the world: no one acts for it and it loses nothing when a rival takes a place. Give it territory, or someone who serves it.'
            });
        }
    });

    if (factions.length > 1) {
        const stated = factions.filter(faction => (faction.relations || []).length).length;
        if (!stated) {
            add({
                id: 'factions_no_relations', type: 'report_faction_relations', severity: 'suggestion',
                title: `${factions.length} factions, none of whom have a stated view of each other`,
                detail: 'They will all start neutral and only drift apart by chance. Setting standing on the Factions tab is what makes them allies or enemies from turn one.'
            });
        }
    }

    // A shop with nothing priced is a shop the player cannot buy from.
    locations.forEach(location => {
        const freeItems = (location.shop || []).filter(stock => !Number(stock.price));
        if (freeItems.length) {
            add({
                id: `shop_free_${location.id}`, type: 'report_shop_price', severity: 'suggestion',
                title: `${location.name}: ${freeItems.length} item${freeItems.length === 1 ? ' is' : 's are'} priced at zero`,
                detail: `${freeItems.map(stock => stock.item).slice(0, 3).join(', ')} — the player can take these for nothing. Set a price, or that is what will happen.`
            });
        }
        const outOfStock = (location.shop || []).filter(stock =>
            !Number(stock.quantity) && !Number(stock.regenPerTurn));
        if (outOfStock.length) {
            add({
                id: `shop_empty_${location.id}`, type: 'report_shop_stock', severity: 'suggestion',
                title: `${location.name}: ${outOfStock.length} item${outOfStock.length === 1 ? '' : 's'} can never be bought`,
                detail: `${outOfStock.map(stock => stock.item).slice(0, 3).join(', ')} — no stock and no restock, so every purchase fails.`
            });
        }
    });

    // A vendor nobody can reach, and a shop nobody tends.
    const shopLocations = locations.filter(location => (location.shop || []).length);
    shopLocations.forEach(location => {
        if (!npcs.some(entity => entity.vendorFor === location.id)) {
            add({
                id: `shop_unattended_${location.id}`, type: 'report_shop_vendor', severity: 'suggestion',
                title: `${location.name} sells things but nobody trades there`,
                detail: 'Buying still works, but the DM has no one to sell it to the player. Set an NPC as the vendor on their card.'
            });
        }
    });

    // Older worlds load safely, but safe defaults are not the same thing as a
    // fully authored directory. Report those semantic gaps in useful batches
    // instead of creating hundreds of noisy one-record warnings.
    const directoryHealth = worldDirectoryHealth(world);
    const directoryNouns = { Regions: 'region', Locations: 'location', Map: 'location', Travel: 'connection', People: 'person', 'Living world': 'person', Households: 'person', Items: 'item', Groups: 'group' };
    directoryHealth.issues.forEach((issue, index) => add({
        id: `directory_gap_${index}_${issue.area.toLowerCase().replace(/\W+/g, '_')}`,
        type: 'report_directory_gap',
        severity: issue.count > 20 ? 'warning' : 'suggestion',
        title: `${issue.count} ${directoryNouns[issue.area] || 'directory record'}${issue.count === 1 ? '' : 's'} need enrichment`,
        detail: `${issue.detail}. Run the ${issue.pass} pass to propose missing details, then review them before applying.`
    }));

    return findings;
}

// Applying a finding is separated from producing it so the whole set can be
// reviewed, tested, and applied selectively.
function applyCalibrationFinding(world, finding) {
    if (!world || !finding) return false;
    const locations = Array.isArray(world.locations) ? world.locations : [];
    switch (finding.type) {
        case 'set_start_location':
            world.startLocationId = finding.patch.startLocationId;
            return true;
        case 'raise_context_size':
            world.contextSize = finding.patch.contextSize;
            return true;
        case 'add_reciprocal_exit': {
            const target = locations.find(l => l.id === finding.patch.locationId);
            if (!target) return false;
            target.exits = Array.isArray(target.exits) ? target.exits : [];
            const already = target.exits.some(exit =>
                String(getExitTargetName(exit) || '').trim().toLowerCase()
                === String(getExitTargetName(finding.patch.exitText) || '').trim().toLowerCase());
            if (already) return false;
            target.exits.push({ text: finding.patch.exitText, travelTime: finding.patch.travelTime || 0, isOneWay: false });
            return true;
        }
        case 'set_map_type': {
            const location = locations.find(l => l.id === finding.patch.locationId);
            if (!location || location.mapType) return false;   // never overwrite an authored role
            location.mapType = finding.patch.mapType;
            return true;
        }
        case 'set_containment': {
            const location = locations.find(l => l.id === finding.patch.locationId);
            if (!location || location.parentLocationId) return false;
            if (location.id === finding.patch.parentLocationId) return false;
            // Refuse to build a containment loop: a place cannot end up inside
            // something that is already inside it.
            const seen = new Set([location.id]);
            let cursor = locations.find(l => l.id === finding.patch.parentLocationId);
            while (cursor) {
                if (seen.has(cursor.id)) return false;
                seen.add(cursor.id);
                const ref = String(cursor.parentLocationId || cursor.region || '').trim().toLowerCase();
                cursor = ref
                    ? locations.find(l => String(l.id).toLowerCase() === ref
                        || String(l.name || '').trim().toLowerCase() === ref)
                    : null;
            }
            location.parentLocationId = finding.patch.parentLocationId;
            return true;
        }
        case 'set_floor': {
            const location = locations.find(l => l.id === finding.patch.locationId);
            if (!location || location.mapFloor) return false;
            location.mapFloor = finding.patch.mapFloor;
            return true;
        }
        case 'connect_location': {
            const location = locations.find(l => l.id === finding.patch.locationId);
            const target = locations.find(l => l.id === finding.patch.targetId);
            if (!location || !target) return false;
            location.exits = Array.isArray(location.exits) ? location.exits : [];
            target.exits = Array.isArray(target.exits) ? target.exits : [];
            const links = (from, toName) => from.exits.some(exit =>
                String(getExitTargetName(exit) || '').trim().toLowerCase() === String(toName).trim().toLowerCase());
            let changed = false;
            if (!links(location, target.name)) {
                location.exits.push({ text: `to ${target.name}`, travelTime: 0, isOneWay: false });
                changed = true;
            }
            // Connect both ways, or we would simply create a new one-way trap.
            if (!links(target, location.name)) {
                target.exits.push({ text: `to ${location.name}`, travelTime: 0, isOneWay: false });
                changed = true;
            }
            return changed;
        }
        case 'set_travel_time': {
            const location = locations.find(l => l.id === finding.patch.locationId);
            const exits = location && Array.isArray(location.exits) ? location.exits : null;
            const exit = exits ? exits[finding.patch.exitIndex] : null;
            if (!exit) return false;
            if (typeof exit === 'object' && exit.travelTime) return false;   // already stated
            exits[finding.patch.exitIndex] = typeof exit === 'string'
                ? { text: exit, travelTime: finding.patch.minutes, isOneWay: false }
                : { ...exit, travelTime: finding.patch.minutes };
            return true;
        }
        case 'set_entity_location':
        case 'set_entity_home': {
            const entity = (world.entities || []).find(e => e.id === finding.patch.entityId);
            if (!entity) return false;
            const field = finding.type === 'set_entity_home' ? 'homeLocation' : 'startLocation';
            if (entity[field]) return false;              // the author already placed them
            entity[field] = finding.patch.locationId;
            return true;
        }
        case 'set_persona': {
            const entity = (world.entities || []).find(e => e.id === finding.patch.entityId);
            if (!entity || String(entity.persona || '').trim()) return false;
            entity.persona = finding.patch.persona;
            return true;
        }
        case 'set_entity_tags': {
            const entity = (world.entities || []).find(e => e.id === finding.patch.entityId);
            if (!entity || (entity.tags || []).length) return false;
            entity.tags = [...new Set((finding.patch.tags || []).map(tag => String(tag).trim()).filter(Boolean))].slice(0, 30);
            return entity.tags.length > 0;
        }
        case 'set_entity_depth': {
            const entity = (world.entities || []).find(e => e.id === finding.patch.entityId);
            if (!entity || !WORLD_DIRECTORY_DEPTHS.includes(finding.patch.simulationDepth)) return false;
            const legacyDefault = !entity.simulationDepth
                || (entity.simulationDepth === 'background' && !entity.isMajor);
            if (!legacyDefault) return false;
            entity.simulationDepth = finding.patch.simulationDepth;
            entity.isMajor = entity.simulationDepth === 'core';
            return true;
        }
        case 'set_entity_group': {
            const entity = (world.entities || []).find(e => e.id === finding.patch.entityId);
            if (!entity || !finding.patch.name) return false;
            if (!Array.isArray(world.groups)) world.groups = [];
            const name = String(finding.patch.name).trim().slice(0, 120);
            let group = world.groups.find(item => String(item.name || '').trim().toLowerCase() === name.toLowerCase());
            if (!group) {
                const base = `grp_${worldDirectorySlug(name, 'group')}`;
                let id = base;
                let suffix = 2;
                while (world.groups.some(item => item.id === id)) id = `${base}_${suffix++}`;
                group = {
                    id, name,
                    type: ['household', 'family', 'organization', 'crew', 'other'].includes(finding.patch.groupType)
                        ? finding.patch.groupType : 'other',
                    description: String(finding.patch.description || '').trim().slice(0, 1200),
                    homeLocationId: getLocationRef(world, finding.patch.homeLocationId)?.id || '',
                    tags: [...new Set((finding.patch.tags || []).map(String).map(tag => tag.trim()).filter(Boolean))].slice(0, 30)
                };
                world.groups.push(group);
            }
            entity.groupIds = Array.isArray(entity.groupIds) ? entity.groupIds : [];
            if (entity.groupIds.includes(group.id)) return false;
            entity.groupIds.push(group.id);
            if (group.type === 'household' && !entity.householdId) entity.householdId = group.id;
            return true;
        }
        case 'set_location_tags': {
            const location = locations.find(l => l.id === finding.patch.locationId);
            if (!location || (location.tags || []).length) return false;
            location.tags = [...new Set((finding.patch.tags || []).map(String).map(tag => tag.trim()).filter(Boolean))].slice(0, 30);
            return location.tags.length > 0;
        }
        case 'set_location_description': {
            const location = locations.find(l => l.id === finding.patch.locationId);
            if (!location || String(location.description || '').trim()) return false;
            location.description = String(finding.patch.description || '').trim().slice(0, 4000);
            return Boolean(location.description);
        }
        case 'set_location_region': {
            const location = locations.find(l => l.id === finding.patch.locationId);
            if (!location || location.regionId || !finding.patch.name) return false;
            if (!Array.isArray(world.regions)) world.regions = [];
            const name = String(finding.patch.name).trim().slice(0, 120);
            let region = world.regions.find(item => item.id === finding.patch.regionId
                || String(item.name || '').trim().toLowerCase() === name.toLowerCase());
            if (!region) {
                const base = `reg_${worldDirectorySlug(name, 'region')}`;
                let id = base;
                let suffix = 2;
                while (world.regions.some(item => item.id === id)) id = `${base}_${suffix++}`;
                region = { id, name, description: '', tags: [] };
                world.regions.push(region);
            }
            location.regionId = region.id;
            location.region = region.name;
            return true;
        }
        case 'set_item_description': {
            const item = (world.entities || []).find(e => e.id === finding.patch.entityId && e.type === 'item');
            if (!item || String(item.description || '').trim()) return false;
            item.description = String(finding.patch.description || '').trim().slice(0, 4000);
            return Boolean(item.description);
        }
        case 'set_schedule': {
            const entity = (world.entities || []).find(e => e.id === finding.patch.entityId);
            if (!entity || (entity.schedule || []).length) return false;
            entity.schedule = safeJsonClone(finding.patch.schedule);
            return true;
        }
        case 'set_agenda': {
            const entity = (world.entities || []).find(e => e.id === finding.patch.entityId);
            if (!entity || String(entity.goal || '').trim()) return false;
            entity.goal = finding.patch.goal;
            if (finding.patch.beats?.length) entity.goalSteps = [...finding.patch.beats];
            if (finding.patch.pool?.length) entity.goalPool = [...finding.patch.pool];
            if (finding.patch.autonomy) entity.goalAutonomy = finding.patch.autonomy;
            if (finding.patch.difficulty != null) entity.goalDifficulty = finding.patch.difficulty;
            return true;
        }
        case 'set_beats': {
            const entity = (world.entities || []).find(e => e.id === finding.patch.entityId);
            if (!entity || (entity.goalSteps || []).length) return false;
            entity.goalSteps = [...finding.patch.beats];
            if (finding.patch.pool?.length && !(entity.goalPool || []).length) {
                entity.goalPool = [...finding.patch.pool];
            }
            return true;
        }
        case 'set_relationship': {
            const entities = world.entities || [];
            const { a, b, label, score, reason } = finding.patch;
            if (!entities.some(e => e.id === a) || !entities.some(e => e.id === b)) return false;
            if (!Array.isArray(world.relationships)) world.relationships = [];
            const key = relationshipKey(a, b);
            // The author's standing for a pair is never overwritten.
            if (world.relationships.some(rel => relationshipKey(rel.a, rel.b) === key)) return false;
            world.relationships.push({ a, b, label, score, reason });
            return true;
        }
        case 'set_location_state': {
            const location = locations.find(l => l.id === finding.patch.locationId);
            if (!location) return false;
            if (location.danger != null && location.danger !== '') return false;
            location.danger = finding.patch.danger;
            location.prosperity = finding.patch.prosperity;
            if (finding.patch.conditions?.length) location.conditions = [...finding.patch.conditions];
            return true;
        }
        case 'add_faction': {
            if (!Array.isArray(world.factions)) world.factions = [];
            const { id, name } = finding.patch;
            if (world.factions.some(faction => faction.id === id
                || String(faction.name || '').trim().toLowerCase() === name.trim().toLowerCase())) {
                return false;
            }
            world.factions.push(normalizeWorldFaction(finding.patch, world.factions.length));
            return true;
        }
        case 'set_faction_membership': {
            const entity = (world.entities || []).find(e => e.id === finding.patch.entityId);
            if (!entity || entity.factionId) return false;
            // The faction may have been proposed alongside this and declined.
            if (!(world.factions || []).some(faction => faction.id === finding.patch.factionId)) return false;
            entity.factionId = finding.patch.factionId;
            return true;
        }
        default:
            return false;   // informational findings carry no automatic repair
    }
}

// --- The model used for structured work -------------------------------------
// Narration and JSON want opposite models. A reasoning model writes excellent
// prose and then talks itself past the token limit before emitting an object,
// which is why the chronicle classifier, the world turn and calibration each
// failed the same way. Every structured pass therefore routes through one
// deliberately chosen model instead of whatever is telling the story.
//
// This list used to be hand-written from memory, which meant it went stale the
// moment a provider retired a slug — "No endpoints found for
// anthropic/claude-3-5-haiku" was a model id that had simply never existed in
// that form. Nothing here is guessed any more: the candidates are derived from
// the live OpenRouter catalog, the same one AI Config already fetches, using
// the capability flags the catalog itself reports.

// A model has to be able to return an object on demand. Without one of these
// it is being asked to hit a JSON contract by luck.
const STRUCTURED_PARAM_FLAGS = Object.freeze(['response_format', 'structured_outputs']);

// Reasoning models are the specific failure this picker exists to avoid: they
// spend the whole budget thinking and emit nothing usable. The catalog reports
// the parameters that mark one.
const REASONING_PARAM_FLAGS = Object.freeze(['reasoning', 'include_reasoning', 'thinking']);

// A batch's answer has to fit in one reply. Below this, a model cannot finish
// even a small batch, which is what "the reply was cut off" actually meant.
const STRUCTURED_MIN_OUTPUT_TOKENS = 8000;

/**
 * How well a model is likely to hold a long structured answer together.
 *
 * Ranking purely on price put the smallest, cheapest models first, and those
 * are the ones that lose the shape of a big JSON object halfway through. Size
 * is not reported by the catalog, so this reads the proxies that are: how much
 * it can write, how much it can read, and what it costs — a model priced at
 * nothing is nearly always a tiny one.
 */
function structuredCapabilityBand(model) {
    let band = 0;
    if (model.maxOutput >= 16000) band += 2;
    else if (model.maxOutput >= 8000) band += 1;
    if (model.context >= 128000) band += 1;
    // Free and near-free models are the small ones. Still offered — just not
    // recommended ahead of something that will finish the work.
    if (model.price >= 0.05) band += 1;
    if (model.price >= 0.20) band += 1;
    return band;
}

function structuredModelPricePerMillion(model) {
    const prompt = parseFloat(model?.pricing?.prompt);
    const completion = parseFloat(model?.pricing?.completion);
    if (!Number.isFinite(prompt) || !Number.isFinite(completion)) return null;
    // Structured passes read a lot and write a little, so weight accordingly.
    return ((prompt * 3 + completion) / 4) * 1_000_000;
}

/**
 * Rank the live catalog for structured work: can emit JSON, is not a reasoning
 * model, has room for a world digest, and is cheap. Returns [] when the
 * catalog has not loaded, so the picker degrades to a plain text field rather
 * than offering ids that may no longer resolve.
 */
function rankStructuredModels(models, limit = 12) {
    return (Array.isArray(models) ? models : [])
        .map(model => {
            const params = Array.isArray(model?.supported_parameters) ? model.supported_parameters : [];
            const outputs = model?.architecture?.output_modalities;
            const price = structuredModelPricePerMillion(model);
            return {
                id: typeof model?.id === 'string' ? model.id : '',
                name: model?.name || model?.id || '',
                context: Number(model?.context_length) || 0,
                // What a pass can actually WRITE, which is the ceiling that was
                // silently truncating replies — not the context window.
                maxOutput: Number(model?.top_provider?.max_completion_tokens) || 0,
                price,
                json: STRUCTURED_PARAM_FLAGS.some(flag => params.includes(flag)),
                reasoning: REASONING_PARAM_FLAGS.some(flag => params.includes(flag)),
                // Sorting by price alone put two music-generation models at the
                // top: they are cheap and report response_format, but a model
                // that answers in audio cannot return a calibration object.
                textOnly: Array.isArray(outputs)
                    ? outputs.length === 1 && outputs[0] === 'text'
                    : true,                    // no modality reported: assume text
                free: price === 0
            };
        })
        .filter(model => model.id && model.json && !model.reasoning && model.textOnly
            && model.context >= 32000          // a world digest has to fit
            // The reply has to fit too. A model that can only write 4k tokens
            // will truncate a batch however cheap it is — this is the exact
            // ceiling that was failing, so it is now a hard requirement.
            && (model.maxOutput === 0 || model.maxOutput >= STRUCTURED_MIN_OUTPUT_TOKENS)
            && model.price != null)
        // Cheapest first was the wrong order: it put 4-billion-parameter models
        // at the top, and small models are exactly the ones that lose the
        // thread of a long structured answer. Sort by capability band first,
        // then by price inside the band, so the default is something that can
        // actually finish the job.
        .sort((left, right) =>
            structuredCapabilityBand(right) - structuredCapabilityBand(left)
            || left.price - right.price)
        .slice(0, limit)
        .map(model => {
            const price = model.free
                ? 'free'
                : '$' + (model.price < 1 ? model.price.toFixed(3) : model.price.toFixed(2)) + '/M';
            const out = model.maxOutput ? `${Math.round(model.maxOutput / 1000)}k out` : 'output unstated';
            return { ...model, note: `${price} · ${Math.round(model.context / 1000)}k ctx · ${out}` };
        });
}

/**
 * The model to use for anything that must return structured data. Falls back
 * through the world's own settings so nothing breaks when it is unset.
 */
function structuredModelFor(world) {
    const chosen = String(state.globalSettings?.structuredModel || '').trim();
    if (chosen) return chosen;
    const agent = world ? normalizeWorldAgentConfig(world).model : '';
    return agent || world?.model || state.globalSettings.defaultModel;
}

/**
 * One small call for one character's beats — the cheapest useful unit of AI
 * help. Beats are what turn "made progress" into something the player can
 * actually discover, and writing four of them by hand for every NPC is the
 * kind of chore that stops a world ever getting finished.
 */
async function generateAgendaBeats(entity, button) {
    const world = state.editingWorld;
    if (!world || !entity) return;
    if (!hasApiCredentials()) return showToast('API Key missing (Settings).', 'error');
    if (!String(entity.goal || '').trim()) {
        return showToast('Give them an agenda first — the beats are the steps toward it.', 'info');
    }
    const original = button ? button.textContent : '';
    if (button) { button.disabled = true; button.textContent = '⏳'; }
    try {
        const response = await fetch(apiBase() + '/chat/completions', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', ...authHeaders(), ...attributionHeaders() },
            body: JSON.stringify({
                model: structuredModelFor(world),
                max_tokens: 1200,
                response_format: { type: 'json_object' },
                messages: [
                    { role: 'system', content: `You write the concrete steps a character takes toward a private goal, for a roleplay world engine.

Return 4 or 5 beats in order, escalating. Each is ONE specific observable action, written in past tense, as a bystander would report it — "asked the mason about the old seal", "was seen carrying a lantern down to the cellar long after closing". Never vague ("made progress", "worked on her plan"), never internal ("decided to"), never a whole scene.

Also suggest one follow-up aim they would take up once this one resolves.

Reply with only this JSON: {"beats":["...","..."],"next_goal":"..."}` },
                    { role: 'user', content: `WORLD: ${world.name}\n${world.description ? `PREMISE: ${String(world.description).slice(0, 300)}\n` : ''}CHARACTER: ${entity.name}\n${entity.description ? `ABOUT: ${String(entity.description).slice(0, 600)}\n` : ''}${entity.persona ? `MANNER: ${String(entity.persona).slice(0, 600)}\n` : ''}THEIR GOAL: ${entity.goal}\n\nWrite their beats.` }
                ]
            })
        });
        if (!response.ok) {
            throw new Error((await response.json().catch(() => ({})))?.error?.message || response.statusText);
        }
        const message = (await response.json())?.choices?.[0]?.message || {};
        let text = message.content || '';
        if (Array.isArray(text)) text = text.map(part => part?.text || '').join(' ');
        if (!String(text).trim() && message.reasoning) text = String(message.reasoning);
        text = String(text).replace(/<(think|thinking|reasoning)>[\s\S]*?<\/\1>/gi, ' ');

        let parsed = null;
        for (let start = text.indexOf('{'); start >= 0 && !parsed; start = text.indexOf('{', start + 1)) {
            const end = text.indexOf('}', start);
            if (end < 0) break;
            try {
                const candidate = JSON.parse(text.slice(start, text.lastIndexOf('}') + 1));
                if (Array.isArray(candidate?.beats)) parsed = candidate;
            } catch (error) { /* keep scanning */ }
        }
        if (!parsed) throw new Error('The model did not return beats. Try a smaller, non-reasoning model above.');

        const beats = parsed.beats.map(beat => String(beat || '').trim()).filter(Boolean).slice(0, 20);
        if (!beats.length) throw new Error('The model returned no usable beats.');
        entity.goalSteps = beats;
        const next = String(parsed.next_goal || '').trim();
        if (next && !(entity.goalPool || []).length) entity.goalPool = [next.slice(0, 240)];
        renderWorldEntities();
        showToast(`${beats.length} beats written for ${entity.name} — edit freely, then Save World.`, 'success');
    } catch (error) {
        console.error('Beat generation failed', error);
        showToast(error.message || 'Could not write beats.', 'error');
    } finally {
        if (button) { button.disabled = false; button.textContent = original || '✨ Generate'; }
    }
}

// --- Calibration: AI passes -------------------------------------------------
// Tier 0 repairs facts. These passes supply the judgement a hand-built world is
// missing — which room is inside which building, how far apart places are, who
// lives where, who is married to whom. Each pass is small and focused so it
// stays reliable, gap-fills only (an authored value is never overwritten), and
// is idempotent, so a partial failure can simply be run again.

const CALIBRATION_PASSES = Object.freeze({
    structure: {
        label: 'Structure',
        blurb: 'Which places sit inside which, how they are laid out, and how long it takes to walk between them.'
    },
    people: {
        label: 'People',
        blurb: 'Where each character lives and starts, how they speak, who they belong with, their daily routine, and the agenda they pursue when you are not watching.'
    },
    items: {
        label: 'Items',
        blurb: 'Separately enriches objects with a useful description, placement and search tags—without treating them like people.'
    },
    society: {
        label: 'Society',
        blurb: 'Who stands in what relation to whom, which powers exist and who belongs to them, and how safe or prosperous each place is before play begins.'
    }
});

// How many pairs the Society pass will ever ask about. A world may hold
// hundreds of people, and every pair is a question — so the engine chooses
// which pairs are worth asking about and the model never sees the rest.
const SOCIETY_PAIR_CAP = 60;

// Below this many people, every pair is enumerable and cheap, so the pass asks
// about all of them rather than leaving a hand-written world with no proposals.
const SOCIETY_SMALL_CAST = 40;

/**
 * The pairs whose standing actually matters, most telling first.
 *
 * Asking a model about every pair is O(n²) and unaffordable past a few dozen
 * people; asking about none leaves a world of strangers. So the pairs are
 * chosen here, from evidence already in the world: people who share a roof,
 * who serve the same power, who are named in each other's description, or who
 * are both prominent enough that the player will deal with them.
 */
function calibrationPairCandidates(world) {
    const npcs = (world?.entities || []).filter(entity => entity?.type === 'npc' && entity.id);
    const nameOf = entity => String(entity.name || '').trim();
    const scored = new Map();
    const consider = (a, b, weight, why) => {
        if (a.id === b.id) return;
        const key = relationshipKey(a.id, b.id);
        const existing = scored.get(key);
        if (existing) {
            existing.weight += weight;
            if (!existing.reasons.includes(why)) existing.reasons.push(why);
            return;
        }
        scored.set(key, { a, b, weight, reasons: [why] });
    };

    // Named in each other's text — the strongest signal a world can give.
    npcs.forEach(entity => {
        const haystack = `${entity.description || ''} ${entity.persona || ''} ${entity.goal || ''}`.toLowerCase();
        if (!haystack.trim()) return;
        npcs.forEach(other => {
            const name = nameOf(other).toLowerCase();
            if (!name || other.id === entity.id || name.length < 3) return;
            if (haystack.includes(name)) consider(entity, other, 100, 'named in their description');
        });
    });

    // Under one roof: households, families, the people a life is actually lived with.
    const byHome = new Map();
    npcs.forEach(entity => {
        const home = String(entity.homeLocation || '').trim().toLowerCase();
        if (!home) return;
        if (!byHome.has(home)) byHome.set(home, []);
        byHome.get(home).push(entity);
    });
    byHome.forEach(group => {
        if (group.length > 8) return;         // a barracks is not a household
        group.forEach((a, i) => group.slice(i + 1).forEach(b => consider(a, b, 60, 'share a home')));
    });

    // Sworn to the same power.
    const byFaction = new Map();
    npcs.forEach(entity => {
        const faction = String(entity.factionId || '').trim();
        if (!faction) return;
        if (!byFaction.has(faction)) byFaction.set(faction, []);
        byFaction.get(faction).push(entity);
    });
    byFaction.forEach(group => {
        if (group.length > 8) return;
        group.forEach((a, i) => group.slice(i + 1).forEach(b => consider(a, b, 40, 'serve the same faction')));
    });

    // Standing in the same place when play begins.
    const byStart = new Map();
    npcs.forEach(entity => {
        const start = String(entity.startLocation || '').trim().toLowerCase();
        if (!start) return;
        if (!byStart.has(start)) byStart.set(start, []);
        byStart.get(start).push(entity);
    });
    byStart.forEach(group => {
        if (group.length > 8) return;
        group.forEach((a, i) => group.slice(i + 1).forEach(b => consider(a, b, 30, 'begin play together')));
    });

    // The cast the player will actually deal with.
    const majors = npcs.filter(entity => entity.isMajor);
    majors.forEach((a, i) => majors.slice(i + 1).forEach(b => consider(a, b, 20, 'both central to the story')));

    // A hand-written world often states none of the above — no homes, no
    // factions, nobody flagged major — and would then get no proposals at all,
    // which is the opposite of the point. When the cast is small enough that
    // every pair fits inside the cap anyway, ask about all of them; the O(n²)
    // concern only bites on a large cast, and a large cast has the signals.
    if (npcs.length <= SOCIETY_SMALL_CAST) {
        npcs.forEach((a, i) => npcs.slice(i + 1).forEach(b =>
            consider(a, b, 5, 'both live in this world')));
    }

    // Anything the world already states is not worth a question.
    const stated = new Set(readWorldRelationships(world).map(relation => relationshipKey(relation.a, relation.b)));
    return [...scored.entries()]
        .filter(([key]) => !stated.has(key))
        .sort((left, right) => right[1].weight - left[1].weight)
        .slice(0, SOCIETY_PAIR_CAP)
        .map(([, pair]) => pair);
}

// --- Batching -----------------------------------------------------------
// Every pass used to send the whole world in one call and hope the answer fit
// in one reply. It does not: 60 judged pairs is roughly 5,400 tokens of JSON
// before places, factions and memberships are added, and a reply cut off at
// the limit was thrown away whole. The size of a world is not the model's
// problem to solve, so the work is now cut into batches the answer can fit in.
//
// Sized by how much OUTPUT one unit provokes, not how much input it costs:
// a location's role and travel times are a short answer, a character's whole
// routine and agenda is a long one.
const CALIBRATION_BATCH_SIZES = Object.freeze({
    structure: 40,   // a line or two of JSON each
    people: 10,      // persona + schedule + beats + pool: the longest answers
    items: 24,       // description + placement + tags are compact
    society: 15      // a judged pair plus a place, each a short object
});

/**
 * The units of work a pass has to get through, so it can be run in batches.
 * Returns [] when a pass has nothing left to ask about.
 */
function calibrationWorkUnits(world, pass) {
    if (pass === 'structure') return (world?.locations || []).slice();
    if (pass === 'people') return (world?.entities || []).filter(entity => entity?.type === 'npc');
    if (pass === 'items') return (world?.entities || []).filter(entity => entity?.type === 'item');
    if (pass === 'society') {
        // Three kinds of unit share the pass, batched together so each call
        // carries a slice of each. Whoever has no faction is a unit too: they
        // were previously listed in full in EVERY batch, which asked the same
        // question six times over and paid for six sets of duplicate answers.
        const pairs = calibrationPairCandidates(world);
        const places = (world?.locations || [])
            .filter(location => location.danger == null || location.danger === '');
        const unaffiliated = (world?.entities || [])
            .filter(entity => entity?.type === 'npc' && !entity.factionId);
        return [...pairs.map(pair => ({ kind: 'pair', pair })),
                ...places.map(place => ({ kind: 'place', place })),
                ...unaffiliated.map(entity => ({ kind: 'member', entity }))];
    }
    return [];
}

function calibrationBatches(world, pass) {
    const units = calibrationWorkUnits(world, pass);
    const size = CALIBRATION_BATCH_SIZES[pass] || 20;
    const batches = [];
    for (let index = 0; index < units.length; index += size) {
        batches.push(units.slice(index, index + size));
    }
    return batches;
}

function calibrationSocietyDigest(world, batch) {
    const about = entity => String(entity.description || entity.persona || '')
        .replace(/\s+/g, ' ').slice(0, 160);
    const units = batch || calibrationWorkUnits(world, 'society');
    const pairs = units.filter(unit => unit.kind === 'pair').map((unit, index) => {
        const pair = unit.pair;
        return `${index + 1}. [${pair.a.id}] "${pair.a.name}" ↔ [${pair.b.id}] "${pair.b.name}" (${pair.reasons.join(', ')})
   ${pair.a.name}: ${about(pair.a) || 'nothing written'}
   ${pair.b.name}: ${about(pair.b) || 'nothing written'}`;
    }).join('\n');

    const places = units.filter(unit => unit.kind === 'place').map(unit => {
        const location = unit.place;
        return `- [${location.id}] "${location.name}"${location.description ? ` — ${String(location.description).replace(/\s+/g, ' ').slice(0, 160)}` : ''}`;
    }).join('\n');

    const factions = (world.factions || []).length
        ? (world.factions || []).map(faction =>
            `- [${faction.id}] "${faction.name}"${faction.goal ? ` — seeks ${faction.goal}` : ''}`).join('\n')
        : '(none — propose any the fiction clearly implies)';

    // Only the people this batch is responsible for. Sending the whole roster
    // every time is what produced the same proposal over and over.
    const unaffiliated = units.filter(unit => unit.kind === 'member').map(unit => {
        const entity = unit.entity;
        return `- [${entity.id}] "${entity.name}"${entity.description ? ` — ${String(entity.description).replace(/\s+/g, ' ').slice(0, 120)}` : ''}`;
    }).join('\n');

    return { pairs, places, factions, unaffiliated };
}

function calibrationLocationDigest(world, batch) {
    return (batch || world.locations || []).map(location => {
        const exits = (location.exits || []).map(exit => {
            const target = getExitTargetName(exit);
            const minutes = (exit && typeof exit === 'object' && exit.travelTime) || 0;
            return `${target}${minutes ? ` (${minutes}m)` : ' (no travel time)'}`;
        }).join('; ') || 'none';
        const bits = [`- [${location.id}] "${location.name}"`];
        if (location.mapType) bits.push(`role=${location.mapType}`);
        if (location.parentLocationId || location.region) bits.push(`inside=${location.parentLocationId || location.region}`);
        if (location.mapFloor) bits.push(`floor=${location.mapFloor}`);
        bits.push(`exits: ${exits}`);
        const description = String(location.description || '').replace(/\s+/g, ' ').slice(0, 220);
        if (description) bits.push(`— ${description}`);
        return bits.join(' | ');
    }).join('\n');
}

function calibrationPeopleDigest(world, batch) {
    const npcs = batch || (world.entities || []).filter(entity => entity.type === 'npc');
    return npcs.map(entity => {
        const has = [];
        if (entity.startLocation) has.push(`starts=${entity.startLocation}`);
        if (entity.homeLocation) has.push(`home=${entity.homeLocation}`);
        if (entity.persona) has.push('persona=written');
        if ((entity.schedule || []).length) has.push(`schedule=${entity.schedule.length} blocks`);
        if (entity.goal) has.push('agenda=written');
        if ((entity.goalSteps || []).length) has.push(`beats=${entity.goalSteps.length}`);
        if ((entity.groupIds || []).length) has.push(`groups=${entity.groupIds.join(',')}`);
        if ((entity.tags || []).length) has.push(`tags=${entity.tags.join(',')}`);
        const bits = [`- [${entity.id}] "${entity.name}" | depth=${entity.simulationDepth || (entity.isMajor ? 'core' : 'unset')}`];
        bits.push(has.length ? `already has: ${has.join(', ')}` : 'has nothing set');
        const about = String(entity.description || '').replace(/\s+/g, ' ').slice(0, 300);
        if (about) bits.push(`— ${about}`);
        return bits.join(' | ');
    }).join('\n');
}

function calibrationItemDigest(world, batch) {
    return (batch || (world.entities || []).filter(entity => entity.type === 'item')).map(item => {
        const has = [];
        if (item.description) has.push('description=written');
        if (item.startLocation) has.push(`placed=${item.startLocation}`);
        if ((item.tags || []).length) has.push(`tags=${item.tags.join(',')}`);
        return `- [${item.id}] "${item.name}" | ${has.length ? `already has: ${has.join(', ')}` : 'has nothing set'}`;
    }).join('\n');
}

function buildCalibrationPrompt(world, pass, batch) {
    if (pass === 'society') {
        const { pairs, places, factions, unaffiliated } = calibrationSocietyDigest(world, batch);
        if (!pairs && !places && !unaffiliated) return '';
        // Only ask for the work this batch actually carries. Asking every
        // section every time is what made six calls answer the same question
        // about factions six times over.
        const sections = [];
        if (pairs) sections.push(`1. RELATIONSHIPS. For each numbered pair, judge their standing from what is written about them. Give:
   - label: what they are to each other in the world's own words — "wife", "estranged brother", "rival", "old debt", "mentor". Never "acquaintance" for people who share a home or a history; a marriage is a marriage and a feud is a feud.
   - score: -100 (would see them dead) to 100 (would die for them). Family and love sit high, rivalry low, indifference near zero. A bond can be close AND bitter — score how they FEEL, and let the label carry the rest.
   - reason: one short clause naming what the standing rests on.
   Skip any pair the text gives you no basis for. A guess is worse than a gap.`);
        if (places) sections.push(`2. PLACES. For each listed location give danger 0-100 and prosperity 0-100, judged from what it is. A guarded hall is not dangerous; a bandit road is. A market thrives; a flooded crypt does not. Add conditions only where something is visibly true of the place right now ("under curfew", "smoke-logged"), at most two, never speculation.`);
        if (unaffiliated) sections.push(`3. FACTIONS AND WHO SERVES THEM. For each character listed under CHARACTERS BELONGING TO NOBODY, decide whether they plainly serve one of the powers above, and say so with a membership. An innkeeper, a hedge-witch or a farmer usually serves nobody — leave them out rather than forcing everyone into a box.
   Where the fiction clearly implies an organised power that is NOT already listed — a guild those characters belong to, a watch, an order, a cartel — propose it too: name, one-line goal, influence 0-100, reputation -100..100. You may then give it members by name. Propose none if the world does not call for them; an invented faction is worse than no faction.`);
        return `You are settling the society of a roleplay world before play begins: who stands in what relation to whom, which powers exist, and what each place is like to be in.

${sections.join('\n\n')}

OUTPUT FORMAT — this is strict:
Your entire reply is one JSON object and nothing else. The first character you write must be {. Do not restate the task or reason in the open; put justification in each item's own field.

{"relationships":[{"a":"<id>","b":"<id>","label":"<text>","score":<int>,"reason":"<short>"}],
 "places":[{"id":"<id>","danger":<int>,"prosperity":<int>,"conditions":["<text>"],"why":"<short>"}],
 "factions":[{"name":"<text>","goal":"<text>","influence":<int>,"reputation":<int>,"why":"<short>"}],
 "memberships":[{"entity":"<id>","faction":"<faction id or the name of one you proposed>","why":"<short>"}]}

Omit any array you are not using. Never use an id that is not listed above.

WORLD: ${world.name}
${world.description ? `PREMISE: ${String(world.description).slice(0, 400)}\n` : ''}
EXISTING FACTIONS:
${factions}
${pairs ? `\nPAIRS TO JUDGE:\n${pairs}` : ''}${places ? `\nPLACES WITH NOTHING SET:\n${places}` : ''}${unaffiliated ? `\nCHARACTERS BELONGING TO NOBODY:\n${unaffiliated}` : ''}`;
    }
    if (pass === 'people') {
        const places = (world.locations || [])
            .map(location => `- [${location.id}] "${location.name}"${location.description ? ` — ${String(location.description).replace(/\s+/g, ' ').slice(0, 120)}` : ''}`)
            .join('\n');
        return `You are settling the cast of a roleplay world into it, so its engine can run them when the player is not watching.

For each character, supply ONLY what is missing — anything listed under "already has" is the author's and must not be replaced:
- start: the location id where they are when play begins
- home: the location id they belong to and return to (often the same)
- persona: how they speak, behave and carry themselves. Give every person one: 2-3 sentences for core/recurring cast, one sharp sentence for background cast. Second person absent.
- depth: background | recurring | core — how much simulation/context attention they deserve
- tags: 2-6 short search terms that describe role, occupation, temperament or story function
- group: where the fiction clearly implies a reusable household, family, organization or crew, give {name,type,description,tags}. Omit it for genuinely unaffiliated people.
- schedule: 2-5 blocks of {time "HH:MM" (24h), location id, short activity}. A believable day, in order, using places that exist.
- goal: one private aim they pursue off-screen, drawn from who they are
- beats: 4-5 concrete steps toward it, in order, each ONE observable past-tense action a bystander could report ("asked the mason about the old seal", "was seen carrying a lantern down to the cellar"). Never vague, never internal.
- next_goals: one or two aims they would take up after that one resolves
- autonomy: paused | low | medium | high — how hard they push
- difficulty: 0-100, higher is slower going

Draw everything from the description you are given. Do not invent a different character. Do not use any location id that is not listed.

OUTPUT FORMAT — this is strict:
Your entire reply is one JSON object and nothing else. The first character you write must be {. Do not restate the task or reason in the open; put justification in each item's "why" field.

{"people":[{"id":"<id>","start":"<loc id>","home":"<loc id>","persona":"<text>","depth":"recurring","tags":["<tag>"],"group":{"name":"<text>","type":"household|family|organization|crew|other","description":"<short>","tags":["<tag>"]},"schedule":[{"time":"HH:MM","location":"<loc id>","activity":"<short>"}],"goal":"<text>","beats":["<text>"],"next_goals":["<text>"],"autonomy":"medium","difficulty":50,"why":"<short>"}]}

Omit any field you have no opinion on.

WORLD: ${world.name}
${world.description ? `PREMISE: ${String(world.description).slice(0, 400)}\n` : ''}
PLACES:
${places}

CHARACTERS:
${calibrationPeopleDigest(world, batch)}`;
    }
    if (pass === 'items') {
        const places = (world.locations || [])
            .map(location => `- [${location.id}] "${location.name}"`)
            .join('\n');
        return `You are enriching the object directory of a roleplay world. Items are objects, not people: do not give them personas, schedules, homes, emotions or relationships.

For every listed item, supply ONLY what is missing:
- description: one concrete player-facing sentence explaining what it looks like and why it matters
- location: the id of the place where it begins, but only when the fiction supports a placement
- tags: 2-6 short search terms covering kind, use, owner or story relevance

OUTPUT FORMAT — strict JSON only. The first character must be {.
{"items":[{"id":"<id>","description":"<text>","location":"<loc id>","tags":["<tag>"],"why":"<short>"}]}

Omit fields the world already has or that the fiction cannot support. Never invent an item or location id.

WORLD: ${world.name}
${world.description ? `PREMISE: ${String(world.description).slice(0, 400)}\n` : ''}
PLACES:
${places}

ITEMS:
${calibrationItemDigest(world, batch)}`;
    }
    if (pass !== 'structure') return '';
    return `You are laying out the map of a roleplay world so its engine can run it.

For each location decide, ONLY where the world has not already said:
- description: one concise player-facing sentence for a blank location
- region: an existing region id, or a short reusable region name when none exists
- role: one of region, route, building, outdoor, room, area
- inside: the id of the place that physically contains it (a bathroom is inside a house; a house is not inside anything). Omit for top-level places.
- floor: a storey number when a building has more than one ("2", "-1" for a cellar). Omit otherwise.
- connect_to: for any place NOTHING leads to, the id of the location it should connect to, judged from the fiction.
- tags: 2-6 short search terms for the place, its function and atmosphere

Also estimate walking time in whole minutes for each connection that has none. Be realistic and modest: a door between two rooms of one house is 0-1 minutes; crossing a village 5-15; travelling between settlements 30-240. Never propose a time for a connection that already has one.

OUTPUT FORMAT — this is strict:
Your entire reply is one JSON object and nothing else. The first character you write must be {. Do not restate the task, do not reason in the open, do not add commentary before or after. If you want to justify a decision, put it in that item's "why" field — that is what it is for.

{"locations":[{"id":"<id>","description":"<text>","region":"<region id or name>","role":"<role>","inside":"<id or omit>","floor":"<string or omit>","connect_to":"<id or omit>","tags":["<tag>"],"why":"<short>"}],
 "travel":[{"from":"<id>","to":"<id>","minutes":<integer>}]}

Omit any array you are not using, and omit any field you have no opinion on. Never invent locations that are not listed.

WORLD: ${world.name}
${world.description ? `PREMISE: ${String(world.description).slice(0, 400)}\n` : ''}
LOCATIONS:
${calibrationLocationDigest(world, batch)}

EXISTING REGIONS:
${(world.regions || []).length ? world.regions.map(region => `- [${region.id}] "${region.name}"`).join('\n') : '(none — create only broad reusable regions the listed places clearly imply)'}`;
}

// Turn a pass's reply into reviewable findings. Anything the world already
// states is skipped, so running a pass twice proposes nothing the second time.
function calibrationFindingsFromStructure(world, payload) {
    const findings = [];
    const byId = new Map((world.locations || []).map(l => [String(l.id), l]));
    const seen = new Set();

    (Array.isArray(payload?.locations) ? payload.locations : []).forEach(entry => {
        const location = byId.get(String(entry?.id || ''));
        if (!location) return;
        const why = String(entry?.why || '').slice(0, 200);

        const description = String(entry?.description || '').trim();
        if (description && !String(location.description || '').trim()) {
            findings.push({
                tier: 'structure', id: `description_${location.id}`, type: 'set_location_description', severity: 'suggestion',
                title: `Describe "${location.name}"`, detail: description.slice(0, 240),
                patch: { locationId: location.id, description }
            });
        }

        const regionRef = String(entry?.region || '').trim();
        if (regionRef && !location.regionId) {
            const existingRegion = (world.regions || []).find(region => region.id === regionRef
                || String(region.name || '').trim().toLowerCase() === regionRef.toLowerCase());
            findings.push({
                tier: 'structure', id: `region_${location.id}`, type: 'set_location_region', severity: 'suggestion',
                title: `Group "${location.name}" under ${existingRegion?.name || regionRef}`,
                detail: why || 'Regions keep large location directories browsable and reusable.',
                patch: { locationId: location.id, regionId: existingRegion?.id || '', name: existingRegion?.name || regionRef }
            });
        }

        const tags = [...new Set((Array.isArray(entry?.tags) ? entry.tags : [])
            .map(tag => String(tag || '').trim()).filter(Boolean))].slice(0, 30);
        if (tags.length && !(location.tags || []).length) {
            findings.push({
                tier: 'structure', id: `tags_${location.id}`, type: 'set_location_tags', severity: 'suggestion',
                title: `Make "${location.name}" searchable`,
                detail: tags.join(' · '),
                patch: { locationId: location.id, tags }
            });
        }

        const role = String(entry?.role || '').trim().toLowerCase();
        if (role && WORLD_MAP_TYPES.has(role) && !location.mapType) {
            findings.push({
                tier: 'structure', id: `role_${location.id}`, type: 'set_map_type', severity: 'suggestion',
                title: `"${location.name}" is a ${formatWorldMapType(role)}`,
                detail: why || 'Sets how this place is drawn on the map and how containment reads.',
                patch: { locationId: location.id, mapType: role }
            });
        }

        const insideId = String(entry?.inside || '').trim();
        const parent = byId.get(insideId);
        if (parent && parent.id !== location.id
            && !location.parentLocationId
            && String(location.region || '').trim().toLowerCase() !== String(parent.id).toLowerCase()
            && String(location.region || '').trim().toLowerCase() !== String(parent.name || '').trim().toLowerCase()) {
            findings.push({
                tier: 'structure', id: `inside_${location.id}`, type: 'set_containment', severity: 'warning',
                title: `"${location.name}" is inside "${parent.name}"`,
                detail: why || 'Containment lets the player walk in and out without an explicit exit on both sides.',
                patch: { locationId: location.id, parentLocationId: parent.id }
            });
        }

        const floor = String(entry?.floor || '').trim();
        if (floor && !location.mapFloor) {
            findings.push({
                tier: 'structure', id: `floor_${location.id}`, type: 'set_floor', severity: 'suggestion',
                title: `"${location.name}" is on floor ${floor}`,
                detail: why || 'Used when drawing a multi-storey building.',
                patch: { locationId: location.id, mapFloor: floor }
            });
        }

        const connectId = String(entry?.connect_to || '').trim();
        const connectTo = byId.get(connectId);
        if (connectTo && connectTo.id !== location.id && !(location.exits || []).length) {
            findings.push({
                tier: 'structure', id: `connect_${location.id}`, type: 'connect_location', severity: 'critical',
                title: `Connect "${location.name}" to "${connectTo.name}"`,
                detail: why || 'Nothing currently leads here, so the player can never arrive.',
                patch: { locationId: location.id, targetId: connectTo.id, targetName: connectTo.name,
                         sourceName: location.name }
            });
        }
    });

    (Array.isArray(payload?.travel) ? payload.travel : []).forEach(entry => {
        const from = byId.get(String(entry?.from || ''));
        const to = byId.get(String(entry?.to || ''));
        const minutes = Math.max(0, Math.min(1440, parseInt(entry?.minutes) || 0));
        if (!from || !to || !minutes) return;
        const key = `${from.id}>${to.id}`;
        if (seen.has(key)) return;
        const exitIndex = (from.exits || []).findIndex(exit =>
            String(getExitTargetName(exit) || '').trim().toLowerCase() === String(to.name || '').trim().toLowerCase()
            || String(getExitTargetName(exit) || '').trim().toLowerCase() === String(to.id).toLowerCase());
        if (exitIndex < 0) return;
        const existing = from.exits[exitIndex];
        if (existing && typeof existing === 'object' && existing.travelTime) return;   // already stated
        seen.add(key);
        findings.push({
            tier: 'structure', id: `travel_${from.id}_${to.id}`, type: 'set_travel_time', severity: 'suggestion',
            title: `${from.name} → ${to.name}: ${minutes} min`,
            detail: 'Travel time drives the world clock, so journeys cost real time and schedules stay in step.',
            patch: { locationId: from.id, exitIndex, minutes }
        });
    });

    return findings;
}

function calibrationFindingsFromPeople(world, payload) {
    const findings = [];
    const byId = new Map((world.entities || []).map(entity => [String(entity.id), entity]));
    const locations = new Map();
    (world.locations || []).forEach(location => {
        locations.set(String(location.id).toLowerCase(), location);
        if (location.name) locations.set(String(location.name).trim().toLowerCase(), location);
    });
    const resolveLocation = ref => locations.get(String(ref || '').trim().toLowerCase()) || null;

    (Array.isArray(payload?.people) ? payload.people : []).forEach(entry => {
        const entity = byId.get(String(entry?.id || ''));
        if (!entity || entity.type !== 'npc') return;
        const why = String(entry?.why || '').slice(0, 200);
        const push = (type, id, severity, title, detail, patch) =>
            findings.push({ tier: 'people', id: `${id}_${entity.id}`, type, severity, title, detail, patch });

        const start = resolveLocation(entry?.start);
        if (start && !entity.startLocation) {
            push('set_entity_location', 'start', 'warning',
                `${entity.name} starts at ${start.name}`,
                why || 'Without this they begin wherever the location list happens to start.',
                { entityId: entity.id, locationId: start.id });
        }
        const home = resolveLocation(entry?.home);
        if (home && !entity.homeLocation) {
            push('set_entity_home', 'home', 'suggestion',
                `${entity.name} belongs to ${home.name}`,
                why || 'Home decides where they can be found when nothing else is driving them.',
                { entityId: entity.id, locationId: home.id });
        }

        const persona = String(entry?.persona || '').trim();
        if (persona && !String(entity.persona || '').trim()) {
            push('set_persona', 'persona', 'suggestion',
                `Give ${entity.name} a voice`,
                persona.slice(0, 180) + (persona.length > 180 ? '…' : ''),
                { entityId: entity.id, persona: persona.slice(0, 4000) });
        }

        const depth = String(entry?.depth || '').trim().toLowerCase();
        if (WORLD_DIRECTORY_DEPTHS.includes(depth)
            && (!entity.simulationDepth || (entity.simulationDepth === 'background' && !entity.isMajor))) {
            push('set_entity_depth', 'depth', 'suggestion',
                `${entity.name}: ${depth} cast`,
                'Controls simulation and context priority; it does not gate persona editing.',
                { entityId: entity.id, simulationDepth: depth });
        }

        const tags = [...new Set((Array.isArray(entry?.tags) ? entry.tags : [])
            .map(tag => String(tag || '').trim()).filter(Boolean))].slice(0, 30);
        if (tags.length && !(entity.tags || []).length) {
            push('set_entity_tags', 'tags', 'suggestion',
                `Tag ${entity.name} for search`, tags.join(' · '), { entityId: entity.id, tags });
        }

        const proposedGroup = isPlainObject(entry?.group) ? entry.group : null;
        if (proposedGroup && !(entity.groupIds || []).length) {
            const groupName = String(proposedGroup.name || '').trim();
            const groupType = String(proposedGroup.type || '').trim().toLowerCase();
            if (groupName && ['household', 'family', 'organization', 'crew', 'other'].includes(groupType)) {
                push('set_entity_group', 'group', 'suggestion',
                    `${entity.name} belongs to ${groupName}`,
                    String(proposedGroup.description || why || 'A reusable cast group inferred from the fiction.').slice(0, 240),
                    {
                        entityId: entity.id, name: groupName, groupType,
                        description: String(proposedGroup.description || '').trim(),
                        homeLocationId: home?.id || '',
                        tags: Array.isArray(proposedGroup.tags) ? proposedGroup.tags : []
                    });
            }
        }

        // Schedules only count if every block is usable — a half-valid routine
        // would leave the character stranded at an impossible time.
        const blocks = (Array.isArray(entry?.schedule) ? entry.schedule : [])
            .map(block => {
                const location = resolveLocation(block?.location ?? block?.location_id);
                const time = String(block?.time || '').trim();
                if (!location || !isValidScheduleTime(time)) return null;
                const days = (Array.isArray(block?.days) ? block.days : (block?.day ? [block.day] : []))
                    .map(day => String(day || '').trim()).filter(Boolean).slice(0, 7);
                return { time, locationId: location.id, activity: String(block?.activity || '').slice(0, 160), ...(days.length ? { days } : {}) };
            })
            .filter(Boolean)
            .sort((a, b) => a.time.localeCompare(b.time))
            .slice(0, 20);
        if (blocks.length && !(entity.schedule || []).length) {
            push('set_schedule', 'schedule', 'warning',
                `${entity.name}: a daily routine (${blocks.length} blocks)`,
                blocks.map(block => `${block.time} ${locations.get(block.locationId.toLowerCase())?.name || block.locationId}${block.activity ? ` — ${block.activity}` : ''}`).join(' · '),
                { entityId: entity.id, schedule: blocks });
        }

        // The agenda is proposed as one unit: a goal with no beats is the vague
        // state we were trying to escape, and beats without a goal go nowhere.
        const goal = String(entry?.goal || '').trim();
        const beats = (Array.isArray(entry?.beats) ? entry.beats : [])
            .map(beat => String(beat || '').trim()).filter(Boolean).slice(0, 20);
        const pool = (Array.isArray(entry?.next_goals) ? entry.next_goals : [])
            .map(item => String(item || '').trim()).filter(Boolean).slice(0, 20);
        const autonomy = ['paused', 'low', 'medium', 'high'].includes(entry?.autonomy) ? entry.autonomy : '';
        const difficulty = Number.isFinite(Number(entry?.difficulty))
            ? Math.max(0, Math.min(100, Math.round(Number(entry.difficulty)))) : null;

        if (goal && !String(entity.goal || '').trim()) {
            push('set_agenda', 'agenda', 'warning',
                `${entity.name} wants: ${goal.slice(0, 90)}${goal.length > 90 ? '…' : ''}`,
                beats.length
                    ? `${beats.length} beats — ${beats.slice(0, 2).join('; ')}${beats.length > 2 ? '…' : ''}`
                    : (why || 'A private aim they pursue off-screen.'),
                { entityId: entity.id, goal: goal.slice(0, 200), beats, pool, autonomy, difficulty });
        } else if (beats.length && String(entity.goal || '').trim() && !(entity.goalSteps || []).length) {
            // They already have an aim but no concrete steps toward it.
            push('set_beats', 'beats', 'suggestion',
                `${entity.name}: ${beats.length} beats for their existing agenda`,
                beats.slice(0, 2).join('; ') + (beats.length > 2 ? '…' : ''),
                { entityId: entity.id, beats, pool });
        }
    });
    return findings;
}

function calibrationFindingsFromItems(world, payload) {
    const findings = [];
    const items = new Map((world.entities || [])
        .filter(entity => entity?.type === 'item').map(entity => [String(entity.id), entity]));
    const locations = new Map();
    (world.locations || []).forEach(location => {
        locations.set(String(location.id).toLowerCase(), location);
        if (location.name) locations.set(String(location.name).trim().toLowerCase(), location);
    });
    (Array.isArray(payload?.items) ? payload.items : []).forEach(entry => {
        const item = items.get(String(entry?.id || ''));
        if (!item) return;
        const description = String(entry?.description || '').trim();
        const why = String(entry?.why || '').trim().slice(0, 240);
        if (description && !String(item.description || '').trim()) {
            findings.push({
                tier: 'items', id: `item_description_${item.id}`, type: 'set_item_description', severity: 'suggestion',
                title: `Describe ${item.name}`, detail: description.slice(0, 240),
                patch: { entityId: item.id, description }
            });
        }
        const location = locations.get(String(entry?.location || '').trim().toLowerCase());
        if (location && !item.startLocation) {
            findings.push({
                tier: 'items', id: `item_location_${item.id}`, type: 'set_entity_location', severity: 'warning',
                title: `Place ${item.name} at ${location.name}`,
                detail: why || 'An unplaced item exists in the directory but cannot enter a scene.',
                patch: { entityId: item.id, locationId: location.id }
            });
        }
        const tags = [...new Set((Array.isArray(entry?.tags) ? entry.tags : [])
            .map(tag => String(tag || '').trim()).filter(Boolean))].slice(0, 30);
        if (tags.length && !(item.tags || []).length) {
            findings.push({
                tier: 'items', id: `item_tags_${item.id}`, type: 'set_entity_tags', severity: 'suggestion',
                title: `Tag ${item.name} for search`, detail: tags.join(' · '),
                patch: { entityId: item.id, tags }
            });
        }
    });
    return findings;
}

function calibrationFindingsFromSociety(world, payload, carriedFactions) {
    const findings = [];
    const npcs = new Map((world.entities || [])
        .filter(entity => entity?.type === 'npc').map(entity => [String(entity.id), entity]));
    const locations = new Map((world.locations || []).map(location => [String(location.id), location]));
    const stated = new Set(readWorldRelationships(world).map(relation => relationshipKey(relation.a, relation.b)));
    const proposedPairs = new Set();

    (Array.isArray(payload?.relationships) ? payload.relationships : []).forEach(entry => {
        const a = npcs.get(String(entry?.a || ''));
        const b = npcs.get(String(entry?.b || ''));
        if (!a || !b || a.id === b.id) return;
        const key = relationshipKey(a.id, b.id);
        if (stated.has(key) || proposedPairs.has(key)) return;   // the author's word stands
        const label = String(entry?.label || '').trim().slice(0, 80);
        if (!label) return;                 // a bare number says nothing an author can review
        proposedPairs.add(key);
        const score = livingClamp(Number(entry?.score) || 0, -100, 100);
        const reason = String(entry?.reason || '').trim().slice(0, 240);
        findings.push({
            tier: 'society', id: `rel_${key}`, type: 'set_relationship',
            severity: Math.abs(score) >= 50 ? 'warning' : 'suggestion',
            title: `${a.name} & ${b.name}: ${label}`,
            detail: `${score > 0 ? '+' : ''}${score}${reason ? ` — ${reason}` : ''}`,
            patch: { a: a.id, b: b.id, label, score, reason }
        });
    });

    (Array.isArray(payload?.places) ? payload.places : []).forEach(entry => {
        const location = locations.get(String(entry?.id || ''));
        if (!location) return;
        if (location.danger != null && location.danger !== '') return;   // already described
        const hasDanger = Number.isFinite(Number(entry?.danger));
        const hasProsperity = Number.isFinite(Number(entry?.prosperity));
        const conditions = (Array.isArray(entry?.conditions) ? entry.conditions : [])
            .map(item => String(item || '').trim()).filter(Boolean).slice(0, 2);
        if (!hasDanger && !hasProsperity && !conditions.length) return;
        const danger = hasDanger ? livingClamp(Number(entry.danger), 0, 100) : 0;
        const prosperity = hasProsperity ? livingClamp(Number(entry.prosperity), 0, 100) : 50;
        findings.push({
            tier: 'society', id: `place_${location.id}`, type: 'set_location_state',
            severity: danger >= 60 ? 'warning' : 'suggestion',
            title: `${location.name}: danger ${danger}, prosperity ${prosperity}`,
            detail: [conditions.join(', '), String(entry?.why || '').trim()].filter(Boolean).join(' — ')
                || 'Sets how the place reads before anything happens in it.',
            patch: { locationId: location.id, danger, prosperity, conditions }
        });
    });

    // A faction is proposed by name, since the model has no id to give.
    const existingNames = new Set((world.factions || []).map(faction =>
        String(faction.name || '').trim().toLowerCase()));
    // Factions proposed in an earlier batch of the same run. Without these, a
    // member found in batch 6 could not be joined to a guild proposed in
    // batch 5, because nothing is applied to the world until the author says so.
    const proposedFactions = carriedFactions instanceof Map
        || (carriedFactions && typeof carriedFactions.get === 'function'
            && typeof carriedFactions.set === 'function' && typeof carriedFactions.has === 'function')
        ? carriedFactions : new Map();
    (Array.isArray(payload?.factions) ? payload.factions : []).forEach(entry => {
        const name = String(entry?.name || '').trim().slice(0, 120);
        if (!name || existingNames.has(name.toLowerCase())) return;
        if (proposedFactions.has(name.toLowerCase())) return;
        const id = livingId('faction', name);
        proposedFactions.set(name.toLowerCase(), id);
        findings.push({
            tier: 'society', id: `faction_${id}`, type: 'add_faction', severity: 'suggestion',
            title: `New faction: ${name}`,
            detail: [String(entry?.goal || '').trim(), String(entry?.why || '').trim()]
                .filter(Boolean).join(' — ') || 'An organised power the fiction implies.',
            patch: {
                id, name,
                goal: String(entry?.goal || '').trim().slice(0, 240),
                influence: livingClamp(Number(entry?.influence) ?? 50, 0, 100),
                reputation: livingClamp(Number(entry?.reputation) || 0, -100, 100)
            }
        });
    });

    (Array.isArray(payload?.memberships) ? payload.memberships : []).forEach(entry => {
        const entity = npcs.get(String(entry?.entity || ''));
        if (!entity || entity.factionId) return;
        const ref = String(entry?.faction || '').trim();
        if (!ref) return;
        // The model may name a faction that exists, or one it has just proposed.
        const existing = (world.factions || []).find(faction =>
            faction.id === ref || String(faction.name || '').trim().toLowerCase() === ref.toLowerCase());
        const factionId = existing ? existing.id : proposedFactions.get(ref.toLowerCase());
        if (!factionId) return;
        findings.push({
            tier: 'society', id: `member_${entity.id}`, type: 'set_faction_membership', severity: 'suggestion',
            title: `${entity.name} serves ${existing ? existing.name : ref}`,
            detail: String(entry?.why || '').trim()
                || 'Membership is how a faction reaches a scene through the people in it.',
            // Applying a membership before its faction exists would dangle, so
            // the apply step re-checks that the faction is actually there.
            patch: { entityId: entity.id, factionId }
        });
    });

    return findings;
}

/**
 * Run one pass over the whole world, in as many calls as the world needs.
 *
 * A large world used to fail outright: everything went in one call, the reply
 * was cut off at the token limit, and the whole thing was discarded with an
 * error blaming the model — which had in fact been emitting correct JSON right
 * up to the cut. Batches are sized so an answer fits, a batch that fails does
 * not sink the ones that worked, and whatever was learned is returned.
 */
async function runCalibrationPass(world, pass, onProgress) {
    if (!CALIBRATION_PASSES[pass]) throw new Error(`Unknown calibration pass: ${pass}`);
    const batches = calibrationBatches(world, pass);
    if (!batches.length || !buildCalibrationPrompt(world, pass, batches[0])) {
        // A pass with nothing to ask about is a finished world, not a broken
        // one — saying "unknown pass" here sent the author looking for a bug.
        throw new Error(`Nothing left for the ${CALIBRATION_PASSES[pass].label} pass to settle — this world already states everything it looks at.`);
    }

    const findings = [];
    const failures = [];
    let cutShort = 0;
    // Carried across batches so a member found late can join a power that an
    // earlier batch proposed but the author has not applied yet.
    const carriedFactions = new Map();
    for (let index = 0; index < batches.length; index++) {
        if (typeof onProgress === 'function') onProgress(index, batches.length);
        try {
            const result = await runCalibrationBatch(world, pass, batches[index], carriedFactions);
            // Two batches can land on the same proposal — most obviously a
            // faction the fiction implies to both of them. The author should
            // review it once, not once per call.
            result.findings.forEach(finding => {
                if (findings.some(seen => seen.id === finding.id)) return;
                findings.push(finding);
            });
            if (result.truncated) cutShort++;
        } catch (error) {
            failures.push(error.message);
            console.warn(`Calibration ${pass} batch ${index + 1}/${batches.length} failed:`, error);
        }
    }
    // Every batch failed: there is nothing to show and a real problem to report.
    if (!findings.length && failures.length) throw new Error(failures[0]);
    return {
        findings,
        batches: batches.length,
        failed: failures.length,
        cutShort,
        // The caller says this out loud rather than silently returning less.
        note: [
            failures.length ? `${failures.length} of ${batches.length} batches failed` : '',
            cutShort ? `${cutShort} reply(s) were cut short and only their complete entries were kept` : ''
        ].filter(Boolean).join('; ')
    };
}

async function runCalibrationBatch(world, pass, batch, carriedFactions) {
    const prompt = buildCalibrationPrompt(world, pass, batch);
    if (!prompt) return { findings: [], truncated: false };
    const model = structuredModelFor(world);

    // Mirrors the shape the Deep Audit already proves works against real
    // providers: a system role AND a user turn (a system-only conversation
    // returns nothing on many models), a budget generous enough that reasoning
    // models still have room to emit visible output, and one strict retry.
    let truncated = false;
    const callPass = async (extraNudge, useJsonMode) => {
        const messages = [
            { role: 'system', content: prompt },
            { role: 'user', content: 'Calibrate the world above. Output the JSON object and nothing else — your first character must be {. Do not think out loud, restate the task, or explain your choices; put any reasoning in the per-item "why" fields.' }
        ];
        if (extraNudge) messages.push({ role: 'user', content: extraNudge });
        const body = {
            // Room for the whole batch's answer plus any prose a model insists
            // on. Most models in the picker report a 16k-32k output ceiling, so
            // this is well inside what they will actually allow — and batching
            // is what keeps a real answer under it.
            model,
            max_tokens: 16000,
            messages
        };
        // Constrained decoding where the provider supports it — the single most
        // reliable way to stop a model narrating its way past the token limit.
        if (useJsonMode) body.response_format = { type: 'json_object' };

        const response = await fetch(apiBase() + '/chat/completions', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', ...authHeaders(), ...attributionHeaders() },
            body: JSON.stringify(body)
        });
        if (!response.ok) {
            const errorText = (await response.json().catch(() => ({})))?.error?.message || response.statusText;
            // Not every model accepts json_object; fall back rather than fail.
            if (useJsonMode && /response_format|json_object|json mode|not support/i.test(String(errorText))) {
                console.warn('Horde Engine: model rejected JSON mode, retrying without it.');
                return callPass(extraNudge, false);
            }
            throw new Error(errorText);
        }
        const choice = (await response.json())?.choices?.[0] || {};
        const message = choice.message || {};
        if (choice.finish_reason === 'length') truncated = true;
        let text = message.content || '';
        if (Array.isArray(text)) text = text.map(part => part?.text || '').join(' ');
        // Some providers put everything in `reasoning` and leave content empty.
        if (!String(text).trim() && message.reasoning) text = String(message.reasoning);
        return String(text);
    };

    let raw = await callPass(null, true);
    let payload = parseCalibrationPayload(raw);
    if (!payload) {
        console.warn('Horde Engine: calibration reply unparseable, retrying strict. Raw reply was:\n', raw.slice(0, 2000));
        raw = await callPass('[SYSTEM: Your previous reply was prose, not JSON. Do not restate the task or reason in the open. Reply NOW with ONLY the JSON object — no commentary, no markdown fences. Your very first character must be {.]', true);
        payload = parseCalibrationPayload(raw);
    }
    if (!payload) {
        console.error('Horde Engine: calibration failed. Full raw reply:\n', raw);
        const preview = raw.replace(/\s+/g, ' ').trim().slice(0, 200);
        // Distinguish the two failures honestly. A reply that STARTED as JSON
        // and ran out of room is our fault for asking too much — telling the
        // author to change model sent them chasing something that was working.
        if (truncated && /^\s*[{[]/.test(raw)) {
            throw new Error(`The reply was cut off before a single complete entry (it began: "${preview}…"). This world needs smaller batches — please report it, because the batch size should already have prevented this.`);
        }
        if (truncated) {
            throw new Error(`The model spent its whole budget on prose and never reached the JSON${preview ? ` (it began: "${preview}…")` : ''}. Pick a non-reasoning model in the list above.`);
        }
        throw new Error(preview
            ? `The model replied but not with JSON. It said: "${preview}${raw.length > 200 ? '…' : ''}"`
            : 'The model returned an empty reply (its budget was probably consumed by hidden reasoning).');
    }
    const wasCutShort = payload.__truncated === true;
    delete payload.__truncated;
    const findings = pass === 'people' ? calibrationFindingsFromPeople(world, payload)
        : pass === 'items' ? calibrationFindingsFromItems(world, payload)
        : pass === 'society' ? calibrationFindingsFromSociety(world, payload, carriedFactions)
        : calibrationFindingsFromStructure(world, payload);
    return { findings, truncated: wasCutShort };
}

// parseWorldAgentPayload insists on engine state keys, which a calibration
// reply does not have — so calibration needs its own tolerant reader.
function parseCalibrationPayload(raw) {
    let text = String(raw || '').trim();
    if (!text) return null;
    // Visible chain-of-thought wrappers first: the JSON we want is after them,
    // and braces inside the thinking would otherwise capture the scan.
    text = text.replace(/<(think|thinking|reasoning|analysis)>[\s\S]*?<\/\1>/gi, ' ').trim();

    // Every key any pass can return. The Society pass answers with
    // relationships/places/factions/memberships, none of which were listed
    // here — so a complete, perfectly valid Society reply was rejected as
    // unusable and reported as a model failure. It could never have worked.
    const PAYLOAD_KEYS = ['locations', 'travel', 'people', 'items',
        'relationships', 'places', 'factions', 'memberships'];
    const usable = value => value && typeof value === 'object' && !Array.isArray(value)
        && PAYLOAD_KEYS.some(key => Array.isArray(value[key]));
    const tryParse = candidate => {
        try {
            const parsed = JSON.parse(candidate);
            return usable(parsed) ? parsed : null;
        } catch (error) { return null; }
    };

    const tagged = text.match(/<calibration_json>\s*([\s\S]*?)\s*<\/calibration_json>/i);
    if (tagged) {
        const hit = tryParse(tagged[1]);
        if (hit) return hit;
    }
    for (const fence of text.matchAll(/```(?:json)?\s*([\s\S]*?)```/gi)) {
        const hit = tryParse(fence[1]);
        if (hit) return hit;
    }
    // Scan every balanced object in the reply, string-aware, so prose with
    // braces before or after the payload cannot derail it.
    for (let start = text.indexOf('{'); start >= 0; start = text.indexOf('{', start + 1)) {
        let depth = 0;
        let quote = null;
        let escaped = false;
        for (let i = start; i < text.length; i++) {
            const char = text[i];
            if (quote) {
                if (escaped) escaped = false;
                else if (char === '\\') escaped = true;
                else if (char === quote) quote = null;
                continue;
            }
            if (char === '"') { quote = char; continue; }
            if (char === '{') depth++;
            else if (char === '}' && --depth === 0) {
                const hit = tryParse(text.slice(start, i + 1));
                if (hit) return hit;
                break;
            }
        }
    }
    // Nothing closed: the reply was cut off mid-object. Everything the model
    // finished is still good work — throwing it away and reporting a failure
    // wastes a paid call and tells the author their model is broken when it
    // was answering correctly right up to the cut.
    return salvageTruncatedPayload(text, usable);
}

/**
 * Recover the complete entries from a reply that stopped mid-flight.
 *
 * Walks the text keeping track of the last position at which every open array
 * had just finished an element, rewinds to it, and closes what is still open.
 * A partial trailing object is discarded rather than guessed at.
 */
function salvageTruncatedPayload(text, usable) {
    const start = text.indexOf('{');
    if (start < 0) return null;
    const stack = [];
    let quote = null;
    let escaped = false;
    let lastGood = -1;

    for (let i = start; i < text.length; i++) {
        const char = text[i];
        if (quote) {
            if (escaped) escaped = false;
            else if (char === '\\') escaped = true;
            else if (char === quote) quote = null;
            continue;
        }
        if (char === '"') { quote = char; continue; }
        if (char === '{' || char === '[') { stack.push(char); continue; }
        if (char === '}' || char === ']') {
            stack.pop();
            // An element of an array just closed: everything up to here is
            // whole, so this is a safe place to cut.
            if (stack[stack.length - 1] === '[') lastGood = i;
            continue;
        }
        // A comma directly inside an array also marks a clean boundary.
        if (char === ',' && stack[stack.length - 1] === '[') lastGood = i - 1;
    }
    if (lastGood < 0) return null;

    // Rebuild the closers for whatever was still open at the cut.
    const head = text.slice(start, lastGood + 1);
    const open = [];
    let q = null, esc = false;
    for (let i = 0; i < head.length; i++) {
        const char = head[i];
        if (q) {
            if (esc) esc = false;
            else if (char === '\\') esc = true;
            else if (char === q) q = null;
            continue;
        }
        if (char === '"') { q = char; continue; }
        if (char === '{' || char === '[') open.push(char);
        else if (char === '}' || char === ']') open.pop();
    }
    const closed = head + open.reverse().map(char => (char === '[' ? ']' : '}')).join('');
    try {
        const parsed = JSON.parse(closed);
        if (!usable(parsed)) return null;
        parsed.__truncated = true;   // so the caller can say so honestly
        return parsed;
    } catch (error) {
        return null;
    }
}

// A pass costs an API call, so its proposals must outlive a re-render of the
// audit panel. Applying one finding used to rebuild the panel and destroy the
// rest of the list, forcing another paid run to get them back.
let calibrationPassState = null;   // { worldId, findings, applied:Set<number>, dismissed:Set<number> }
let worldMigrationPreviewState = null; // { worldId, sourceVersion, result }

function downloadLegacyWorldBackup(world) {
    if (!world) return;
    const backup = safeJsonClone(world);
    backup._format = 'horde-world';
    backup._version = 2;
    backup._migrationBackup = {
        createdAt: new Date().toISOString(),
        schemaVersion: worldSchemaVersion(world),
        targetSchemaVersion: WORLD_SCHEMA_VERSION
    };
    const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `${String(world.name || 'world').replace(/[^a-z0-9_-]+/gi, '_')}_pre_upgrade.horde_world`;
    anchor.click();
    URL.revokeObjectURL(url);
    showToast('Pre-upgrade world backup downloaded.', 'success');
}

function normalizeMigratedWorldInstance(world, instance) {
    if (!isPlainObject(instance)) return instance;
    const canonical = value => getLocationRef(world, value)?.id || value;
    (Array.isArray(instance.sessions) ? instance.sessions : []).forEach(session => {
        if (!isPlainObject(session)) return;
        session.playerLocation = canonical(session.playerLocation);
        (Array.isArray(session.scheduledEvents) ? session.scheduledEvents : []).forEach(event => {
            if (event?.locationId) event.locationId = canonical(event.locationId);
        });
        Object.values(isPlainObject(session.npcScheduleOverrides) ? session.npcScheduleOverrides : {}).forEach(override => {
            if (override?.locationId) override.locationId = canonical(override.locationId);
        });
        if (isPlainObject(session.locationStates)) {
            const canonicalStates = {};
            Object.entries(session.locationStates).forEach(([key, value]) => {
                canonicalStates[canonical(key)] = value;
            });
            session.locationStates = canonicalStates;
        }
    });
    return instance;
}

function worldMigrationPreview(world) {
    if (!world) return null;
    if (worldMigrationPreviewState?.worldId === world.id
        && worldMigrationPreviewState?.sourceVersion === worldSchemaVersion(world)) {
        return worldMigrationPreviewState.result;
    }
    try {
        const result = upgradeWorldSchemaData(world, { source: 'world-audit-preview' });
        worldMigrationPreviewState = { worldId: world.id, sourceVersion: worldSchemaVersion(world), result };
        return result;
    } catch (error) {
        return { error };
    }
}

function renderWorldMigrationSection(world) {
    const version = worldSchemaVersion(world);
    const current = version >= WORLD_SCHEMA_VERSION;
    const history = Array.isArray(world.migrationHistory) ? world.migrationHistory.at(-1) : null;
    if (current) {
        return `<div class="world-migration-card current">
            <div class="world-migration-icon">✓</div>
            <div><span class="vh-eyebrow">WORLD SCHEMA ${WORLD_SCHEMA_VERSION}</span><h3>Current world format</h3>
            <p>${escapeHTML(WORLD_SCHEMA_LABEL)}${history?.migratedAt ? ` · upgraded ${escapeHTML(new Date(history.migratedAt).toLocaleDateString())}` : ''}</p></div>
        </div>`;
    }
    const result = worldMigrationPreview(world);
    if (result?.error) {
        return `<div class="world-migration-card blocked"><div class="world-migration-icon">!</div><div>
            <span class="vh-eyebrow">LEGACY WORLD</span><h3>Upgrade preview could not be built</h3>
            <p>${escapeHTML(result.error.message || 'This world contains invalid legacy data.')}</p></div></div>`;
    }
    const changed = (result?.changes || []).reduce((sum, item) => sum + Math.max(1, Number(item.count) || 1), 0);
    return `<section class="world-migration-card legacy" aria-labelledby="world-migration-title">
        <div class="world-migration-icon">↥</div>
        <div class="world-migration-content">
            <span class="vh-eyebrow">LEGACY WORLD · SCHEMA ${version || 'UNVERSIONED'}</span>
            <h3 id="world-migration-title">Upgrade to the new world directory</h3>
            <p>A transactional migration creates canonical regions, rooms, travel links, People, Items and Groups. Ambiguous geography is reported, never guessed.</p>
            <div class="world-migration-summary">
                ${(result?.changes || []).length ? result.changes.map(item => `<span><b>${item.count || 1}</b> ${escapeHTML(item.area)}<small>${escapeHTML(item.detail)}</small></span>`).join('') : '<span><b>0</b> structural rewrites<small>The schema receipt and validation gate will still be added.</small></span>'}
            </div>
            ${(result?.warnings || []).length ? `<details class="world-migration-warnings"><summary>${result.warnings.length} decision${result.warnings.length === 1 ? '' : 's'} still need your review</summary>${result.warnings.map(item => `<p><b>${escapeHTML(item.area)}:</b> ${escapeHTML(item.detail)}</p>`).join('')}</details>` : ''}
            <div class="world-migration-actions">
                <button id="world-migration-backup-btn" class="btn btn-ghost" type="button">Download original</button>
                <button id="world-migration-apply-btn" class="btn btn-primary" type="button">Upgrade &amp; save${changed ? ` · ${changed} changes` : ''}</button>
            </div>
            <p class="form-hint">The new world is validated before it replaces anything. If validation or saving fails, Horde Studio restores the original automatically.</p>
        </div>
    </section>`;
}

function wireWorldMigrationControls(world) {
    const backupButton = document.getElementById('world-migration-backup-btn');
    if (backupButton) backupButton.onclick = () => downloadLegacyWorldBackup(world);
    const applyButton = document.getElementById('world-migration-apply-btn');
    if (!applyButton) return;
    applyButton.onclick = async () => {
        const result = worldMigrationPreview(world);
        if (!result || result.error) return showToast(result?.error?.message || 'Upgrade preview failed.', 'error');
        if (!confirm(`Upgrade “${world.name || 'this world'}” to schema ${WORLD_SCHEMA_VERSION}? Downloading the original first is recommended.`)) return;
        applyButton.disabled = true;
        applyButton.textContent = 'Upgrading…';
        const worldIndex = state.worlds.findIndex(entry => entry.id === world.id);
        const previousStored = worldIndex >= 0 ? safeJsonClone(state.worlds[worldIndex]) : null;
        const previousDraft = safeJsonClone(state.editingWorld);
        const previousInstance = state.worldInstances?.[world.id] ? safeJsonClone(state.worldInstances[world.id]) : null;
        const previousWorldMediaDirty = worldMediaDirty;
        try {
            const migrated = safeJsonClone(result.world);
            validateWorldData(migrated, 'Migrated world');
            state.editingWorld = migrated;
            if (worldIndex >= 0) state.worlds[worldIndex] = safeJsonClone(migrated);
            else state.worlds.push(safeJsonClone(migrated));
            if (state.worldInstances?.[world.id]) normalizeMigratedWorldInstance(migrated, state.worldInstances[world.id]);
            worldMigrationPreviewState = null;
            worldMediaDirty = true;
            await saveState();
            renderWorldStudio();
            renderWorldAudit();
            showToast(`World upgraded safely to schema ${WORLD_SCHEMA_VERSION}.`, 'success');
        } catch (error) {
            console.error('World migration rolled back:', error);
            state.editingWorld = previousDraft;
            if (worldIndex >= 0 && previousStored) state.worlds[worldIndex] = previousStored;
            else state.worlds = state.worlds.filter(entry => entry.id !== world.id);
            if (previousInstance) state.worldInstances[world.id] = previousInstance;
            else if (state.worldInstances) delete state.worldInstances[world.id];
            worldMediaDirty = previousWorldMediaDirty;
            worldMigrationPreviewState = null;
            // saveState writes several IndexedDB records. If an unexpected
            // storage error happened after one write, persist the restored
            // snapshot as a best-effort compensating transaction so a reload
            // cannot expose a half-applied migration.
            try { await saveState(); }
            catch (rollbackError) { console.error('World migration rollback could not be persisted:', rollbackError); }
            renderWorldStudio();
            renderWorldAudit();
            showToast(`Upgrade rolled back: ${error.message || 'validation failed'}`, 'error');
        }
    };
}

// Handlers are attached here rather than inline, because the page's CSP blocks
// inline event attributes outright.
function wireCalibrationControls(world, calibration, container) {
    if (!container) return;

    // The structured-model choice is a tooling preference, not world content,
    // so it saves immediately rather than waiting on Save World.
    const picker = container.querySelector('#structured-model-picker');
    const custom = container.querySelector('#structured-model-custom');
    if (picker && custom) {
        const commit = async (value) => {
            state.globalSettings.structuredModel = String(value || '').trim().slice(0, 200);
            try { await saveState(); } catch (error) { console.error('Could not save model choice', error); }
            showToast(state.globalSettings.structuredModel
                ? `Audits will use ${state.globalSettings.structuredModel}`
                : "Audits will use this world's own model", 'info');
        };
        picker.onchange = () => { custom.value = picker.value; commit(picker.value); };
        custom.onchange = () => {
            const value = custom.value.trim();
            picker.value = [...picker.options].some(option => option.value === value) ? value : '';
            commit(value);
        };

        // Populated from the live catalog rather than a list written by hand,
        // which is how a retired model id ended up being offered as a
        // suggestion and failed with "No endpoints found".
        const status = container.querySelector('#structured-model-status');
        const refresh = container.querySelector('#structured-model-refresh');
        const fallbackLabel = world.model || state.globalSettings.defaultModel || 'unset';
        const populate = async (force) => {
            if (force) { openRouterModels = []; modelCatalogSource = null; openRouterPresetCache = null; }
            if (status) status.textContent = 'Checking which models can do this…';
            let ranked = [];
            try {
                ranked = rankStructuredModels(await getOpenRouterModels());
            } catch (error) {
                console.error('Could not read the model catalog', error);
            }
            const chosen = String(state.globalSettings.structuredModel || '').trim();
            picker.innerHTML =
                `<option value="">Use this world's model (${escapeHTML(fallbackLabel)})</option>`
                + ranked.map(model =>
                    `<option value="${escapeHTML(model.id)}" ${chosen === model.id ? 'selected' : ''}>${escapeHTML(model.id)} — ${escapeHTML(model.note)}</option>`).join('')
                // A model the author typed, or picked before the catalog moved,
                // stays selectable rather than silently resetting to blank.
                + (chosen && !ranked.some(model => model.id === chosen)
                    ? `<option value="${escapeHTML(chosen)}" selected>${escapeHTML(chosen)} (typed)</option>` : '');
            if (!status) return;
            status.textContent = ranked.length
                ? `${ranked.length} models offered, cheapest first — live from ${isLocalProvider() ? 'your local server' : cloudProviderName()}, so nothing here is a stale id.`
                : `Could not reach the ${isLocalProvider() ? 'local' : cloudProviderName()} catalog. Type a model id above, or press Refresh once you are online.`;
        };
        if (refresh) refresh.onclick = () => populate(true);
        populate(false);
    }
    // The Studio edits a draft copy of the world; every other repair in this
    // panel writes to that draft and leaves persistence to Save World. Doing
    // anything else here would either be lost or would bypass the author's
    // chance to undo by simply not saving.
    const persist = (appliedCount, label) => {
        if (!appliedCount) {
            showToast('Nothing changed — that repair was already in place.', 'info');
            return;
        }
        showToast(`${label} — remember to Save World.`, 'success');
        renderWorldAudit();          // recompute: applied findings should vanish
        renderWorldStudio();         // exits and settings may have changed
    };

    const applyAll = container.querySelector('#calibrate-apply-all-btn');
    if (applyAll) {
        applyAll.onclick = () => {
            const applied = calibration.reduce((count, finding) =>
                count + (applyCalibrationFinding(world, finding) ? 1 : 0), 0);
            persist(applied, `Calibrated: ${applied} repair${applied === 1 ? '' : 's'} applied.`);
        };
    }

    container.querySelectorAll('.calibrate-one-btn').forEach(button => {
        button.onclick = () => {
            const finding = calibration[Number(button.dataset.index)];
            if (!finding) return;
            persist(applyCalibrationFinding(world, finding) ? 1 : 0, `Applied: ${finding.title}`);
        };
    });

    const passResults = container.querySelector('#calibrate-pass-results');
    if (!passResults) return;

    // Restore the proposals from the last run, so re-rendering the panel (which
    // happens on every apply) never costs the author another call.
    if (calibrationPassState && calibrationPassState.worldId === world.id) {
        renderCalibrationPassFindings(world, passResults);
    }

    container.querySelectorAll('.calibrate-pass-run').forEach(passButton => {
        const pass = passButton.dataset.pass;
        passButton.onclick = async () => {
            if (!hasApiCredentials()) return showToast('API Key missing (Settings).', 'error');
            container.querySelectorAll('.calibrate-pass-run').forEach(other => { other.disabled = true; });
            passButton.textContent = '⏳ Working...';
            passResults.innerHTML = `<div style="color:var(--text-3); font-size:0.85rem;">Reading the world for the ${escapeHTML(CALIBRATION_PASSES[pass]?.label || pass)} pass...</div>`;
            try {
                // A big world takes several calls, so say which one is running
                // rather than leaving the author watching a frozen spinner.
                const result = await runCalibrationPass(world, pass, (done, total) => {
                    passResults.innerHTML = `<div style="color:var(--text-3); font-size:0.85rem;">Reading the world for the ${escapeHTML(CALIBRATION_PASSES[pass]?.label || pass)} pass — batch ${done + 1} of ${total}...</div>`;
                });
                calibrationPassState = {
                    worldId: world.id, pass, findings: result.findings,
                    applied: new Set(), dismissed: new Set(), note: result.note
                };
                renderCalibrationPassFindings(world, passResults);
            } catch (error) {
                console.error('Calibration pass failed', error);
                calibrationPassState = null;
                passResults.innerHTML = `<div style="color:var(--red); font-size:0.85rem;">${escapeHTML(error.message || 'The pass failed.')} Nothing was changed — you can run it again.</div>`;
            } finally {
                container.querySelectorAll('.calibrate-pass-run').forEach(other => { other.disabled = false; });
                passButton.textContent = 'Run';
            }
        };
    });
}

function renderCalibrationPassFindings(world, host) {
    const state = calibrationPassState;
    if (!host || !state || state.worldId !== world.id) return;
    const findings = Array.isArray(state.findings) ? state.findings : [];
    const applied = state.applied instanceof Set ? state.applied : (state.applied = new Set());
    const dismissed = state.dismissed instanceof Set ? state.dismissed : (state.dismissed = new Set());
    if (!findings.length) {
        host.innerHTML = `<div style="color:var(--text-3); font-size:0.85rem;">Nothing to add — this world already says everything the ${escapeHTML(String(CALIBRATION_PASSES[state.pass]?.label || state.pass).toLowerCase())} pass looks for.</div>`;
        return;
    }
    const sevStyle = { critical: 'var(--red)', warning: 'var(--warning, #F4A261)', suggestion: 'var(--text-3)' };
    const remainingIndexes = findings.map((_, index) => index)
        .filter(index => !applied.has(index) && !dismissed.has(index));
    const remaining = remainingIndexes.length;
    host.innerHTML = `
        <div class="calibration-proposal-head">
            <strong>${escapeHTML(CALIBRATION_PASSES[state.pass]?.label || '')} — ${remaining} open · ${applied.size} applied · ${dismissed.size} dismissed${state.note ? ` · ${escapeHTML(state.note)}` : ''}</strong>
            <div class="calibration-proposal-actions">
                ${remaining ? `<button id="calibrate-pass-apply-all" class="btn btn-primary">Apply remaining</button>
                    <button id="calibrate-pass-dismiss-all" class="btn btn-ghost">Dismiss remaining</button>` : ''}
                <button id="calibrate-pass-clear" class="btn btn-ghost">Clear proposals</button>
            </div>
        </div>
        <div style="display:flex; flex-direction:column; gap:6px;">
            ${remainingIndexes.length ? remainingIndexes.map(index => {
                const finding = findings[index];
                return `<div class="calibration-proposal" style="border-left-color:${sevStyle[finding.severity] || 'var(--text-3)'};">
                    <div style="flex:1;">
                        <div style="font-weight:bold;">${escapeHTML(finding.title)}</div>
                        <div style="color:var(--text-3); margin-top:2px;">${escapeHTML(finding.detail)}</div>
                    </div>
                    <div class="calibration-proposal-actions">
                        <button class="btn btn-ghost calibrate-pass-dismiss" data-index="${index}">Dismiss</button>
                        <button class="btn btn-primary calibrate-pass-one" data-index="${index}">Apply</button>
                    </div>
                </div>`;
            }).join('') : '<div class="form-hint">No open proposals. Clear this result or run another pass.</div>'}
        </div>`;

    // Re-render the panel so Tier 0 reflects the change, then put these
    // proposals straight back — they are paid for and must not vanish.
    const afterApply = (count) => {
        showToast(count
            ? `Applied ${count} change${count === 1 ? '' : 's'} — remember to Save World.`
            : 'That proposal was already represented, so it was closed without changing the world.', count ? 'success' : 'info');
        renderWorldAudit();
        renderWorldStudio();
    };

    const applyAll = host.querySelector('#calibrate-pass-apply-all');
    if (applyAll) {
        applyAll.onclick = () => {
            let count = 0;
            remainingIndexes.forEach(index => {
                const finding = findings[index];
                if (applyCalibrationFinding(world, finding)) count++;
                applied.add(index);   // mark either way: it is no longer outstanding
            });
            afterApply(count);
        };
    }
    host.querySelectorAll('.calibrate-pass-one').forEach(button => {
        button.onclick = () => {
            const index = Number(button.dataset.index);
            const changed = applyCalibrationFinding(world, findings[index]) ? 1 : 0;
            applied.add(index);
            afterApply(changed);
        };
    });
    host.querySelectorAll('.calibrate-pass-dismiss').forEach(button => {
        button.onclick = () => {
            dismissed.add(Number(button.dataset.index));
            renderCalibrationPassFindings(world, host);
        };
    });
    const dismissAll = host.querySelector('#calibrate-pass-dismiss-all');
    if (dismissAll) dismissAll.onclick = () => {
        remainingIndexes.forEach(index => dismissed.add(index));
        renderCalibrationPassFindings(world, host);
        showToast(`Dismissed ${remainingIndexes.length} proposal${remainingIndexes.length === 1 ? '' : 's'}.`, 'info');
    };
    const clear = host.querySelector('#calibrate-pass-clear');
    if (clear) clear.onclick = () => {
        calibrationPassState = null;
        host.innerHTML = '<div class="form-hint">Proposals cleared. Run a pass whenever you want a fresh set.</div>';
    };
}

function simulateWorldAutonomyHealth(world, days = 7) {
    const horizon = Math.max(1, Math.min(30, parseInt(days) || 7));
    const findings = [];
    const npcIds = new Set((world.entities || []).filter(entity => entity.type === 'npc').map(entity => entity.id));
    const locationIds = new Set((world.locations || []).map(location => location.id));
    let evaluatedMoves = 0;
    let impossibleMoves = 0;
    let repeatedBeats = 0;
    let missingKnowledge = 0;
    let eventCollisions = 0;

    (world.entities || []).filter(entity => entity.type === 'npc').forEach(npc => {
        const schedule = (Array.isArray(npc.schedule) ? npc.schedule : [])
            .map(block => ({ ...block, locationId: getLocationRef(world, block.locationId || block.location)?.id || '' }))
            .filter(block => block.locationId).sort((a, b) => String(a.time || '').localeCompare(String(b.time || '')));
        for (let day = 0; day < horizon; day++) {
            for (let index = 1; index < schedule.length; index++) {
                evaluatedMoves++;
                const from = schedule[index - 1];
                const to = schedule[index];
                if (from.locationId === to.locationId) continue;
                const path = findWorldTravelPath(world, from.locationId, to.locationId);
                if (!path?.length) impossibleMoves++;
            }
        }
        const beats = (npc.goalSteps || []).map(step => String(step || '').trim().toLowerCase()).filter(Boolean);
        repeatedBeats += beats.length - new Set(beats).size;
        if (!(npc.persona || npc.description)) missingKnowledge++;
    });

    const scheduled = (world.scheduledEvents || []).map(event => `${event.dueTurn ?? ''}|${event.dueMinute ?? ''}|${event.locationId || ''}|${event.title || ''}`);
    eventCollisions = scheduled.length - new Set(scheduled).size;
    if (impossibleMoves) findings.push({ severity: 'critical', text: `${impossibleMoves} of ${evaluatedMoves} simulated schedule transitions have no travel path.` });
    if (repeatedBeats) findings.push({ severity: 'warning', text: `${repeatedBeats} repeated NPC agenda beats may create echoing off-screen updates.` });
    if (missingKnowledge) findings.push({ severity: 'warning', text: `${missingKnowledge} NPCs lack enough authored identity for stable behavior.` });
    if (eventCollisions) findings.push({ severity: 'warning', text: `${eventCollisions} scheduled events are exact duplicates.` });
    const directory = worldDirectoryHealth(world);
    directory.issues.slice(0, 8).forEach(issue => findings.push({
        severity: issue.area === 'Travel' || issue.area === 'Hierarchy' ? 'critical' : 'warning',
        text: `${issue.count} ${issue.area.toLowerCase()} record(s) ${issue.detail}.`
    }));
    const score = Math.max(0, Math.min(100, 100
        - impossibleMoves * 8 - repeatedBeats * 3 - missingKnowledge * 2 - eventCollisions * 4
        - Math.max(0, 100 - directory.score) * 0.35));
    return {
        days: horizon,
        score: Math.round(score),
        findings,
        stats: {
            npcs: npcIds.size,
            locations: locationIds.size,
            scheduleTransitions: evaluatedMoves,
            providerCalls: 0,
            impossibleMoves
        }
    };
}

function renderWorldAutonomyHealthResult(world, host) {
    const report = simulateWorldAutonomyHealth(world, 7);
    host.innerHTML = `<div class="world-health-card" style="margin-top:12px;">
        <div class="world-health-score"><strong>${report.score}</strong><span>/100</span></div>
        <div><h3>7-day autonomy forecast</h3>
        <p>${report.stats.npcs} people · ${report.stats.locations} places · ${report.stats.scheduleTransitions} schedule transitions · ${report.stats.providerCalls} model calls</p>
        ${report.findings.length ? `<div class="world-health-gaps">${report.findings.map(item =>
            `<span><b>${item.severity === 'critical' ? '!' : '•'}</b> ${escapeHTML(item.text)}</span>`).join('')}</div>`
            : '<p class="world-health-complete">No spam loops, impossible travel, duplicate events or major directory gaps were detected.</p>'}
        <p class="form-hint">This is a deterministic dry run. It never edits the world, spends credits or calls a model.</p></div>
    </div>`;
}

function renderWorldAudit() {
    const world = state.editingWorld;
    const container = document.getElementById('audit-results-container');
    if (!world || !container) return;

    const report = validateWorldReferences(world);
    const lint = buildWorldLintReport(world);
    const directoryHealth = worldDirectoryHealth(world);

    const sevStyle = { critical: 'var(--red)', warning: 'var(--warning, #F4A261)', suggestion: 'var(--text-3)' };
    const lintHtml = lint.length ? `
        <div style="margin:20px 0 10px;"><h3>Structural Lint (${lint.length})</h3></div>
        <div style="display:flex; flex-direction:column; gap:8px;">
            ${lint.map(f => `
                <div style="background:var(--surface2); padding:10px 12px; border-radius:8px; border-left:4px solid ${sevStyle[f.sev]}; font-size:0.82rem;">
                    <span class="mini-tag" style="margin-right:8px;">${escapeHTML(f.area)}</span>${escapeHTML(f.msg)}
                </div>`).join('')}
        </div>` : '';

    // One model for every structured pass. Narration and JSON want opposite
    // models, and picking the wrong one here is what made calibration, the
    // chronicle classifier and the world turn all fail the same way.
    const activeStructured = String(state.globalSettings.structuredModel || '').trim();
    const structuredSection = `
        <div style="background:var(--surface2); padding:12px 14px; border-radius:10px; margin-bottom:18px; border:1px solid var(--border);">
            <div style="display:flex; justify-content:space-between; align-items:center; gap:10px;">
                <label class="form-label" style="margin:0;">🧮 Model for audits &amp; calibration</label>
                <button id="structured-model-refresh" class="btn btn-ghost" style="font-size:0.68rem; padding:3px 9px; white-space:nowrap;">↻ Refresh list</button>
            </div>
            <p class="form-hint" style="margin:4px 0 8px;">Used by the Deep Audit, every calibration pass, the chronicle classifier and the World Agent — but never for narration. The list is pulled live from your selected provider and shows only models that report being able to return JSON and are not reasoning models — those spend their whole budget thinking and return nothing usable. Cheapest first. Leave blank to use this world's own model.</p>
            <div style="display:flex; gap:8px; flex-wrap:wrap;">
                <select id="structured-model-picker" class="form-select" style="flex:1; min-width:200px;">
                    <option value="">Loading provider models…</option>
                </select>
                <input type="text" id="structured-model-custom" class="form-input" style="flex:1; min-width:200px;"
                       placeholder="…or type any OpenRouter model id" value="${escapeHTML(activeStructured)}">
            </div>
            <div class="form-hint" id="structured-model-status" style="margin-top:6px;">Checking which models can do this…</div>
        </div>`;

    // Calibration: everything the engine can repair on its own, with no API
    // call. Shown before the AI audit because it costs nothing and fixes the
    // faults that stop a world working at all.
    const calibration = calibrateStructuralFindings(world, getAllPresets().find(p => p.id === world.activePresetId));
    const directlyFixableTypes = new Set(['set_start_location', 'raise_context_size', 'add_reciprocal_exit', 'set_map_type', 'set_containment', 'set_floor', 'connect_location']);
    const fixable = calibration.filter(f => directlyFixableTypes.has(f.type));
    const directoryHealthHtml = `${renderWorldMigrationSection(world)}<div class="world-health-card">
        <div class="world-health-score"><strong>${directoryHealth.score}</strong><span>/100</span></div>
        <div><h3>Directory readiness</h3><p>${directoryHealth.counts.locations} locations · ${directoryHealth.counts.people} people · ${directoryHealth.counts.items} items · ${directoryHealth.counts.groups} groups</p>
        ${directoryHealth.issues.length ? `<div class="world-health-gaps">${directoryHealth.issues.map(issue => `<span><b>${issue.count}</b> ${escapeHTML(issue.area)} · ${escapeHTML(issue.detail)}</span>`).join('')}</div>` : '<p class="world-health-complete">Every new-format directory field is represented.</p>'}</div>
    </div>`;
    const calibrationSection = `
        <div style="margin-top:24px; padding-top:16px; border-top:1px solid var(--border);">
            <div style="display:flex; justify-content:space-between; align-items:center; gap:10px;">
                <div>
                    <h3 style="margin:0;">🎛️ Calibrate World</h3>
                    <p class="form-hint" style="margin:4px 0 0;">No API call. Repairs deterministic engine facts and reports new-directory gaps across locations, people, groups and items. Nothing changes until you apply it.</p>
                </div>
                ${fixable.length ? `<button id="calibrate-apply-all-btn" class="btn btn-primary" style="white-space:nowrap;">Apply ${fixable.length} fix${fixable.length === 1 ? '' : 'es'}</button>` : ''}
            </div>
            ${calibration.length ? `
                <details class="world-audit-findings" ${calibration.length <= 8 ? 'open' : ''}>
                    <summary>Review ${calibration.length} deterministic finding${calibration.length === 1 ? '' : 's'}</summary>
                <div style="display:flex; flex-direction:column; gap:8px; margin-top:12px; max-height:min(52vh,620px); overflow:auto; padding-right:4px;">
                    ${calibration.map((f, index) => `
                        <div style="background:var(--surface2); padding:10px 12px; border-radius:8px; border-left:4px solid ${sevStyle[f.severity] || 'var(--text-3)'}; font-size:0.82rem; display:flex; gap:10px; align-items:flex-start;">
                            <div style="flex:1;">
                                <div style="font-weight:bold;">${escapeHTML(f.title)}</div>
                                <div style="color:var(--text-3); margin-top:2px;">${escapeHTML(f.detail)}</div>
                            </div>
                            ${directlyFixableTypes.has(f.type)
                                ? `<button class="btn btn-ghost calibrate-one-btn" data-index="${index}" style="font-size:0.7rem; padding:4px 8px; white-space:nowrap;">Apply</button>`
                                : `<span class="mini-tag" style="white-space:nowrap;">needs your call</span>`}
                        </div>`).join('')}
                </div></details>`
            : `<div style="margin-top:12px; color:var(--text-3); font-size:0.85rem;">Nothing to repair — this world's structure is already sound.</div>`}

            <div style="margin-top:18px; padding-top:14px; border-top:1px dashed var(--border);">
                ${Object.entries(CALIBRATION_PASSES).map(([key, pass]) => `
                    <div style="display:flex; justify-content:space-between; align-items:center; gap:10px; margin-bottom:10px;">
                        <div>
                            <strong style="font-size:0.9rem;">✨ ${escapeHTML(pass.label)} pass <span class="mini-tag">batched</span></strong>
                            <p class="form-hint" style="margin:4px 0 0;">${escapeHTML(pass.blurb)} Fills only what this world has not already said, and proposes everything for review first.</p>
                        </div>
                        <button class="btn btn-ghost calibrate-pass-run" data-pass="${escapeHTML(key)}" style="white-space:nowrap;">Run</button>
                    </div>`).join('')}
                <div id="calibrate-pass-results" style="margin-top:12px;"></div>
            </div>
        </div>`;

    const autonomySection = `
        <div style="margin-top:24px; padding-top:16px; border-top:1px solid var(--border);">
            <div style="display:flex; justify-content:space-between; align-items:center; gap:10px;">
                <div><h3 style="margin:0;">🫀 Autonomy Health</h3>
                <p class="form-hint" style="margin:4px 0 0;">Fast-forward seven days without changing canon. Checks schedule travel, repetition, identity gaps, event collisions and directory integrity.</p></div>
                <button id="run-autonomy-health-btn" class="btn btn-ghost" style="white-space:nowrap;">Simulate 7 days</button>
            </div>
            <div id="autonomy-health-results"></div>
        </div>`;

    const aiSection = `
        <div style="margin-top:24px; padding-top:16px; border-top:1px solid var(--border);">
            <div style="display:flex; justify-content:space-between; align-items:center; gap:10px;">
                <div>
                    <h3 style="margin:0;">🤖 AI Deep Audit</h3>
                    <p class="form-hint" style="margin:4px 0 0;">A QA agent reads the complete world directory for semantic problems the lint can't see: geography, containment, travel, people, starting lives, lore and contradictions. Large worlds are safely audited in indexed batches. Each finding is proposed for review—nothing changes without your click.</p>
                </div>
                <button id="run-ai-audit-btn" class="btn btn-primary" style="white-space:nowrap;">✨ Run</button>
            </div>
            <div id="ai-audit-results" style="margin-top:14px;"></div>
        </div>`;

    if (report.broken.length === 0 && lint.length === 0) {
        container.innerHTML = `
            <div style="text-align:center; padding:20px;">
                <div style="font-size:3rem; margin-bottom:15px;">✅</div>
                <h3>Structure is Healthy</h3>
                <p style="color:var(--text-3);">All references linked, every room reachable, every secret complete.</p>
            </div>${directoryHealthHtml}${structuredSection}${calibrationSection}${autonomySection}${aiSection}`;
        const btn = document.getElementById('run-ai-audit-btn');
        if (btn) btn.onclick = runAIWorldAudit;
        wireWorldMigrationControls(world);
        wireCalibrationControls(world, calibration, container);
        document.getElementById('run-autonomy-health-btn')?.addEventListener('click', () =>
            renderWorldAutonomyHealthResult(world, document.getElementById('autonomy-health-results')));
        return;
    }

    container.innerHTML = `
        ${directoryHealthHtml}
        ${structuredSection}
        ${report.broken.length > 0 ? `
        <div style="margin-bottom:20px;">
            <h3 style="color:var(--red);">Broken References Found (${report.broken.length})</h3>
            <p class="form-hint">These are items that point to locations that don't exist (possibly due to typos or deletions).</p>
        </div>` : ''}
        <div style="display:flex; flex-direction:column; gap:12px;">
            ${report.broken.map(item => {
                const suggestion = report.suggestions[item.ref];
                return `
                    <div style="background:var(--surface2); padding:12px; border-radius:8px; border-left:4px solid var(--red);">
                        <div style="font-size:0.75rem; color:var(--text-3); text-transform:uppercase; font-weight:bold;">${escapeHTML(item.source)}</div>
                        <div style="margin:8px 0; font-family:monospace; background:rgba(255,0,0,0.1); padding:4px 8px; border-radius:4px;">
                            Invalid Reference: "${escapeHTML(item.ref)}"
                        </div>
                        ${suggestion ? `
                            <div style="display:flex; justify-content:space-between; align-items:center; margin-top:8px;">
                                <div style="font-size:0.8rem;">Suggest fixing to: <span style="color:var(--accent); font-weight:bold;">${escapeHTML(suggestion)}</span></div>
                                <button class="btn btn-ghost fix-ref-btn" data-old="${escapeHTML(item.ref)}" data-new="${escapeHTML(suggestion)}" style="font-size:0.7rem; padding:4px 8px;">Apply Fix</button>
                            </div>
                        ` : '<div style="font-size:0.8rem; color:var(--text-3);">No matching location found. Please fix manually.</div>'}
                    </div>
                `;
            }).join('')}
        </div>
        ${lintHtml}
        ${calibrationSection}
        ${autonomySection}
        ${aiSection}
    `;

    const aiBtn = document.getElementById('run-ai-audit-btn');
    if (aiBtn) aiBtn.onclick = runAIWorldAudit;
    wireWorldMigrationControls(world);
    wireCalibrationControls(world, calibration, container);
    document.getElementById('run-autonomy-health-btn')?.addEventListener('click', () =>
        renderWorldAutonomyHealthResult(world, document.getElementById('autonomy-health-results')));

    container.querySelectorAll('.fix-ref-btn').forEach(btn => {
        btn.onclick = () => {
            const oldRef = btn.dataset.old;
            const newRef = btn.dataset.new;
            
            // Apply fix globally
            world.entities.forEach(ent => {
                if (ent.startLocation === oldRef) ent.startLocation = newRef;
                if (ent.homeLocation === oldRef) ent.homeLocation = newRef;
                (ent.schedule || []).forEach(s => {
                    if (s.locationId === oldRef) s.locationId = newRef;
                });
            });
            world.locations.forEach(loc => {
                loc.exits = (loc.exits || []).map(ex => {
                    if (typeof ex === 'string') {
                        return ex.replace(new RegExp(oldRef, 'gi'), newRef);
                    } else if (ex.text) {
                        ex.text = ex.text.replace(new RegExp(oldRef, 'gi'), newRef);
                    }
                    return ex;
                });
            });

            showToast('Reference repaired!', 'success');
            renderWorldAudit();
            renderWorldStudio(); // Refresh studio to show valid states
        };
    });
}

/**
 * 🤖 AI DEEP AUDIT — a QA agent that reads the whole world for semantic
 * problems the deterministic lint can't see. Every finding renders as a card;
 * fixes only apply on explicit click, and only to whitelisted fields.
 */
const AI_AUDIT_FIELD_WHITELIST = {
    region: ['name', 'description'],
    location: ['name', 'description', 'hiddenDescription', 'region', 'regionId', 'parentLocationId', 'mapType', 'mapFloor'],
    entity: ['name', 'description', 'persona', 'homeLocation', 'startLocation', 'goal'],
    group: ['name', 'description', 'homeLocationId'],
    lore: ['keyword', 'text'],
    world: ['description', 'dmPrompt', 'authorNote', 'intro'],
    secret: ['label', 'hint', 'truth']
};

function serializeWorldForAudit(world) {
    const clip = (s, n = 2400) => (s || '').slice(0, n);
    return JSON.stringify({
        name: world.name,
        description: clip(world.description, 6000),
        dmPrompt: clip(world.dmPrompt, 12000),
        authorNote: clip(world.authorNote, 6000),
        intro: clip(world.intro, 6000),
        startLocationId: world.startLocationId,
        regions: (world.regions || []).map(region => ({
            id: region.id, name: region.name, description: clip(region.description), tags: region.tags || []
        })),
        locations: (world.locations || []).map(l => ({
            id: l.id, name: l.name, regionId: l.regionId, region: l.region,
            mapType: l.mapType, parentLocationId: l.parentLocationId, floor: l.mapFloor, tags: l.tags || [],
            description: clip(l.description), hiddenDescription: clip(l.hiddenDescription),
            exits: (l.exits || []).map(ex => typeof ex === 'string' ? { text: ex } : ({
                text: ex.text, targetLocationId: ex.targetLocationId,
                transport: ex.mode, minutes: ex.travelTime, route: ex.routeName,
                cost: ex.cost, oneWay: ex.isOneWay === true
            })),
            secrets: (l.secrets || []).map(s => ({ label: s.label, hint: clip(s.hint, 200), truth: clip(s.truth, 200) }))
        })),
        entities: (world.entities || []).map(e => ({
            id: e.id, name: e.name, type: e.type, simulationDepth: e.simulationDepth,
            description: clip(e.description), persona: clip(e.persona, 6000), tags: e.tags || [],
            homeLocation: e.homeLocation, startLocation: e.startLocation,
            groupIds: e.groupIds || [], goal: clip(e.goal), schedule: e.schedule || [],
            secrets: (e.secrets || []).map(s => ({ label: s.label, hint: clip(s.hint, 200), truth: clip(s.truth, 200) }))
        })),
        groups: (world.groups || []).map(group => ({
            id: group.id, name: group.name, type: group.type, homeLocationId: group.homeLocationId,
            description: clip(group.description), tags: group.tags || []
        })),
        factions: world.factions || [],
        relationships: world.relationships || [],
        startingLives: world.startingLives || [],
        lorebook: (world.lorebook || []).map(l => ({ keyword: l.keyword, text: clip(l.text, 6000) })),
        rules: world.rules || world.gameRules || {},
        hudConfig: world.hudConfig || {}
    });
}

function buildWorldAuditPayloads(world) {
    const full = serializeWorldForAudit(world);
    const contextTokens = Math.max(8192, Number(world?.contextSize) || 32768);
    const safeChars = Math.max(18000, (contextTokens - 6500) * 3);
    if (full.length <= safeChars) return [full];
    const index = JSON.stringify({
        world: world.name,
        regions: (world.regions || []).map(item => ({ id: item.id, name: item.name })),
        locations: (world.locations || []).map(item => ({ id: item.id, name: item.name, regionId: item.regionId, parentLocationId: item.parentLocationId, mapType: item.mapType })),
        entities: (world.entities || []).map(item => ({ id: item.id, name: item.name, type: item.type, homeLocation: item.homeLocation, startLocation: item.startLocation, groupIds: item.groupIds || [] })),
        groups: (world.groups || []).map(item => ({ id: item.id, name: item.name, homeLocationId: item.homeLocationId }))
    });
    const locations = world.locations || [];
    const entities = world.entities || [];
    const lorebook = world.lorebook || [];
    const size = 35;
    const count = Math.max(Math.ceil(locations.length / size), Math.ceil(entities.length / size), Math.ceil(lorebook.length / size), 1);
    return Array.from({ length: count }, (_, batch) => {
        const slice = {
            ...world,
            locations: locations.slice(batch * size, (batch + 1) * size),
            entities: entities.slice(batch * size, (batch + 1) * size),
            lorebook: lorebook.slice(batch * size, (batch + 1) * size)
        };
        return `CANONICAL WHOLE-WORLD INDEX (use this to validate links across batches):\n${index}\n\nDETAILED BATCH ${batch + 1}/${count}:\n${serializeWorldForAudit(slice)}`;
    });
}

/** Tolerant parse: models wrap JSON in prose/fences or lead with reasoning. */
function parseAuditFindings(raw) {
    if (!raw || !raw.trim()) throw new Error('empty response');
    const attempts = [];
    attempts.push(raw);
    const anchor = raw.indexOf('{"findings"');
    if (anchor !== -1) attempts.push(raw.slice(anchor));
    const fence = raw.match(/```(?:json)?([\s\S]*?)```/i);
    if (fence) attempts.push(fence[1]);
    for (const candidate of attempts) {
        try {
            const p = extractJSON(candidate);
            if (Array.isArray(p)) return p;
            if (p && Array.isArray(p.findings)) return p.findings;
        } catch (e) { /* try next strategy */ }
        // Bare top-level array (extractJSON only hunts for {...})
        try {
            const a = candidate.indexOf('['), b = candidate.lastIndexOf(']');
            if (a !== -1 && b > a) {
                const p = JSON.parse(candidate.slice(a, b + 1));
                if (Array.isArray(p)) return p;
            }
        } catch (e) { /* try next strategy */ }
    }
    throw new Error('The model did not return parseable JSON.');
}

async function runAIWorldAudit() {
    const world = state.editingWorld;
    const btn = document.getElementById('run-ai-audit-btn');
    const results = document.getElementById('ai-audit-results');
    if (!world || !results) return;
    if (!hasApiCredentials()) return showToast('API Key missing (Settings).', 'error');

    btn.disabled = true;
    btn.textContent = '⏳ Auditing...';
    results.innerHTML = '<div style="text-align:center; padding:16px; color:var(--text-3);">The QA agent is reading your world...</div>';

    // Reasoning models (DeepSeek Pro etc.) sometimes burn the budget on hidden
    // thinking or wrap JSON in prose. Attempt, then one strict retry.
    const callAudit = async (payload, extraNudge) => {
        const messages = [
                    { role: 'system', content: `You are a meticulous whole-world QA agent for a persistent roleplay simulation. Read every supplied directory—not just prose—and audit INTERNAL problems only:
- Misplaced info: content in the wrong field (exit lists inside descriptions, personality text in physical descriptions, DM-only secrets leaked into player-visible description)
- Geography and containment: regions must be broad geographic areas; buildings are locations in regions; rooms/floors are child locations whose parentLocationId points to their containing building. Flag buildings incorrectly modeled as regions, orphan rooms, cycles, impossible containment and region/parent disagreements
- Travel: every route must connect real locations, use a positive plausible duration and preserve its author-defined transport (horse, dragon, train, portal, etc.). Never assume a modern setting
- People and society: homes, schedules, groups, factions, relationships and starting lives must resolve to canonical IDs and agree with one another
- Rules and starts: starting lives, starting location, capabilities, HUD/rules and intro must describe compatible initial facts
- Lorebook: keywords that don't match their entry text; entries contradicting locations/NPCs/other lore
- Secrets: hints that spoil their own truth; truths contradicting established world facts
- Contradictions between any two elements (geography, names, timeline, tone vs dmPrompt)
- Descriptions that contradict the location's actual exits
- Leftover placeholder text ("TODO", "xxx", lorem)
Do NOT invent new content beyond minimal corrections. Do NOT flag stylistic preferences. If the world is clean, return an empty findings array.
Return ONLY JSON:
{"findings":[{"severity":"critical|warning|suggestion","issue":"<one sentence>","target_type":"region|location|entity|group|lore|world|secret","target_id":"<canonical id, lore keyword, or owner id for secrets>","secret_label":"<secrets only>","field":"<field to change>","new_value":"<full corrected scalar field value — ONLY when a safe fix exists, else omit>","fix_description":"<what the author should do>"}]}` },
                    { role: 'user', content: `Audit this world:\n\n${payload}` }
        ];
        if (extraNudge) messages.push({ role: 'user', content: extraNudge });
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), 10 * 60 * 1000);
        const response = await fetch(apiBase() + '/chat/completions', {
            method: 'POST',
            signal: controller.signal,
            headers: { 'Content-Type': 'application/json', ...authHeaders() },
            body: JSON.stringify({
                model: structuredModelFor(world),
                max_tokens: 4000, // reasoning models eat budget before emitting content
                messages
            })
        }).finally(() => clearTimeout(timeout));
        if (!response.ok) throw new Error((await response.json().catch(() => ({}))).error?.message || response.statusText);
        const msg = (await response.json()).choices?.[0]?.message;
        return msg?.content || '';
    };

    try {
        const payloads = buildWorldAuditPayloads(world);
        let findings = [];
        for (let index = 0; index < payloads.length; index += 1) {
            results.innerHTML = `<div style="text-align:center; padding:16px; color:var(--text-3);">Reading world section ${index + 1} of ${payloads.length}…</div>`;
            let batchFindings;
            try {
                batchFindings = parseAuditFindings(await callAudit(payloads[index], null));
            } catch (firstErr) {
                console.warn(`AI Audit section ${index + 1} unparseable — retrying strict:`, firstErr.message);
                results.innerHTML = `<div style="text-align:center; padding:16px; color:var(--text-3);">Section ${index + 1} returned malformed output — repairing it once…</div>`;
                batchFindings = parseAuditFindings(await callAudit(payloads[index],
                    '[SYSTEM: Your previous reply contained no parseable JSON. Respond NOW with ONLY the JSON object — no markdown fences, commentary or reasoning. Begin exactly with {"findings":['));
            }
            findings.push(...batchFindings);
        }
        findings = findings.filter((finding, index, list) => index === list.findIndex(other =>
            `${other.issue}|${other.target_type}|${other.target_id}|${other.field}` === `${finding.issue}|${finding.target_type}|${finding.target_id}|${finding.field}`));

        if (!findings.length) {
            results.innerHTML = '<div style="text-align:center; padding:16px;">✅ <b>The agent found no semantic issues.</b></div>';
            return;
        }

        const sevStyle = { critical: 'var(--red)', warning: 'var(--warning, #F4A261)', suggestion: 'var(--text-3)' };
        results.innerHTML = `<div style="display:flex; flex-direction:column; gap:10px;">${findings.map((f, i) => `
            <div style="background:var(--surface2); padding:12px; border-radius:8px; border-left:4px solid ${sevStyle[f.severity] || sevStyle.suggestion};">
                <div style="font-size:0.7rem; color:var(--text-3); text-transform:uppercase; font-weight:bold; margin-bottom:4px;">
                    ${escapeHTML(f.severity || 'note')} · ${escapeHTML(f.target_type || '')} ${escapeHTML(f.target_id || '')}${f.secret_label ? ` / ${escapeHTML(f.secret_label)}` : ''}
                </div>
                <div style="font-size:0.85rem; margin-bottom:6px;">${escapeHTML(f.issue || '')}</div>
                <div style="font-size:0.78rem; color:var(--text-2);">💡 ${escapeHTML(f.fix_description || 'No suggestion')}</div>
                ${f.new_value && f.field ? `
                    <div style="margin-top:8px; display:flex; gap:8px; align-items:flex-start;">
                        <div style="flex:1; font-size:0.75rem; font-family:monospace; background:var(--bg); padding:6px 8px; border-radius:6px; max-height:80px; overflow-y:auto;">${escapeHTML(String(f.new_value).slice(0, 400))}</div>
                        <button class="btn btn-ghost ai-fix-btn" data-idx="${i}" style="font-size:0.72rem; white-space:nowrap;">✅ Apply</button>
                    </div>` : ''}
            </div>`).join('')}</div>`;

        results.querySelectorAll('.ai-fix-btn').forEach(fixBtn => {
            fixBtn.onclick = () => {
                const f = findings[parseInt(fixBtn.dataset.idx)];
                if (applyAIWorldFix(world, f)) {
                    fixBtn.disabled = true;
                    fixBtn.textContent = '✔ Applied';
                    renderWorldStudio();
                    updateWorldTokenCount();
                    showToast('Fix applied — remember to Save World.', 'success');
                } else {
                    showToast('Could not apply: target or field not found/allowed.', 'error');
                }
            };
        });
    } catch (err) {
        results.innerHTML = `<div style="color:var(--red); font-size:0.85rem;">Audit failed after retry: ${escapeHTML(err.message)}<br>
            <span style="color:var(--text-3);">Reasoning-heavy models sometimes can't produce structured output — try again, or temporarily set a non-reasoning model on this world for the audit.</span></div>`;
    } finally {
        btn.disabled = false;
        btn.textContent = '✨ Run';
    }
}

/** Apply one AI finding — whitelisted fields only, target must resolve. */
function applyAIWorldFix(world, f) {
    if (!f || !f.field || f.new_value === undefined) return false;
    const allowed = AI_AUDIT_FIELD_WHITELIST[f.target_type];
    if (!allowed || !allowed.includes(f.field)) return false;
    const val = String(f.new_value);

    if (f.target_type === 'world') { world[f.field] = val; openWorldStudio(); return true; }
    if (f.target_type === 'region') {
        const region = (world.regions || []).find(item => item.id === f.target_id);
        if (!region) return false;
        region[f.field] = val;
        if (f.field === 'name') (world.locations || []).forEach(location => {
            if (location.regionId === region.id) location.region = val;
        });
        return true;
    }
    if (f.target_type === 'location') {
        const loc = world.locations.find(l => l.id === f.target_id) || findFuzzyLocation(f.target_id, world.locations);
        if (!loc) return false;
        if (f.field === 'regionId' && val && !(world.regions || []).some(region => region.id === val)) return false;
        if (f.field === 'parentLocationId') {
            const parent = getLocationRef(world, val);
            if (val && (!parent || parent.id === loc.id || (parent.regionId && loc.regionId && parent.regionId !== loc.regionId))) return false;
        }
        if (f.field === 'mapType' && !['transit', 'route', 'building', 'outdoor', 'room', 'area'].includes(val)) return false;
        loc[f.field] = val; return true;
    }
    if (f.target_type === 'entity') {
        const id = resolveNpcId(world, f.target_id);
        const ent = world.entities.find(e => e.id === (id || f.target_id));
        if (!ent) return false;
        if (['homeLocation', 'startLocation'].includes(f.field) && val && !getLocationRef(world, val)) return false;
        ent[f.field] = val; return true;
    }
    if (f.target_type === 'group') {
        const group = (world.groups || []).find(item => item.id === f.target_id);
        if (!group) return false;
        if (f.field === 'homeLocationId' && val && !getLocationRef(world, val)) return false;
        group[f.field] = val; return true;
    }
    if (f.target_type === 'lore') {
        const entry = (world.lorebook || []).find(l => (l.keyword || '').toLowerCase() === (f.target_id || '').toLowerCase());
        if (!entry) return false;
        entry[f.field] = val; return true;
    }
    if (f.target_type === 'secret') {
        const owner = world.locations.find(l => l.id === f.target_id)
            || world.entities.find(e => e.id === f.target_id)
            || findFuzzyLocation(f.target_id, world.locations);
        const secret = owner && (owner.secrets || []).find(s => s.label === f.secret_label);
        if (!secret) return false;
        secret[f.field] = val; return true;
    }
    return false;
}

/**
 * Epistemic Isolation Filter: Redacts whispers or private text addressed to other characters
 */
function redactPrivateWhispers(text, targetCharName, otherNames) {
    if (!text || !otherNames || otherNames.length === 0) return text;
    
    let redacted = text;
    otherNames.forEach(name => {
        if (!name || name.trim().toLowerCase() === targetCharName.trim().toLowerCase()) return;
        
        const escapedName = name.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
        
        // Pattern 1: Match standard whispers introduces, supporting any text inside the asterisks (e.g. privately, ing)
        const whisperActionPattern = new RegExp(`(\\*[^\\*]*whisper[^\\*]*to\\s+${escapedName}[^\\*]*\\*\\s*)([^\\*\\r\\n]+)`, 'gi');
        
        // Pattern 2: *private to Name* ... or *privately to Name* ...
        const privateActionPattern = new RegExp(`(\\*[^\\*]*private(?:ly)?\\s+to\\s+${escapedName}[^\\*]*\\*\\s*)([^\\*\\r\\n]+)`, 'gi');
        
        // Pattern 3: (to Name) ... or [to Name] ...
        const parenthesesPattern = new RegExp(`((\\(|\\[)to\\s+${escapedName}(\\)|\\])\\s*)([^\\r\\n]+)`, 'gi');

        // Apply redacting replacements
        redacted = redacted.replace(whisperActionPattern, (match, prefix, dialogue) => {
            const trailingSpace = dialogue.match(/\s+$/) ? ' ' : '';
            return `${prefix}(You observe them whispering privately, but are unable to hear)${trailingSpace}`;
        });
        redacted = redacted.replace(privateActionPattern, (match, prefix, dialogue) => {
            const trailingSpace = dialogue.match(/\s+$/) ? ' ' : '';
            return `${prefix}(You observe them whispering privately, but are unable to hear)${trailingSpace}`;
        });
        redacted = redacted.replace(parenthesesPattern, (match, prefix, dialogue) => {
            const trailingSpace = dialogue.match(/\s+$/) ? ' ' : '';
            return `${prefix}(whispering privately - inaudible)${trailingSpace}`;
        });
    });
    
    return redacted;
}

/**
 * Returns the canonical text of a message, accounting for reroll versions.
 * World messages keep canon in versions[currentVersion]; chat uses content.
 */
function canonicalMsgText(m) {
    if (!m) return '';
    if (Array.isArray(m.versions) && m.versions.length > 0) {
        const idx = (m.currentVersion !== undefined && m.currentVersion >= 0) ? m.currentVersion : m.versions.length - 1;
        return m.versions[idx] || m.text || m.content || '';
    }
    return m.content || m.text || '';
}

/**
 * Ghost-cleanup for chat mode: when a message that contributed a [MEMORY]
 * chronicle line is rerolled or deleted, remove that line from the session
 * ledger so abandoned events can't bleed back into context.
 */
function stripChatLedgerEntry(session, msg) {
    if (!session || !msg || !msg.ledgerEntry || !session.ledger) return;
    const targetKey = worldLedgerEntryKey(msg.ledgerEntry);
    const history = Array.isArray(session.messages) ? session.messages : (Array.isArray(session.history) ? session.history : []);
    const stillCanonicalElsewhere = history.some(other =>
        other !== msg && other?.ledgerEntry && worldLedgerEntryKey(other.ledgerEntry) === targetKey);
    if (stillCanonicalElsewhere) return;
    session.ledger = session.ledger
        .split('\n')
        .filter(line => worldLedgerEntryKey(line) !== targetKey)
        .join('\n')
        .trim();
    session.ledgerRevision = (Number(session.ledgerRevision) || 0) + 1;
}

/**
 * Invalidate episodic memories that cover message `msgIndex` or any later message.
 * Called when a message is edited, rerolled, or deleted so summaries built from
 * now-stale ("non-canon") text are dropped and the region is rebuilt on the next
 * consolidation pass. Also self-heals lastConsolidatedIndex drift after deletes,
 * since the rewound region re-consolidates against the current message array.
 */
// Memory epoch: bumped whenever history/state is rewritten (reroll, edit,
// delete, snapshot restore). In-flight background consolidations check it
// before committing, so a summary of an abandoned take can never land on
// restored state after the fact.
function bumpMemoryEpoch(session) {
    if (session) session._memEpoch = (session._memEpoch || 0) + 1;
}

function invalidateEpisodicFrom(session, msgIndex) {
    bumpMemoryEpoch(session);
    if (!session) return false;

    let rewindTo = session.lastConsolidatedIndex || 0;
    let droppedAny = false;
    const kept = [];

    for (const m of (session.episodicMemories || [])) {
        const start = (m.startIndex ?? 0);
        const end = (m.endIndex ?? Infinity); // exclusive
        // Memory is stale if its coverage includes msgIndex or extends past it.
        if (end > msgIndex) {
            rewindTo = Math.min(rewindTo, start);
            droppedAny = true;
        } else {
            kept.push(m);
        }
    }

    if (droppedAny) {
        session.episodicMemories = kept;
    }

    // Chat v2 memories live in the continuity store, outside the transcript.
    // Remove every derived record whose provenance touches the rewritten tail.
    const continuity = state.chatContinuities?.[session.continuityId];
    if (continuity && Array.isArray(continuity.records)) {
        const invalidMessageIds = new Set((session.messages || []).slice(msgIndex).map(message => message.id).filter(Boolean));
        const before = continuity.records.length;
        continuity.records = continuity.records.filter(memory => {
            if (memory.sourceSessionId !== session.id) return true;
            const coveredByIndex = Number.isFinite(Number(memory.endIndex)) && Number(memory.endIndex) > msgIndex;
            const coveredById = (memory.sourceMessageIds || []).some(id => invalidMessageIds.has(id));
            if (!coveredByIndex && !coveredById) return true;
            rewindTo = Math.min(rewindTo, Number(memory.startIndex) || 0);
            return false;
        });
        if (continuity.records.length !== before) {
            droppedAny = true;
            continuity.updatedAt = Date.now();
            // If the removed record had superseded a prior state, restore the
            // newest surviving value for that key.
            const newestByKey = new Map();
            continuity.records.forEach(memory => {
                if (!memory.key || !['fact', 'relationship', 'state', 'thread'].includes(memory.type)) return;
                const key = `${memory.type}:${memory.key}`;
                const current = newestByKey.get(key);
                if (!current || Number(memory.updatedAt) > Number(current.updatedAt)) newestByKey.set(key, memory);
            });
            newestByKey.forEach(memory => {
                if (memory.status === 'superseded') memory.status = 'active';
            });
        }
    }

    if ((session.lastConsolidatedIndex || 0) > msgIndex || droppedAny) {
        session.lastConsolidatedIndex = Math.min(session.lastConsolidatedIndex || 0, rewindTo, msgIndex);
    }
    return droppedAny;
}

/**
 * Rolling Episodic Memory Consolidation (Background Dream Loop)
 * Unified support for Chat/Room Mode (messages) and World Mode (history).
 */
// Trim a possibly-truncated string back to its last complete sentence, so a
// budget-cut summary ends cleanly ("…owes the user.") instead of mid-word
// ("…relationship support—while"). Falls back to a clause boundary, then to an
// ellipsis, so we always store something readable.
function trimToLastSentence(text) {
    if (!text) return text;
    const t = text.trim();
    const lastEnd = Math.max(t.lastIndexOf('. '), t.lastIndexOf('! '), t.lastIndexOf('? '),
        t.endsWith('.') || t.endsWith('!') || t.endsWith('?') ? t.length - 1 : -1);
    if (lastEnd > 40) return t.slice(0, lastEnd + 1).trim();
    const lastClause = Math.max(t.lastIndexOf('; '), t.lastIndexOf(', '), t.lastIndexOf('—'));
    if (lastClause > 40) return t.slice(0, lastClause).trim() + '…';
    return t + '…';
}

const memoryConsolidationJobs = new WeakMap();

async function consolidateSessionEpisodicMemory(session, config) {
    if (!session) return;
    const existing = memoryConsolidationJobs.get(session);
    if (existing) return existing;
    const job = consolidateSessionEpisodicMemoryRun(session, config)
        .finally(() => memoryConsolidationJobs.delete(session));
    memoryConsolidationJobs.set(session, job);
    return job;
}

function parseStructuredChatMemory(rawText) {
    const raw = String(rawText || '').trim();
    const fenced = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
    const firstBrace = fenced.indexOf('{');
    const lastBrace = fenced.lastIndexOf('}');
    if (firstBrace >= 0 && lastBrace > firstBrace) {
        try {
            const parsed = JSON.parse(fenced.slice(firstBrace, lastBrace + 1));
            const summary = String(parsed.summary || '').trim();
            const memories = (Array.isArray(parsed.memories) ? parsed.memories : []).slice(0, 16)
                .filter(isPlainObject).map(memory => ({
                    type: CHAT_MEMORY_TYPES.has(memory.type) ? memory.type : 'fact',
                    key: String(memory.key || '').slice(0, 240),
                    text: String(memory.text || '').slice(0, 4000),
                    importance: memory.importance,
                    confidence: memory.confidence,
                    status: memory.status,
                    scope: memory.scope,
                    characterIds: memory.characterIds,
                    witnessedBy: memory.witnessedBy
                })).filter(memory => memory.text.trim());
            if (summary || memories.length) return { summary, memories };
        } catch (error) {
            console.warn('Structured memory JSON was invalid; preserving it as an episode.', error);
        }
    }
    return { summary: raw.replace(/^\[EPISODIC ARCHIVE\]:?\s*/i, ''), memories: [] };
}

async function consolidateSessionEpisodicMemoryRun(session, config) {
    if (!session) return;
    // Race guard: remember the epoch at read time; if a reroll/edit/restore
    // rewrites history while our API calls are in flight, we must not commit.
    const startEpoch = session._memEpoch || 0;

    const messages = session.messages || session.history;
    if (!messages || messages.length < 2) return;
    
    const lastIdx = session.lastConsolidatedIndex || 0;
    const currentLen = messages.length;
    
    // Consolidate in rolling chunks of 8 messages
    const CONSOLIDATION_CHUNK_SIZE = 8;
    if (currentLen - lastIdx < CONSOLIDATION_CHUNK_SIZE) return;
    
    if (!hasApiCredentials()) {
        console.warn('Consolidation: Skipping - API Key missing.');
        return;
    }
    
    // FIX 1: World sessions use config.title, not config.name
    const configName = config.name || config.title || 'Narrator';

    // Process the next sequential block of unconsolidated messages (up to 40 max)
    const MAX_SLICE = 40;
    const chunkEnd = Math.min(lastIdx + MAX_SLICE, currentLen);
    const slice = messages.slice(lastIdx, chunkEnd);
    const isChatMemory = Array.isArray(session.messages);
    if (isChatMemory) ensureChatMessageIds(session);
    
    console.log(`Consolidation: Archiving messages ${lastIdx}–${chunkEnd} (${slice.length} msgs)`);

    const sliceText = slice.map(m => {
        if (m.role === 'system') return null; // skip injected system blocks
        let prefix = 'Participant';
        if (m.role === 'user') {
            prefix = 'User';
        } else if (m.role === 'assistant' || m.role === 'dm') {
            prefix = configName;
            if (m.charId) {
                const char = state.characters.find(c => c.id === m.charId);
                if (char) prefix = char.name;
            }
        }
        const content = (canonicalMsgText(m)).trim();
        return content ? `${prefix}: ${content}` : null;
    }).filter(Boolean).join('\n\n');

    if (!sliceText) {
        session.lastConsolidatedIndex = chunkEnd;
        return;
    }
    
    try {
        // FIX 3: Use a dedicated fast model — never the character's full model
        // A flash-tier model is sufficient and avoids context limit / cost issues
        const consolidationModel = state.globalSettings?.consolidationModel
            || (isLocalProvider() ? state.globalSettings.defaultModel : 'google/gemini-flash-1.5-8b');

        const response = await fetch(apiBase() + '/chat/completions', {
            method: 'POST',
            headers: {
                ...authHeaders(),
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                model: consolidationModel,
                max_tokens: isChatMemory ? 1100 : 500,
                messages: [
                    {
                        role: 'system',
                        content: isChatMemory ? `You are Horde Chronos, a precise long-term memory archivist for roleplay.
Return ONLY valid JSON with this shape:
{"summary":"2-4 factual sentences describing the scene","memories":[{"type":"fact|relationship|state|thread","key":"stable_subject:attribute","text":"one atomic durable fact","importance":0.0,"confidence":0.0,"status":"active|resolved|disputed","scope":"timeline|relationship|canon","characterIds":["names or ids"],"witnessedBy":["names or ids"]}]}
Record only durable changes: decisions, promises, relationships, discoveries, secrets, injuries, possessions, locations, goals, identities, and unresolved threads. Each memory must contain one fact. Use the same key when a newer fact replaces an older state. Mark concluded threads resolved. Distinguish narrator canon from what characters personally witnessed. Do not invent details and do not include ordinary banter or transient mood.`
                            : `You are "Horde Chronos" — a narrative memory archivist.
Summarize the roleplay segment below in AT MOST 3 short sentences (roughly 60 words). Capture only the key events, decisions, secrets revealed, and status changes. Third person, factual, no embellishment. Finish every sentence — never trail off.
Begin your response with: [EPISODIC ARCHIVE]:`
                    },
                    { role: 'user', content: `Roleplay segment:\n\n${sliceText}` }
                ]
            })
        });

        if (!response.ok) {
            const errBody = await response.text();
            throw new Error(`Consolidation API ${response.status}: ${errBody.slice(0, 200)}`);
        }

        const data = await response.json();
        let rawMemory = data.choices?.[0]?.message?.content?.trim();
        if (!rawMemory) throw new Error('Consolidation model returned empty content');
        const extracted = isChatMemory ? parseStructuredChatMemory(rawMemory) : { summary: rawMemory, memories: [] };
        let summary = extracted.summary || rawMemory;

        // Safety net: if the model still overran the budget, trim to the last
        // COMPLETE sentence so we never archive a mid-word fragment like "…while".
        if (data.choices?.[0]?.finish_reason === 'length') {
            summary = trimToLastSentence(summary);
        }
        
        console.log(`Consolidation OK: ${summary.slice(0, 100)}...`);
        
        // Stamp the covered message range so this memory can be invalidated if
        // any of its source messages are later edited, rerolled, or deleted.
        // Commit gate: history was rewritten while we were summarizing —
        // this summary describes an abandoned take. Discard it.
        if ((session._memEpoch || 0) !== startEpoch) {
            console.warn('Consolidation aborted: history changed during archiving (reroll/edit) — summary discarded.');
            return;
        }

        let totalMemories = 0;
        let pendingEmbeddings = [];
        if (isChatMemory) {
            const continuity = ensureChatContinuity(session, config?.id || chatOwnerId());
            const sourceMessageIds = slice.map(message => message.id).filter(Boolean);
            const participantIds = [...new Set(slice.map(message => message.charId).filter(Boolean))];
            const records = [{
                type: 'episode', key: `scene:${session.id}:${lastIdx}:${chunkEnd}`, text: summary,
                importance: 0.62, confidence: 0.9, scope: 'timeline', characterIds: participantIds,
                witnessedBy: participantIds
            }, ...extracted.memories];
            const inserted = upsertContinuityMemoryRecords(continuity, records, {
                sourceSessionId: session.id,
                sourceMessageIds,
                startIndex: lastIdx,
                endIndex: chunkEnd,
                personaId: state.activePersonaId || ''
            });
            pendingEmbeddings = inserted;
            totalMemories = continuity.records.filter(record => record.status !== 'superseded').length;
        } else {
            const embedding = await HordeVectorMemory.getCachedEmbedding(summary);
            session.episodicMemories = session.episodicMemories || [];
            session.episodicMemories.push({
                text: summary, embedding,
                embeddingNamespace: embedding ? HordeVectorMemory.namespace() : '',
                createdAt: Date.now(), startIndex: lastIdx, endIndex: chunkEnd
            });
            totalMemories = session.episodicMemories.length;
        }
        session.lastConsolidatedIndex = chunkEnd;

        await saveState();

        // Raw structured records are already durable. Vector enrichment is a
        // second phase, so closing the app or losing the embedding provider can
        // never erase the memory itself.
        if (pendingEmbeddings.length) {
            for (const record of pendingEmbeddings) {
                try { await hydrateChatMemoryEmbedding(record); }
                catch (error) { console.warn('Memory vector enrichment failed; hybrid text recall remains active.', error); }
            }
            await HordeDB.set('chatContinuities', state.chatContinuities);
        }

        // FIX 4: Visible feedback so you know it actually ran
        showToast(`🧠 Memory archived (${totalMemories} active)`, 'info');
        console.log(`Consolidation saved. Total active memories: ${totalMemories}`);
    } catch (e) {
        // Do NOT update lastConsolidatedIndex on failure — will retry next turn
        console.warn(`Consolidation failed (will retry next turn):`, e.message);
    }
}

/**
 * 🧠 VECTOR MEMORY INSPECTOR & PLAYGROUND ENGINE
 */
let currentVectorTab = 'episodic';
let currentEpisodicStore = null; // live array backing the episodic inspector tab

function setupVectorMemoryViewerEvents() {
    const openBtn = document.getElementById('open-vector-memory-btn');
    const worldOpenBtn = document.getElementById('world-open-vector-memory-btn');
    const closeBtn = document.getElementById('close-vector-memory-btn');
    const closeFtBtn = document.getElementById('close-vector-memory-ft-btn');
    const overlay = document.getElementById('vector-memory-modal-overlay');
    
    const tabEpisodic = document.getElementById('vector-tab-episodic');
    const tabBiography = document.getElementById('vector-tab-biography');
    
    const searchBtn = document.getElementById('vector-test-search-btn');
    const queryInput = document.getElementById('vector-test-query');

    if (openBtn) {
        openBtn.onclick = () => {
            currentVectorTab = 'episodic';
            overlay.classList.remove('hidden');
            updateVectorTabUI();
            renderVectorMemoryList();
        };
    }
    
    if (worldOpenBtn) {
        worldOpenBtn.onclick = () => {
            currentVectorTab = 'episodic';
            overlay.classList.remove('hidden');
            updateVectorTabUI();
            renderVectorMemoryList();
        };
    }
    
    const closeModal = () => {
        overlay.classList.add('hidden');
        if (queryInput) queryInput.value = '';
    };
    
    if (closeBtn) closeBtn.onclick = closeModal;
    if (closeFtBtn) closeFtBtn.onclick = closeModal;
    
    if (tabEpisodic) {
        tabEpisodic.onclick = () => {
            currentVectorTab = 'episodic';
            updateVectorTabUI();
            renderVectorMemoryList();
        };
    }
    
    if (tabBiography) {
        tabBiography.onclick = () => {
            currentVectorTab = 'biography';
            updateVectorTabUI();
            renderVectorMemoryList();
        };
    }
    
    if (searchBtn && queryInput) {
        searchBtn.onclick = () => {
            const val = queryInput.value.trim();
            renderVectorMemoryList(val);
        };
        
        queryInput.onkeydown = (e) => {
            if (e.key === 'Enter') {
                const val = queryInput.value.trim();
                renderVectorMemoryList(val);
            }
        };
    }

    // Force Archive Now — bypass 8-turn wait and immediately consolidate all history
    const forceArchiveBtn = document.getElementById('force-archive-now-btn');
    if (forceArchiveBtn) {
        forceArchiveBtn.onclick = async () => {
            forceArchiveBtn.disabled = true;
            forceArchiveBtn.textContent = '⏳ Archiving...';

            const isWorld = !document.getElementById('world-play-view').classList.contains('hidden');
            try {
                if (isWorld) {
                    const world = state.worlds.find(w => w.id === state.activeWorldId);
                    const sess = getCurrentWorldSession();
                    if (!sess || !world) throw new Error('No active world session');
                    // Full rebuild: clear stale memories and re-consolidate from scratch
                    // (otherwise we'd duplicate the entire archive on top of old entries).
                    sess.episodicMemories = [];
                    sess.lastConsolidatedIndex = 0;
                    while (sess.history.length - (sess.lastConsolidatedIndex || 0) >= 8) {
                        await consolidateSessionEpisodicMemory(sess, world);
                    }
                } else {
                    const session = getCurrentSession();
                    const config = state.characters.find(c => c.id === state.activeCharId)
                                || state.rooms.find(r => r.id === state.activeRoomId);
                    if (!session || !config) throw new Error('No active chat session');
                    // Full rebuild: clear stale memories and re-consolidate from scratch
                    // (otherwise we'd duplicate the entire archive on top of old entries).
                    session.episodicMemories = [];
                    const continuity = ensureChatContinuity(session, config.id);
                    continuity.records = continuity.records.filter(memory => memory.sourceSessionId !== session.id);
                    session.lastConsolidatedIndex = 0;
                    while (session.messages.length - (session.lastConsolidatedIndex || 0) >= 8) {
                        await consolidateSessionEpisodicMemory(session, config);
                    }
                }
                // Refresh the list
                renderVectorMemoryList();
            } catch (e) {
                showToast('Force archive failed: ' + e.message, 'error');
            } finally {
                forceArchiveBtn.disabled = false;
                forceArchiveBtn.textContent = '⚡ Force Archive Now';
            }
        };
    }
}

function updateVectorTabUI() {
    const tabEpisodic = document.getElementById('vector-tab-episodic');
    const tabBiography = document.getElementById('vector-tab-biography');
    
    if (currentVectorTab === 'episodic') {
        if (tabEpisodic) {
            tabEpisodic.style.color = 'var(--accent)';
            tabEpisodic.style.fontWeight = 'bold';
            tabEpisodic.style.borderBottom = '2px solid var(--accent)';
        }
        if (tabBiography) {
            tabBiography.style.color = 'var(--text-3)';
            tabBiography.style.fontWeight = 'normal';
            tabBiography.style.borderBottom = 'none';
        }
    } else {
        if (tabEpisodic) {
            tabEpisodic.style.color = 'var(--text-3)';
            tabEpisodic.style.fontWeight = 'normal';
            tabEpisodic.style.borderBottom = 'none';
        }
        if (tabBiography) {
            tabBiography.style.color = 'var(--accent)';
            tabBiography.style.fontWeight = 'bold';
            tabBiography.style.borderBottom = '2px solid var(--accent)';
        }
    }
}

async function renderVectorMemoryList(filterQuery = "") {
    const listContainer = document.getElementById('vector-memory-list');
    if (!listContainer) return;
    
    listContainer.innerHTML = `<div style="text-align:center; padding:20px; color:var(--text-3);">Loading memories...</div>`;
    
    const isWorld = !document.getElementById('world-play-view').classList.contains('hidden');
    let candidates = [];
    
    // Track the live array backing the episodic tab so cards can edit/delete entries
    currentEpisodicStore = null;
    if (currentVectorTab === 'episodic') {
        // Retrieve rolling episodic summaries
        if (isWorld) {
            const sess = getCurrentWorldSession();
            if (sess && sess.episodicMemories) {
                currentEpisodicStore = sess.episodicMemories;
                candidates = sess.episodicMemories.map(m => ({ text: m.text, embedding: m.embedding, source: 'episodic', ref: m }));
            }
        } else {
            const session = getCurrentSession();
            if (session) {
                const continuity = ensureChatContinuity(session, chatOwnerId());
                currentEpisodicStore = continuity.records;
                candidates = continuity.records.map(m => ({ ...m, source: 'continuity', ref: m }));
            }
        }
    } else {
        // Retrieve Biography & Lore memories
        if (isWorld) {
            const world = state.worlds.find(w => w.id === state.activeWorldId);
            const sess = getCurrentWorldSession();
            if (world && sess) {
                // Return all entities in current location
                const currentLocationId = sess.playerLocation;
                const loc = world.locations.find(l => l.id === currentLocationId);
                const npcs = sessionNpcs(world, sess).filter(e =>
                    sess.entityStates[e.id]?.location === currentLocationId && isNpcActive(sess.entityStates[e.id]));
                
                // Add loc and npcs as lore/bio sources
                if (loc && loc.description) {
                    candidates.push({ text: `[LOCATION: ${loc.name}] ${loc.description}`, source: 'biography' });
                }
                npcs.forEach(n => {
                    if (n.prompt) {
                        candidates.push({ text: `[NPC: ${n.name}] ${n.prompt}`, source: 'biography' });
                    }
                    if (n.memory) {
                        const memArray = Array.isArray(n.memory) ? n.memory : [];
                        memArray.forEach(m => {
                            candidates.push({ text: `[NPC MEMORY: ${n.name}] ${m.text || m}`, embedding: m.embedding, source: 'biography' });
                        });
                    }
                });
            }
        } else {
            const session = getCurrentSession();
            if (session) {
                const config = state.characters.find(c => c.id === state.activeCharId) || 
                               state.rooms.find(r => r.id === state.activeRoomId);
                if (config) {
                    if (state.activeRoomId) {
                        // Room Scenario Context
                        if (config.scenario) {
                            candidates.push({ text: `[ROOM SCENARIO] ${config.scenario}`, source: 'biography' });
                        }
                        // Room: collect all participant memories and bios
                        (config.characterIds || []).forEach(cid => {
                            const tc = state.characters.find(c => c.id === cid);
                            if (tc) {
                                if (tc.desc) {
                                    candidates.push({ text: `[${tc.name} DESCRIPTION] ${tc.desc}`, source: 'biography' });
                                }
                                if (tc.prompt) {
                                    candidates.push({ text: `[${tc.name} PROMPT] ${tc.prompt}`, source: 'biography' });
                                }
                                const memArray = Array.isArray(tc.memory) ? tc.memory : [];
                                memArray.forEach(m => {
                                    candidates.push({ text: `[${tc.name} MEMORY] ${m.text || m}`, embedding: m.embedding, source: 'biography' });
                                });
                            }
                        });
                    } else {
                        // Solo Character Description & Prompt Context
                        if (config.desc) {
                            candidates.push({ text: `[CHARACTER DESCRIPTION] ${config.desc}`, source: 'biography' });
                        }
                        if (config.prompt) {
                            candidates.push({ text: `[CHARACTER PROMPT] ${config.prompt}`, source: 'biography' });
                        }
                        // Solo: collect character memory
                        const memArray = Array.isArray(config.memory) ? config.memory : [];
                        memArray.forEach(m => {
                            candidates.push({ text: m.text || m, embedding: m.embedding, source: 'biography' });
                        });
                    }
                }
            }
        }
    }
    
    if (candidates.length === 0) {
        listContainer.innerHTML = `<div style="text-align:center; padding:30px; color:var(--text-3); font-style:italic;">No vector memories indexed in this category yet. Summarize the chat or proceed with roleplay to generate them!</div>`;
        return;
    }
    
    let displayList = [];
    
    // If user typed a query, perform a similarity match or keyword fallback match!
    if (filterQuery) {
        listContainer.innerHTML = `<div style="text-align:center; padding:20px; color:var(--text-3);">Calculating cosine similarity scores...</div>`;
        
        try {
            // Check cache for candidates missing embeddings to be fast
            for (const cand of candidates) {
                if (!cand.embedding) {
                    const key = `${HordeVectorMemory.namespace()}|${HordeVectorMemory.hashText(cand.text)}`;
                    if (HordeVectorMemory.cache.has(key)) {
                        cand.embedding = HordeVectorMemory.cache.get(key);
                    }
                }
            }
            
            const queryVec = await HordeVectorMemory.getCachedEmbedding(filterQuery);
            if (queryVec && !HordeVectorMemory.isFallbackActive) {
                displayList = candidates.map(cand => {
                    let score = 0;
                    if (Array.isArray(cand.embedding) && cand.embedding.length > 0
                        && (!cand.embeddingNamespace || cand.embeddingNamespace === HordeVectorMemory.namespace())) {
                        score = cosineSimilarity(queryVec, cand.embedding);
                    }
                    return {
                        text: cand.text,
                        score: score,
                        cached: !!cand.embedding,
                        ref: cand.ref,
                        type: cand.type,
                        status: cand.status,
                        importance: cand.importance,
                        sourceSessionId: cand.sourceSessionId,
                        pinned: cand.pinned
                    };
                });
                displayList.sort((a, b) => b.score - a.score);
            } else {
                // Fallback concept matching
                const cLower = filterQuery.toLowerCase();
                displayList = candidates.map(cand => {
                    const score = cand.text.toLowerCase().includes(cLower) ? 0.99 : 0.0;
                    return { ...cand, text: cand.text, score, cached: false, ref: cand.ref };
                });
                displayList.sort((a, b) => b.score - a.score);
            }
        } catch (e) {
            console.warn("Inspector search failed, falling back to keyword scoring:", e);
            const cLower = filterQuery.toLowerCase();
            displayList = candidates.map(cand => {
                const score = cand.text.toLowerCase().includes(cLower) ? 0.99 : 0.0;
                return { ...cand, text: cand.text, score, cached: false, ref: cand.ref };
            });
            displayList.sort((a, b) => b.score - a.score);
        }
    } else {
        displayList = candidates.map(c => ({
            text: c.text,
            score: null,
            cached: !!c.embedding,
            ref: c.ref,
            type: c.type,
            status: c.status,
            importance: c.importance,
            sourceSessionId: c.sourceSessionId,
            pinned: c.pinned
        }));
    }
    
    listContainer.innerHTML = "";
    displayList.forEach(item => {
        const card = document.createElement('div');
        card.style.background = 'var(--surface)';
        card.style.border = '1px solid var(--border)';
        card.style.borderRadius = '8px';
        card.style.padding = '12px 16px';
        card.style.display = 'flex';
        card.style.flexDirection = 'column';
        card.style.gap = '8px';
        card.style.boxShadow = '0 2px 8px rgba(0,0,0,0.1)';
        card.style.transition = 'transform 0.2s, border-color 0.2s';
        
        // Dynamic hover effects
        card.onmouseenter = () => {
            card.style.borderColor = 'var(--accent)';
            card.style.transform = 'translateY(-1px)';
        };
        card.onmouseleave = () => {
            card.style.borderColor = 'var(--border)';
            card.style.transform = 'none';
        };
        
        // HSL Tag styling for score
        let scoreTag = "";
        if (item.score !== null) {
            const pct = Math.round(item.score * 100);
            let color = 'var(--red)';
            if (pct >= 70) color = 'var(--success)';
            else if (pct >= 40) color = 'var(--warning)';
            
            scoreTag = `<span style="font-size:0.7rem; font-weight:800; font-family:monospace; background:rgba(0,0,0,0.2); color:${color}; padding:2px 8px; border-radius:10px; border:1px solid ${color};">MATCH ${pct}%</span>`;
        }
        
        const cacheTag = item.cached
            ? `<span style="font-size:0.6rem; font-weight:800; text-transform:uppercase; color:var(--success); opacity:0.85;">⚡ EMBEDDED</span>`
            : `<span style="font-size:0.6rem; font-weight:800; text-transform:uppercase; color:var(--text-3); opacity:0.6;">⏳ RAW TEXT</span>`;

        // Editable only for episodic memories (which we have a live ref to)
        const editable = currentVectorTab === 'episodic' && item.ref && currentEpisodicStore;
        const escaped = (item.text || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

        const actionBtns = editable ? `
            <div style="display:flex; gap:6px;">
                <button class="tool-btn epi-pin-btn" title="Keep this memory in recall" style="font-size:11px; padding:2px 8px;">${item.ref?.pinned ? '★ Pinned' : '☆ Pin'}</button>
                <button class="tool-btn epi-edit-btn" title="Edit memory" style="font-size:11px; padding:2px 8px;">✎ Edit</button>
                <button class="tool-btn tool-btn-danger epi-del-btn" title="Delete memory" style="font-size:11px; padding:2px 8px;">✕</button>
            </div>` : '';

        const metadata = item.ref ? [
            String(item.ref.type || 'episode').replace('_', ' '),
            item.ref.status || 'active',
            `importance ${Math.round((Number(item.ref.importance) || 0.5) * 100)}%`,
            item.ref.sourceSessionId ? `source ${item.ref.sourceSessionId}` : '',
            Number.isFinite(Number(item.ref.startIndex)) ? `messages ${item.ref.startIndex}–${item.ref.endIndex ?? '?'}` : ''
        ].filter(Boolean).join(' · ') : '';

        card.innerHTML = `
            <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid var(--border2); padding-bottom:6px;">
                <div style="display:flex; gap:8px; align-items:center;">${cacheTag}${scoreTag}</div>
                ${actionBtns}
            </div>
            ${metadata ? `<div style="font-size:0.68rem; color:var(--text-3); text-transform:uppercase; letter-spacing:.04em;">${escapeHTML(metadata)}</div>` : ''}
            <div class="epi-text" style="font-size:0.9rem; line-height:1.5; color:var(--text); white-space:pre-wrap;">${escaped}</div>
            ${editable ? `<textarea class="form-textarea epi-edit-box" rows="6" style="display:none;">${escaped}</textarea>` : ''}
        `;

        if (editable) {
            const ref = item.ref;
            const textDiv = card.querySelector('.epi-text');
            const box = card.querySelector('.epi-edit-box');
            const editBtn = card.querySelector('.epi-edit-btn');
            const delBtn = card.querySelector('.epi-del-btn');
            const pinBtn = card.querySelector('.epi-pin-btn');

            pinBtn.onclick = async () => {
                ref.pinned = !ref.pinned;
                ref.updatedAt = Date.now();
                await saveState();
                renderVectorMemoryList(filterQuery);
            };

            delBtn.onclick = async () => {
                const i = currentEpisodicStore.indexOf(ref);
                if (i === -1) return;
                currentEpisodicStore.splice(i, 1);
                await saveState();
                renderVectorMemoryList(filterQuery);
                showToast('Memory deleted', 'success');
            };

            editBtn.onclick = async () => {
                const editing = box.style.display !== 'none';
                if (!editing) {
                    textDiv.style.display = 'none';
                    box.style.display = 'block';
                    box.focus();
                    editBtn.textContent = '✓ Save';
                } else {
                    const newText = box.value.trim();
                    if (!newText) return showToast('Memory text cannot be empty', 'error');
                    ref.text = newText;
                    try {
                        ref.embedding = await getEmbedding(newText);
                        ref.embeddingNamespace = HordeVectorMemory.namespace();
                        ref.updatedAt = Date.now();
                    } catch (e) {
                        console.warn('Re-embed failed, keeping text only:', e);
                        delete ref.embedding;
                    }
                    await saveState();
                    renderVectorMemoryList(filterQuery);
                    showToast('Memory updated', 'success');
                }
            };
        }

        listContainer.appendChild(card);
    });
}

/* ═══════════════════════════════════════════════════════════════════════
   SYNTHETIC COMPANIONS — a texting/DM simulator with a digital brain.

   Deliberately standalone from the World/NPC engine above: a companion is
   not an NPC in a world, it is a person with their own thread, their own
   evolving mood and memory, and their own simulated life running against
   real wall-clock time rather than turn counts. Everything here is a pure
   function wherever possible — mood decay, the life-tick, memory
   consolidation — so the whole brain can be exercised without a network
   call, the same discipline the World engine holds itself to.
   ═══════════════════════════════════════════════════════════════════════ */

// --- Data model --------------------------------------------------------

