        desirePattern: COMPANION_DESIRE_PATTERNS.includes(c.desirePattern)
            ? c.desirePattern : 'mixed',
        sexualConfidence: COMPANION_SEXUAL_CONFIDENCE.includes(c.sexualConfidence)
            ? c.sexualConfidence : 'natural',
        sexualRiskAppetite: COMPANION_SEXUAL_RISK.includes(c.sexualRiskAppetite)
            ? c.sexualRiskAppetite : 'moderate',
        sexualInitiative: c.sexualInitiative === true,
        intimacyBoundaries: String(c.intimacyBoundaries || '').trim().slice(0, 2400),
        textProvider: ['provider', ...TEXT_PROVIDER_IDS].includes(c.textProvider)
            ? c.textProvider : 'provider',
        imageSource: ['provider', 'openrouter', 'gptproto', 'nanogpt', 'local', 'local_image', 'comfyui', 'higgsfield', 'magnific'].includes(c.imageSource)
            ? c.imageSource : 'provider',
        imageModel: typeof c.imageModel === 'string' ? c.imageModel : '',
        mcpImageTool: typeof c.mcpImageTool === 'string' ? c.mcpImageTool.trim().slice(0, 300) : '',
        mcpImageArguments: isPlainObject(c.mcpImageArguments) ? safeJsonClone(c.mcpImageArguments) : {},
        imageProviderTag: typeof c.imageProviderTag === 'string' ? c.imageProviderTag : '',
        imageParameters: normalizeCompanionImageParameters(c.imageParameters),
        imageProviderOptions: normalizeCompanionImageProviderOptions(c.imageProviderOptions),
        photoStyle: normalizeCompanionPhotoStyle(c.photoStyle),
        photoCapturePolicy: normalizeCompanionPhotoCapturePolicy(c.photoCapturePolicy),
        photoReferenceFallback: c.photoReferenceFallback !== false,
        allowPhotos: c.allowPhotos !== false,
        allowVoiceNotes: c.allowVoiceNotes !== false,
        allowVideoClips: c.allowVideoClips === true,
        videoProvider: normalizedVideoProviderId(c.videoProvider),
        videoModel: String(c.videoModel || '').trim().slice(0, 300),
        videoResolution: ['480p', '720p', '1080p'].includes(c.videoResolution) ? c.videoResolution : '480p',
        videoDuration: livingClamp(Number(c.videoDuration) || 5, 2, 30),
