function companionGeocodingUrl(query, count = 40) {
    const params = new URLSearchParams({
        name: String(query || '').trim(),
        count: String(livingClamp(parseInt(count) || 40, 1, 100)),
        language: String(navigator.language || 'en').split('-')[0].toLowerCase(),
        format: 'json'
    });
    return `https://geocoding-api.open-meteo.com/v1/search?${params}`;
}

async function searchCompanionRealLocations(query, options = {}) {
    const term = String(query || '').trim();
    if (term.length < 2) return [];
    const response = await fetch(companionGeocodingUrl(term, options.count), {
        signal: options.signal
    });
    if (!response.ok) throw new Error(`Place search failed (${response.status})`);
    const data = await response.json();
    const seen = new Set();
    return (Array.isArray(data?.results) ? data.results : []).map(place => {
        const parts = [place.name, place.admin1, place.admin2, place.country]
            .map(value => String(value || '').trim()).filter((value, index, all) =>
                value && all.findIndex(other => other.toLowerCase() === value.toLowerCase()) === index);
        const label = parts.join(', ');
        const timezone = String(place.timezone || '').trim();
        const coordinates = Number.isFinite(Number(place.latitude)) && Number.isFinite(Number(place.longitude))
            ? `${Number(place.latitude).toFixed(3)}, ${Number(place.longitude).toFixed(3)}` : '';
        return {
            id: String(place.id || `${label}|${timezone}`),
            label,
            timezone,
            latitude: Number(place.latitude),
            longitude: Number(place.longitude),
            countryCode: String(place.country_code || '').toUpperCase(),
            meta: [timezone, coordinates].filter(Boolean).join(' · ')
        };
    }).filter(place => {
        const key = `${place.label.toLowerCase()}|${place.timezone}`;
        if (!place.label || !place.timezone || seen.has(key)) return false;
        seen.add(key);
        return true;
    });
}

function companionTimeZoneOptions() {
    let zones = [];
    try {
        zones = typeof Intl.supportedValuesOf === 'function'
            ? Intl.supportedValuesOf('timeZone') : [];
    } catch (error) {
        zones = [];
    }
    if (!zones.length) {
        zones = [...new Set(companionLocationOptions().map(option => option.timezone))];
    }
    return ['UTC', ...zones.filter(zone => zone !== 'UTC')].map(value => {
        const parts = value.split('/');
        const city = (parts[parts.length - 1] || value).replace(/_/g, ' ');
        const region = parts.length > 1 ? parts.slice(0, -1).join(' / ') : 'Universal';
        return { value, label: city, meta: `${region} · ${value}` };
    });
}

function isValidCompanionTimeZone(value) {
    const zone = String(value || '').trim();
    if (!zone) return false;
    try {
        new Intl.DateTimeFormat('en', { timeZone: zone }).format();
        return true;
    } catch (error) {
        return false;
    }
}

function shuffledCompanionClips() {
    const clips = state.companions.flatMap(companion => (companion.videoJobs || [])
        .filter(job => job.status === 'ready' && (job.assetId || job.bundledSrc || job.outputUrl))
        .map(job => ({ companion, job })));
    for (let index = clips.length - 1; index > 0; index -= 1) {
        const swap = Math.floor(Math.random() * (index + 1));
        [clips[index], clips[swap]] = [clips[swap], clips[index]];
    }
    return clips;
}

function closeCompanionDiscoveryClips() {
    const backdrop = document.getElementById('vh-clips-discovery-backdrop');
    backdrop?.querySelectorAll('video').forEach(video => video.pause());
    backdrop?.classList.add('hidden');
}

function bindCompanionDiscoveryClipViewer(root, items) {
    const feed = root.querySelector('.vh-clips-feed');
    const cards = [...root.querySelectorAll('.vh-discovery-clip')];
    if (!feed || !cards.length) return;
    let activeCard = cards[0];
    let soundOn = false;
    const activate = async card => {
        if (!card) return;
        activeCard = card;
        cards.forEach(item => {
            const video = item.querySelector('video');
            item.classList.toggle('is-active', item === card);
            if (video && item !== card) video.pause();
        });
        const video = card.querySelector('video');
        if (!video) return;
        video.muted = !soundOn;
        const sound = card.querySelector('[data-discovery-sound]');
        if (sound) {
            sound.textContent = soundOn ? '🔊' : '🔇';
            sound.setAttribute('aria-label', soundOn ? 'Mute clip' : 'Unmute clip');
        }
        if (video.paused) {
            try { await video.play(); } catch (_) { card.classList.add('needs-play'); }
        }
    };
    const observer = typeof IntersectionObserver === 'function' ? new IntersectionObserver(entries => {
        const visible = entries.filter(entry => entry.isIntersecting)
            .sort((left, right) => right.intersectionRatio - left.intersectionRatio)[0];
        if (visible?.intersectionRatio >= .62) activate(visible.target);
    }, { root: feed, threshold: [.2, .62, .9] }) : null;
    cards.forEach(card => observer?.observe(card));
    cards.forEach((card, index) => {
        const item = items[index];
        const video = card.querySelector('video');
        if (!item || !video) return;
        video.addEventListener('timeupdate', () => {
            const progress = card.querySelector('[data-discovery-progress]');
            if (progress) progress.style.width = `${video.duration ? livingClamp(video.currentTime / video.duration * 100, 0, 100) : 0}%`;
        });
        video.addEventListener('playing', () => card.classList.remove('needs-play', 'is-buffering'));
        video.addEventListener('waiting', () => card.classList.add('is-buffering'));
        video.addEventListener('canplay', () => card.classList.remove('is-buffering'));
        video.addEventListener('error', () => {
            card.classList.remove('is-buffering', 'needs-play');
            card.classList.add('media-unavailable');
            card.querySelector('.vh-discovery-video-slot')?.insertAdjacentHTML('beforeend', '<div class="companion-media-error"><strong>Clip unavailable</strong><span>This bundled file could not be loaded. Reload after starting Horde Studio locally.</span></div>');
        }, { once: true });
        video.addEventListener('pause', () => { if (!video.ended) card.classList.add('needs-play'); });
        video.addEventListener('ended', () => { video.currentTime = 0; if (card === activeCard) activate(card); });
        card.querySelector('[data-discovery-play]')?.addEventListener('click', () => {
            if (video.paused) activate(card); else video.pause();
        });
        card.querySelector('[data-discovery-sound]')?.addEventListener('click', event => {
            event.stopPropagation(); soundOn = !soundOn; activate(card);
        });
        card.querySelector('[data-discovery-like]')?.addEventListener('click', async event => {
            event.stopPropagation();
            item.job.likedByPlayer = !item.job.likedByPlayer;
            const button = event.currentTarget;
            button.classList.toggle('liked', item.job.likedByPlayer);
            button.setAttribute('aria-label', item.job.likedByPlayer ? 'Unlike clip' : 'Like clip');
            button.querySelector('b').textContent = item.job.likedByPlayer ? '♥' : '♡';
            button.querySelector('span').textContent = companionClipCountLabel(item.job.likeCount + (item.job.likedByPlayer ? 1 : 0));
            item.companion.socialRelationship.engagement = livingClamp(item.companion.socialRelationship.engagement + (item.job.likedByPlayer ? 1 : -1), 0, 100);
            recordCompanionSocialInteraction(item.companion, {
                id: item.job.id, text: item.job.caption || item.job.concept || 'video clip'
            }, item.job.likedByPlayer ? 'liked' : 'unliked');
            persistCompanionRuntime(item.companion); await saveState();
        });
        card.querySelector('[data-discovery-open-human]')?.addEventListener('click', event => {
            event.stopPropagation();
            state.activeCompanionId = item.companion.id;
            saveState(); closeCompanionDiscoveryClips(); switchView('companionChat');
        });
        card.querySelector('[data-discovery-prev]')?.addEventListener('click', () => cards[Math.max(0, index - 1)]?.scrollIntoView({ behavior: 'smooth', block: 'start' }));
        card.querySelector('[data-discovery-next]')?.addEventListener('click', () => cards[Math.min(cards.length - 1, index + 1)]?.scrollIntoView({ behavior: 'smooth', block: 'start' }));
    });
    feed.addEventListener('keydown', event => {
        const index = Math.max(0, cards.indexOf(activeCard));
        if (event.key === 'ArrowDown') { event.preventDefault(); cards[Math.min(cards.length - 1, index + 1)]?.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
        if (event.key === 'ArrowUp') { event.preventDefault(); cards[Math.max(0, index - 1)]?.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
        if (event.key === ' ') { event.preventDefault(); const video = activeCard?.querySelector('video'); if (video?.paused) activate(activeCard); else video?.pause(); }
    });
    activate(cards[0]);
}

function renderCompanionDiscoveryClips() {
    const content = document.getElementById('vh-clips-discovery-content');
    if (!content) return;
    const items = shuffledCompanionClips();
    if (!items.length) {
        content.innerHTML = '<div class="vh-clips-empty"><span>▶</span><strong>No clips yet</strong><p>Clips generated or bundled for any Virtual Human will appear here.</p></div>';
        return;
    }
    content.innerHTML = `<div class="vh-clips-feed" tabindex="0" aria-label="Clips from all Virtual Humans">${items.map(({ companion, job }, index) => {
        const avatarStyle = companion.profilePhoto ? `background-image:url(&quot;${escapeHTML(companion.profilePhoto)}&quot;)` : '';
        return `<article class="vh-discovery-clip" data-discovery-clip="${escapeHTML(companion.id)}:${escapeHTML(job.id)}">
            <div class="vh-discovery-video-slot"></div>
            <button type="button" class="vh-discovery-play" data-discovery-play aria-label="Play or pause clip"><span>▶</span></button>
            <div class="companion-clip-shade"></div>
            <div class="vh-discovery-creator"><button type="button" data-discovery-open-human aria-label="Open ${escapeHTML(companion.name || 'Virtual Human')}'s chat"><span style="${avatarStyle}">${companion.profilePhoto ? '' : escapeHTML(companionInitials(companion.name))}</span></button><div><strong>${escapeHTML(companion.name || 'Virtual Human')}</strong><p>${escapeHTML(job.caption || job.concept || job.requestText || 'A new moment.')}</p><small>♫ original sound</small></div></div>
            <div class="vh-discovery-actions"><button type="button" data-discovery-like class="${job.likedByPlayer ? 'liked' : ''}" aria-label="${job.likedByPlayer ? 'Unlike' : 'Like'} clip"><b>${job.likedByPlayer ? '♥' : '♡'}</b><span>${escapeHTML(companionClipCountLabel(job.likeCount + (job.likedByPlayer ? 1 : 0)))}</span></button><button type="button" data-discovery-sound aria-label="Unmute clip">🔇</button></div>
            <div class="vh-discovery-nav"><button type="button" data-discovery-prev ${index === 0 ? 'disabled' : ''} aria-label="Previous clip">⌃</button><button type="button" data-discovery-next ${index === items.length - 1 ? 'disabled' : ''} aria-label="Next clip">⌄</button></div>
            <div class="vh-discovery-progress"><i data-discovery-progress></i></div>
        </article>`;
    }).join('')}</div>`;
    Promise.all(items.map(async ({ job }, index) => {
        const slot = content.querySelectorAll('.vh-discovery-video-slot')[index];
        const src = await companionVideoJobSource(job);
        if (src && slot?.isConnected) slot.innerHTML = `<video playsinline muted preload="auto" src="${escapeHTML(src)}"${job.poster ? ` poster="${escapeHTML(job.poster)}"` : ''}></video>`;
        else if (slot?.isConnected) slot.innerHTML = '<div class="companion-media-error"><strong>Clip unavailable</strong><span>No playable media source was found.</span></div>';
    })).then(() => { if (content.isConnected) bindCompanionDiscoveryClipViewer(content, items); });
}

function openCompanionDiscoveryClips() {
    const backdrop = document.getElementById('vh-clips-discovery-backdrop');
    if (!backdrop) return;
    backdrop.classList.remove('hidden');
    renderCompanionDiscoveryClips();
}

function renderCompanionSearchResults(results, items, onSelect, emptyText) {
    if (!results) return;
    results.innerHTML = '';
    if (!items.length) {
        const empty = document.createElement('div');
        empty.className = 'vh-search-empty';
        empty.textContent = emptyText;
        results.appendChild(empty);
    } else {
        items.forEach(item => {
            const button = document.createElement('button');
            button.type = 'button';
            button.className = 'searchable-dropdown-item';
            button.setAttribute('role', 'option');
            const label = document.createElement('span');
            label.className = 'model-display-name';
            label.textContent = item.label;
            const meta = document.createElement('span');
            meta.className = 'model-display-id';
            meta.textContent = item.meta || item.value || '';
            button.append(label, meta);
            button.onclick = () => onSelect(item);
            results.appendChild(button);
        });
    }
    results.classList.remove('hidden');
}

function setCompanionSearchOpen(input, results, open) {
    if (!input || !results) return;
    results.classList.toggle('hidden', !open);
    input.setAttribute('aria-expanded', String(open));
}

function companionEffectiveLifeBuilderModel(companion) {
    return String(
        companion?.lifeBuilderModel
        || companion?.model
        || state.globalSettings.defaultModel
        || ''
    ).trim();
}

function updateCompanionLifeBuilderModelStatus(companion) {
    const status = document.getElementById('cs-life-builder-model-status');
    if (!status) return;
    const dedicated = String(companion?.lifeBuilderModel || '').trim();
    const conversation = String(companion?.model || state.globalSettings.defaultModel || '').trim();
    const effective = companionEffectiveLifeBuilderModel(companion);
    status.textContent = dedicated
        ? `Active Life will use ${effective}. This selection is saved only for this human.`
        : conversation
            ? `Using the conversation model · ${conversation}. Choose another model here without changing chat.`
            : 'No effective model is configured. Choose one here or configure a conversation/global default model.';
    status.classList.toggle('invalid-field-hint', !effective);
}

function updateCompanionTimezoneFieldStatus() {
    const input = document.getElementById('cs-timezone');
    const status = document.getElementById('cs-timezone-status');
    if (!input || !status) return;
    const value = input.value.trim();
    const custom = document.getElementById('cs-custom-location-mode')?.checked === true;
    if (custom) {
        const offset = Number(document.getElementById('cs-timezone-offset')?.value || 0);
        status.textContent = value
            ? `${value} · simulated clock uses ${formatCompanionUtcOffset(offset)}`
            : `Enter a fictional timezone name · simulated clock uses ${formatCompanionUtcOffset(offset)}`;
        status.classList.remove('invalid-field-hint');
        return;
    }
    const valid = isValidCompanionTimeZone(value);
    status.textContent = !value
        ? 'Choose a timezone so their clock, sleep and routines use the correct local time.'
        : valid
            ? `Valid timezone · current local time ${new Date().toLocaleTimeString([], { timeZone: value, hour: 'numeric', minute: '2-digit' })}`
            : 'Unknown timezone. Search and select a listed IANA timezone, or correct the custom value.';
    status.classList.toggle('invalid-field-hint', !!value && !valid);
}

function setupCompanionSearchableFields() {
    const locationInput = document.getElementById('cs-location-label');
    const locationResults = document.getElementById('cs-location-results');
    const locationStatus = document.getElementById('cs-location-status');
    const timezoneInput = document.getElementById('cs-timezone');
    const timezoneResults = document.getElementById('cs-timezone-results');
    const customLocationMode = document.getElementById('cs-custom-location-mode');
    const customOffsetWrap = document.getElementById('cs-custom-timezone-offset-wrap');
    const customOffset = document.getElementById('cs-timezone-offset');
    const attribution = document.getElementById('cs-location-attribution');
    const builderInput = document.getElementById('cs-builder-model');
    const builderResults = document.getElementById('cs-builder-model-results');
    const builderStatus = document.getElementById('cs-builder-model-status');
    const lifeBuilderInput = document.getElementById('cs-life-builder-model');
    const lifeBuilderResults = document.getElementById('cs-life-builder-model-results');
    const timezones = companionTimeZoneOptions();
    let locationTimer = null;
    let locationController = null;

    if (customOffset) {
        customOffset.innerHTML = '';
        for (let minutes = -720; minutes <= 840; minutes += 15) {
            const option = document.createElement('option');
            option.value = String(minutes);
            option.textContent = formatCompanionUtcOffset(minutes);
            customOffset.appendChild(option);
        }
    }

    const applyLocationModeUI = () => {
        const custom = customLocationMode?.checked === true;
        locationInput.placeholder = custom
            ? 'Enter a fictional or custom place…'
            : 'Search worldwide places or postal codes…';
        timezoneInput.placeholder = custom
            ? 'Enter a fictional timezone name…'
            : 'Search city, region or IANA timezone…';
        customOffsetWrap?.classList.toggle('hidden', !custom);
        attribution?.classList.toggle('hidden', custom);
        if (locationStatus) {
            locationStatus.textContent = custom
                ? 'Custom mode: enter any invented place. No online lookup is performed.'
                : 'Search the worldwide place database by city, town, village, district, or postal code.';
        }
        if (custom) {
            locationController?.abort();
            setCompanionSearchOpen(locationInput, locationResults, false);
            setCompanionSearchOpen(timezoneInput, timezoneResults, false);
        }
        updateCompanionTimezoneFieldStatus();
    };
    const showLocationMatches = matches => {
        renderCompanionSearchResults(locationResults, matches, option => {
            const companion = getCompanion(state.editingCompanionId);
            locationInput.value = option.label;
            timezoneInput.value = option.timezone;
            if (companion) {
                companion.locationLabel = option.label;
                companion.timezone = option.timezone;
                companion.locationMode = 'real';
                companion.locationLatitude = Number.isFinite(option.latitude) ? option.latitude : null;
                companion.locationLongitude = Number.isFinite(option.longitude) ? option.longitude : null;
                companion.locationCountryCode = option.countryCode || '';
            }
            setCompanionSearchOpen(locationInput, locationResults, false);
            if (locationStatus) locationStatus.textContent =
                `Selected real location · ${option.meta || option.timezone}`;
            updateCompanionTimezoneFieldStatus();
        }, 'No worldwide place matches. Check the spelling or enable fictional/custom location.');
        locationInput.setAttribute('aria-expanded', 'true');
    };
    const searchLocations = async () => {
        if (customLocationMode?.checked) return;
        const query = String(locationInput?.value || '').trim();
        if (query.length < 2) {
            setCompanionSearchOpen(locationInput, locationResults, false);
            if (locationStatus) locationStatus.textContent =
                'Type at least 2 characters. Three or more enables fuzzy worldwide matching.';
            return;
        }
        locationController?.abort();
        locationController = new AbortController();
        if (locationStatus) locationStatus.textContent = 'Searching worldwide places…';
        try {
            const matches = await searchCompanionRealLocations(query, {
                count: 50, signal: locationController.signal
            });
            showLocationMatches(matches);
            if (locationStatus) locationStatus.textContent = matches.length
                ? `${matches.length} worldwide result${matches.length === 1 ? '' : 's'} · select one to set its timezone automatically.`
                : 'No worldwide place matched. Check the spelling or enable fictional/custom location.';
        } catch (error) {
            if (error.name === 'AbortError') return;
            console.warn('Worldwide place search failed:', error);
            const fallback = companionLocationOptions().filter(option =>
                `${option.label} ${option.timezone}`.toLowerCase().includes(query.toLowerCase())).map(option => ({
                    ...option, meta: `${option.timezone} · offline fallback`
                })).slice(0, 20);
            showLocationMatches(fallback);
            if (locationStatus) locationStatus.textContent = fallback.length
                ? 'Worldwide search is unavailable; showing a small offline fallback list.'
                : 'Worldwide place search is unavailable. Check your connection or use fictional/custom mode.';
        }
    };
    const scheduleLocationSearch = () => {
        clearTimeout(locationTimer);
        locationTimer = setTimeout(searchLocations, 320);
    };
    const renderTimezones = () => {
        if (customLocationMode?.checked) {
            setCompanionSearchOpen(timezoneInput, timezoneResults, false);
            return;
        }
        const query = String(timezoneInput?.value || '').trim().toLowerCase().replace(/\s+/g, '_');
        const matches = timezones.filter(option =>
            !query || `${option.label} ${option.meta} ${option.value}`.toLowerCase().replace(/\s+/g, '_').includes(query))
            .slice(0, 60);
        renderCompanionSearchResults(timezoneResults, matches, option => {
            const companion = getCompanion(state.editingCompanionId);
            timezoneInput.value = option.value;
            if (companion) companion.timezone = option.value;
            setCompanionSearchOpen(timezoneInput, timezoneResults, false);
            updateCompanionTimezoneFieldStatus();
        }, 'No timezone matches. Try a city, region, or exact IANA name.');
        timezoneInput.setAttribute('aria-expanded', 'true');
    };
    const renderBuilderModels = async () => {
        if (!builderInput || !builderResults) return;
        if (!companionTextModelCatalog.length) {
            try { companionTextModelCatalog = rankCompanionTextModels(await getOpenRouterModels()); }
            catch (error) { console.warn('Could not load builder model suggestions:', error); }
        }
        const query = builderInput.value.trim().toLowerCase();
        const effectiveDefault = state.globalSettings.defaultModel || '';
        const options = [{
            value: '', label: 'Use global default',
            meta: effectiveDefault || 'No global default configured'
        }, ...companionTextModelCatalog.map(model => ({
            value: model.id,
            label: model.name,
            meta: `${model.id}${model.supportsTools ? ' · tools' : ''}`
        }))].filter(option =>
            !query || `${option.label} ${option.meta}`.toLowerCase().includes(query)).slice(0, 60);
        renderCompanionSearchResults(builderResults, options, option => {
            builderInput.value = option.value;
            setCompanionSearchOpen(builderInput, builderResults, false);
            if (builderStatus) {
                builderStatus.textContent = option.value
                    ? `Builder will use ${option.label} · ${option.value}`
                    : `Builder will use the global default${effectiveDefault ? ` · ${effectiveDefault}` : ''}.`;
            }
        }, 'No text model matches. A custom provider model ID can still be entered.');
        builderInput.setAttribute('aria-expanded', 'true');
        if (builderStatus) builderStatus.textContent =
            `${companionTextModelCatalog.length} text models available from ${isLocalProvider() ? 'your local server' : cloudProviderName()}.`;
    };
    const renderLifeBuilderModels = async () => {
        if (!lifeBuilderInput || !lifeBuilderResults) return;
        const companion = getCompanion(state.editingCompanionId);
        if (!companionTextModelCatalog.length) {
            try {
                companionTextModelCatalog = rankCompanionTextModels(
                    await getCompanionOutputModels('text', false, companionTextProviderId(companion)));
            }
            catch (error) { console.warn('Could not load Active Life model suggestions:', error); }
        }
        const query = lifeBuilderInput.value.trim().toLowerCase();
        const conversationModel = String(companion?.model || state.globalSettings.defaultModel || '').trim();
        const options = [{
            value: '',
            label: 'Use conversation model',
            meta: conversationModel || 'No conversation or global model configured'
        }, ...companionTextModelCatalog.map(model => ({
            value: model.id,
            label: model.name,
            meta: `${model.id}${model.supportsJSON ? ' · structured output' : ''}`
        }))].filter(option =>
            !query || `${option.label} ${option.meta}`.toLowerCase().includes(query)
        ).slice(0, 60);
        renderCompanionSearchResults(lifeBuilderResults, options, option => {
            lifeBuilderInput.value = option.value;
            if (companion) companion.lifeBuilderModel = option.value;
            setCompanionSearchOpen(lifeBuilderInput, lifeBuilderResults, false);
            updateCompanionLifeBuilderModelStatus(companion);
        }, 'No text model matches. You can still enter an exact custom model ID.');
        lifeBuilderInput.setAttribute('aria-expanded', 'true');
        updateCompanionLifeBuilderModelStatus(companion);
    };

    if (locationInput && locationResults) {
        locationInput.onfocus = scheduleLocationSearch;
        locationInput.addEventListener('input', () => {
            const companion = getCompanion(state.editingCompanionId);
            if (companion && companion.locationMode !== 'custom') {
                companion.locationLatitude = null;
                companion.locationLongitude = null;
                companion.locationCountryCode = '';
            }
            scheduleLocationSearch();
        });
        locationInput.addEventListener('keydown', event => {
            if (event.key === 'Escape') setCompanionSearchOpen(locationInput, locationResults, false);
        });
    }
    if (timezoneInput && timezoneResults) {
        timezoneInput.onfocus = renderTimezones;
        timezoneInput.addEventListener('input', () => {
            renderTimezones();
            updateCompanionTimezoneFieldStatus();
        });
        timezoneInput.addEventListener('keydown', event => {
            if (event.key === 'Escape') setCompanionSearchOpen(timezoneInput, timezoneResults, false);
        });
    }
    if (builderInput && builderResults) {
        builderInput.onfocus = renderBuilderModels;
        builderInput.addEventListener('input', renderBuilderModels);
        builderInput.addEventListener('keydown', event => {
            if (event.key === 'Escape') setCompanionSearchOpen(builderInput, builderResults, false);
        });
    }
    if (lifeBuilderInput && lifeBuilderResults) {
        lifeBuilderInput.onfocus = renderLifeBuilderModels;
        lifeBuilderInput.addEventListener('input', () => {
            const companion = getCompanion(state.editingCompanionId);
            if (companion) companion.lifeBuilderModel = lifeBuilderInput.value.trim();
            renderLifeBuilderModels();
        });
        lifeBuilderInput.addEventListener('keydown', event => {
            if (event.key === 'Escape') setCompanionSearchOpen(lifeBuilderInput, lifeBuilderResults, false);
        });
    }
    if (customLocationMode) {
        customLocationMode.onchange = () => {
            const companion = getCompanion(state.editingCompanionId);
            if (companion) {
                companion.locationMode = customLocationMode.checked ? 'custom' : 'real';
                if (customLocationMode.checked) {
                    companion.locationLatitude = null;
                    companion.locationLongitude = null;
                    companion.locationCountryCode = '';
                }
            }
            applyLocationModeUI();
        };
    }
    if (customOffset) {
        customOffset.onchange = () => {
            const companion = getCompanion(state.editingCompanionId);
            if (companion) companion.timezoneOffsetMinutes =
                livingClamp(parseInt(customOffset.value) || 0, -720, 840);
            updateCompanionTimezoneFieldStatus();
        };
    }
    document.addEventListener('click', event => {
        [
            [locationInput, locationResults],
            [timezoneInput, timezoneResults],
            [builderInput, builderResults],
            [lifeBuilderInput, lifeBuilderResults]
        ].forEach(([input, results]) => {
            if (input && results && !input.contains(event.target) && !results.contains(event.target)) {
                setCompanionSearchOpen(input, results, false);
            }
        });
    });
    applyLocationModeUI();
    updateCompanionTimezoneFieldStatus();
    updateCompanionLifeBuilderModelStatus(getCompanion(state.editingCompanionId));
}

async function getSettingsProviderCatalog() {
    const provider = document.getElementById('global-api-provider')?.value || state.globalSettings.apiProvider;
    const value = id => document.getElementById(id)?.value.trim() || '';
    let base = '';
    let headers = {};
    if (provider === 'local') {
        base = normalizeRemoteApiBase(value('global-local-url'), 'http://localhost:11434/v1');
        if (value('global-local-key')) headers.Authorization = `Bearer ${value('global-local-key')}`;
    } else if (provider === 'gptproto') {
        base = 'https://gptproto.com/v1'; headers.Authorization = `Bearer ${value('global-gptproto-key')}`;
    } else if (provider === 'nanogpt') {
        base = 'https://nano-gpt.com/api/v1'; headers.Authorization = `Bearer ${value('global-nanogpt-key')}`;
    } else if (provider === 'nvidia') {
        base = 'https://integrate.api.nvidia.com/v1'; headers.Authorization = `Bearer ${value('global-nvidia-key')}`;
    } else if (provider === 'bedrock') {
        base = normalizeRemoteApiBase(value('global-bedrock-base-url'))
            || `https://bedrock-mantle.${normalizedBedrockRegion(value('global-bedrock-region'))}.api.aws/v1`;
        headers.Authorization = `Bearer ${value('global-bedrock-key')}`;
    } else if (provider === 'custom') {
        base = normalizeRemoteApiBase(value('global-custom-base-url'));
        if (!base) return [];
        if (value('global-custom-api-key')) headers.Authorization = `Bearer ${value('global-custom-api-key')}`;
        headers = { ...headers, ...parseCustomHeaders(document.getElementById('global-custom-headers')?.value.trim()) };
    } else {
        base = 'https://openrouter.ai/api/v1';
        headers = { Authorization: `Bearer ${value('global-api-key')}`, 'HTTP-Referer': 'https://horde-studio.ai', 'X-Title': 'Horde Studio' };
    }
    const response = await fetch(base.replace(/\/+$/, '') + '/models', { headers });
    if (!response.ok) throw new Error(`Model catalog request failed (${response.status})`);
    const data = await response.json();
    const catalog = Array.isArray(data) ? data : Array.isArray(data?.data) ? data.data : Array.isArray(data?.models) ? data.models : [];
    return catalog.filter(model => isPlainObject(model) && typeof model.id === 'string')
        .map(model => ({ ...model, name: typeof model.name === 'string' ? model.name : model.id }));
}

async function getSettingsEmbeddingCatalog() {
    const explicitBase = normalizeOpenAICompatibleBase(
        document.getElementById('global-embedding-url')?.value.trim() || '');
    if (!explicitBase) return getSettingsProviderCatalog();
    const key = document.getElementById('global-embedding-key')?.value.trim() || '';
    const response = await fetch(explicitBase + '/models', {
        headers: key ? { Authorization: `Bearer ${key}` } : {}
    });
    if (!response.ok) throw new Error(`Embedding catalog request failed (${response.status})`);
    const data = await response.json();
    const catalog = Array.isArray(data) ? data : Array.isArray(data?.data) ? data.data : Array.isArray(data?.models) ? data.models : [];
    return catalog.filter(model => isPlainObject(model) && typeof model.id === 'string')
        .map(model => ({ ...model, name: typeof model.name === 'string' ? model.name : model.id }));
}

function setupCatalogModelSearchFields() {
    const definitions = [
        { inputId: 'w-agent-model', resultsId: 'w-agent-model-results', blankLabel: 'Use this world’s DM model', kind: 'text' },
        { inputId: 'global-default-model', resultsId: 'global-default-model-results', kind: 'text' },
        { inputId: 'global-consolidation-model', resultsId: 'global-consolidation-model-results', kind: 'text' },
        { inputId: 'global-embedding-model', resultsId: 'global-embedding-model-results', kind: 'embedding' },
        { inputId: 'room-model', resultsId: 'room-model-results', kind: 'text' }
    ];
    definitions.forEach(definition => {
        const input = document.getElementById(definition.inputId);
        const results = document.getElementById(definition.resultsId);
        if (!input || !results) return;
        const render = async () => {
            let rawModels = [];
            try {
                rawModels = definition.inputId === 'global-default-model'
                    ? await getSettingsProviderCatalog()
                    : definition.kind === 'embedding'
                        ? await getSettingsEmbeddingCatalog()
                        : await getOpenRouterModels();
            }
            catch (error) { console.warn(`Could not load models for ${definition.inputId}:`, error); }
            const models = definition.kind === 'embedding'
                ? rawModels.filter(model => {
                    const outputs = modelOutputModalities(model);
                    return outputs.some(output => /embed/.test(output))
                        || /(?:^|[/._-])embed(?:ding)?(?:$|[/._-])/i.test(model.id);
                }).map(model => ({ id: model.id, name: model.name || model.id }))
                : rankCompanionTextModels(rawModels);
            const query = input.value.trim().toLowerCase();
            const options = [
                ...(definition.blankLabel ? [{ value: '', label: definition.blankLabel, meta: 'Automatic' }] : []),
                ...models.map(model => ({
                    value: model.id,
                    label: model.name || model.id,
                    meta: model.id
                }))
            ].filter(option =>
                !query || `${option.label} ${option.meta}`.toLowerCase().includes(query)).slice(0, 60);
            renderCompanionSearchResults(results, options, option => {
                input.value = option.value;
                setCompanionSearchOpen(input, results, false);
            }, definition.kind === 'embedding'
                ? 'No embedding model matches. You can still enter an exact custom model ID.'
                : 'No text model matches. You can still enter an exact custom model ID.');
            input.setAttribute('aria-expanded', 'true');
        };
        input.addEventListener('focus', render);
        input.addEventListener('input', render);
        input.addEventListener('keydown', event => {
            if (event.key === 'Escape') setCompanionSearchOpen(input, results, false);
        });
        document.addEventListener('click', event => {
            if (!input.contains(event.target) && !results.contains(event.target)) {
                setCompanionSearchOpen(input, results, false);
            }
        });
    });
}

function renderCompanionsGrid() {
    const grid = document.getElementById('companions-grid');
    if (!grid) return;
    renderIncludedHumansCatalog();
    grid.innerHTML = '';
    const query = String(document.getElementById('vh-search')?.value || '').trim().toLowerCase();
    const now = Date.now();
    const availableCount = state.companions.filter(companion =>
        companionLifeState(companion, now).availability === 'available').length;
    const totalEl = document.getElementById('vh-total-count');
    const totalUnitEl = document.getElementById('vh-human-unit');
    const availableEl = document.getElementById('vh-available-count');
    if (totalEl) totalEl.textContent = state.companions.length;
    if (totalUnitEl) totalUnitEl.textContent = state.companions.length === 1 ? 'human' : 'humans';
    if (availableEl) availableEl.textContent = availableCount;

    const companions = state.companions.filter(companion => {
        if (!query) return true;
        return [companion.name, companion.occupation, companion.personality, companion.socialWorld]
            .some(value => String(value || '').toLowerCase().includes(query));
    });
    if (!companions.length) {
        grid.innerHTML = query
            ? `<div class="vh-empty"><strong>No matching virtual humans</strong><span>Try a name, occupation, personality trait or social detail.</span></div>`
            : `<div class="vh-empty"><strong>Your human library is empty</strong><span>Create one from rough notes with the AI Human Builder, or author every detail yourself.</span></div>`;
        return;
    }
    companions.forEach(companion => {
        const thread = getCompanionThread(companion.id);
        const timeline = getActiveCompanionTimeline(companion.id);
        const unreadCount = thread.filter(message =>
            message.role === 'companion' && message.timestamp > (timeline?.lastViewedAt || 0)).length;
        const last = thread[thread.length - 1];
        const life = companionLifeState(companion, now);
        const unanswered = companionUnansweredState(thread, now);
        const card = document.createElement('article');
        card.className = 'vh-card';
        const meta = [companion.age ? `${companion.age}` : '', companion.pronouns].filter(Boolean).join(' · ');
        const role = companion.occupation || companion.personality || 'A persistent virtual human with a life beyond the conversation.';
        const lastText = last
            ? `${last.role === 'user' ? 'You: ' : ''}${last.type === 'photo' ? '📷 Photo' : last.type === 'voice' ? '🎙 Voice note' : last.text}`
            : 'No conversation yet';
        card.innerHTML = `
            <div class="vh-card-head">
                <div class="vh-card-avatar" style="${companionAvatarStyle(companion)}">
                    ${companion.profilePhoto ? '' : escapeHTML(companionInitials(companion.name))}
                </div>
                <div class="vh-card-identity">
                    <div class="vh-card-name">${escapeHTML(companion.name || 'Unnamed')}</div>
                    <div class="vh-card-meta">${escapeHTML(meta || 'Identity details not set')}</div>
                </div>
                <span class="vh-status ${escapeHTML(life.availability)}">${escapeHTML(life.availability)}</span>
            </div>
            <div class="vh-card-role">${escapeHTML(role)}</div>
            <div class="vh-card-state">
                <span class="vh-chip">${escapeHTML(life.label)}</span>
                <span class="vh-chip">Mood: ${escapeHTML(companion.mood?.label || 'content')}</span>
                ${unanswered.shouldAcknowledgeSilence ? '<span class="vh-chip">Awaiting your reply</span>' : ''}
            </div>
            <div class="vh-card-last">${escapeHTML(lastText.slice(0, 120))}</div>
            ${unreadCount ? `<div class="vh-card-state"><span class="vh-chip">${unreadCount} unread</span></div>` : ''}
            <div class="vh-card-actions">
                <button class="btn btn-primary" type="button" data-vh-chat>Open chat</button>
                <button class="btn btn-ghost" type="button" data-vh-edit title="Edit in Virtual Human Studio">Edit</button>
                <button class="btn btn-ghost" type="button" data-vh-export title="Export a clean template or complete portable human">Export</button>
            </div>`;
        card.querySelector('[data-vh-chat]').onclick = () => {
            const issues = companionReadinessIssues(companion);
            if (issues.length) {
                showToast(`Finish this human first: ${issues.join(' and ')}.`, 'info');
                openCompanionStudio(companion.id);
                switchView('companionStudio');
                activateCompanionStudioTab('cs-identity');
                return;
            }
            state.activeCompanionId = companion.id;
            saveState();
            switchView('companionChat');
        };
        card.querySelector('[data-vh-edit]').onclick = () => {
            openCompanionStudio(companion.id);
            switchView('companionStudio');
        };
        card.querySelector('[data-vh-export]').onclick = () => exportCompanionArchive(companion.id);
        grid.appendChild(card);
    });
}

function includedHumanCandidates() {
    return (Array.isArray(globalThis.HORDE_INCLUDED_HUMANS) ? globalThis.HORDE_INCLUDED_HUMANS : [])
        .filter(candidate => candidate?.bundledId && candidate?.companion?.name);
}

async function installIncludedHuman(bundleId) {
    const candidate = includedHumanCandidates().find(item => item.bundledId === bundleId);
    if (!candidate) return showToast('That built-in human is unavailable in this package.', 'error');
    try {
        const companion = restoreCompanionArchive(candidate);
        companion.bundledId = candidate.bundledId;
        const receipts = Array.isArray(state.globalSettings.includedHumanReceipts)
            ? state.globalSettings.includedHumanReceipts : [];
        state.globalSettings.includedHumanReceipts = [...new Set([...receipts, candidate.bundledId])];
        await saveState();
        renderCompanionsGrid();
        showToast(`${companion.name} was added as a fresh built-in copy.`, 'success');
    } catch (error) {
        console.error('Could not restore included Virtual Human:', error);
        showToast(`Could not add the built-in human: ${error.message}`, 'error');
    }
}

function renderIncludedHumansCatalog() {
    const section = document.getElementById('included-humans-section');
    const grid = document.getElementById('included-humans-grid');
    if (!section || !grid) return;
    const included = includedHumanCandidates();
    // Never turn a packaging failure into a blank, apparently legitimate
    // library. Portable releases inline these definitions; seeing this state
    // means the package is incomplete or an old index was copied alone.
    section.classList.remove('hidden');
    grid.innerHTML = '';
    if (!included.length) {
        grid.innerHTML = `<article class="vh-included-card vh-included-error" role="alert">
            <div class="vh-included-copy">
                <strong>Built-in humans did not load</strong>
                <span>This copy of Horde Studio is incomplete. Use the portable release rather than copying index.html by itself.</span>
            </div>
        </article>`;
        return;
    }
    included.forEach(candidate => {
        const authored = normalizeCompanion(candidate.companion);
        const installed = state.companions.some(companion =>
            companion?.bundledId === candidate.bundledId
            || companion?.name === authored.name);
        const card = document.createElement('article');
        card.className = 'vh-included-card';
        card.innerHTML = `
            <div class="vh-included-avatar" style="${companionAvatarStyle(authored)}"></div>
            <div class="vh-included-copy">
                <strong>${escapeHTML(authored.name)}</strong>
                <span>${escapeHTML(authored.occupation || authored.personality || 'Included Virtual Human')}</span>
            </div>
            <button class="btn ${installed ? 'btn-ghost' : 'btn-primary'}" type="button">
                ${installed ? 'Add fresh copy' : 'Add to library'}
            </button>`;
        card.querySelector('button').onclick = () => installIncludedHuman(candidate.bundledId);
        grid.appendChild(card);
    });
}

// --- UI: Virtual Human Studio -------------------------------------------------

function openCompanionStudio(id) {
    state.editingCompanionId = id;
    renderCompanionStudioForm();
    activateCompanionStudioTab('cs-overview');
}

function resetNewCompanionStudioState() {
    const builderInput = document.getElementById('cs-builder-input');
    const builderStatus = document.getElementById('cs-builder-status');
    const builderResult = document.getElementById('cs-builder-result');
    const builderSummary = document.getElementById('cs-builder-summary');
    const photoPrompt = document.getElementById('cs-photo-test-prompt');
    const voiceSample = document.getElementById('cs-voice-sample-text');
    const voiceStatus = document.getElementById('cs-voice-preview-status');
    const voicePlayer = document.getElementById('cs-voice-preview-player');
    const photoResult = document.getElementById('cs-photo-test-result');
    const photoImage = document.getElementById('cs-photo-test-image');
    if (builderInput) builderInput.value = '';
    if (builderStatus) builderStatus.textContent = 'Nothing is sent until you press Build.';
    if (builderResult) builderResult.classList.add('hidden');
    if (builderSummary) builderSummary.textContent = '—';
    if (photoPrompt) photoPrompt.value = '';
    if (voiceSample) voiceSample.value = 'Hey, it’s me. This is what I sound like.';
    if (voiceStatus) voiceStatus.textContent = 'Ready.';
    if (voicePlayer) {
        voicePlayer.pause();
        voicePlayer.classList.add('hidden');
        voicePlayer.removeAttribute('src');
    }
    if (photoResult) photoResult.classList.add('hidden');
    if (photoImage) photoImage.removeAttribute('src');
    ['cs-photo-input', 'cs-reference-input'].forEach(id => {
        const input = document.getElementById(id);
        if (input) input.value = '';
    });
}

function setupCompanionStudioTabs() {
    document.querySelectorAll('.companion-studio-tab').forEach(tab => {
        tab.onclick = () => {
            commitCompanionStudioForm();
            activateCompanionStudioTab(tab.dataset.tab);
        };
    });
    document.querySelectorAll('[data-companion-studio-target]').forEach(button => {
        button.onclick = () => {
            commitCompanionStudioForm();
            activateCompanionStudioTab(button.dataset.companionStudioTarget);
        };
    });
    const videoToggle = document.getElementById('cs-video-enabled');
    if (videoToggle) videoToggle.onclick = () => {
        const companion = getCompanion(state.editingCompanionId);
        if (!companion) return;
        companion.allowVideoClips = !companion.allowVideoClips;
        renderCompanionVideoStudio(companion);
    };
    const videoProvider = document.getElementById('cs-video-provider');
    if (videoProvider) videoProvider.onchange = () => {
        const companion = getCompanion(state.editingCompanionId);
        if (!companion) return;
        companion.videoProvider = normalizedVideoProviderId(videoProvider.value);
        companion.videoModel = '';
        renderCompanionVideoStudio(companion, true);
    };
    const videoModel = document.getElementById('cs-video-model');
    if (videoModel) videoModel.onchange = () => {
        const companion = getCompanion(state.editingCompanionId);
        if (companion) companion.videoModel = videoModel.value;
    };
}

function activateCompanionStudioTab(tabName) {
    document.querySelectorAll('.companion-studio-tab').forEach(tab => {
        tab.classList.toggle('active', tab.dataset.tab === tabName);
    });
    document.querySelectorAll('#companion-studio-view .studio-panel').forEach(panel => panel.classList.add('hidden'));
    document.getElementById(`tab-${tabName}`)?.classList.remove('hidden');
    if (tabName === 'cs-life') {
        updateCompanionLifeBuilderModelStatus(getCompanion(state.editingCompanionId));
    }
    if (tabName === 'cs-social') renderCompanionSocialStudio(getCompanion(state.editingCompanionId));
    if (tabName === 'cs-video') renderCompanionVideoStudio(getCompanion(state.editingCompanionId), true);
    const content = document.querySelector('#companion-studio-view .studio-content-wrap');
    if (content) content.scrollTop = 0;
}

async function renderCompanionVideoStudio(companion, refreshModels = false) {
    if (!companion) return;
    const toggle = document.getElementById('cs-video-enabled');
    const provider = document.getElementById('cs-video-provider');
    const model = document.getElementById('cs-video-model');
    const status = document.getElementById('cs-video-model-status');
    if (!toggle || !provider || !model) return;
    toggle.setAttribute('aria-pressed', String(companion.allowVideoClips));
    toggle.classList.toggle('active', companion.allowVideoClips);
    document.getElementById('cs-video-enabled-label').textContent = companion.allowVideoClips ? 'Clips on' : 'Clips off';
    provider.value = normalizedVideoProviderId(companion.videoProvider);
    document.getElementById('cs-video-resolution').value = companion.videoResolution;
    document.getElementById('cs-video-duration').value = String(companion.videoDuration);
    document.getElementById('cs-video-reference').value = companion.videoReferencePolicy;
    document.getElementById('cs-video-audio').checked = companion.videoAudio;
    document.getElementById('cs-video-style-rules').value = companion.videoStyleRules;
    status.textContent = videoProviderHasCredentials(provider.value)
        ? `Loading ${videoProviderDisplayName(provider.value)} reference-video models…`
        : `${videoProviderDisplayName(provider.value)} is not connected in Settings → Connections.`;
    const models = await fetchVideoModels(provider.value, refreshModels);
    model.innerHTML = models.map(item => `<option value="${escapeHTML(item.id)}">${escapeHTML(item.name || item.id)}</option>`).join('');
    if (companion.videoModel && !models.some(item => item.id === companion.videoModel)) {
        model.insertAdjacentHTML('afterbegin', `<option value="${escapeHTML(companion.videoModel)}">${escapeHTML(companion.videoModel)} · custom</option>`);
    }
    model.value = companion.videoModel || models[0]?.id || '';
    if (!companion.videoModel && model.value) companion.videoModel = model.value;
    status.textContent = `${models.length} reference-capable model${models.length === 1 ? '' : 's'} · ${videoProviderDisplayName(provider.value)}${videoProviderHasCredentials(provider.value) ? ' connected' : ' key required before generation'}.`;
}

function updateCompanionPhotoStyleDescription(styleId) {
    const description = document.getElementById('cs-photo-style-description');
    const style = COMPANION_PHOTO_STYLES[normalizeCompanionPhotoStyle(styleId)];
    if (description) description.textContent = style.description;
}

function updateCompanionPhotoCaptureDescription(policyId) {
    const description = document.getElementById('cs-photo-capture-description');
    const policy = COMPANION_PHOTO_CAPTURE_POLICIES[normalizeCompanionPhotoCapturePolicy(policyId)];
    if (description) description.textContent = policy.description;
}

function formatCompanionScheduleMinute(minute) {
    const normalized = livingClamp(Math.round(Number(minute) || 0), 0, 1440);
    const hour = Math.floor(normalized / 60) % 24;
    const mins = normalized % 60;
    const suffix = hour >= 12 ? 'PM' : 'AM';
    return `${hour % 12 || 12}:${String(mins).padStart(2, '0')} ${suffix}`;
}

function companionScheduleTimeValue(minute) {
    const value = livingClamp(Math.round(Number(minute) || 0), 0, 1439);
    return `${String(Math.floor(value / 60)).padStart(2, '0')}:${String(value % 60).padStart(2, '0')}`;
}

function companionScheduleMinuteFromInput(value) {
    const match = /^(\d{1,2}):(\d{2})$/.exec(String(value || ''));
    if (!match) return 0;
    return livingClamp((parseInt(match[1]) || 0) * 60 + (parseInt(match[2]) || 0), 0, 1439);
}

function companionLifeEditorRowActions(type) {
    return `<button class="tool-btn tool-btn-danger" type="button" data-life-remove="${escapeHTML(type)}" title="Remove">×</button>`;
}

function collectCompanionLifeEditorValues(editor, life) {
    editor.querySelectorAll('[data-life-texture]').forEach(input => {
        life[input.dataset.lifeTexture] = input.value.trim();
    });
    editor.querySelectorAll('[data-life-place]').forEach(row => {
        const place = life.places[Number(row.dataset.lifePlace)];
        if (!place) return;
        place.label = row.querySelector('[data-field="label"]').value.trim();
        place.kind = row.querySelector('[data-field="kind"]').value;
        place.detail = row.querySelector('[data-field="detail"]').value.trim();
        place.travelMinutesFromHome = livingClamp(Number(row.querySelector('[data-field="travelMinutesFromHome"]').value) || 0, 0, 360);
    });
    editor.querySelectorAll('[data-life-person]').forEach(row => {
        const person = life.socialCircle[Number(row.dataset.lifePerson)];
        if (!person) return;
        ['name','relationship','role','contactFrequency','description','currentTension','playerContext'].forEach(field => {
            person[field] = row.querySelector(`[data-field="${field}"]`).value.trim();
        });
        person.closeness = livingClamp(Number(row.querySelector('[data-field="closeness"]').value) || 0, -100, 100);
        person.trust = livingClamp(Number(row.querySelector('[data-field="trust"]').value) || 0, -100, 100);
        person.tension = livingClamp(Number(row.querySelector('[data-field="tension"]').value) || 0, 0, 100);
        person.influence = livingClamp(Number(row.querySelector('[data-field="influence"]').value) || 0, 0, 100);
        person.knowsPlayer = row.querySelector('[data-field="knowsPlayer"]').checked;
    });
    editor.querySelectorAll('[data-life-schedule]').forEach(row => {
        const block = life.weeklySchedule[Number(row.dataset.lifeSchedule)];
        if (!block) return;
        block.days = [...row.querySelectorAll('[data-life-day]:checked')].map(input => Number(input.dataset.lifeDay));
        block.startMinute = companionScheduleMinuteFromInput(row.querySelector('[data-field="startMinute"]').value);
        block.endMinute = companionScheduleMinuteFromInput(row.querySelector('[data-field="endMinute"]').value);
        ['activity','placeId','availability','flexibility','outfitContext'].forEach(field => {
            block[field] = row.querySelector(`[data-field="${field}"]`).value.trim();
        });
    });
    editor.querySelectorAll('[data-life-look]').forEach(row => {
        const look = life.wardrobe[Number(row.dataset.lifeLook)];
        if (!look) return;
        ['label','context','items','notes'].forEach(field => {
            look[field] = row.querySelector(`[data-field="${field}"]`).value.trim();
        });
    });
    editor.querySelectorAll('[data-life-wildcard]').forEach(row => {
        const event = life.wildcardDeck[Number(row.dataset.lifeWildcard)];
        if (!event) return;
        ['label','category','availability','initiativeHook','consequences'].forEach(field => {
            event[field] = row.querySelector(`[data-field="${field}"]`).value.trim();
        });
        event.minGapDays = livingClamp(Number(row.querySelector('[data-field="minGapDays"]').value) || 1, 1, 90);
        event.durationMinutes = livingClamp(Number(row.querySelector('[data-field="durationMinutes"]').value) || 60, 15, 1440);
    });
    return life;
}

